INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('beiliao','北辽','["大辽","燕京辽"]','契丹','cn','east_asia',1122,1,NULL,'year',1123,12,NULL,'month',13464,13487,'ochre',NULL,NULL,'辽朝末年金军南下，辽宗室与留守官员在燕京拥立耶律淳，1122年建立短暂的北辽。耶律淳死后，萧德妃称制主持政务；金军攻取燕京，北辽于1123年瓦解，萧德妃随后归附天祚帝。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('cao-chunqiu','曹','["曹","曹国"]',NULL,'cn','east_asia',-1046,1,NULL,'year',-487,12,NULL,'month',-12540,-5821,'ochre',NULL,NULL,'周武王封弟振铎于曹；前487年宋灭曹。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('chen-han','陈汉','["汉","大汉"]',NULL,'cn','east_asia',1360,6,NULL,'year',1364,1,NULL,'year',16325,16368,'ochre',NULL,NULL,'陈友谅由徐寿辉部将崛起，控制湖广、江西等地，1360年杀徐寿辉后称帝、国号汉。政权以江州、武昌为中心，与朱元璋争夺长江流域；1363年鄱阳湖战败，陈友谅阵亡，子陈理继位，次年出降，陈汉亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('chen-nan','南陈','["陈"]',NULL,'cn','east_asia',557,1,NULL,'year',589,1,NULL,'year',6684,7068,'ochre',NULL,'nan-chao','陈霸先557年代梁建陈，都建康；文帝、宣帝时期整顿江南并一度收复淮南。北周灭北齐后陈朝独处江南，589年隋军攻陷建康，陈亡并结束南北朝。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('cheng-han','{"periods":[{"name":"成","start":{"year":304,"month":1,"confidence":"year"},"end":{"year":337,"month":1,"confidence":"year"}},{"name":"汉","start":{"year":338,"month":1,"confidence":"year"},"end":{"year":347,"month":1,"confidence":"year"}}]}','["成汉","成","汉","大成"]','巴氐','cn','east_asia',304,1,NULL,'year',347,1,NULL,'year',3648,4164,'ochre',NULL,'wuhu','巴氐李氏于西晋末在益州建立的政权。李雄以成都为中心稳固统治；李寿一度改国号为汉，347年为东晋桓温所灭。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('chimei','赤眉','["汉","赤眉军"]',NULL,'cn','east_asia',23,1,NULL,'year',27,1,NULL,'year',276,324,'ochre',NULL,NULL,'新莽末赤眉起义军政权，樊崇为首，25年立刘盆子为帝，27年降刘秀。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('chouchi','仇池','["仇池","前仇池","氐仇池"]','氐','cn','east_asia',296,1,NULL,'year',371,1,NULL,'year',3552,4452,'ochre',NULL,NULL,'前仇池由略阳清水氐杨氏建立。296年杨茂搜率部众据守仇池山地，借险固地势经营地方势力；此后杨氏历代在东晋、汉赵及前秦等强邻之间交涉、称藩或抵抗。杨世死后杨统、杨纂争位，前秦于371年攻取仇池，前仇池政权终结。其地域政权与后来复起的后仇池杨氏相关但并非同一连续君位序列，也不属崔鸿所列十六国。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('chu-chunqiu','楚','["楚","荆楚","楚国"]',NULL,'cn','east_asia',-1042,1,NULL,'year',-223,12,NULL,'month',-12492,-2653,'ochre',NULL,NULL,'周成王封熊绎于楚；春秋战国南方大国，前223年秦灭楚。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('chu-nan','楚','["楚","马楚"]',NULL,'cn','east_asia',907,1,NULL,'year',951,1,NULL,'year',10884,11412,'ochre',NULL,'shiguo','马殷控制湖南、以潭州（长沙）为中心建立马楚，获后梁封楚王。马楚依靠农业、茶叶贸易和与中原王朝的朝贡关系维持地方政权，马希范时期疆域与财赋达到高峰。此后诸王争位引发内战，南唐乘势攻入长沙；951年马希崇出降，马楚亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('chu-west','西楚','["楚"]',NULL,'cn','east_asia',-206,1,NULL,'year',-202,12,NULL,'month',-2460,-2401,'ochre',NULL,NULL,'项羽分封后自立西楚霸王，都彭城；垓下败亡，政权终结。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('dai-warring','代','["代","代国"]',NULL,'cn','east_asia',-228,1,NULL,'year',-222,12,NULL,'month',-2724,-2641,'ochre',NULL,NULL,'前228年赵嘉于代郡自立代王；前222年秦将王贲灭代。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('dali','大理','["大理国","后大理"]','白族','cn','east_asia',937,1,NULL,'year',1253,12,NULL,'month',11244,15047,'ochre',NULL,NULL,'937年段思平联合滇东三十七部推翻大义宁，建立大理国，以羊苴咩城为都，政治中心在洱海地区。大理承接南诏的地域与部分制度，同时发展出自身的政区和官僚体系；段氏世袭为主，高氏相国长期辅政。1094年高升泰改国号大中，1096年段氏复位。大理与宋保持朝贡、使节及马匹等贸易往来，佛教深刻影响王室与地方社会。1253年蒙古军攻取大理，段氏归降，此后仍以地方总管身份延续治理。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('dashun','大顺','["大顺","李顺"]',NULL,'cn','east_asia',1644,1,NULL,'year',1645,12,NULL,'month',19728,19751,'ochre',NULL,NULL,'李自成1644年正月西安称帝，年号永昌；克北京后旋败，1645年李自成阵亡，政权瓦解。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('daxi','大西','["大西","西"]',NULL,'cn','east_asia',1644,12,NULL,'month',1647,12,NULL,'month',19739,19775,'ochre',NULL,NULL,'张献忠1644年十二月成都称帝，年号大顺；1647年1月战死于西充，余部至同年归顺南明。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('dian','滇','["滇","滇国"]',NULL,'cn','east_asia',-279,1,NULL,'year',-109,1,NULL,'year',-3336,-1296,'ochre',NULL,NULL,'楚将庄蹻入滇称王；武帝元封二年（前109）尝羌降汉，设益州郡。庄蹻与尝羌之间世系失考。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('dongliao','东辽','["辽"]','契丹','cn','east_asia',1213,1,NULL,'year',1269,12,NULL,'month',14556,15239,'ochre',NULL,NULL,'1213年耶律留哥称辽王；1269年耶律古乃去职，广宁并入东京。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('gaogouli','高句丽','["高句丽","高句骊","高丽"]','高句丽','cn','east_asia',-37,1,NULL,'year',668,1,NULL,'year',-432,8016,'ochre',NULL,NULL,'前37年朱蒙建国；668年唐将薛仁贵等灭之，宝藏王被俘。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('guo-chunqiu','西虢国','["虢","虢国","南虢"]',NULL,'cn','east_asia',-1046,1,NULL,'year',-655,12,NULL,'month',-12540,-7837,'ochre',NULL,NULL,'周朝姬姓诸侯国，本条目聚焦西虢；其东迁后三门峡一带亦称南虢。西虢传统君主序列：虢叔 → 郭叔 → 史料缺 → 城公 → 史料缺 → 厉公 → 宣公 → 文公 → 石父 → 翰 → 忌父 → 林父 → 丑。长父之后的君主，一说为宣公，一说为文公。
有待考证的西虢君主世系：易父 → 宄公 → 幽叔 → 德叔 → 师丞。五代家族世系见师丞钟，但其是否兼任西虢君主及与主序列的衔接存在争议。
东、西虢始封君归属存在异说。西虢东迁后三门峡一带称南虢，前655年晋献公借道虞国灭虢。《左传·僖公五年》记虢公丑亡国后出奔京师。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('guo-east','东虢国','["虢","东虢国"]',NULL,'cn','east_asia',-1046,1,NULL,'approximate_year',-767,12,NULL,'approximate_year',-12540,-9181,'ochre',NULL,NULL,'西周姬姓诸侯国，位于制邑（今河南荥阳一带）。通行说为周文王弟虢仲的封国，与西虢分别屏卫周王室。可考人物有虢仲、虢惠叔大林、虢叔旅及末君虢叔；惠叔与旅为父子，其余世系有断层。东、西虢始封君的归属存在异说。东虢为郑所灭，通行系年前767年；《左传》记末君虢叔死于制邑。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('han-bei','北汉','["汉"]','沙陀','cn','east_asia',951,1,NULL,'year',979,1,NULL,'year',11412,11748,'ochre',NULL,'shiguo','后汉宗室刘崇（刘旻）于951年在太原建立北汉，统治核心在今山西北部，是五代结束后仍与北宋对峙的十国之一。北汉依靠契丹援助抵御后周、北宋，但疆域狭小、资源有限，长期处于军事压力之下。979年宋太宗围攻太原，刘继元出降，北汉灭亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('han-east','东汉','["汉","后汉"]',NULL,'cn','east_asia',25,8,NULL,'month',220,11,NULL,'month',307,2650,'ochre',NULL,NULL,'刘秀于25年重建汉室、定都洛阳，初期整顿吏治并恢复社会生产，明、章时期国势较盛，经营西域亦有进展。和帝以后外戚与宦官交替掌权，黄巾起事及州郡割据削弱朝廷；献帝于220年禅位曹丕，东汉结束。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('han-gengshi','更始','["汉","玄汉"]',NULL,'cn','east_asia',23,1,NULL,'year',25,10,NULL,'month',276,309,'ochre',NULL,NULL,'绿林军拥立更始帝刘玄，复汉号；赤眉入长安后刘玄降被杀。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('han-hou','后汉','["汉"]','沙陀','cn','east_asia',947,1,NULL,'year',951,1,NULL,'year',11364,11412,'ochre',NULL,'wudai','契丹灭后晋、北撤后，刘知远于947年在太原称帝，随后进入开封建立后汉。后汉以沙陀军政集团为统治核心，疆域和国祚都较短；刘承祐即位后与郭威等将领冲突，950年郭威起兵，次年建立后周，后汉结束。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('han-houjing','汉','["汉","侯汉","大汉"]',NULL,'cn','east_asia',552,1,NULL,'month',552,5,NULL,'month',6624,6628,'ochre',NULL,'nan-chao','侯景原为东魏将领，降梁后于548年发动叛乱并攻陷建康。552年初在建康称帝、国号汉，旋被陈霸先和王僧辩击败，政权仅存数月。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('han-nan','南汉','["汉"]',NULL,'cn','east_asia',917,1,NULL,'year',971,1,NULL,'year',11004,11652,'ochre',NULL,'shiguo','刘氏政权以广州为中心，控制岭南并曾向广西及交趾方向扩展；刘龑于917年称帝，次年改国号为汉，史称南汉。广州的港口贸易和岭南地理屏障支撑其长期独立，后期宫廷权争与统治失序加重。971年北宋军攻入广州，刘鋹出降，南汉结束。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('han-warring','韩','["韩","韩国"]',NULL,'cn','east_asia',-403,1,NULL,'year',-230,12,NULL,'month',-4824,-2737,'ochre',NULL,NULL,'三家分晋后韩氏立国，前403年周天子册命；前230年秦灭韩。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('han-west','西汉','["汉","前汉"]',NULL,'cn','east_asia',-202,2,NULL,'month',9,1,NULL,'year',-2411,108,'ochre',NULL,NULL,'刘邦在楚汉战争后于前202年称帝，定都长安，建立以郡县为骨干、兼行诸侯王国的统治秩序。文景时期休养生息，武帝时中央集权与疆域扩展并进；宣帝以后外戚势力渐强，王莽于9年代汉，西汉告终。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('han-zhao','{"periods":[{"name":"汉","start":{"year":304,"month":1,"confidence":"year"},"end":{"year":318,"month":1,"confidence":"year"}},{"name":"赵","start":{"year":319,"month":1,"confidence":"year"},"end":{"year":329,"month":1,"confidence":"year"}}]}','["汉赵","汉","前赵","赵"]','匈奴','cn','east_asia',304,1,NULL,'year',329,1,NULL,'year',3648,3948,'ochre',NULL,'wuhu','匈奴刘氏建立，初称汉，后刘曜改国号为赵，史称汉赵或前赵。政权曾攻陷洛阳、长安并终结西晋，后与石勒争夺华北，329年为后赵所灭。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('huihu','回鹘','["回鹘","回纥","回纥汗国"]','回鹘','cn','east_asia',744,1,NULL,'year',840,1,NULL,'year',8928,10080,'ochre',NULL,NULL,'744年骨力裴罗建国；840年黠戛斯攻破牙帐，㕎馺可汗被杀，漠北汗国终结。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('jiaodong-warring','胶东','["胶东","胶东国"]',NULL,'cn','east_asia',-221,1,NULL,'year',-206,12,NULL,'month',-2640,-2449,'ochre',NULL,NULL,'秦灭齐后即墨一带齐宗室残余；田巿等据胶东，至楚汉之际并入分封格局。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('jin-chunqiu','晋','["晋","晋国"]',NULL,'cn','east_asia',-1042,1,NULL,'year',-349,12,NULL,'month',-12492,-4165,'ochre',NULL,NULL,'周成王封叔虞于唐，其子燮继位后改国号为晋。曲村—天马遗址为西周时期晋国早期都邑，发现连续的晋侯及夫人墓葬；早期都邑与文献所称翼的对应、唐至晋的迁移过程及始用年代仍有争议。昭侯时晋君都翼，曲沃支系与翼公室争位，前678年曲沃武公代翼。献公时都绛，景公前585年迁新田。前403年三家分晋；前376年公室被废、另立傀儡君，前349年静公被杀而国亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('jin-east','东晋','["晋"]',NULL,'cn','east_asia',317,1,NULL,'year',420,7,NULL,'month',3804,5046,'ochre',NULL,NULL,'西晋覆亡后，司马睿于317年在建康重建晋室，史称东晋；政权以江南为中心，与北方多个政权长期并立，王导、谢安等士族及桓温、刘裕等掌兵重臣深刻影响朝政。383年淝水之战挫败前秦南下，东晋得以延续；此后北伐未能统一，刘裕逐步控制朝廷，420年受禅建立刘宋，东晋结束。北方人口南迁也推动江南开发与政治文化重心南移。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('jin-hou','后晋','["晋"]','沙陀','cn','east_asia',936,1,NULL,'year',947,1,NULL,'year',11232,11364,'ochre',NULL,'wudai','石敬瑭于936年借契丹兵推翻后唐、建立后晋，定都开封。为取得契丹支持，他称契丹主为父并割让燕云十六州，后晋因此长期受制于契丹。石重贵即位后改变对契丹的臣属姿态，引发战争；契丹军于946—947年南下攻陷开封，后晋覆亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('jin-nvzhen','金','["大金","女真金"]','女真','cn','east_asia',1115,1,NULL,'year',1234,1,NULL,'year',13380,14808,'ochre',NULL,NULL,'女真完颜氏建立的王朝。完颜阿骨打于1115年称帝建国，先后灭辽、灭北宋，统治中国北方；金朝在中都等地推行中原官制，同时保留猛安谋克等女真制度。此后金与南宋长期对峙，1141年议和后边界和关系相对稳定。蒙古兴起后金国力渐衰，1234年蒙古与南宋联军攻破蔡州，金亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('jin-west','西晋','["晋","司马晋"]',NULL,'cn','east_asia',266,2,NULL,'month',316,12,NULL,'month',3193,3803,'ochre',NULL,NULL,'司马炎于266年承魏禅建立晋朝，定都洛阳，280年灭吴而短暂统一。武帝死后，皇后贾南风与宗室诸王争权引发八王之乱；北方战乱中，汉赵于311年攻陷洛阳、316年迫使长安朝廷出降，西晋覆亡。大量北方人口与士族南迁，为晋室在江南延续统治奠定基础。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('jingnan','荆南','["南平"]',NULL,'cn','east_asia',924,1,NULL,'year',963,1,NULL,'year',11088,11556,'ochre',NULL,'shiguo','高季兴以江陵为据点建立荆南政权，后受封南平王。其辖境较小，却扼长江中游水陆交通；政权通过朝贡、贸易和在后唐、后晋及南方诸国之间周旋维持生存，虽列为十国之一，却始终未称帝。963年高继冲纳土归宋，荆南结束。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('ju-chunqiu','莒','["莒","莒国"]',NULL,'cn','east_asia',-1046,1,NULL,'year',-431,12,NULL,'month',-12540,-5149,'ochre',NULL,NULL,'周初（断代工程取前1046年）封兹舆期；至春秋早期世系与具体在位年长期失载，以史料缺占位至前616年，后接可考莒君；前481年后至前431年楚灭莒前再以史料缺占位。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('liang-back','后凉','["凉"]','氐','cn','east_asia',386,1,NULL,'year',403,1,NULL,'year',4632,4836,'ochre',NULL,'wuhu','吕光率前秦军队经营凉州后建立，定都姑臧。吕光晚年继承纷争使河西割据加深，403年吕隆降后秦。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('liang-front','前凉','["凉"]',NULL,'cn','east_asia',301,1,NULL,'year',376,1,NULL,'year',3612,4512,'ochre',NULL,'wuhu','张氏据河西建立的政权，长期奉晋正朔而实际独立，以姑臧为中心。张骏时期势力最盛，376年向前秦出降。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('liang-hou','后梁','["梁"]',NULL,'cn','east_asia',907,1,NULL,'year',923,1,NULL,'year',10884,11076,'ochre',NULL,'wudai','唐末朱温凭宣武军控制中原，907年受禅建国、定都开封。后梁延续藩镇主导的政治格局，与河东李克用、李存勖父子长期争战；朱温死后，朱友珪、朱友贞相继卷入宫变与继承冲突。923年后唐军攻入开封，后梁覆亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('liang-nan','南梁','["梁","萧梁"]',NULL,'cn','east_asia',502,1,NULL,'year',557,1,NULL,'year',6024,6684,'ochre',NULL,'nan-chao','萧衍502年取代南齐建梁，都建康；前期推行宽政并崇佛，梁朝文化繁盛。548年侯景之乱攻陷建康、梁武帝被困而死，宗室割据内战延续至557年陈霸先受禅。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('liang-north','北凉','["凉"]','卢水胡匈奴','cn','east_asia',397,1,NULL,'year',439,1,NULL,'year',4764,5268,'ochre',NULL,'wuhu','卢水胡沮渠氏据河西建立的政权，逐步取代后凉并扩张至河西大部。439年北魏攻陷姑臧，北凉亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('liang-south','南凉','["凉"]','秃发鲜卑','cn','east_asia',397,1,NULL,'year',414,1,NULL,'year',4764,4968,'ochre',NULL,'wuhu','鲜卑秃发氏在河湟建立的政权，后迁都姑臧；与后凉、北凉、西秦交战，414年为西秦所灭。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('liang-xi','西凉','["凉"]',NULL,'cn','east_asia',400,1,NULL,'year',421,1,NULL,'year',4800,5052,'ochre',NULL,'wuhu','李暠建立、以敦煌和酒泉为中心的河西政权，注重经营绿洲与屯田。420年李歆败死于北凉，西凉亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('liao','辽','["大辽","契丹"]','契丹','cn','east_asia',916,1,NULL,'year',1125,1,NULL,'year',10992,13500,'ochre',NULL,NULL,'辽由契丹耶律氏建立，耶律阿保机统一契丹诸部，916年称帝，947年定国号辽。辽以南、北面官分别治理农耕与草原地区，兼采中原制度并保留契丹旧制；鼎盛时控制燕云地区，与北宋长期对峙。澶渊之盟后，宋辽边境长期相对安定，互市和人员往来增多。女真兴起后辽国势衰落，1125年天祚帝被金军俘获，辽亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('lu-chunqiu','鲁','["鲁","鲁国"]',NULL,'cn','east_asia',-1042,1,NULL,'year',-256,12,NULL,'year',-12492,-3049,'ochre',NULL,NULL,'周武王封周公旦于鲁；孔子故乡，前256年楚灭鲁。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('min-fujian','闽','["闽","闽国"]',NULL,'cn','east_asia',909,1,NULL,'year',945,1,NULL,'year',10908,11340,'ochre',NULL,'shiguo','王潮、王审知兄弟控制福建后，由王审知建立王氏政权，以福州为中心。闽地凭山海形势发展港口贸易，并与中原王朝保持册封关系。王审知去世后，继承纷争和福州、建州对立不断削弱政权；945年南唐军攻陷建州，王延政出降，闽亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('ming','{"periods":[{"name":"吴","start":{"year":1364,"month":2,"day":4,"confidence":"day"},"end":{"year":1368,"month":1,"day":23,"confidence":"day"}},{"name":"明","start":{"year":1368,"month":1,"day":23,"confidence":"day"},"end":{"year":1644,"month":4,"day":25,"confidence":"day"}},{"name":"南明","start":{"year":1644,"month":6,"day":19,"confidence":"day"},"end":{"year":1662,"month":6,"day":1,"confidence":"day"}}]}','["明","大明","吴","西吴","南明"]',NULL,'cn','east_asia',1364,1,NULL,'year',1662,12,NULL,'year',16368,19955,'ochre',NULL,NULL,'朱元璋以应天为中心经营江南，击败陈友谅、张士诚后，于1364年称吴王，起初仍奉韩宋龙凤年号。1367年改用吴年号并发动北伐；次年在应天称帝、建立明朝，吴政权阶段结束。
朱元璋于1368年建立明朝，初都南京；永乐年间迁都北京，经营北方边防并开展郑和下西洋等对外活动。明代前中期中央集权持续加强，农业、手工业与商业发展，后期经历财政压力、边疆战争和政治纷争。1644年李自成军攻入北京，崇祯帝自缢，明朝中央政权覆亡；南方明室政权此后继续抵抗。
明亡后朱氏多支并立：通行主线弘光→隆武→永历；鲁监国、绍武为并行朝廷。1662年永历帝殉，南明终结。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('mingzheng','明郑','["大明","东宁","延平"]',NULL,'cn','east_asia',1661,6,NULL,'month',1683,10,NULL,'month',19937,20205,'ochre',NULL,NULL,'郑成功1662年收复台湾后建承天府，奉永历正朔；1683年郑克塽降清，东宁终结。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('nanyue','南越','["南越","南越国"]',NULL,'cn','east_asia',-203,1,NULL,'year',-111,1,NULL,'year',-2424,-1320,'ochre',NULL,NULL,'赵佗据岭南自立，前203年建国；前111年汉武帝遣军灭南越，设九郡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('nanzhao','南诏','["大蒙","蒙舍诏","大礼","大封民"]',NULL,'cn','east_asia',649,1,NULL,'year',902,12,NULL,'month',7788,10835,'ochre',NULL,NULL,'蒙舍诏细奴逻起于649年；738年皮逻阁统一六诏后南诏国号始显；902年亡于郑买嗣。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('prc','中华人民共和国','["中华人民共和国","新中国"]',NULL,'cn','east_asia',1949,10,NULL,'month',2026,9,NULL,'month',23397,24320,'ochre',NULL,NULL,'1949年10月1日成立。正统自起始。元首按维基百科「中华人民共和国国家元首列表」收录中央人民政府主席、国家主席、国家副主席代行、国家代主席及废除主席期间的全国人大常委会，截至2026年9月。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('qi-bei','北齐','["齐","高齐"]',NULL,'cn','east_asia',550,1,NULL,'year',577,1,NULL,'year',6600,6924,'ochre',NULL,'bei-chao','高洋550年取代东魏建齐，都邺；初期整军建制，后期及继位诸帝时朝政渐乱。北周武帝于577年攻灭北齐，北方归于北周。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('qi-chunqiu','齐','["齐","姜齐","田齐","齐国"]',NULL,'cn','east_asia',-1046,1,NULL,'year',-221,12,NULL,'month',-12540,-2629,'ochre',NULL,NULL,'周武王封姜太公于齐；前386年田氏代齐；前221年秦灭齐。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('qi-nan','南齐','["齐","萧齐"]',NULL,'cn','east_asia',479,1,NULL,'year',502,1,NULL,'year',5748,6024,'ochre',NULL,'nan-chao','萧道成479年受禅建齐，都建康；齐武帝时期政治与文化较为兴盛。此后宗室争位、皇帝更迭频繁，萧鸾一支大规模诛杀高帝和武帝后裔，最终于502年被萧衍取代。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('qi-state-chunqiu','杞','["杞","杞国"]',NULL,'cn','east_asia',-750,1,NULL,'year',-445,12,NULL,'month',-8988,-5317,'ochre',NULL,NULL,'自杞武公起有通行在位年；东楼公等更早君主失考。前445年为齐所灭。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('qin','秦','["秦","嬴秦","秦国"]',NULL,'cn','east_asia',-778,1,NULL,'year',-207,12,NULL,'month',-9324,-2461,'ochre',NULL,NULL,'前778年秦襄公即位；前770年护周平王东迁列为诸侯；前221年嬴政称帝统一；前207年子婴降，秦亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('qin-back','后秦','["秦"]','羌','cn','east_asia',384,1,NULL,'year',417,1,NULL,'year',4608,5004,'ochre',NULL,'wuhu','羌族姚氏建立、据有关中的政权，姚兴时期扩张并支持佛教译经事业。姚兴死后内乱与刘裕北伐并至，417年后秦亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('qin-front','前秦','["秦"]','氐','cn','east_asia',350,1,NULL,'year',394,1,NULL,'year',4200,4728,'ochre',NULL,'wuhu','氐族苻氏据关中建立的政权。苻坚、王猛整合北方诸国，淝水之战后诸地相继割据，394年为西秦所灭。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('qin-xi','西秦','["秦"]','乞伏鲜卑','cn','east_asia',385,1,NULL,'year',431,1,NULL,'year',4620,5172,'ochre',NULL,'wuhu','鲜卑乞伏氏在陇西、河湟建立的政权，曾降后秦而复国，并灭南凉。431年乞伏暮末降胡夏，西秦结束。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('qing','{"periods":[{"name":"金","start":{"year":1616,"month":2,"confidence":"month"},"end":{"year":1636,"month":5,"day":14,"confidence":"day"}},{"name":"清","start":{"year":1636,"month":5,"day":15,"confidence":"day"},"end":{"year":1912,"month":2,"confidence":"month"}}]}','["清","大清","金","后金"]','女真/满洲','cn','east_asia',1616,2,NULL,'month',1912,2,NULL,'month',19393,22945,'ochre',NULL,NULL,'1616年2月努尔哈赤建后金，1636年改国号大清；1912年2月宣统退位。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('ranwei','冉魏','["魏","冉魏"]',NULL,'cn','east_asia',350,1,NULL,'year',352,12,NULL,'month',4200,4235,'ochre',NULL,NULL,'后赵石虎死后政局崩解，原后赵将领冉闵于350年在邺称帝，国号魏，试图在河北重建政权。冉魏长期受到后赵残部、前燕及其他势力夹击，352年冉闵被前燕擒杀，政权随之灭亡。冉魏仅历一帝，常与十六国时期并论，但不列入崔鸿《十六国春秋》所定十六国。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('roc','中华民国','["中华民国","民国"]',NULL,'cn','east_asia',1912,1,NULL,'month',2026,9,NULL,'month',22944,24320,'ochre',NULL,NULL,'辛亥革命后，中华民国于1912年建立，先后经历南京临时政府、北京政府、南京国民政府及行宪后的总统制度。民国时期伴随政权更迭、军阀割据、北伐、抗日战争与国共内战；1949年中央政府迁往台湾后，中华民国政府在台湾继续运作。其后经历解除戒严、国会改选和政治民主化，1996年举行首次总统直接选举，2000年实现首次政党轮替。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('san-huang','三皇','[]',NULL,'cn','east_asia',-2804,1,NULL,'year',-2465,12,NULL,'month',-33636,-29557,'ochre',NULL,NULL,'司马贞《三皇本纪》：伏羲、女娲、神农。在位年取《帝王世纪》伏羲一百十年、神农一百二十年；女娲无年，与伏羲同长。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('shang','商','["商","殷","殷商"]',NULL,'cn','east_asia',-1600,1,NULL,'year',-1046,1,NULL,'year',-19188,-12540,'ochre',NULL,NULL,'断代工程：商始约前1600年，盘庚迁殷约前1300年，武王克商前1046年。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('shu','蜀汉','["汉","蜀","季汉"]',NULL,'cn','east_asia',221,5,NULL,'month',263,12,NULL,'month',2656,3167,'ochre',NULL,'sanguo','221年刘备在成都称帝，国号汉，后世称蜀汉或季汉，以益州为核心、成都为都，立国主张承续汉统。刘备死后刘禅在位，诸葛亮等主持政务并多次北伐；蜀汉长期与曹魏交战，263年魏军入蜀、刘禅投降，王朝结束。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('shu-hou','后蜀','["蜀"]',NULL,'cn','east_asia',934,1,NULL,'year',965,2,NULL,'month',11208,11581,'ochre',NULL,'shiguo','孟知祥在后唐内乱中控制两川，934年于成都建立后蜀。政权以四川盆地为核心，拥有相对稳定的农业和财政基础；孟昶统治前期延续地方治理，后期宫廷开支与防务问题加重。965年北宋军攻入成都，孟昶出降，后蜀覆亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('shu-qian','前蜀','["蜀"]',NULL,'cn','east_asia',907,1,NULL,'year',925,1,NULL,'year',10884,11100,'ochre',NULL,'shiguo','王建在唐末据有西川，以成都为中心建立前蜀，907年称帝。前蜀以四川盆地为根基，曾控制东川并扩展至汉中等地，借地势和地方资源维持独立。王建死后王衍继位，宫廷用人及边防渐趋松弛；925年后唐军入蜀，王衍出降，前蜀亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('song-chunqiu','宋','["宋","宋国"]',NULL,'cn','east_asia',-1034,1,NULL,'year',-286,12,NULL,'month',-12396,-3409,'ochre',NULL,NULL,'周成王封微子启于宋；前286年齐湣王灭宋。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('song-han','韩宋','["宋","小明王"]',NULL,'cn','east_asia',1355,2,NULL,'year',1366,12,NULL,'month',16261,16403,'ochre',NULL,NULL,'红巾军北方主力拥立韩林儿建立的宋政权，号小明王、建元龙凤。刘福通主持军政，曾据亳州并攻取汴梁，元军反攻后退守安丰；刘福通战死后韩林儿投奔朱元璋，1366年渡江途中溺亡，政权告终。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('song-liu','刘宋','["宋","南朝宋"]',NULL,'cn','east_asia',420,7,NULL,'year',479,1,NULL,'year',5046,5748,'ochre',NULL,'nan-chao','刘裕420年取代东晋建国，都建康；文帝时期一度出现“元嘉之治”，后因宗室内乱与权臣兴起而衰弱。479年萧道成受禅，刘宋亡、南齐建立。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('song-north','北宋','["宋"]',NULL,'cn','east_asia',960,2,NULL,'month',1127,3,NULL,'month',11521,13526,'ochre',NULL,NULL,'960年赵匡胤在陈桥兵变后建立宋朝、定都开封；太祖、太宗先后平定主要割据政权，形成中原与南方的大体统一。北宋以文官体系、科举和中央机构改革加强中央集权，农业、城市商业、手工业与印刷文化发展。朝廷长期面对辽、西夏等北方政权，1004年澶渊之盟后宋辽维持相对稳定的边境关系。王安石变法引发持续政争；联金灭辽后宋金关系迅速破裂，1127年金军攻陷开封，徽、钦二帝被俘，北宋覆亡，宋室随后在南方延续。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('song-south','南宋','["宋"]',NULL,'cn','east_asia',1127,6,NULL,'month',1279,3,NULL,'month',13529,15350,'ochre',NULL,NULL,'1127年靖康之变后，赵构在应天府即位，宋廷南迁并定都临安，疆域以淮河以南及东南为核心，先与金长期对峙，后又面对蒙古扩张。北方人口南迁推动江南开发，临安成为政治与商业中心，手工业、城市文化和海上贸易繁盛。1276年临安陷落后，宋室在东南沿海延续抵抗，1279年崖山战败，南宋覆亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('song-xu','徐宋','["宋","天完"]',NULL,'cn','east_asia',1351,10,NULL,'year',1360,6,NULL,'month',16221,16325,'ochre',NULL,NULL,'元末红巾军建立的区域政权。徐寿辉1351年在蕲水称帝，后迁都汉阳，势力一度扩展至湖广、江西；国号及政权称谓在史籍中有宋、天完等不同记载。陈友谅掌权并于1360年杀徐寿辉，徐宋由此终结。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('sui','隋','["隋","大隋"]',NULL,'cn','east_asia',581,3,NULL,'month',619,5,NULL,'month',6974,7432,'ochre',NULL,NULL,'581年杨坚受禅建隋，589年灭陈结束南北分裂；文帝时期整顿官制、律令与户籍财政，社会经济恢复。炀帝营建东都洛阳、开通沟通南北的运河并发动高句丽战争，持续征发加剧政局危机。618年杨广被杀、李渊建唐后，洛阳杨侗仍延续隋室；619年5月杨侗被废杀，隋亡。隋代制度与交通建设成为唐朝治理和南北经济联系的重要基础。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('taiping','太平天国','["太平天国","太平天囯","天囯"]',NULL,'cn','east_asia',1851,3,NULL,'month',1864,7,NULL,'month',22214,22374,'ochre',NULL,NULL,'1851年3月23日洪秀全登基称天王、正号太平天国；1853年3月定都天京（南京）；1864年7月19日天京陷落，政权覆亡。与清廷并立，非正统。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('tang','唐','["唐","李唐"]',NULL,'cn','east_asia',618,6,NULL,'month',907,1,NULL,'year',7421,10884,'ochre',NULL,NULL,'唐（618–907）由李渊于隋末建立，定都长安，初期经太宗治理和高宗时期的扩张形成强盛帝国；690–705年武则天改国号周，唐中宗复位后恢复李唐。玄宗开元年间臻于鼎盛，安史之乱后中央权力削弱，藩镇、宦官与朝廷长期角力；黄巢起义进一步加剧晚唐危机，907年朱温迫使哀帝禅位，唐亡。唐代科举、律令制度与文学艺术发展显著，长安也是东亚及欧亚交流的重要中心。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('tang-hou','后唐','["唐"]','沙陀','cn','east_asia',923,1,NULL,'year',936,1,NULL,'year',11076,11232,'ochre',NULL,'wudai','李存勖于923年灭后梁、建立后唐，定都洛阳；政权由沙陀军事集团发展而来，以唐为国号。明宗李嗣源时期一度整顿吏治、恢复秩序，后唐又于925年灭前蜀。其后皇位更迭与藩镇兵变相互交织，河东节度使石敬瑭借契丹兵攻入洛阳，后唐于936年灭亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('tang-nan','南唐','["唐"]',NULL,'cn','east_asia',937,1,NULL,'year',975,1,NULL,'year',11244,11700,'ochre',NULL,'shiguo','徐知诰（李昪）于937年取代杨吴，建立南唐，以金陵为都。南唐依托江淮经济与文臣治理，李璟时期一度向闽、楚扩张；但958年败于后周，割让江北地并去帝号，国势转入守成。975年北宋攻陷金陵，后主李煜出降，南唐覆亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('teng-chunqiu','滕','["滕","滕国"]',NULL,'cn','east_asia',-1045,1,NULL,'year',-296,12,NULL,'approximate_year',-12528,-3529,'ochre',NULL,NULL,'姬姓诸侯国，周武王封错叔绣。前414年一度为越所灭，后复国，前296年为宋所灭。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('tubo','吐蕃','["大蕃","吐番"]','藏','cn','east_asia',618,1,NULL,'year',842,1,NULL,'year',7416,10104,'ochre',NULL,NULL,'618年南日松赞统一青藏高原诸部；842年朗达玛被杀，帝国分裂。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('tuyuhun','吐谷浑','["吐谷浑","吐谷浑汗国","白兰"]','慕容鲜卑','cn','east_asia',329,1,NULL,'year',663,1,NULL,'year',3948,7956,'ochre',NULL,NULL,'329年叶延确立国号；663年吐蕃灭之，诺曷钵投唐。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('wei','曹魏','["魏"]',NULL,'cn','east_asia',220,12,NULL,'month',266,2,NULL,'month',2651,3193,'ochre',NULL,'sanguo','220年曹丕受汉献帝禅让称帝，国号魏，史称曹魏；以洛阳为都，主要统治中国北方，与蜀汉、孙吴长期对峙。曹氏历经曹丕、曹叡及曹芳、曹髦、曹奂五帝；高平陵之变后司马氏掌握朝政，266年曹奂禅位于司马炎，曹魏为西晋取代。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('wei-east','东魏','["魏"]','拓跋鲜卑','cn','east_asia',534,11,NULL,'year',550,2,NULL,'month',6418,6601,'ochre',NULL,'bei-chao','高欢控制洛阳朝廷后，于534年迁元善见至邺，东魏由此建立。皇帝长期受高氏挟制，550年高欢之子高洋受禅建北齐，东魏亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('wei-north','{"periods":[{"name":"代","start":{"year":386,"month":1,"confidence":"year"},"end":{"year":386,"month":6,"confidence":"approximate_month"}},{"name":"魏","start":{"year":386,"month":6,"confidence":"approximate_month"},"end":{"year":535,"month":2,"confidence":"month"}}]}','["北魏","魏","拓跋魏"]','拓跋鲜卑','cn','east_asia',386,1,NULL,'year',535,2,NULL,'month',4632,6421,'ochre',NULL,'bei-chao','拓跋珪386年重建代国并改称魏，439年太武帝灭北凉、统一北方。孝文帝迁都洛阳并推行制度与风俗改革；六镇之乱后政权衰弱，534年分裂为东魏、西魏，535年北魏名义终结。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('wei-warring','魏','["魏","梁","魏国"]',NULL,'cn','east_asia',-403,1,NULL,'year',-225,12,NULL,'month',-4824,-2677,'ochre',NULL,NULL,'三家分晋后魏氏立国，都大梁；前225年秦灭魏。与三国曹魏 wei 区分。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('wei-weiguo','卫','["卫","卫国"]',NULL,'cn','east_asia',-1040,1,NULL,'year',-209,12,NULL,'month',-12468,-2485,'ochre',NULL,NULL,'周成王封康叔封于卫；小国久存，秦二世时废。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('wei-west','西魏','["魏"]','拓跋鲜卑','cn','east_asia',535,2,NULL,'year',557,2,NULL,'month',6421,6685,'ochre',NULL,'bei-chao','宇文泰于535年在长安拥立元宝炬，建立西魏，与高欢控制的东魏对峙。西魏朝廷由宇文泰掌握，557年宇文觉受禅建北周，西魏结束。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('wu','孙吴','["吴"]',NULL,'cn','east_asia',222,10,NULL,'month',280,5,NULL,'month',2673,3364,'ochre',NULL,'sanguo','孙氏政权立足江东，孙权于222年受魏封吴王，229年称帝，后世称孙吴或东吴；建业是其主要都城，疆域包括长江下游及南方广大地区。孙权之后由孙亮、孙休、孙皓相继即位，孙吴在三国中延续最久，280年孙皓向西晋投降，政权灭亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('wu-chunqiu','吴','["吴","吴国"]',NULL,'cn','east_asia',-1100,1,NULL,'year',-473,12,NULL,'month',-13188,-5653,'ochre',NULL,NULL,'传世世系上溯至泰伯；《史记·吴太伯世家》记载武王克殷时周章已君吴，本项目以西周建国年（前1046）为周章起年确定锚点。锚点前后的无年表连续君主分别按世系均分，失考边标为 interpolated；寿梦起始保留前585年年表锚点。前473年越灭吴。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('wu-di','五帝','[]',NULL,'cn','east_asia',-2464,1,NULL,'year',-2071,12,NULL,'month',-29556,-24829,'ochre',NULL,NULL,'《史记·五帝本纪》世系，含帝挚过渡。相对在位年下锚夏始前2071，绝对年代为传说推算。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('wu-shi','吴','["吴","杨吴","十国吴"]',NULL,'cn','east_asia',902,1,NULL,'year',937,1,NULL,'year',10824,11244,'ochre',NULL,'shiguo','杨行密以淮南为根基，控制扬州及江淮地区，为杨吴奠定基础。杨隆演时期徐温掌握实权，919年杨氏建立吴国，927年杨溥称帝；政权名义上由杨氏世袭，实际长期受徐氏控制。937年徐知诰迫杨溥禅位，建立南唐，杨吴结束。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('wuyue','吴越','["吴越","吴越国"]',NULL,'cn','east_asia',907,1,NULL,'year',978,1,NULL,'year',10884,11736,'ochre',NULL,'shiguo','钱镠据有两浙、以杭州为中心，钱氏政权在五代时期受封吴越王，并延续至北宋初。吴越通过向历代中原王朝称臣来维持地方自治，较少卷入北方王朝争战；钱氏经营水利、海塘和区域贸易。978年钱俶纳土归宋，两浙和平并入宋朝。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('xia','夏','["夏","夏后氏"]',NULL,'cn','east_asia',-2070,1,NULL,'year',-1600,12,NULL,'month',-24828,-19177,'ochre',NULL,NULL,'王朝窗口取断代工程前2070–前1600。各王起迄依今本《竹书纪年》在位年数自夏始顺推（桀用《帝王世纪》五十二年以接商汤），全部标 interpolated。相、少康之间有穷后羿、寒浞占夏行而非夏后正统。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('xia-dou-jiande','夏','["夏","窦夏","夏王窦建德政权"]',NULL,'cn','east_asia',618,11,NULL,'month',621,5,NULL,'month',7426,7456,'ochre',NULL,NULL,'窦建德于618年11月在乐寿建夏称王；621年5月虎牢战败被俘，夏政权覆亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('xia-hu','胡夏','["大夏","夏"]','匈奴','cn','east_asia',407,1,NULL,'year',431,1,NULL,'year',4884,5172,'ochre',NULL,'wuhu','匈奴铁弗部赫连氏建立，以统万城为都，控制河套并向关中扩张。赫连昌被北魏俘获后国势衰退，431年赫连定被俘，胡夏亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('xia-ming','明夏','["大夏","夏"]',NULL,'cn','east_asia',1362,1,NULL,'year',1371,1,NULL,'year',16344,16452,'ochre',NULL,NULL,'明玉珍由徐寿辉部将转而经营四川，1362年在重庆称帝、国号夏，建元天统，以四川为核心并据有周边地区。政权设置官署、学校并实行较轻赋税；明玉珍死后子明升继位，1371年明军攻取重庆，明夏亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('xiliang','西梁','["梁","后梁","萧梁"]',NULL,'cn','east_asia',555,2,NULL,'month',587,10,NULL,'month',6661,7053,'ochre',NULL,'nan-chao','西魏攻陷江陵、梁元帝被杀后，西魏于555年扶立萧詧为梁主，江陵成为依附西魏的缓冲政权。西梁沿用梁制，疆域狭小，历萧詧、萧巋、萧琮三代；先后依附西魏、北周并与隋通婚。587年隋文帝召萧琮入朝并废国，西梁并入隋。它延续了梁的皇室名号与礼制，但政治自主受到宗主国限制。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('xiliao','西辽','["大辽","哈剌契丹","黑契丹"]','契丹','cn','east_asia',1124,1,NULL,'year',1218,12,NULL,'month',13488,14627,'ochre',NULL,NULL,'辽亡前后，宗室耶律大石率部西行，依托可敦城及漠北诸部整军；此后进入中亚，以巴拉沙衮为中心建立西辽，又称哈剌契丹。西辽控制中亚绿洲与商路，1141年卡特万之战后势力扩展至河中地区；此后因内乱和屈出律夺权而衰弱，1218年为蒙古所灭。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('xin','新','["新","新莽"]',NULL,'cn','east_asia',9,1,NULL,'month',23,10,NULL,'month',108,285,'ochre',NULL,NULL,'王莽于9年1月10日受孺子婴禅让，改国号为新；地皇四年绿林攻入长安，王莽被杀。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('xixia','西夏','["大夏","党项西夏"]','党项','cn','east_asia',982,1,NULL,'year',1227,1,NULL,'year',11784,14724,'ochre',NULL,NULL,'党项李氏原据夏州一带，李继迁时期逐步摆脱宋朝控制并扩展至河西；1038年李元昊称帝，国号大夏，定都兴庆府，宋人因其地在西而称西夏。西夏在党项旧制基础上设置官僚机构，创制并推行西夏文字，翻译佛经、发展佛教文化。其政权与北宋、辽长期并立，先后交战、议和并开展贸易；金灭辽后，又处于宋金之间。蒙古自13世纪初持续进攻，1227年西夏为蒙古所灭。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('xiyan','西燕','["燕"]','慕容鲜卑','cn','east_asia',384,1,NULL,'year',394,1,NULL,'year',4608,4728,'ochre',NULL,NULL,'前燕亡于前秦后，慕容泓于384年在关中聚集鲜卑部众起兵，慕容冲继之并于385年据长安称帝。386年迁徙东归途中政变频仍，段随、慕容顗、慕容瑶、慕容忠等相继短暂在位，慕容永最终掌权并定都长子。西燕与后燕争衡至394年，后燕慕容垂攻灭西燕。该政权由前燕宗室复兴运动形成，但内部权力更迭频繁。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('xu','许','["许","宇文化及许"]',NULL,'cn','east_asia',618,9,NULL,'month',619,5,NULL,'month',7424,7432,'ochre',NULL,NULL,'宇文化及杀杨浩后自立，国号许，旋为窦建德所败，619年覆亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('xue-chunqiu','薛','["薛","薛国"]',NULL,'cn','east_asia',-548,1,NULL,'interpolated_by_other',-327,12,NULL,'month',-6564,-3901,'ochre',NULL,NULL,'任姓诸侯国。薛献公在位始年不详，前511年卒；薛襄公、薛公比、薛惠公的在位见于《春秋》《左传》。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('yan-anshi','大燕','["大燕","燕","安史燕"]',NULL,'cn','east_asia',755,12,16,'day',763,12,NULL,'month',9071,9167,'ochre',NULL,NULL,'安禄山于755年12月16日在范阳起兵，至756年2月5日在洛阳称帝、国号大燕；政权记录从起兵阶段起，正式称帝从756年2月5日起。政权由安禄山、安庆绪、史思明、史朝义先后统治；史朝义政权于763年初败亡，具体自杀日期记载有异，末端以败亡日期范围内的推定日表示。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('yan-back','后燕','["燕"]','慕容鲜卑','cn','east_asia',384,1,NULL,'year',409,1,NULL,'year',4608,4908,'ochre',NULL,'wuhu','慕容垂于淝水之战后复兴慕容政权，定都中山并控制河北。慕容垂死后皇位更迭、北魏南进，407年为冯跋所取代。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('yan-chunqiu','燕','["燕","燕国"]',NULL,'cn','east_asia',-1044,1,NULL,'year',-222,12,NULL,'month',-12516,-2641,'ochre',NULL,NULL,'周武王封召公奭于燕；战国七雄之一，前222年秦灭燕。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('yan-front','前燕','["燕"]','慕容鲜卑','cn','east_asia',337,1,NULL,'year',370,1,NULL,'year',4044,4440,'ochre',NULL,'wuhu','鲜卑慕容氏据辽东建立的政权，后迁都邺城并扩展至华北。慕容儁灭冉魏后国势达峰，370年为前秦所灭。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('yan-north','北燕','["燕"]',NULL,'cn','east_asia',407,1,NULL,'year',436,1,NULL,'year',4884,5232,'ochre',NULL,'wuhu','后燕冯跋取代慕容氏后建立的政权，以和龙为中心。北魏扩张压迫其疆域，436年和龙陷落，冯弘出奔后北燕终结。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('yan-south','南燕','["燕"]','慕容鲜卑','cn','east_asia',398,1,NULL,'year',410,1,NULL,'year',4776,4920,'ochre',NULL,'wuhu','慕容德在后燕分裂后据广固建立，统治山东一带。慕容超时期遭东晋刘裕北伐，410年广固陷落，南燕亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('yelang','夜郎','["夜郎","夜郎国"]',NULL,'cn','east_asia',-300,1,NULL,'year',-27,1,NULL,'year',-3588,-312,'ochre',NULL,NULL,'战国时已有夜郎；汉武帝时夜郎侯多同，末王兴前27年被诛。君主在位年多失考，不强行拉满王朝跨度。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('yuan','{"periods":[{"name":"蒙古帝国","start":{"year":1206,"month":1,"confidence":"year"},"end":{"year":1271,"month":12,"day":18,"confidence":"day"}},{"name":"元","start":{"year":1271,"month":12,"day":18,"confidence":"day"},"end":{"year":1388,"month":11,"confidence":"month"}}]}','["元","大元","蒙元","北元","残元","故元","蒙古帝国","大蒙古国","蒙古汗国"]','蒙古','cn','east_asia',1206,1,NULL,'year',1388,11,NULL,'month',14472,16666,'ochre',NULL,NULL,'1206年铁木真称成吉思汗建国；1271年忽必烈定国号大元，中原史语境转入元朝。帝国诸汗国此后分治。
忽必烈1271年定国号大元；1368年顺帝北逃漠北继续称大元。北元延续至1388年11月天元帝被杀，政权终结。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('yue-chunqiu','越','["越","越国"]',NULL,'cn','east_asia',-565,1,NULL,'year',-306,12,NULL,'month',-6768,-3649,'ochre',NULL,NULL,'东南古国。传说夏少康庶子无余始封会稽，中间世系多缺载；有年表自允常。勾践灭吴后北进；前306年楚破越。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('zhao-back','后赵','["赵","魏"]','羯','cn','east_asia',319,1,NULL,'year',351,1,NULL,'year',3828,4212,'ochre',NULL,'wuhu','羯族石勒建立的政权，定都襄国、后迁邺，曾统治华北大部。石虎死后诸子争位并遭冉闵夺权，石祗于351年败亡。');
