INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('zhongshan','中山','["中山","中山国"]',NULL,'cn','east_asia',-424,1,NULL,'year',-296,12,NULL,'month',-5076,-3529,'ochre',NULL,NULL,'鲜虞白狄所建。有年表自文公、武公；前406年后亡国，桓公复兴。前296年赵灭中山。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('zhou-bei','北周','["周","宇文周"]','宇文鲜卑','cn','east_asia',557,2,NULL,'month',581,3,NULL,'month',6685,6974,'ochre',NULL,'bei-chao','宇文觉557年受禅建周，都长安，实际政权先受宇文护控制。武帝亲政后整军并于577年灭北齐、统一北方；581年杨坚受禅建隋，北周结束。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('zhou-east','东周','["周"]',NULL,'cn','east_asia',-770,1,NULL,'year',-256,12,NULL,'month',-9228,-3049,'ochre',NULL,NULL,'平王东迁至秦灭周。前770–前750年与携王二王并立，后世以平王为正统。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('zhou-guo-east','东周国','["周","东周","东周公国"]',NULL,'cn','east_asia',-367,1,NULL,'year',-249,12,NULL,'month',-4392,-2965,'ochre',NULL,NULL,'战国周王畿小国，都巩（巩义）；前367年由西周威公少子根所立，非东周王朝（zhou-east）。前249年秦庄襄王灭。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('zhou-guo-west','西周国','["周","西周","西周公国"]',NULL,'cn','east_asia',-440,1,NULL,'year',-256,12,NULL,'month',-5268,-3049,'ochre',NULL,NULL,'战国周王畿小国，都王城（洛阳）；前440年周考王封弟揭所立，非西周王朝（zhou-west）。前367年威公卒后与东周国分立；前256年秦灭。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('zhou-hou','后周','["周"]',NULL,'cn','east_asia',951,1,NULL,'year',960,1,NULL,'year',11412,11520,'ochre',NULL,'wudai','郭威于951年建立后周，定都开封；继位的柴荣整顿军队与财政，削弱割据势力，并向南唐用兵、取得淮南等地，使中原政权的统一能力增强。柴荣北伐途中病逝，幼主柴宗训继位。960年赵匡胤发动陈桥兵变，后周禅代为宋，北宋继而推进统一。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('zhou-west','西周','["周"]',NULL,'cn','east_asia',-1046,1,NULL,'year',-771,12,NULL,'month',-12540,-9229,'ochre',NULL,NULL,'武王克商至犬戎破镐。列王年取夏商周断代工程《夏商周年表》。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('zhou-wu','武周','["周"]',NULL,'cn','east_asia',690,1,NULL,'year',705,1,NULL,'year',8280,8460,'ochre',NULL,NULL,'武周是武则天于690年改唐为周后建立的王朝，定都洛阳，至705年神龙政变后唐中宗复位而终。武则天由高宗皇后、临朝太后逐步掌握政权并正式称帝；武周延续唐代官僚与制度，同时通过选官、整顿统治巩固皇权，并以佛教建构政治声望。其统治改变唐朝皇位继承与政治格局，退位后国号复唐。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('zhou-zhang','大周','["大周","周"]',NULL,'cn','east_asia',1354,1,NULL,'year',1367,9,NULL,'month',16248,16412,'ochre',NULL,NULL,'张士诚起兵后于1354年在高邮称诚王、国号周，建元天祐，1356年据平江并以江南为根基。1363年改称吴王；朱元璋军围攻平江，城破后张士诚被俘，政权于1367年覆亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('zou-state','邹','["邾","邹国","邾国","邾娄","邹"]',NULL,'cn','east_asia',-1046,1,NULL,'year',-256,12,NULL,'approximate_year',-12540,-3049,'ochre',NULL,NULL,'周代曹姓诸侯国，春秋称邾或邾娄，战国至孟子时称邹。文公于前614年迁都绎并同年去世；楚灭邹的年代依晚战国通行说，具体年份有异说。早期传世世系及战国晚期君主的部分世次、在位年代存在资料局限；插值坐标仅用于时间轴定位，不表示已证实的在位年月或时长。');
