INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('bai-qi','白起','qin','[]',NULL,NULL,-332,1,NULL,'year',-257,1,NULL,'year','["军事家"]','战国秦国名将，长期为秦昭襄王攻城略地，伊阙、长平等战役重创韩、魏、赵军。长平之战后处置赵军降卒的记载影响深远；后因与秦相范雎失和，被赐死于杜邮。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/白起"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ban-chao','班超','han-east','[]',NULL,NULL,32,1,NULL,'year',102,1,NULL,'year','["外交家","军事家"]','东汉将领、外交家，字仲升，扶风安陵人，班彪之子、班固之弟。永平年间投笔从戎出使西域，经营西域三十余年，击退匈奴势力并促使诸国归附，晚年返洛阳。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/班超"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('bao-si','褒姒','zhou-west','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["后妃"]','周幽王宠妃，传说与烽火戏诸侯、犬戎之祸相关；犬戎攻入镐京后幽王与太子被杀，褒姒下落不详；“烽火戏诸侯”细节存疑。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/褒姒"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('bao-zheng','包拯','song-north','[]',NULL,NULL,999,1,NULL,'year',1062,1,NULL,'year','["政治家"]','北宋官员，字希仁，庐州合肥人。历任监察御史、开封府尹及枢密副使，以执法严明、敢于弹劾权贵闻名；身后谥孝肃，包公形象在戏曲小说中进一步传奇化。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/包拯"}]',NULL,NULL,NULL,'[]');
