INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('bian-que','扁鹊','qin','[]',NULL,NULL,-407,1,NULL,'year',-310,1,NULL,'year','["医学家"]','战国名医，传说本名秦越人，因医术高明而被尊称扁鹊。史籍记载其周游行医，善察病情并采用多种疗法；望、闻、问、切四诊与其联系主要见于后世医史叙述。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/扁鹊"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('bo-qin','伯禽','lu-chunqiu','[]','姬','鲁',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','周公旦之子，周成王封于鲁为开国君主，帅师洙泗、修礼乐，治理鲁国约四十五年，事见《史记》本国世家记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/伯禽"}]',NULL,NULL,'伯禽','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('bo-yi','伯益',NULL,'["益","柏翳","大费"]','嬴',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','舜禹时虞官，佐禹治水；禹卒后一度受禅，传统记载启继位而益避居。生卒年不可考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/伯益"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cai-e','蔡锷','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','近代军事家，字松坡，湖南邵阳人，早年留学日本并参与云南新军建设。1915年云南宣布独立后，他与唐继尧等组织护国军反对袁世凯称帝；后赴日本治病，1916年病逝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/蔡锷"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cai-huanhou','蔡桓侯','zhou-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','蔡国君主，讳疾忌医寓言所指。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/蔡桓侯"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cai-lun','蔡伦','han-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["发明家"]','东汉宦官，改进造纸术，纸张普及为之勃兴；《后汉书》记其改进造纸并于元兴元年奏报；纸张此前已出现，他主要推动工艺改良与推广。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/蔡伦"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cai-tingkai','蔡廷锴','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','国民革命军将领，淞沪抗战期间任第十九路军军长，参与指挥驻沪部队抵抗日军进攻。','[{"label":"上海市民政局：是谁打响“一·二八”淞沪抗战第一枪","url":"https://mzj.sh.gov.cn/lnb-wsws/20220207/97fe1737b42c42ad93b2c426450660f1.html"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cai-yingwen','蔡英文','roc','[]',NULL,NULL,1956,8,NULL,'month',NULL,NULL,NULL,NULL,'["政治家"]','蔡英文是法律与两岸事务学者，曾任行政院副院长及民进党主席，2016年当选总统，成为首位女性国家元首。任内推动年金改革、能源转型与国防政策调整，并签署同性婚姻法案；2020年连任，2024年卸任。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/蔡英文"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-cao','曹操','wei','[]',NULL,NULL,155,1,NULL,'year',220,3,NULL,'month','["政治家","军事家","文学家"]','东汉末权臣，魏武帝（追尊），官渡之战主将。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹操"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-fang','曹芳','wei','[]',NULL,NULL,231,1,NULL,'year',274,1,NULL,'year','["皇帝"]','曹叡养子，239年即位，至254年被废，在位期间先后由曹爽与司马懿辅政。249年高平陵之变后司马氏掌握魏国军政；司马师随后废曹芳为齐王，曹芳后来被降封为邵陵县公。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹芳"}]','邵陵厉公',NULL,'齐王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-gui','曹刿','lu-chunqiu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','春秋鲁国人，事迹主要见于《左传·庄公十年》。齐鲁长勺之战前，他向鲁庄公陈说取信于民、审时用兵之理；战后以“一鼓作气”解释待齐军疲惫再追击的战术。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹刿"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-huan','曹奂','wei','[]',NULL,NULL,246,1,NULL,'year',302,1,NULL,'year','["皇帝"]','曹操之孙、燕王曹宇之子，260年被司马昭拥立为帝，在位至266年。此时魏政由司马氏掌控；曹奂于咸熙二年禅位给司马炎，曹魏灭亡，随后受封陈留王。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹奂"}]','元皇帝',NULL,'魏元帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-kun','曹锟','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家","政治家"]','曹锟是北洋直系军阀首领，曾任直隶督军。1923年通过贿选当选大总统，任内颁行《中华民国宪法》；1924年冯玉祥发动北京政变，曹锟被囚并辞职，北洋政府陷入新一轮权力重组。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹锟"}]',NULL,NULL,'大总统','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-mao','曹髦','wei','[]',NULL,NULL,241,1,NULL,'year',260,5,NULL,'month','["皇帝"]','曹丕之孙，254年由司马师拥立为帝，在位至260年。司马氏掌权期间，他曾试图亲自讨伐司马昭，兵败后在洛阳被成济所杀，是曹魏第四帝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹髦"}]',NULL,NULL,'高贵乡公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-pi','曹丕','wei','[]',NULL,NULL,187,1,NULL,'year',226,6,NULL,'month','["皇帝"]','曹操之子，承袭魏王后于220年受汉献帝禅让称帝，建立曹魏，在位至226年。他延续父亲奠定的北方政权，并以九品中正制等措施整顿选官；其子曹叡继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹丕"}]','文皇帝','高祖','魏文帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-r0','振铎','cao-chunqiu','[]','姬','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','周武王弟，受封于曹。为曹国始祖，西周初年立国，封地在今山东定陶一带，国势平稳，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/叔振铎"}]',NULL,NULL,'叔振铎','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-r1','脾','cao-chunqiu','[]','姬','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','曹国第二代君主，太伯。西周时期在位，史料记述较少，事迹不详，维持小国局面，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹太伯"}]','太伯',NULL,'曹太伯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-r10','武','cao-chunqiu','[]','姬','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','废伯之弟，在位三年。旋即传位桓公，曹国政局渐趋稳定，国势略有回升，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹穆公"}]','穆公',NULL,'曹穆公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-r11','终生','cao-chunqiu','[]','姬','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','曹桓公（姬终生），《史记·蔡世家》载前756–前702年在位，共55年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹桓公"}]','桓公',NULL,'曹桓公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-r12','夕姑','cao-chunqiu','[]','姬','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','在位三十年，曹国尚存一定影响力。春秋中期君主，国势尚可，无力争霸，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹庄公"}]','庄公',NULL,'曹庄公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-r13','夷','cao-chunqiu','[]','姬','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','庄公之子，在位八年。曹国已渐趋式微，无力外争，仰息于晋楚等强邻，事迹载于《史记》相关记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹釐公"}]','釐公',NULL,'曹釐公','[]');
