INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-r15','襄','cao-chunqiu','[]','姬','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','以刻薄闻名，《左传》载晋公子重耳过曹曾受冷遇。在位三十余年，国势日衰，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹共公"}]','共公',NULL,'曹共公','[]');
