INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-r21','午','cao-chunqiu','[]','姬','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','在位八年，曹国已濒临灭亡，无力抵抗宋国，国势奄奄一息，国亡在即，事迹载于《史记》相关记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹悼公"}]','悼公',NULL,'曹悼公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-r22','野','cao-chunqiu','[]','姬','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','在位仅四年，旋即传位隐公，曹国末代君主相继，国势危急，无力抵抗，事迹载于《史记》相关记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹声公"}]','声公',NULL,'曹声公','[]');
