INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-r24','露','cao-chunqiu','[]','姬','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','在位仅三年，旋即传位末代伯阳，曹国濒临灭亡，国势奄奄一息，事迹载于《史记》相关记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹靖公"}]','靖公',NULL,'曹靖公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-r25','伯阳','cao-chunqiu','[]','姬','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','曹国末代君主。前487年为宋国所灭，国亡，曹国历史终结，姬姓曹国不复存在，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/伯阳"}]',NULL,NULL,'伯阳','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-r3','侯','cao-chunqiu','[]','姬','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','曹国第四代君主，宫伯。西周时期在位，事迹不详，维持小国局面，国势平稳，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹宫伯"}]','宫伯',NULL,'曹宫伯','[]');
