INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-r7','苏','cao-chunqiu','[]','姬','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','曹国第八代君主，戴伯。春秋初年在位，事迹不详，维持小国局面，国势平稳，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹戴伯"}]','戴伯',NULL,'曹戴伯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-r8','兕','cao-chunqiu','[]','姬','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','曹国第九代君主，惠伯。在位三十余年，国力平平，无显著事迹，维持小国，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹惠伯"}]','惠伯',NULL,'曹惠伯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-r9','石甫','cao-chunqiu','[]','姬','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','惠伯之子，在位仅一年即被废。曹国政局一度动荡，旋即传位穆公，国势不稳，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹废伯"}]','废伯',NULL,'曹废伯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-ren','曹仁','wei','[]',NULL,NULL,168,1,NULL,'year',223,4,NULL,'month','["将领"]','曹魏宗室将领，字子孝，沛国谯人，曹操从弟。参与平定北方及赤壁后南征，曾镇守江陵、樊城；襄樊之战中抵御关羽围攻，后官至大司马。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹仁"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-rui','曹叡','wei','[]',NULL,NULL,206,1,NULL,'year',239,1,NULL,'year','["皇帝"]','曹丕之子，226—239年在位，是曹魏第二帝。即位后面对蜀汉、孙吴的持续攻势，主持防御与政务；因无亲生子，临终托孤并立养子曹芳为帝，由曹爽、司马懿辅政。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹叡"}]','明皇帝','烈祖','魏明帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-xiu','曹休','wei','[]',NULL,NULL,NULL,NULL,NULL,NULL,228,6,NULL,'month','["将领"]','曹魏宗室将领，字文烈，沛国谯人，曹操族子。随军征讨孙权、蜀汉，历任征东将军等职；石亭之战被吴将陆逊击败，后因病去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹休"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-xueqin','曹雪芹','qing','[]',NULL,NULL,1715,1,NULL,'year',1763,1,NULL,'year','["文学家"]','清代小说家，名霑，字梦阮，号雪芹，出身江宁织造曹氏家族。家道衰落后居北京西郊，晚年创作《红楼梦》；生卒年与小说定稿情况均有不同考说。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹雪芹"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chai-rong','柴荣','zhou-hou','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','郭威养子，继承后周帝位，在位954—959年。改革军政、整顿财政并多次亲征，先后取秦凤、淮南等地，推动统一进程；北伐契丹途中病重返京，留下年幼之子继位；统一战争尚未完成时幼主继位，使后周失去稳固军政核心。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周世宗"}]',NULL,'世宗','后周世宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chai-zongxun','柴宗训','zhou-hou','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','柴荣之子，959年继位时年幼，由符太后与大臣辅政。960年赵匡胤发动陈桥兵变，柴宗训禅位，后周亡；宋朝建立后被封郑王；陈桥兵变以禅让形式完成改朝，开启北宋统一进程。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/柴宗训"}]','恭帝',NULL,'后周恭帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('changsheng-wang','长寿王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','高句丽君主，名巨连，长期在位，国势稳定。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/长寿王"}]',NULL,NULL,'长寿王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-baxian','陈霸先','chen-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','出身吴兴陈氏，先后参与平定侯景之乱并掌握梁朝政权，557年受禅建陈，在位至559年。即位后稳定江南局势，陈朝以建康为都。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陈霸先"}]','武皇帝','高祖','陈武帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-bozong','陈伯宗','chen-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','陈蒨之子，566年即位，在位至568年。因年幼且政局受叔父陈顼掌握，旋被废为临海王；陈顼继位后陈朝进入新的统治阶段。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陈伯宗"}]',NULL,NULL,'陈废帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-gongbo','陈公博','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','汪精卫政权重要成员，曾任立法院长、行政院长。1944年汪精卫赴日治疗后代理汪伪国民政府主席，1945年8月16日宣布解散该政权；抗战胜利后被捕并以汉奸罪审判。','[{"label":"中国抗日战争史：汪精卫建立伪国民政府","url":"https://szzy.7lue.cn/read/eddf364fc59f9d9306913a56193b3e20/2dfe4578f86d60f92960c1df4e84e7b7.md"},{"label":"人民日报党史频道：汪伪政权的最后一天","url":"https://dangshi.people.com.cn/n1/2016/0811/c85037-28628608.html"}]',NULL,NULL,'国民政府代主席','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-jiongming','陈炯明','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家","政治家"]','民国政治人物、军事将领，字竞存，广东海丰人。曾任广东都督，支持联省自治与地方自治；1922年与孙中山决裂并炮击总统府，后在粤军攻势下退出广东。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陈炯明"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-li','陈理','chen-han','[]',NULL,NULL,1351,1,NULL,'year',1408,1,NULL,'year','["皇帝"]','陈友谅次子。父亲在鄱阳湖战死后于武昌继位，改元德寿；朱元璋次年亲征，陈理出降，陈汉政权告终，后被封归德侯。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陈理_(元末)"}]',NULL,NULL,'陈汉帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-qian','陈蒨','chen-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','陈霸先之侄，陈朝第二帝，559—566年在位。其间整顿政务、恢复江南生产并多次击退北齐，陈朝国势较建国初有所恢复。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陈蒨"}]','文皇帝',NULL,'陈文帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-qingzhi','陈庆之','liang-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','南朝梁将领，字子云，义兴国山人。梁武帝时率军护送北魏宗室元颢北上，曾连克洛阳周边城邑；元颢败亡后退兵，部众在河洛地区溃散，陈庆之辗转返回南梁。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陈庆之"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-sheng','陈胜','qin','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["起义领袖"]','秦末起义领袖，阳城人，原为屯长。前209年与吴广在大泽乡起兵，建立张楚政权并称王，揭开秦末大规模反秦战争；起义迅速扩展后因内部矛盾而失败。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陈胜"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-shubao','陈叔宝','chen-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','陈顼长子，582—589年在位，是陈朝末帝。北周灭北齐后，陈朝独处江南而未能整军；589年隋军渡江攻陷建康，陈亡，南北朝结束。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陈叔宝"}]',NULL,NULL,'陈后主','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-shuibian','陈水扁','roc','[]',NULL,NULL,1950,10,NULL,'month',NULL,NULL,NULL,NULL,'["政治家"]','陈水扁曾任台北市长，2000年当选总统，结束国民党长期执政并实现首次和平政党轮替。其两届任内推动“小三通”、社会与司法改革，台湾于2002年加入世界贸易组织；2008年卸任。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陈水扁"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-xu','陈顼','chen-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','陈霸先之侄、陈蒨之弟，568—582年在位。整顿军政并趁北齐衰乱发动北伐，一度收复淮南；晚年继承安排未稳，死后由子陈叔宝即位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陈顼"}]','宣皇帝',NULL,'陈宣帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-youliang','陈友谅','chen-han','[]',NULL,NULL,1320,1,NULL,'year',1363,1,NULL,'year','["皇帝"]','原为徐寿辉部将，后兼并倪文俊余部并控制江西、湖广多地。1359年自称汉王，次年在采石杀徐寿辉后称帝、国号汉，定都江州，后迁武昌。与朱元璋争夺长江中下游，1363年鄱阳湖之战兵败，中流矢身亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陈友谅"}]',NULL,NULL,'陈汉帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cheng-yi','程颐','song-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["思想家"]','北宋理学家，字正叔，河南洛阳人，与兄程颢并称“二程”。师从周敦颐，讲学洛阳，强调格物穷理；其学说由门人记录，成为程朱理学的重要源头。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/程颐"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r0','绎','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','熊狂之子，鬻熊后裔，楚国受西周分封后的首任国君。周成王时受封于楚蛮，获子男之田，居丹阳；与鲁、卫、晋、齐诸侯共事成王。具体在位起讫年代失考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/熊绎"},{"label":"《史记·楚世家》","url":"https://www.chinakongzi.org/kzsf/wxxs/mingpian/shiji/200705/t20070524_25207.htm"}]',NULL,NULL,'熊绎','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r1','艾','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','熊绎之子，继父为楚君，子熊䵣继位。世系见于《史记·楚世家》，具体在位年代与政事未见详载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/熊艾"},{"label":"《史记·楚世家》","url":"https://www.chinakongzi.org/kzsf/wxxs/mingpian/shiji/200705/t20070524_25207.htm"}]',NULL,NULL,'熊艾','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r10','霜','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','熊严之子。卒后三弟争位，仲雪死、叔堪亡濮，少弟熊徇得立，前827–前822年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/熊霜"}]',NULL,NULL,'熊霜','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r11','徇','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','熊霜少弟熊徇，平定兄弟之争后继位。在位时郑桓公初封于郑，前821–前800年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/熊徇"}]',NULL,NULL,'熊徇','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r12','咢','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','熊徇之子熊咢，楚国世系所载君主，事迹少见详载，年代见于《楚世家》，前799–前791年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/熊咢"}]',NULL,NULL,'熊咢','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r13','仪','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','芈姓，称若敖。周幽王被杀、平王东迁时在位，为楚国较早有称号之君，前790–前764年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/若敖"}]',NULL,NULL,'若敖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r14','坎','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','若敖之子熊坎，称霄敖。在位六年而卒，子熊眴（蚡冒）继立，前763–前758年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/霄敖"}]',NULL,NULL,'霄敖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r15','眴','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','霄敖之子熊眴，称蚡冒。在位十七年后，弟熊通杀其子而代立，前757–前741年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/蚡冒"}]',NULL,NULL,'蚡冒','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r16','通','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','芈姓，名通。杀侄代位后自立为楚王，开诸侯僭号称王先河；连年征伐，前690年伐随途中病逝，前740–前690年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚武王"}]','武王',NULL,'楚武王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r17','赀','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','武王之子，迁都郢，灭申、邓等国，楚国始成南方大国。前675年卒，前689–前675年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚文王"}]','文王',NULL,'楚文王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r18','艰','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','文王之子熊艰，称堵敖。欲杀弟熊恽未就，五年后熊恽与随国袭杀之而自立，前674–前672年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/堵敖"}]',NULL,NULL,'堵敖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r19','恽','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杀兄堵敖即位，曾与晋、齐争霸。前626年被太子商臣围困，自知不免而死，前671–前626年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚成王"}]','成王',NULL,'楚成王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r2','䵣','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','熊艾之子，继父为楚君，子熊胜继位。世系见于《史记·楚世家》，具体在位年代与政事未见详载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/熊䵣"},{"label":"《史记·楚世家》","url":"https://www.chinakongzi.org/kzsf/wxxs/mingpian/shiji/200705/t20070524_25207.htm"}]',NULL,NULL,'熊䵣','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r20','商臣','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','成王太子熊商臣，弑父自立，谥穆王。任用子重等，与晋争夺郑国，前625–前614年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚穆王"}]','穆王',NULL,'楚穆王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r22','审','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','庄王之子熊审，谥共王。在位三十年与晋国久争，鄢陵之战败于晋，前590–前560年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚共王"}]','共王',NULL,'楚共王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r23','招','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','共王之子，国事多赖令尹子囊。在位十四年，楚国与诸侯关系趋于守成，前559–前545年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚康王"}]','康王',NULL,'楚康王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r24','员','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','康王之子熊员，称郏敖。在位仅三年，叔父熊围弑之自立，是为灵王，前544–前541年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郏敖"}]',NULL,NULL,'郏敖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r25','围','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','康王弟，弑侄郏敖即位。大修章华台、征伐诸侯；前529年弟比、子弃疾谋反，灵王自杀，前540–前529年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚灵王"}]','灵王',NULL,'楚灵王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r26','比','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','共王之子熊比，灵王弟。趁兄自杀自立，仅十余日后即被弃疾逼迫自杀，前529年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/比"}]',NULL,NULL,'比','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r27','居','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','弃疾改名熊居即位，诛兄比。诬陷伍奢、杀伍子胥父兄，伍子胥逃亡吴国，前528–前516年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚平王"}]','平王',NULL,'楚平王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r28','珍','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','平王之子。伍子胥引吴军入郢，昭王出走；后复国，与陈、蔡联军败吴于颍水，前515–前489年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚昭王"}]','昭王',NULL,'楚昭王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r29','章','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','昭王之子，楚国中兴之主。灭陈、伐蔡，又立新蔡；晚年灭越国，前488–前432年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚惠王"}]','惠王',NULL,'楚惠王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r3','胜','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','熊䵣之子，继父为楚君，后由弟熊杨继位。世系见于《史记·楚世家》，具体在位年代与政事未见详载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/熊胜"},{"label":"《史记·楚世家》","url":"https://www.chinakongzi.org/kzsf/wxxs/mingpian/shiji/200705/t20070524_25207.htm"}]',NULL,NULL,'熊胜','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r30','中','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','惠王之子熊中，谥简王。在位时屡伐郑、卫等国，前408年卒，前431–前408年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚简王"}]','简王',NULL,'楚简王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r31','当','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','简王之子熊当，谥声王。在位五年而卒，战国初期楚国仍列大国，前407–前402年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚声王"}]','声王',NULL,'楚声王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r32','疑','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','声王之子，用吴起变法，明审法令、裁汰冗官、开疆拓土。变法未久而卒，前401–前381年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚悼王"}]','悼王',NULL,'楚悼王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r33','臧','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','悼王之子熊臧，在位十一年，国政继吴起变法之后渐趋稳定，前380–前370年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚肃王"}]','肃王',NULL,'楚肃王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r34','良夫','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','肃王弟。在位时楚为南方强国，曾与齐宣王、秦惠文王并列称雄，前369–前340年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚宣王"}]','宣王',NULL,'楚宣王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r35','商','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','宣王之子熊商，谥威王。破越、灭中山，威震江淮，前329年卒，前339–前329年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚威王"}]','威王',NULL,'楚威王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r36','槐','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','威王之子。初期用昭雎，后受张仪欺诈背齐；接见秦王于武关，客死于秦，前328–前299年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚怀王"}]','怀王',NULL,'楚怀王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r37','横','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','怀王之子，秦伐楚取汉中。白起反攻，前279年鄢郢失陷，楚国迁都陈，前298–前263年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚顷襄王"}]','顷襄王',NULL,'楚顷襄王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r38','元','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','顷襄王之子，迁都淮南寿春。封春申君黄歇为令尹，相楚二十余年，前262–前238年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚考烈王"}]','考烈王',NULL,'楚考烈王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r39','悍','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','考烈王之子熊悍，谥幽王。在位时楚国国力日衰，战国末期已难抗秦，前237–前228年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚幽王"}]','幽王',NULL,'楚幽王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r4','杨','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','熊䵣之子、熊胜之弟，继兄为楚君，子熊渠继位。世系见于《史记·楚世家》，名又作熊炀；具体在位年代与政事未见详载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/熊杨"},{"label":"《史记·楚世家》","url":"https://www.chinakongzi.org/kzsf/wxxs/mingpian/shiji/200705/t20070524_25207.htm"}]',NULL,NULL,'熊杨','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r40','犹','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','考烈王少子熊犹，谥哀王，幽王弟。幽王死后继立，仅数月即被兄负刍所杀，前228年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚哀王"}]','哀王',NULL,'楚哀王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r41','负刍','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','考烈王庶子，杀哀王自立。秦将王翦破楚，负刍被俘，楚国灭亡，前227–前223年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/负刍"}]',NULL,NULL,'负刍','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r42','启','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','考烈王庶子熊启，曾任秦相。秦末项燕立为楚王，与秦军战于淮南而败死，前223年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/昌平君"}]',NULL,NULL,'昌平君','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r43','熊心','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','楚怀王之后熊心，项羽所立义帝。后徙郴县，被项羽遣人所弑，前208–前205年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/义帝"}]',NULL,NULL,'义帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r5','渠','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','熊杨之子，西周楚君。周夷王时兴兵伐庸、扬越，进至鄂，立三子为句亶王、鄂王和越章王；周厉王时惧周讨伐，撤去王号。具体在位起讫年代失考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/熊渠"},{"label":"《史记·楚世家》","url":"https://www.chinakongzi.org/kzsf/wxxs/mingpian/shiji/200705/t20070524_25207.htm"}]',NULL,NULL,'熊渠','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r6','挚','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','熊挚红，一作熊挚。《史记·楚世家》记为熊渠之子，曾封鄂王，后继为楚君；关于其继位、去世及与熊延的关系，传世文献有异说。具体在位起讫年代失考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/熊挚红"},{"label":"《史记·楚世家》","url":"https://www.chinakongzi.org/kzsf/wxxs/mingpian/shiji/200705/t20070524_25207.htm"}]',NULL,NULL,'熊挚红','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r7','延','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','熊勇之父，西周楚君。《史记·楚世家》记其为熊挚红之弟，杀兄代立；关于熊挚与熊延的继承关系，传世文献有异说。即位年代失考，后由子熊勇继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/熊延"},{"label":"《史记·楚世家》","url":"https://www.chinakongzi.org/kzsf/wxxs/mingpian/shiji/200705/t20070524_25207.htm"}]',NULL,NULL,'熊延','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r8','勇','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','熊延之子，前847—前838年在位。《史记·楚世家》载其六年周厉王出奔彘，十年卒，弟熊严继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/熊勇"},{"label":"《史记·楚世家》","url":"https://www.chinakongzi.org/kzsf/wxxs/mingpian/shiji/200705/t20070524_25207.htm"}]',NULL,NULL,'熊勇','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chu-r9','严','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','熊勇之弟，继兄为楚君，前837—前828年在位。有伯霜、仲雪、叔堪、季徇四子；在位十年而卒，长子伯霜继位，是为熊霜。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/熊严"},{"label":"《史记·楚世家》","url":"https://www.chinakongzi.org/kzsf/wxxs/mingpian/shiji/200705/t20070524_25207.htm"}]',NULL,NULL,'熊严','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ci-an','慈安','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇太后","政治家"]','钮祜禄氏，咸丰帝皇后；辛酉政变后与慈禧共同垂帘听政；政变后与慈禧共同辅佐同治、光绪两朝；史料对她去世原因有不同解释。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慈安"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ci-xi','慈禧','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇太后","政治家"]','叶赫那拉氏，咸丰帝妃、同治帝生母，与恭亲王奕訢发动辛酉政变并开始垂帘听政。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慈禧"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cida-wang','次大王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','高句丽君主，名遂成，太祖王之嗣。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/次大王"}]',NULL,NULL,'次大王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cui-hao','崔颢','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["诗人"]','盛唐诗人，汴州人，早年诗风绮丽，后转写边塞与行旅。《黄鹤楼》因李白题诗传说而广为流传；其诗作数量不多，主要由《全唐诗》收录。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/崔颢"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('da-ji','妲己','shang','[]',NULL,NULL,NULL,NULL,NULL,NULL,-1046,1,NULL,'year','["后妃"]','传说中商末帝辛宠妃，生卒年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/妲己"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('daewuseong','大武神王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','高句丽君主，名无恤，扩张辽东。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/大武神王"}]',NULL,NULL,'大武神王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('deng-ai','邓艾','wei','[]',NULL,NULL,197,1,NULL,'year',264,1,NULL,'year','["军事家","将领"]','曹魏将领，景元四年率军由阴平道奇袭江油，参与灭蜀之战；钟会诬告邓艾谋反并将其囚禁，钟会兵变失败后邓艾在押送途中被杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/邓艾"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('deng-shichang','邓世昌','qing','[]',NULL,NULL,1849,1,NULL,'year',1894,1,NULL,'year','["军事家"]','清末海军将领，字正卿，广东番禺人，出身水师学堂。任致远舰管带，甲午战争黄海海战中率舰作战，舰沉后与官兵一同殉难；其事迹成为近代海军史的重要记忆。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/邓世昌"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('deng-xiaoping','邓小平','prc','[]',NULL,NULL,1904,8,NULL,'month',1997,2,NULL,'month','["政治家"]','1978年十一届三中全会后成为实际最高领导人，推动改革开放；曾任中共中央军委主席，从未担任国家主席。1997年2月19日逝世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/邓小平"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('di-renjie','狄仁杰','tang','[]',NULL,NULL,630,1,NULL,'year',700,1,NULL,'year','["政治家"]','唐代政治家，字怀英，并州太原人。历任大理丞、御史及宰相，以执法审慎、敢于直谏著称；武则天执政时劝其恢复李唐继承，后世将其塑造成断案名臣。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/狄仁杰"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('dian-changqiang','尝羌','dian','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','滇王，汉武帝元封二年率众降汉，设益州郡。中间世系多失考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滇国"}]',NULL,NULL,'滇王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('dong-biwu','董必武','prc','[]',NULL,NULL,1886,3,NULL,'month',1975,4,NULL,'month','["政治家"]','国家副主席。1968年10月31日起与宋庆龄共同代行国家主席职权；1972年2月24日起以中华人民共和国代主席名义行使职权，至1975年1月17日四届全国人大一次会议修宪废除国家主席。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/董必武"}]',NULL,NULL,'国家代主席','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('dong-zhongshu','董仲舒','han-west','[]',NULL,NULL,-179,1,NULL,'year',-104,1,NULL,'year','["思想家"]','西汉思想家，广川人，治《春秋公羊传》。汉武帝时上《天人三策》，阐发天人感应与大一统思想；“罢黜百家、独尊儒术”是后世对汉代政策变化的概括，不宜简单归为一人主张。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/董仲舒"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('dongchuan-wang','东川王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','高句丽君主，名忧位居，东川王时期。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/东川王"}]',NULL,NULL,'东川王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('dorgon','多尔衮','qing','[]',NULL,NULL,1612,1,NULL,'year',1650,1,NULL,'year','["政治家","军事家"]','清初满洲贵族，爱新觉罗氏，努尔哈赤第十四子。皇太极死后拥立顺治帝并摄政，统兵入关、迁都北京，主导清初统一与制度建设；死后曾被追尊，后遭削爵，乾隆朝复爵。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/多尔衮"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('dou-jiande','窦建德','xia-dou-jiande','[]',NULL,NULL,573,NULL,NULL,'year',621,NULL,NULL,'year','["君主","起义领袖"]','隋末河北割据者，先称长乐王，后建夏称王；援郑败于虎牢，被俘后在长安处死。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/窦建德"}]',NULL,NULL,'夏王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('dou-taihou','窦太后','han-west','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["太后","政治家"]','汉文帝皇后，景帝生母，崇尚黄老，文景之治重要推手；景帝时反对削藩，武帝初年仍影响朝政；其主张与黄老思想关系密切。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/窦太后"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('du-fu','杜甫','tang','[]',NULL,NULL,712,1,NULL,'year',770,1,NULL,'year','["诗人"]','唐代诗人，字子美，自号少陵野老，祖籍襄阳，生于巩县。安史之乱中辗转流离，曾任左拾遗、检校工部员外郎；诗作广写时政与民生，后世尊为“诗圣”。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杜甫"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('du-mu','杜牧','tang','[]',NULL,NULL,803,1,NULL,'year',852,1,NULL,'year','["诗人"]','晚唐诗人、官员，字牧之，京兆万年人。曾任黄州、池州等地刺史，长于七言绝句与咏史诗；与李商隐并称“小李杜”，《阿房宫赋》《泊秦淮》等作品传诵至今。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杜牧"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('du-ruhui','杜如晦','tang','[]',NULL,NULL,585,1,NULL,'year',630,1,NULL,'year','["政治家"]','唐初宰相，辅佐李世民定策夺位、治理天下；杜如晦去世较早，唐太宗追念其谋划才能；后世与房玄龄并称“房谋杜断”。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杜如晦"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('du-xigui','杜锡珪','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家","政治家"]','杜锡珪为海军将领，曾任海军总长和国务总理。1926年颜惠庆内阁解散后，他短暂代理国务总理并以国务院名义摄行大总统职权，随后将权力交由顾维钧内阁。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杜锡珪"}]',NULL,NULL,'国务院摄行','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-lianyi','段廉义','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','大理段氏君主，承接段思廉，在位五年。1080年为杨义贞所杀并发生短暂篡位，段氏随后复位；这场政变是大理十一世纪后期的重要王位危机；在位1075—1080年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段廉义"}]','上德皇帝',NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-qirui','段祺瑞','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家","政治家"]','段祺瑞是北洋皖系首领，袁世凯时期多次任国务总理。1924年北京政变后出任临时执政，试图召开善后会议、重组政局；其政府在国民会议争议及奉系、直系压力下失势，1926年下台。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段祺瑞"}]',NULL,NULL,'临时执政','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-shouhui','段寿辉','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','段廉义遇弑、杨义贞政权被推翻后即位的大理君主，使用上明年号。其在位约一年即让位于段正明，处于政变后恢复段氏统治的阶段；在位1080—1081年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段寿辉"}]','上明皇帝',NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-sicong','段思聪','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','段思良之后的大理君主，在位时期跨越十世纪中叶。其年号见于后世大理君主名录；由于相关史料简略，具体政事与对外关系难以详考；在位952—968年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段思聪"}]','至道广慈皇帝',NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-silian','段思廉','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','段思平后裔、段素兴之后继位的大理君主，庙号世宗，在位三十一年。其长统治连接大理早期与中期，后由段廉义继位；现存材料对其朝政细节有限；在位1044—1075年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段思廉"}]','孝德皇帝','世宗','大理世宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-siliang','段思良','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','段思平之弟，继段思英之后为大理第三位君主。其在位七年，处于新王朝早期接续皇位的阶段，现存君主名录对其具体施政记载不多；在位945—952年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段思良"}]','圣慈文武皇帝',NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-siping','段思平','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','大理开国君主，出身白蛮段氏，乘南诏衰亡后大义宁内乱之机起兵，于937年建立大理。传世记载将其列为太祖，早期政权以洱海地区为政治中心；在位937—944年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段思平"}]','圣神文武皇帝','太祖','大理太祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-siying','段思英','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','段思平之子，父死后承继大理皇位，是建国初期第二位君主。其在位仅一年，随后由段思良继位；关于其短暂统治的具体政事，现有材料记载有限；在位944—945年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段思英"}]',NULL,NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-sui','段随','xiyan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','西燕将领。386年慕容冲遇害后，韩延拥立段随为燕王；同年慕容恒、慕容永发动政变杀段随，改立慕容顗。段随在位极短，史籍对其身份与具体经历记载有限。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段隨"}]',NULL,NULL,'西燕皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-sulian','段素廉','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','段素英之后继位的大理君主，使用明启年号。其在位十三年，延续段氏王统；现存资料主要保存世系、年号和在位时间，具体政绩不详；在位1009—1022年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段素廉"}]','宣肃皇帝',NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-sulong','段素隆','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','大理第八位君主，使用明通年号，在位四年后禅位或退位，继位者为段素真。其短暂统治处于段氏王位连续传承过程中，细节记载有限；在位1022—1026年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段素隆"}]','秉义皇帝',NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-sushun','段素顺','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','大理第五位君主，承接段思聪之后的段氏统治。其在位十七年，处于大理早期政权延续与巩固阶段，具体政绩记载不详；在位968—985年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段素顺"}]','应道皇帝',NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-suxing','段素兴','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','大理第十位君主，使用圣明、天明年号，在位三年即被废。其后由段思廉继位，标志段氏王统的一次转折；废立缘由在后世叙述中较简略；在位1041—1044年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段素兴"}]','天明皇帝',NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-suying','段素英','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','大理第六位君主，使用广明、明圣、明统等年号，在位二十四年。其长期统治构成大理早期较稳定的阶段之一，但关于具体制度或战事的记载有限；在位985—1009年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段素英"}]','昭明皇帝',NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-suzhen','段素真','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','大理第九位君主，使用正治年号，在位十五年。其统治结束后由段素兴继位；具体施政事迹记载有限；在位1026—1041年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段素真"}]','圣德皇帝',NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-xiangxing','段祥兴','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','大理君主，承接段智祥，在位时期蒙古帝国势力持续南进。其去世后段兴智继位，面对蒙古对云南的军事压力；在位1238—1251年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段祥兴"}]','孝义皇帝',NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-xingzhi','段兴智','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','大理末代皇帝，段祥兴之子，蒙古军于1253年攻入大理后被俘并降元。其后获任大理总管，段氏以地方世袭总管身份延续，与皇帝统治时期相区别；在位1251—1254年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段兴智"}]',NULL,NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-zhengchun','段正淳','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','高升泰之后复位的段氏君主，庙号中宗，在高氏辅政下恢复大理国号。高氏继续掌握重要政务，段正淳统治期间大理与宋保持往来；在位1096—1108年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段正淳"}]','文安皇帝','中宗','大理中宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-zhengming','段正明','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','大理段氏君主，杨义贞之乱后继位，受到相国高氏家族的强力辅政。1094年高升泰取代段氏称帝，段正明退位；其退位为大理短暂“大中”政权及段氏复国埋下背景；在位1081—1094年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段正明"}]','保定皇帝',NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-zhengxing','段正兴','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','段正严之后继位的大理君主，庙号景宗，在位二十四年。其统治处于大理与宋及周边势力长期交往的阶段，后由段智兴继位；可考具体政事仍较有限；在位1147—1171年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段正兴"}]','正康皇帝','景宗','大理景宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-zhengyan','段和誉','dali','["段正严","段政严"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','段正淳之子，本名段和誉，庙号宪宗，是大理在位时间最长的君主之一。其朝延续高氏相国辅政格局，与宋朝维持交往，后禅位出家；在位1108—1147年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段和誉"}]','宣仁皇帝','宪宗','大理宪宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-zhilian','段智廉','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','大理段氏君主，承接段智兴，在位四年，使用凤历、元寿年号。其后由段智祥继位；相关传世资料主要见于君主世系和年表，个人政务活动记载不详；在位1200—1204年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段智廉"}]','亨天皇帝',NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-zhixiang','段智祥','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','大理神宗，在位三十四年，是蒙古势力进入云南前长期执政的段氏君主。其后由段祥兴继位，大理仍维持独立统治并与周边政权往来；在位1204—1238年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段智祥"}]',NULL,'神宗','大理神宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-zhixing','段智兴','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','段正兴之后继位的大理君主，庙号宣宗，在位近三十年。其统治期间佛教在大理社会与王室文化中保持重要地位；后由段智廉继位；在位1171—1200年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段智兴"}]','功极皇帝','宣宗','大理宣宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('dusong-mangje','杜松芒赞','tubo','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','吐蕃赞普，亦称赤都松赞、杜松芒波杰。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杜松芒赞"}]',NULL,NULL,'赞普','[]');
