INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('enzhen-kehan','遏捻特勤','huihu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["可汗","君主"]','唐封遏捻可汗，846—848年在位，回鹘南迁时期末代可汗。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/遏捻可汗"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('erzhu-rong','尔朱荣','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家","政治家"]','北魏末年将领、权臣，契胡尔朱部首领。六镇起义后拥兵入洛阳，镇压葛荣并掌控朝政，河阴之变中屠杀朝臣；530年入宫被孝庄帝元子攸伏杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/尔朱荣"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fan-chong','樊崇','chimei','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["起义领袖"]','赤眉军首领，拥立刘盆子称帝，后降刘秀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/樊崇"},{"label":"《后汉书》刘盆子传","url":"https://zh.wikisource.org/wiki/後漢書/卷11"}]',NULL,NULL,'赤眉首领','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fan-li','范蠡','yue-chunqiu','[]',NULL,NULL,-536,1,NULL,'year',-448,1,NULL,'year','["政治家","军事家"]','春秋末楚国人，字少伯，仕越为大夫，与文种辅佐越王勾践复国灭吴。越国称霸后辞官离去，辗转齐、陶经商致富，后世尊称陶朱公；晚年事迹多带传说色彩。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/范蠡"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fan-zhongyan','范仲淹','song-north','[]',NULL,NULL,989,1,NULL,'year',1052,1,NULL,'year','["政治家","文学家"]','北宋名臣，庆历新政主持者，岳阳楼记作者；庆历新政提出改革吏治、选官和军事等措施；“先天下之忧而忧”出自《岳阳楼记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/范仲淹"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fang-congze','方从哲','ming','[]',NULL,NULL,1562,1,NULL,'year',1627,1,NULL,'year','["政治家"]','明末首辅，泰昌朝红丸案关键人物，后被东林党弹劾；红丸案、移宫案处置引发朝臣弹劾，成为晚明党争焦点。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/方从哲"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fang-xuanling','房玄龄','tang','[]',NULL,NULL,579,1,NULL,'year',648,1,NULL,'year','["政治家"]','唐初政治家、史学家，名乔，字玄龄，齐州临淄人。隋末归附秦王李世民，参与谋划并典掌文书；唐太宗即位后任宰相，参与制定制度、监修国史及编纂《晋书》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/房玄龄"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('feng-ba','冯跋','yan-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','汉人，曾仕后燕，407年拥立高云并掌权；409年高云被杀后即位，建都和龙，维持北燕与北魏、东晋的周旋，430年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/冯跋"}]','文成皇帝',NULL,'北燕文成皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('feng-fuxi','伏羲','san-huang','["伏羲","太昊","庖牺"]','风',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','太昊伏羲氏，司马贞《三皇本纪》三皇之一。制嫁娶、作网罟，传说文明之始。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/伏羲"}]',NULL,NULL,'伏羲','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('feng-guozhang','冯国璋','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家","政治家"]','冯国璋为北洋将领、直系重要人物，曾任副总统。黎元洪离职后，他以副总统代理大总统，并于1917—1918年任总统；其任内南北对立与护法战争持续，卸任后仍参与北洋政局。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/冯国璋"}]',NULL,NULL,'代理大总统','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('feng-hong','冯弘','yan-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','冯跋之弟，430年继位；北魏持续攻取北燕城地，436年和龙陷落后率众逃往高句丽，后被高句丽王所杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/冯弘"},{"label":"資治通鑑/卷122","url":"https://zh.wikisource.org/wiki/資治通鑑/卷122"}]','昭成帝',NULL,'北燕昭成帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('feng-nuwa','女娲','san-huang','["女娲","娲皇"]','风',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','女娲氏，司马贞《三皇本纪》承伏羲制度。补天、抟土造人传说。无单独在位年，此取与伏羲相同一百十年，manifest 注明无出典。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/女娲"}]',NULL,NULL,'女娲','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('feng-taihou','冯太后','wei-north','[]',NULL,NULL,442,1,NULL,'year',490,1,NULL,'year','["太后","政治家"]','北魏文明太后，献文帝、孝文帝朝两度临朝，推动改革；她推动均田、俸禄等制度变革，并支持孝文帝迁都洛阳及汉化改革。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/冯太后"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('feng-xuan','冯谖','qi-chunqiu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','战国齐国人，孟尝君田文门客。曾为孟尝君赴薛收债，焚券市义；返齐后以“狡兔三窟”劝其经营退路，帮助巩固封邑与政治地位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/冯谖"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('feng-yuxiang','冯玉祥','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','北洋及民国时期将领，字焕章，原籍安徽巢县。曾任西北军首领，1924年发动北京政变，促成清帝溥仪出宫并邀请孙中山北上；后参加抗日活动，1948年在苏联返国途中船难遇难。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/冯玉祥"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fengcheng-kehan','多逻斯','huihu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["可汗","君主"]','顿莫贺达干之子，唐封忠贞可汗，在位仅一年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/忠贞可汗"}]',NULL,NULL,'忠贞可汗','[]');
