INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fengyi-kehan','滕里','huihu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["可汗","君主"]','本名失载，怀信可汗之后，唐封滕里可汗。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕里可汗"}]',NULL,NULL,'滕里可汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fu-chai','夫差','wu-chunqiu','[]','姬','姑发',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','阖闾之子，数次伐越。夫椒战后为勾践所灭，吴国亡，夫差自杀，霸业终结，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吴王夫差"}]',NULL,NULL,'夫差','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fu-chong','苻崇','qin-front','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','苻登之子，394年继位后退保湟中；同年为西秦乞伏乾归击败并杀死，前秦亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/苻崇"}]',NULL,NULL,'前秦末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fu-deng','苻登','qin-front','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','苻坚族孙，386年在枹罕即位，凭借羌氐部众与后秦长期争战；394年兵败被姚兴俘杀，前秦仅余苻崇一支。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/苻登"}]','高皇帝','太宗','前秦高皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fu-hao','妇好','shang','["帚好"]',NULL,NULL,NULL,NULL,NULL,NULL,-1200,1,NULL,'year','["王后","军事家"]','武丁配偶，甲骨所见女将、祭司，殷墟有墓。生年不详，卒于武丁在世时。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/妇好"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fu-jian','苻健','qin-front','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','氐族苻洪之子，350年入关中称秦王，351年称天王，建立前秦；平定关中后整顿政务，355年去世，由子苻生继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/苻健"}]','景明皇帝','高祖','前秦景明皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fu-jian-ming','苻坚','qin-front','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','苻健族孙，357年推翻苻生即位；任用王猛改革并先后灭前燕、前凉及代国，统一北方，383年南征败于淝水，帝国随即瓦解，苻坚于385年被姚苌杀害。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/苻坚"}]','宣昭皇帝','世祖','前秦宣昭皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fu-pi','苻丕','qin-front','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','苻坚长子，淝水败后于385年在晋阳称帝，收集前秦余部；东晋北伐与后秦进攻令其势力受挫，386年战败被东晋将领冯该杀死。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/苻丕"}]','哀平皇帝',NULL,'前秦哀平皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fu-sheng','苻生','qin-front','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','苻健之子，355年继位；统治以严酷猜忌著称，357年被堂弟苻坚废杀，前秦政权转向整合扩张。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/苻生"}]',NULL,NULL,'前秦废帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fu-yue','傅说','shang','["傅說"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','武丁之相。传说原在傅岩版筑为胥靡，武丁梦得圣人而举以为相，助成武丁中兴。生卒年不可考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/傅说"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fulianchou','伏连筹','tuyuhun','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','吐谷浑可汗，在位五十年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/伏连筹"}]',NULL,NULL,'可汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fulin','福临','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','爱新觉罗·福临，皇太极第九子，清世祖。幼年即位，由多尔衮摄政；1644年清军入关并迁都北京，顺治亲政后整顿政务，确立清朝对中原的统治。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/顺治帝"}]','章皇帝','世祖','清世祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fuyun','伏允','tuyuhun','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','步萨钵可汗，与唐、吐蕃长期角力，635年被杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/伏允"}]',NULL,NULL,'步萨钵可汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gan-pan','甘盘','shang','["甘盤"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','小乙、武丁时大臣。传说小乙命其傅武丁；武丁即位后为卿士，不久卒，傅说继之。《尚书·君奭》以之与伊尹、伊陟并称。生卒年不可考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/甘盘"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gao-baorong','高保融','jingnan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','高从诲之子，948年继位。荆南继续向中原王朝称臣，借江陵水陆交通经营朝贡和转口贸易；去世后弟高保勖继位；荆南继续凭地理与外交周旋维持政权，未进行大规模扩张。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/高保融"}]','贞懿王',NULL,'荆南贞懿王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gao-baoxu','高保勖','jingnan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','高从诲之子、高保融之弟，继承荆南王位。即位后不久病重去世，由侄高继冲继位，政权继续维持江陵一隅；短暂统治没有改变荆南依靠交通与朝贡贸易维持的格局。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/高保勖"}]','贞献王',NULL,'荆南贞献王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gao-conghe','高从诲','jingnan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','高季兴之子，继承荆南政权，在位时与后唐、后晋及南方诸国保持往来，借朝贡与贸易维持小国地位。死后子高保融继位；荆南形成依靠贸易、避免卷入大国战争的生存策略。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/高从诲"}]','文献王',NULL,'荆南文献王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gao-heng','高恒','qi-bei','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','高纬之子，577年北齐覆亡之际被立为帝，在位至578年。其即位时北齐领土已尽失，出逃途中被北周军俘获，北齐宗室政权彻底终结。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/高恒"}]',NULL,NULL,'齐幼主','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gao-jichong','高继冲','jingnan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','高保融之子，962年继承荆南。宋军平定湖南后进逼江陵，高继冲于963年纳土归宋，荆南政权结束；荆南归宋后，宋军得以继续沿长江东进。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/高继冲"}]',NULL,NULL,'荆南末王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gao-jixing','高季兴','jingnan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','陕州人，早年为朱温部将，后镇守荆南江陵。后唐建立后据地自立，受封南平王；凭江陵交通位置与周边政权往来、互市，开创荆南政权；荆南疆域虽小，却凭江陵水陆交汇优势在多国之间维持独立。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/高季兴"}]','武信王',NULL,'荆南武信王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gao-lingwei','高凌霨','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','高凌霨是北洋政府官员，曾任直隶省长、国务总理。黎元洪第二次离职后，他于1923年短暂以国务院名义摄行大总统职权，随后曹锟就任总统。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/高凌霨"}]',NULL,NULL,'国务院摄行','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gao-shengtai','高升泰','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','大理相国高智升之子，掌握朝政后于1094年取代段正明称帝，改国号大中。临终前命其子高泰明还政段氏，段正淳于1096年复位；其短暂统治体现高氏长期执政与段氏名义王统并存；在位1094—1096年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/高升泰"}]','富有圣德表正皇帝',NULL,'大中国皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gao-wei','高纬','qi-bei','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','高湛长子，569—577年在位，史称后主。朝政受宠臣与宫廷势力影响，北周武帝于577年攻灭北齐；高纬被俘后仍被处死。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/高纬"}]',NULL,NULL,'齐后主','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gao-yan','高演','qi-bei','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','高欢第六子、高洋同母弟，560年废黜高殷后即位，史称孝昭帝，在位至565年。勤于政事并整顿朝纲，病重后传位弟高湛。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐孝昭帝"}]','孝昭皇帝',NULL,'齐孝昭帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gao-yang','高洋','qi-bei','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','高欢次子、高澄之弟，550年迫使东魏孝静帝禅位，建立北齐，在位至559年。前期整顿军政、奠定新朝，后期酗酒暴虐并大肆杀戮，朝廷局势转坏。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐文宣帝"}]','文宣皇帝',NULL,'齐文宣帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gao-yao','皋陶',NULL,'["咎繇"]','偃',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','尧舜禹时掌刑之臣，传说制五刑、造狱。禹曾欲禅位于他，先禹而卒。生卒年不可考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/皋陶"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gao-yin','高殷','qi-bei','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','高洋长子，559年继位，史称废帝，在位至560年。年少而有意亲政，被叔父高演废黜并幽禁，随后遇害；北齐皇位转入高欢另一支。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐废帝"}]',NULL,NULL,'齐废帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gao-zhan','高湛','qi-bei','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','高欢第九子、高洋与高演之弟，565年继位，在位至569年，随后传位太子高纬而以太上皇身份继续影响政局。其统治使北齐朝政和边防进一步衰弱。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐武成帝"}]','武成皇帝',NULL,'齐武成帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gao-zhumeng','高朱蒙','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','东明圣王，高句丽开国君主，朱蒙。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱蒙"}]',NULL,NULL,'东明圣王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ge-luofeng','阁罗凤','nanzhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','皮逻阁之子，唐封云南王，谥神武王，天宝年间与唐战并与吐蕃结盟。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/阁罗凤"}]','神武王',NULL,'云南王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('geng-ying','更羸','wei-warring','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','战国魏国善射者，事迹见《战国策·楚策四》。他向魏王展示弓术，凭空弦声使受伤的飞鸟坠落，“惊弓之鸟”遂成为典故；其生平细节少见于史籍。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/更羸"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gong-zi-zhen','龚自珍','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["诗人","文学家","政治家"]','清代思想家、文学家，字璱人，浙江仁和人。道光年间任官，主张改革吏治、漕运与边政，辞官后参与讲学；诗文收入《定盦文集》，《己亥杂诗》最为流传。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/龚自珍"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gonghe-regency','周公、召公','zhou-west','["共伯和","周公","召公"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["摄政"]','周厉王出奔后，周公、召公共和行政（一说共伯和摄政）。前841–前828年，共和行政。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/共和_(西周)"}]',NULL,NULL,'共和行政','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gou-jian','勾践','yue-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','先败于夫差，屈身臣吴后反击灭吴，称霸东南。「卧薪尝胆」典出其事，越国霸业巅峰，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/勾践"}]',NULL,NULL,'勾践','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gu-kaizhi','顾恺之','jin-east','[]',NULL,NULL,348,1,NULL,'year',409,1,NULL,'year','["画家"]','东晋画家，字长康，小字虎头，晋陵无锡人。擅长人物画与绘画理论，提出“以形写神”等主张；《女史箴图》《洛神赋图》传为其作，现存本均非确证真迹。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/顾恺之"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gu-weijun','顾维钧','roc','["V. K. Wellington Koo"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["外交家","政治家"]','顾维钧是外交家，因巴黎和会拒绝在《凡尔赛条约》上签字而知名，后任国务总理兼外交总长。1926—1927年他主持内阁并以国务院名义摄行大总统职权，安国军政府成立后结束该段职务。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/顾维钧"}]',NULL,NULL,'国务院摄行','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gu-yanwu','顾炎武','ming','[]',NULL,NULL,1613,1,NULL,'year',1682,1,NULL,'year','["思想家"]','明末清初思想家，日知录作者，经世致用代表；长期游历并搜集碑刻、地理资料；《日知录》《天下郡国利病书》体现经世关怀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/顾炎武"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guan-hanqing','关汉卿','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["文学家"]','元代戏曲家，号已斋叟，大都人，生平年月有争议。长期活动于杂剧创作与演出圈，与王实甫等交游；《窦娥冤》《救风尘》等剧传世，被后世称为元杂剧代表作家。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/关汉卿"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guan-longpang','关龙逢','xia','["关龙逄","龙逢"]',NULL,NULL,NULL,NULL,NULL,NULL,-1600,1,NULL,'year','["政治家"]','夏桀时谏臣。传说桀通宵宴乐，关龙逢进黄图强谏被杀。生卒年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/关龙逢"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guan-yu','关羽','shu','[]',NULL,NULL,160,1,NULL,'year',220,1,NULL,'year','["将领"]','蜀汉名将，襄樊之战北伐曹魏，兵败被俘遇害；关羽被杀后孙权送其首级给曹操；蜀汉追谥壮缪侯，民间崇奉逐渐神化。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/关羽"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guan-zhong','管仲','zhou-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','春秋齐国政治家，名夷吾，字仲，颍上人。早年辅佐公子纠，齐桓公即位后任相，改革赋税、军政与行政制度，帮助齐国富强并成为春秋首位霸主。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/管仲"}]',NULL,NULL,NULL,'[]');
