INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gun','鲧','xia','["崇伯鲧","梼杌"]','姒','崇',NULL,NULL,NULL,NULL,-2070,1,NULL,'year','["政治家"]','禹之父，崇伯。传说奉尧命障洪水九年不成，后被殛于羽山。生卒年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲧"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-de-shu','虢德叔','guo-chunqiu','["即","德叔"]','姬','虢季',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["贵族","西虢君主身份待考"]','虢德叔，姬姓，字即，虢幽叔之子、师丞之父。即簋记其任周王宫廷近臣；活动年代有共王时期、孝王至夷王时期等说。其西虢君主身份有争议，在位起讫不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢德叔"},{"label":"虢国君主世系（主序列与待考虢季家族）","url":"https://zh.wikipedia.org/wiki/Template:虢國君主"},{"label":"西虢国（金文家族君主身份待考）","url":"https://zh.wikipedia.org/wiki/西虢国#金文中的虢国氏族"}]','德叔',NULL,'虢德叔','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-east-dalin','大林','guo-east','["虢惠叔大林","惠叔大林"]','姬','虢',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','东虢君主，谥惠叔，虢叔旅之父。《虢叔旅钟》称“皇考惠叔大林”，记其侍奉周天子，旅作钟追念父亲。其与始封君虢仲之间的具体世系、生卒及在位起讫不详。','[{"label":"东虢国（始封与可考君主）","url":"https://zh.wikipedia.org/wiki/東虢國"},{"label":"何志華《西周金文韻讀研究淺議》（虢叔旅钟、惠叔大林父子）","url":"https://jas.hkbu.edu.hk/content/dam/jas-assets/publications/bulletin-of-the-jao-tsung-i-academy-of-sinology/issue-6-august-2019/12.pdf"},{"label":"虢仲（始封君归属异说及东虢世系待考区段）","url":"https://zh.wikipedia.org/wiki/虢仲"}]','惠叔',NULL,'虢惠叔','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-east-last-shu','？','guo-east','["东虢末君","东虢虢叔"]','姬','虢',NULL,NULL,NULL,NULL,-767,12,NULL,'approximate_year','["君主"]','东虢末代君主，史称虢叔，私名及父祖世系不详。《国语·郑语》记其与郑桓公同时；《左传·隐公元年》借郑庄公之言记“制，岩邑也，虢叔死焉”。东虢为郑所灭，通行系年为前767年；死亡方式未详。此人并非周文王之弟、西虢始封君虢叔。','[{"label":"《左传·隐公元年》（制邑、虢叔死焉）","url":"https://zh.wikisource.org/wiki/春秋左氏傳/隱公"},{"label":"《国语·郑语》（虢叔与郑桓公共时）","url":"https://ctext.org/guo-yu/zheng-yu/ens"},{"label":"孙尚勇《〈春秋〉历史叙事与孔子的文化关怀》（平王四年郑灭虢与杜预注）","url":"https://www.ica.org.cn/att/site17/20240529/1716968303123.pdf"},{"label":"东虢国（始封与可考君主）","url":"https://zh.wikipedia.org/wiki/東虢國"},{"label":"虢仲（始封君归属异说及东虢世系待考区段）","url":"https://zh.wikipedia.org/wiki/虢仲"}]',NULL,NULL,'虢叔','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-east-lv','旅','guo-east','["虢旅"]','姬','虢',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','虢惠叔大林之子，西周虢国君主，东虢君主名录所载。曾作虢叔旅钟追念亡父，铭文记其承继父德、侍奉天子；《秦志》将其审理鬲从与攸卫牧田邑争讼系于前847年。生卒与完整在位起讫不详。','[{"label":"东虢国（始封与可考君主）","url":"https://zh.wikipedia.org/wiki/東虢國"},{"label":"何志華《西周金文韻讀研究淺議》（虢叔旅钟、惠叔大林父子）","url":"https://jas.hkbu.edu.hk/content/dam/jas-assets/publications/bulletin-of-the-jao-tsung-i-academy-of-sinology/issue-6-august-2019/12.pdf"},{"label":"《陕西省志·秦志》大事年表（虢叔旅活动于前847年之说）","url":"https://dfz.shaanxi.gov.cn/zslm/fzzlk/xbsxsz/szdylpdf/201404/P020240923616206405975.pdf"},{"label":"虢仲（始封君归属异说及东虢世系待考区段）","url":"https://zh.wikipedia.org/wiki/虢仲"}]',NULL,NULL,'虢叔旅','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-east-zhong','仲','guo-east','[]','姬','虢',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','王季之子、周文王之弟，曾与虢叔同任文王卿士。周武王克商后分封二虢，通行说以虢仲封于制邑，为东虢始封君；东、西虢始封君的归属另有异说。生卒及具体在位起讫不详。','[{"label":"虢仲（始封君归属异说及东虢世系待考区段）","url":"https://zh.wikipedia.org/wiki/虢仲"},{"label":"东虢国（始封与可考君主）","url":"https://zh.wikipedia.org/wiki/東虢國"}]',NULL,NULL,'虢仲','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-gong-chou','丑','guo-chunqiu','["虢公醜","虢叔"]','姬','虢',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','虢公丑（又作虢公醜），春秋时期西虢末代君主，生卒及父祖世系不详。前673年与郑厉公合兵平定王子颓之乱，助周惠王复位。前655年晋献公再次借道虞国灭虢，虢公丑出奔周王室京师；《左传》同段记被俘者为虞公及井伯。虢公丑此后的确切卒年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢公丑"},{"label":"《左传·僖公五年》（晋灭虢、虢公丑奔京师）","url":"https://zh.wikisource.org/wiki/春秋左氏傳/僖公"}]',NULL,NULL,'虢公丑','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-gui-gong','虢宄公','guo-chunqiu','["虢宫公","师哉","宄公"]','姬','虢季',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["贵族","西虢君主身份待考"]','虢宄公，一作虢宫公，姬姓，字哉，虢季易父之子、虢幽叔之父。师哉鼎记其任周王室军职及受命为太师；主要活动于周穆王、共王时期。其西虢君主身份有争议，在位起讫不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢宄公"},{"label":"虢国君主世系（主序列与待考虢季家族）","url":"https://zh.wikipedia.org/wiki/Template:虢國君主"},{"label":"西虢国（金文家族君主身份待考）","url":"https://zh.wikipedia.org/wiki/西虢国#金文中的虢国氏族"}]','宄公,宫公',NULL,'虢宄公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-ji-yifu','挞','guo-chunqiu','["虢季易父","易父"]','姬','虢季',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["贵族","西虢君主身份待考"]','虢季易父，姬姓，名挞，字易父，西周虢季家族人物，虢宄公之父。师丞钟记其家族五代世系；其是否兼任西虢君主存在争议，在位起讫不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢季易父"},{"label":"虢国君主世系（主序列与待考虢季家族）","url":"https://zh.wikipedia.org/wiki/Template:虢國君主"},{"label":"西虢国（金文家族君主身份待考）","url":"https://zh.wikipedia.org/wiki/西虢国#金文中的虢国氏族"}]',NULL,NULL,'虢季易父','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-r1','叔','guo-chunqiu','[]','姬','虢',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','虢叔，姬姓，周文王弟，曾任文王卿士。传统说法以其为西虢始封君；东、西虢封君归属存在异说，具体在位起讫不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢叔"},{"label":"周朝诸侯国君主列表（西虢中间世系失考）","url":"https://zh.wikipedia.org/wiki/周朝諸侯國君主列表#西虢国"},{"label":"西虢国（金文人物、年代及世系争议）","url":"https://zh.wikipedia.org/wiki/西虢国#金文中的虢国氏族"},{"label":"虢国君主世系（主序列与待考虢季家族）","url":"https://zh.wikipedia.org/wiki/Template:虢國君主"},{"label":"周朝（共时定位采用的年表）","url":"https://zh.wikipedia.org/wiki/周朝"}]',NULL,NULL,'叔','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-r10','林父','guo-chunqiu','["虢仲"]','姬','虢',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','虢公林父，姬姓虢氏，曾任周王室卿士。前707年繻葛之战率王室右军，前706、前703年奉命讨伐曲沃，前702年被迫出奔虞国，均见《左传》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢公林父"}]',NULL,NULL,'虢公林父','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-r2','郭叔','guo-chunqiu','["虢叔"]','姬','虢',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','郭叔（一作虢叔），西周虢国人物。《逸周书·王会》记其掌天子贡币；《虢国研究》认为其为始封君虢叔之子。具体在位起讫不详，与虢城公之间世系失考，不能确定为虢城公的直接前任。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郭叔"},{"label":"周朝诸侯国君主列表（西虢中间世系失考）","url":"https://zh.wikipedia.org/wiki/周朝諸侯國君主列表#西虢国"},{"label":"西虢国（金文人物、年代及世系争议）","url":"https://zh.wikipedia.org/wiki/西虢国#金文中的虢国氏族"},{"label":"《逸周书·王会》（郭叔掌贡币）","url":"https://ctext.org/lost-book-of-zhou/wang-hui/zh"},{"label":"虢国君主世系（主序列与待考虢季家族）","url":"https://zh.wikipedia.org/wiki/Template:虢國君主"},{"label":"周朝（共时定位采用的年表）","url":"https://zh.wikipedia.org/wiki/周朝"}]',NULL,NULL,'郭叔','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-r3','城公','guo-chunqiu','["虢成公"]','姬','虢',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','虢城公，班簋铭文所见西周虢国人物。铭文记周王命毛伯接替其职务，并非国君传位记载。其所属东、西虢及活动年代存在异说，一说为周昭王、穆王时期人；具体在位起讫及直接前任失考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢城公"},{"label":"周朝诸侯国君主列表（西虢中间世系失考）","url":"https://zh.wikipedia.org/wiki/周朝諸侯國君主列表#西虢国"},{"label":"西虢国（金文人物、年代及世系争议）","url":"https://zh.wikipedia.org/wiki/西虢国#金文中的虢国氏族"},{"label":"《班簋铭文》（毛伯接替虢城公职务）","url":"https://zh.wikisource.org/wiki/班簋銘文"},{"label":"虢国君主世系（主序列与待考虢季家族）","url":"https://zh.wikipedia.org/wiki/Template:虢國君主"},{"label":"周朝（共时定位采用的年表）","url":"https://zh.wikipedia.org/wiki/周朝"},{"label":"冯时《班簋铭文补释》（穆王时期）","url":"https://www.ctwx.tsinghua.edu.cn/__local/A/61/04/3B0E595B6786E89BFDFF5B51A67_192072D8_490B29.pdf?e=.pdf"}]',NULL,NULL,'城公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-r4','长父','guo-chunqiu','["虢厉公","虢仲","虢公长父"]','姬','虢',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','虢公长父，又称虢厉公、虢仲，主要活动于周厉王时期，曾任卿士并奉命征讨淮夷。具体在位年代不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢公长父"},{"label":"河南博物院《虢硕父簠》","url":"https://www.chnmus.net/ch/collection/appraise/details.html?id=512153734134559839"}]','厉公',NULL,'虢公长父','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-r5','子白','guo-chunqiu','["虢季子白","虢季"]','姬','虢',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','虢宣公，亦称虢季子白，周宣王时期率军攻猃狁，相关事迹见虢季子白盘铭文。虢公长父之后的继承顺序有宣公、文公两说。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢宣公"},{"label":"虢国君主世系（宣公、文公顺序异说）","url":"https://zh.wikipedia.org/wiki/Template:虢國君主"}]','宣公',NULL,'虢宣公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-r6','季','guo-chunqiu','["虢季"]','姬','虢',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','虢文公，周宣王时期任卿士，曾谏宣王举行籍田礼，事见《国语·周语上》。具体在位年代不详；虢公长父之后的继承顺序有宣公、文公两说。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢文公"},{"label":"虢国君主世系（宣公、文公顺序异说）","url":"https://zh.wikipedia.org/wiki/Template:虢國君主"}]','文公',NULL,'虢文公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-r7','鼓','guo-chunqiu','["虢石甫","虢公鼓","虢硕父"]','姬','虢',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','虢石父，又称虢公鼓，主要活动于周幽王时期，前775年灭焦为一说。西周灭亡后其世系及去向不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢石父"}]',NULL,NULL,'虢石父','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-r8','翰','guo-chunqiu','[]','姬','虢',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','虢公翰，西周末至东周初的虢国君主，一说为虢石父之子。具体在位年代及世系关系不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢公翰"}]',NULL,NULL,'虢公翰','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-r9','忌父','guo-chunqiu','[]','姬','虢',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','虢公忌父，周平王晚年受用为王室卿士，前720年周平王有意分郑伯政于忌父，前715年任右卿士，见《左传·隐公八年》及相关年表。即位年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢公忌父"}]',NULL,NULL,'虢公忌父','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-shi-cheng','师丞','guo-chunqiu','["虢公师丞"]','姬','虢季',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["贵族","西虢君主身份待考"]','师丞，姬姓，字丞，虢德叔之子。师丞钟列叙虢季易父、宄公、幽叔、德叔至师丞五代世系。其活动年代及西虢君主身份存在争议，与城公、厉公主序列的衔接未能确定，在位起讫不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/师丞"},{"label":"虢国君主世系（主序列与待考虢季家族）","url":"https://zh.wikipedia.org/wiki/Template:虢國君主"},{"label":"西虢国（金文家族君主身份待考）","url":"https://zh.wikipedia.org/wiki/西虢国#金文中的虢国氏族"}]',NULL,NULL,'师丞','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-wei','郭威','zhou-hou','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','后汉枢密使，出身军伍，因刘承祐诛其家而起兵。950年入开封后受拥立，建立后周；在位时整顿军政、减轻赋役并抑制藩镇，死后由养子柴荣继位；后周整军与财政措施恢复中原政权能力，为柴荣改革和扩张创造条件。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郭威"}]',NULL,'太祖','后周太祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-you-shu','虢幽叔','guo-chunqiu','["师望","幽叔"]','姬','虢季',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["贵族","西虢君主身份待考"]','虢幽叔，姬姓，字望，虢宄公之子、虢德叔之父。师望鼎记其承袭父亲的太师职务并受周王赏赐；活动年代有共王时期、懿王至孝王时期等说。其西虢君主身份有争议，在位起讫不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢幽叔"},{"label":"虢国君主世系（主序列与待考虢季家族）","url":"https://zh.wikipedia.org/wiki/Template:虢國君主"},{"label":"西虢国（金文家族君主身份待考）","url":"https://zh.wikipedia.org/wiki/西虢国#金文中的虢国氏族"}]','幽叔',NULL,'虢幽叔','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-ziyi','郭子仪','tang','[]',NULL,NULL,697,1,NULL,'year',781,1,NULL,'year','["军事家"]','唐代名将，字子仪，华州郑县人。安史之乱中率军收复长安、洛阳，后参与平定仆固怀恩之乱并迎回唐代宗；历事玄宗至德宗，官至中书令，封汾阳郡王。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郭子仪"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guyuk','贵由','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["大汗"]','贵由，窝阔台长子，1246年经忽里勒台即大汗位。其在位时间短，曾试图加强大汗对诸王和军队的控制，并与拔都关系紧张；1248年西行途中去世，之后皇后斡兀立海迷失摄政。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/贵由"}]','钦定皇帝','定宗','贵由汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('hai-rui','海瑞','ming','[]',NULL,NULL,1514,1,NULL,'year',1587,1,NULL,'year','["政治家"]','明代官员，字汝贤，号刚峰，琼山人。嘉靖年间任职地方，因上《治安疏》直谏世宗而下狱；后历任地方官，推行清丈、整饬吏治，以刚直敢言著称。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/海瑞"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-fei','韩非','han-warring','[]',NULL,NULL,-280,1,NULL,'year',-233,1,NULL,'year','["思想家"]','法家集大成者，秦王政重其书，后遭李斯害死；代表作有《孤愤》《五蠹》，主张法、术、势并用；入秦后遭李斯构陷，在狱中自尽。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩非"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-jiao','浇','xia','["过浇","奡"]','妘','寒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["将领"]','寒浞之子，处过，故称过浇。《左传》载其灭斟灌、斟鄩并杀相，后为少康遣女艾所灭。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/浇"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-jing','虔','han-warring','[]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','前403年与魏、赵同受周室册封为诸侯，韩国正式立国，定都阳翟，开启战国历史，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩景侯"}]','景侯',NULL,'韩景侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-liner','韩林儿','song-han','[]',NULL,NULL,NULL,NULL,NULL,NULL,1366,1,NULL,'year','["皇帝"]','韩山童之子，红巾军拥立的宋政权君主，号小明王。1355年刘福通等在亳州奉其称帝，年号龙凤；韩宋势力曾据汴梁，失守后退守安丰。刘福通战死后，他投奔朱元璋，1366年渡江途中溺亡，政权随之终结。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩林儿"}]',NULL,NULL,'小明王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r1','取','han-warring','[]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','景侯之子，烈侯。在位十二年，韩国初立，实力一般，无力争霸，国势平稳，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩烈侯"}]','烈侯',NULL,'韩烈侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r10','安','han-warring','[]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','韩国末代君主。前230年秦灭韩，国亡，韩国历史终结，姬姓韩国不复存在，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/安"}]',NULL,NULL,'安','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r2','猷','han-warring','[]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','文侯，在位九年。韩国继续发展，未成大患，国势平稳，无力争霸，事迹载于《史记》相关记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩文侯"}]','文侯',NULL,'韩文侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r3','屯蒙','han-warring','[]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','哀侯，在位仅三年。韩国实力尚弱，无力外争，维持小国局面，国势平平，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩哀侯"}]','哀侯',NULL,'韩哀侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r4','若山','han-warring','[]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','共侯，曾与赵攻魏，于浊泽大胜。因与赵争利未灭魏，魏得以存续，韩国错失良机，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩共侯"}]','共侯',NULL,'韩共侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r5','武','han-warring','[]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','即韩昭侯，任申不害变法，以术治国。韩国国力达于最强，诸侯不敢侵伐，为韩国巅峰，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩釐侯"}]','釐侯',NULL,'韩釐侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r6','康','han-warring','[]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','昭侯之子，宣惠王。在位时韩国称王，参与合纵连横，国势尚可，无力争霸，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩宣惠王"}]','宣惠王',NULL,'韩宣惠王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r7','仓','han-warring','[]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','襄王，在位十五年。与诸侯周旋，韩国已渐弱，无力争霸，国势转衰，事迹载于《史记》相关记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩襄王"}]','襄王',NULL,'韩襄王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r8','咎','han-warring','[]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','在位二十三年，秦国东进，韩国屡遭攻伐，割地求和，国势危急，濒临灭亡，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩釐王"}]','釐王',NULL,'韩釐王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r9','然','han-warring','[]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','桓惠王，在位三十三年。韩国沦为秦国附庸，割地求和，国势危急，濒临灭亡，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩桓惠王"}]','桓惠王',NULL,'韩桓惠王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-shizhong','韩世忠','song-south','[]',NULL,NULL,1089,1,NULL,'year',1151,1,NULL,'year','["军事家"]','南宋将领，字良臣，延安人。早年从军抗金，曾在黄天荡与金军交战，后长期镇守两淮；秦桧议和时他当面质问岳飞罪证，晚年退居杭州。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩世忠"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-xin','韩信','han-west','[]',NULL,NULL,-231,1,NULL,'year',-196,1,NULL,'year','["军事家"]','汉初大将，破赵燕齐楚，垓下围项羽，后遭诛；因萧何推荐而受刘邦拜将，统军取关中、破赵齐；前196年被吕后与萧何诱杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩信"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-yu','韩愈','tang','[]',NULL,NULL,768,1,NULL,'year',824,1,NULL,'year','["文学家"]','中唐文学家、思想家，字退之，河阳人。倡导古文运动，反对骈俪文风，曾任吏部侍郎；因谏迎佛骨被贬潮州，散文与诗歌对后世影响深远，列唐宋八大家之首。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩愈"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-zhuo','浞','xia','["浞","韩浞"]','妘','寒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','寒氏，名浞，妘姓。伯明氏谗子弟，后羿用为相，旋杀羿代有穷；使浇灭相。后为少康、靡所灭。生卒年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/寒浞"}]',NULL,NULL,'寒浞','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('helian-bobo','赫连勃勃','xia-hu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','匈奴铁弗部首领，407年脱离后秦建夏，后称帝并定都统万城；凭借河套据点袭扰后秦、拓展关中北部，425年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赫连勃勃"}]','武皇帝',NULL,'胡夏武皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('helian-chang','赫连昌','xia-hu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','赫连勃勃之子，425年继位；北魏攻夏后于427年失统万城，428年被俘，胡夏主力退守关中。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赫连昌"}]',NULL,NULL,'胡夏皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('helian-ding','赫连定','xia-hu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','赫连勃勃之子，赫连昌被俘后于428年继位；431年灭西秦后西行，旋为吐谷浑所俘并送交北魏处死，胡夏亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赫连定"},{"label":"資治通鑑/卷121","url":"https://zh.wikisource.org/wiki/資治通鑑/卷121"}]',NULL,NULL,'胡夏末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('helu','阖闾','wu-chunqiu','[]','姬','姑发',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','弑僚自立，任用伍子胥、孙武。破楚入郢，与越王勾践争霸，战死槜李，吴国霸业奠基，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/阖闾"}]',NULL,NULL,'阖闾','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('hong-tianguifu','洪天贵福','taiping','[]',NULL,NULL,1849,11,NULL,'month',1864,11,NULL,'month','["皇帝"]','洪秀全长子，幼天王；洪秀全死后于六月初六继位，天京陷落后被俘处死。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/洪天贵福"}]',NULL,NULL,'幼天王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('hong-xiuquan','洪秀全','taiping','[]',NULL,NULL,1814,1,NULL,'year',1864,6,NULL,'month','["皇帝","起义领袖"]','太平天国创建者，金田起义后称天王，定都天京；同治三年四月二十七日（1864年6月1日）病逝于南京。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/洪秀全"}]',NULL,NULL,'天王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('hongli','弘历','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','爱新觉罗·弘历，清高宗，雍正帝第四子。乾隆朝平定准噶尔、回部等地，编纂《四库全书》；在位六十年后禅位，仍以太上皇训政至1799年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/乾隆帝"}]','纯皇帝','高宗','清高宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('hou-jing','侯景','han-houjing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["将领"]','原为东魏将领，后降梁并受封河南王，548年举兵反梁。侯景攻陷建康、围困梁武帝，552年自立为汉帝；旋被陈霸先、王僧辩等击败，出逃途中被杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/侯景"}]',NULL,NULL,'汉帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('hou-min','后缗','xia','["缗"]',NULL,'有仍',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["后妃"]','有仍氏女，夏后相之妻。相为浇所灭时方娠，逃出自窦，归于有仍，生少康。见《左传·哀公元年》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/后缗"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('hou-yi','后羿','xia','["羿","夷羿","有穷后羿"]',NULL,'有穷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','有穷氏首领，善射。《左传》载其自鉏迁穷石，因夏民以代夏政，不修民事，为寒浞所杀。生卒年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/后羿_(夏朝)"}]',NULL,NULL,'后羿','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('hu-bilie','忽必烈','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["大汗","皇帝"]','忽必烈，成吉思汗之孙、拖雷之子。1260年即大汗位后与阿里不哥争位，1264年获胜；1271年定国号大元，1279年灭南宋，建都大都并确立中原王朝的行政制度。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/忽必烈"},{"label":"《元典章·建国号诏》","url":"https://zh.wikisource.org/zh-hant/建國號詔"}]',NULL,'世祖','元世祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('hu-jintao','胡锦涛','prc','[]',NULL,NULL,1942,12,NULL,'month',NULL,NULL,NULL,NULL,'["政治家"]','2003年3月15日当选国家主席，2008年连任，至2013年3月14日卸任。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/胡锦涛"}]',NULL,NULL,'国家主席','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('hu-taihou','胡太后','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,528,5,17,'day','["太后","政治家"]','北魏灵太后，孝明帝元诩生母，两度临朝。528年与郑俨、徐纥合谋毒杀孝明帝，先立孝明帝之女，旋改立幼主元钊；尔朱荣进军洛阳后，在河阴将她与元钊沉入黄河。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/胡太后"},{"label":"《资治通鉴》卷152","url":"https://zh.wikisource.org/zh-hans/資治通鑑/卷152"},{"label":"《魏书》卷13·皇后列传","url":"https://zh.wikisource.org/zh-hans/魏書/卷13"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('hu-weide','胡惟德','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["外交家","政治家"]','胡惟德是资深外交官与北洋政府官员，曾任国务总理。段祺瑞下台后，他两度以国务院名义摄行元首职权，分别处于1926年临时执政交接及1927年政府改组期间。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/胡惟德"}]',NULL,NULL,'国务院摄行','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('hu-yaobang','胡耀邦','prc','[]',NULL,NULL,1915,11,NULL,'month',1989,4,NULL,'month','["政治家"]','1980年代任中共中央总书记，主持拨乱反正；1987年辞职，1989年4月15日逝世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/胡耀邦"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('hua-guofeng','华国锋','prc','[]',NULL,NULL,1921,2,NULL,'month',2008,8,NULL,'month','["政治家"]','毛泽东逝世后任中共中央主席、中央军委主席、国务院总理；未担任国家主席。2008年8月20日逝世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/华国锋"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('huairen-kehan','顿莫贺达干','huihu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["可汗","君主"]','杀移地健自立，唐封长寿天亲可汗。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/顿莫贺达干"}]',NULL,NULL,'长寿天亲可汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('huaixin-kehan','骨咄禄','huihu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["可汗","君主"]','阿跌氏，唐封怀信可汗，阿啜之后继统。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/怀信可汗"}]',NULL,NULL,'怀信可汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('huan-wen','桓温','jin-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家","政治家"]','东晋权臣、将领，出身谯国桓氏，长期控制朝政并三次北伐。前两次北伐一度收复洛阳等地；太和六年废海西公、拥立司马昱，后谋求禅代未成，病逝于姑孰。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/桓温"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('huang-chao','黄巢','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["起义领袖"]','唐末起义领袖，曹州冤句人，曾以盐贩为业。乾符年间起兵反唐，转战南北并于880年攻入长安、称帝建大齐；唐军与沙陀军反攻后，起义军瓦解，黄巢在狼虎谷自杀（一说被杀）。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/黄巢"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('huang-fu','黄郛','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','黄郛为国民党政治人物，曾任外交总长等职。1924年北京政变后，他短暂以国务院名义摄行大总统职权，并参与迎段祺瑞出任临时执政；此后转入南京国民政府任职。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/黄郛"}]',NULL,NULL,'国务院摄行','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('huang-taiji','皇太极','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','爱新觉罗·皇太极，努尔哈赤第八子，清太宗。1626年继承汗位，改革政制、整编八旗；1636年改国号为大清并称帝，为清军入关奠定基础。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/皇太极"},{"label":"《清史稿·朝鲜列传》：天聪十年改元崇德、国号大清","url":"https://db.history.go.kr/item/compareViewer.do?levelId=jo_024_0010_0020_0130"}]','文皇帝','太宗','清太宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('huang-zhong','黄忠','shu','[]',NULL,NULL,NULL,NULL,NULL,NULL,220,1,NULL,'year','["将领"]','蜀汉名将，定军山斩夏侯渊，助刘备夺取汉中；刘备称汉中王后封其为后将军，蜀汉追谥刚侯；正史未载确切生年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/黄忠"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('huang-zongxi','黄宗羲','ming','[]',NULL,NULL,1610,1,NULL,'year',1695,1,NULL,'year','["思想家"]','明末清初思想家，明夷待访录作者，批判君主专制；《明夷待访录》提出限制君权、学校议政等主张，后世常视为早期政治批判著作。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/黄宗羲"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('huo-guang','霍光','han-west','[]',NULL,NULL,NULL,NULL,NULL,NULL,-68,1,NULL,'year','["政治家"]','汉昭帝辅政大臣，废立昌邑王、拥立宣帝，权倾朝野；昭帝、宣帝时期长期掌政，霍氏家族显贵；其死后家族因谋反案被诛。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/霍光"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('huo-qubing','霍去病','han-west','[]',NULL,NULL,-140,1,NULL,'year',-117,1,NULL,'year','["军事家"]','汉武帝时名将，河西、漠北连破匈奴，封冠军侯；出击河西后为汉朝控制走廊地区，漠北之战封狼居胥；前117年病逝，年仅二十四岁。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/霍去病"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('irinchibal','懿璘质班','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','懿璘质班，元宁宗，元明宗幼子。1332年由权臣拥立时年仅七岁，在位约两个月便病逝；随后元廷迎立其异母兄妥懽帖睦尔。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元宁宗"}]','冲圣嗣孝皇帝','宁宗','元宁宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-ban','班','zhou-east','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周顷王之子，前612—前607年在位。其时周王室已难主导诸侯政治，国势与王畿规模有限；传世史籍对其个人政事记载较少，死后由其弟周定王继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周匡王"}]','匡王',NULL,'周匡王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-bian','扁','zhou-east','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周烈王之弟，前368—前321年在位，是东周在位较久的天子。战国七雄相继称王，周王室失去对诸侯的实际控制；前344年魏惠王在逢泽会诸侯称王，显示天子名号已难独尊。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周显王"}]','显王',NULL,'周显王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-chang','昌','zhou-west','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["西伯","君主"]','商末周部族领袖，周武王之父。受商封为西伯，发展周人势力并经营岐周；周人追尊为文王，其政治与军事基础由武王承接，最终灭商建周。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周文王"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-chonger','重耳','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋文公（重耳），晋献公之子。流亡十九年后即位，城濮之战败楚，践土会盟，列为春秋五霸之一。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋文公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','文公',NULL,'晋文公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-dan','旦','zhou-west','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','周公旦，武王之弟，成王初摄政，东征平三监；摄政七年后还政成王，封鲁国而留居周都；后世将制礼作乐等传统归于周公。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周公旦"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-ding','定','zhou-east','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周显王之子，前320—前315年在位。战国后期秦、齐等国势力迅速增强，周王室日益依附于王畿诸侯；其子周赧王继位后，周室最终在秦国扩张中灭亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周慎靓王"}]','慎靓王',NULL,'周慎靓王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-fa','发','zhou-west','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周文王之子，继承周人势力，联合诸侯伐商。前1046年牧野之战击败商纣王，灭商后建立周王朝并分封宗亲、功臣；不久去世，子成王年幼继位，由周公旦辅政。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周武王"}]','武王',NULL,'周武王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-gai','匄','zhou-east','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周景王之子、周悼王之弟，前519—前477年在位。即位后王子朝据王城作乱，周敬王一度居于成周，后在晋等诸侯支持下平乱；其晚年三家分晋的局面渐趋形成。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周敬王"}]','敬王',NULL,'周敬王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-gongsheng','宫湦','zhou-west','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周宣王之子，前781—前771年在位。废申后及太子宜臼，改立褒姒为后、伯服为太子；申侯联合缯与犬戎攻周，幽王于骊山一带被杀。前771年镐京失陷，西周结束，诸侯随后拥立宜臼为平王并东迁洛邑。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周幽王"}]','幽王',NULL,'周幽王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-gui','贵','zhou-east','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周灵王之子，前544—前520年在位。春秋晚期周王室内政与诸侯势力交错；景王死后，王子朝与王子猛争位，王室陷入内乱，王子猛短暂即位为周悼王。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周景王"}]','景王',NULL,'周景王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-hu','胡','zhou-west','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周夷王之子，前877—前841年在位。任用荣夷公推行“专利”，并令卫巫监视议论，引发国人不满；前841年国人暴动，厉王出奔彘地。此后周、召二公行政（另有共伯和摄政说），史称共和。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周厉王"}]','厉王',NULL,'周厉王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-huqi','胡齐','zhou-east','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周庄王之子，亦作周僖王，前681—前677年在位。其在位时间较短，周王室对诸侯的控制已弱，诸侯间兼并与争盟持续发展；死后由其子周惠王继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周釐王"}]','釐王',NULL,'周釐王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-jian','囏','zhou-west','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周共王之子，前899—前892年在位。传世记载称西北戎狄侵扰加剧，周人承受边患；其元年系年与“天再旦”日食记录有关，古史年代存在不同方案。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周懿王"}]','懿王',NULL,'周懿王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-jiao','骄','zhou-east','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周威烈王之子，前401—前376年在位。周王室已无力约束诸侯，韩、赵、魏持续扩张；三家分晋的政治格局形成后，周天子对诸侯名分的确认更显形式化。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周安王"}]','安王',NULL,'周安王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-jie','介','zhou-east','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周元王之子，前468—前442年在位。周王室衰微之际，晋国韩、赵、魏等卿族逐步掌握实权；周贞定王死后，诸子相继争位，周室政局更加动荡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周贞定王"}]','贞定王',NULL,'周贞定王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-jing','静','zhou-west','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周厉王之子，共和行政结束后于前827年即位，前782年去世。宣王整顿政事、出兵经营边疆，周室一度恢复影响，后世称“宣王中兴”；晚年征戎失利，王室再度显露衰势。其子幽王继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周宣王"}]','宣王',NULL,'周宣王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-ku','夋','wu-di','["帝喾","高辛","俊"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','帝喾高辛氏，黄帝曾孙。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/帝喾"}]',NULL,NULL,'帝喾','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-lang','阆','zhou-east','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周釐王之子，前676—前652年在位。即位初年宠信王子颓，引发王子颓之乱；郑、虢等国出兵平乱后复位。其后周室仍依赖诸侯援助，王权难复西周旧势。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周惠王"}]','惠王',NULL,'周惠王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-lin','林','zhou-east','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周平王之孙，因父早逝继位，前719—前697年在位。试图收回郑庄公的王室卿士职权，引发周郑交恶；前707年亲率诸侯伐郑，在繻葛战败并受伤，王室威信进一步受损。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周桓王"}]','桓王',NULL,'周桓王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-man','满','zhou-west','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周昭王之子，前976—前923年在位，是西周在位较久的天子之一。传世记载称其曾西巡并与西北诸部交往，也记有征徐、会合诸侯等事；《穆天子传》保存了相关西行叙事，但其内容兼有传说成分。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周穆王"}]','穆王',NULL,'周穆王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-meng','猛','zhou-east','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周景王之子，前520年短暂即位为王，谥悼王。景王死后，王子朝与王子猛争位；悼王在位数月即死，王位由其弟周敬王继承，王子朝之乱仍持续多年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周悼王"}]','悼王',NULL,'周悼王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-pifang','辟方','zhou-west','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周共王之弟，前891—前886年在位，越过懿王一系继位。其时秦人先祖非子为周室养马有功，孝王封其于秦邑，令其延续嬴姓祭祀，是秦国兴起的重要早期背景。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周孝王"}]','孝王',NULL,'周孝王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-quji','去疾','zhou-east','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周贞定王之子，前441年继位为周哀王，仅三个月即被弟叔袭杀。《史记·周本纪》记其短暂在位，是东周王室继承危机加深的表现。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周哀王"}]','哀王',NULL,'周哀王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-ren','仁','zhou-east','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周敬王之子，前476—前469年在位，处于春秋战国之交。此时晋国卿族势力坐大，诸侯兼并加剧；周室政治地位持续下降，史籍对其个人政事少有详载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周元王"}]','元王',NULL,'周元王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-renchen','壬臣','zhou-east','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周襄王之子，前618—前613年在位。继位时东周王室财力与领地有限，诸侯争霸的政治格局已成；在位期间史事记载不多，死后由其子周匡王继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周顷王"}]','顷王',NULL,'周顷王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-shi','奭','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，名奭，西周初年重臣，燕国始封君。周武王灭商后受封于北燕，留在周王室辅政，由其子就封；成王时位列三公，主治陕以西。后世以《甘棠》传颂其治绩，具体封君起讫年代失考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕召公"},{"label":"《史记·燕召公世家》","url":"https://zh.wikisource.org/zh-hans/史記/卷034"},{"label":"河南博物院：燕侯旨鼎","url":"https://www.chnmus.net/sitesources/hnsbwy/page_pc/clzl/zlhg/dszhzgdwh/debfzmds/article301959f6691644fd9661d4e7ed7e351f.html"}]','召公',NULL,'燕召公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-shu','叔','zhou-east','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周贞定王之子，前441年杀兄周哀王而立，称周思王；在位五个月，又被弟嵬所杀。此后嵬即位为周考王，王室短期内连续发生弑立。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周思王"}]','思王',NULL,'周思王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-shuyu','虞','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','唐叔虞（虞），周成王弟，初封于唐，后改国号晋，为晋国始封君。桐叶封弟典故即指其事。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/唐叔虞"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]',NULL,NULL,'唐叔虞','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-song','诵','zhou-west','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周武王之子，西周第二代天子，前1042—前1021年在位。即位初年由周公旦摄政，管叔、蔡叔与武庚叛乱，后由周公东征平定；亲政后营建雒邑、分封诸侯，巩固周在东方的统治。其子康王继位，二王时期后世称“成康之治”。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周成王"}]','成王',NULL,'周成王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-tuo','佗','zhou-east','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周桓王之子，前696—前682年在位。庄王三年，周公黑肩谋立王子克，事泄后被诛，王子克出奔，王室内部政争暂告平息；其子周釐王继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周庄王"}]','庄王',NULL,'周庄王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-wei','嵬','zhou-east','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周思王之弟，前440—前426年在位。此前周哀王、周思王相继被杀，考王在王室内乱后继位；据《史记·周本纪》，考王封其弟于河南，是东周王畿分裂为西周国的重要背景。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周考王"}]','考王',NULL,'周考王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-wu','午','zhou-east','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周考王之子，前425—前402年在位。前403年册命韩、赵、魏为诸侯，史称三家分晋；此举确认了诸侯国卿族裂土自立的既成事实，常被视作战国时代的重要标志。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周威烈王"}]','威烈王',NULL,'周威烈王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-xi','喜','zhou-east','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周安王之子，前375—前369年在位。战国诸侯兼并加剧，周王室仅保有洛邑周边王畿，政治影响日益有限；传世记载主要着眼于诸侯兴替，其个人事迹不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周烈王"}]','烈王',NULL,'周烈王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-xia','瑕','zhou-west','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周康王之子，前995—前977年在位。史籍记其多次南征荆楚；《竹书纪年》及后世注引记载其南征渡汉水后未能返回，具体死因说法不一。其子穆王继位，昭王时期常被视作周势转衰的开端。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周昭王"}]','昭王',NULL,'周昭王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-xiaolan','纪晓岚','qing','[]',NULL,NULL,1724,1,NULL,'year',1805,1,NULL,'year','["文学家","政治家"]','清代学者，四库全书总纂官，阅微草堂笔记作者；奉命主持《四库全书》编纂，另著笔记小说《阅微草堂笔记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/纪晓岚"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-xie','燮','zhou-west','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周孝王之后继位，前885—前878年在位。关于其个人政事，传世记载较少；《史记·周本纪》记周室此时衰微、诸侯渐强。其后厉王继位，周王室与诸侯关系继续紧张。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周夷王"}]','夷王',NULL,'周夷王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-xiexin','泄心','zhou-east','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周简王之子，前571—前545年在位。其时晋、楚长期争夺诸侯，周王室影响力有限；太子晋早逝，王子贵继位，是为周景王。传世记载还保留了太子晋以直谏闻名的故事。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周灵王"}]','灵王',NULL,'周灵王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-xuanyuan','轩辕','wu-di','["黄帝","轩辕","有熊"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','黄帝轩辕氏，《史记·五帝本纪》五帝之首。阪泉、涿鹿传说。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/黄帝"}]',NULL,NULL,'黄帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-yan','延','zhou-east','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周慎靓王之子，东周末代天子，前314—前256年在位。王室分居西周国、东周国，赧王曾迁居西周国并合纵攻秦，未能扭转局势；前256年秦取九鼎、灭西周，赧王卒，周王朝结束。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周赧王"}]','赧王',NULL,'周赧王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-yi','夷','zhou-east','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周定王之子，前585—前572年在位。春秋中期诸侯会盟与晋楚争霸仍是政治主轴，周王室主要维持礼制与名分；现存史籍关于其个人政事记载有限。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周简王"}]','简王',NULL,'周简王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-yihu','繄扈','zhou-west','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周穆王之子，前922—前900年在位。其时西周王室仍维持对诸侯的统治，但传世史籍关于具体政事记载不多；共王之后，王位由其子懿王继承。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周共王"}]','共王',NULL,'周共王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-yijiu','宜臼','zhou-east','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周幽王之子，申侯等拥立为王，与虢公翰所立的周携王并立。前770年东迁洛邑，后世奉其为东周正统；在位至前720年，周室自此以洛邑为中心，王权与领土均较西周大幅收缩。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周平王"}]','平王',NULL,'周平王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-yu','瑜','zhou-east','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周匡王之弟，前606—前586年在位。楚庄王北上问鼎时，王孙满以九鼎象征周室天命，拒绝楚王窥周之意；此事显示周王室名义地位尚存，而实际力量已不及强国。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周定王"}]','定王',NULL,'周定王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-yuchen','余臣','zhou-east','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周携王（携惠王），幽王弟；虢公翰等拥立于携，与平王并立；前750年晋文侯杀之。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周携王"}]','携王',NULL,'周携王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-zhao','钊','zhou-west','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周成王之子，前1020—前996年在位。承接成王时期的政局，延续分封与礼制秩序；《史记》称成康之际天下安宁。其子昭王继位，周王室在昭王时期开始面对南方军事行动与统治压力。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周康王"}]','康王',NULL,'周康王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-zheng','郑','zhou-east','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周惠王之子，前651—前619年在位。王子带之乱中被迫出奔，后由晋文公出兵护送复位；周襄王以河阳之会召见诸侯，反映王室权威已须借助霸主维系。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周襄王"}]','襄王',NULL,'周襄王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-zhi','挚','wu-di','["帝挚","挚"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','帝挚，帝喾子；立不善，放勋代之。《帝王世纪》在位九年，史记过渡人物。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/帝挚"}]',NULL,NULL,'挚','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-zhuanxu','颛顼','wu-di','["颛顼","高阳"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','帝颛顼高阳氏，黄帝孙。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/颛顼"}]',NULL,NULL,'颛顼','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-zi','箕子','shang','["胥余"]','子',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家","宗室"]','商末宗室，帝辛诸父或庶兄。传说谏纣被囚，武王克商后访之，后走朝鲜。生卒年不可考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/箕子"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jia-nanfeng','贾南风','jin-west','[]',NULL,NULL,257,1,NULL,'year',300,1,NULL,'year','["皇后","政治家"]','西晋皇后，出身贾氏，晋惠帝司马衷之妻。惠帝即位后长期干预朝政，先后排斥外戚与政敌；元康年间杀太子司马遹，引发宫廷冲突，后被赵王司马伦废杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/贾南风"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jiang-dai','贷','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,-379,1,NULL,'year','["君主"]','齐康公（姜贷），姜齐末代。前404年继宣公；前391年田和放逐于海上，姜齐在齐君位止。前379年卒，姜太公之祀绝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐康公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"}]','康公',NULL,'齐康公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jiang-guangnai','蒋光鼐','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','国民革命军将领，淞沪抗战期间任第十九路军总指挥，与蔡廷锴等指挥上海守军抵抗日军进攻。','[{"label":"上海市民政局：是谁打响“一·二八”淞沪抗战第一枪","url":"https://mzj.sh.gov.cn/lnb-wsws/20220207/97fe1737b42c42ad93b2c426450660f1.html"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jiang-jieshi','蒋介石','roc','["蒋中正"]',NULL,NULL,1887,10,NULL,'month',1975,4,NULL,'month','["军事家","政治家"]','蒋介石是国民革命军主要领导人，曾任黄埔军校校长并主持北伐。1928年后多次担任南京国民政府主席，抗日战争期间任军事与政府领导职务，1948年当选行宪后首任总统；1949年中央政府迁台后继续执政，1975年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/蒋介石"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jiang-jingguo','蒋经国','roc','[]',NULL,NULL,1910,4,NULL,'month',1988,1,NULL,'year','["政治家"]','蒋经国长期参与国民党与政府事务，曾任行政院院长，1978年继任总统。其任内推动十大建设、扩大本地人才参与，并于1987年宣布解除戒严、开放党禁报禁及赴大陆探亲；1988年去世，由李登辉继任。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/蒋经国"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jiang-qing','江青','prc','[]',NULL,NULL,1914,3,NULL,'month',1991,5,NULL,'month','["政治家"]','毛泽东夫人，文化大革命中中央文革小组成员；1976年10月被捕，后以林彪、江青反革命集团案受审。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/江青"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jiang-shinian','石年','san-huang','["神农","炎帝","神农氏"]','姜',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','炎帝神农氏，司马贞《三皇本纪》三皇末位。尝百草、教稼穑。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/神农氏"}]',NULL,NULL,'神农','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jiang-xiaobai','小白','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐桓公（小白），僖公之子，前685–前643年在位。任用管仲改革，尊王攘夷，九合诸侯，为春秋五霸之首。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐桓公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"},{"label":"《春秋左氏传·僖公》","url":"https://zh.wikisource.org/wiki/春秋左氏傳/僖公"},{"label":"春秋鲁国历法复原（据张培瑜《中国古代历法》）","url":"https://ytliu0.github.io/ChineseCalendar/chunqiu_simp.html"}]','桓公',NULL,'齐桓公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jiang-zemin','江泽民','prc','[]',NULL,NULL,1926,8,NULL,'month',2022,11,NULL,'month','["政治家"]','1993年3月27日当选国家主席，1998年连任，至2003年3月15日卸任。此前1989年起任中共中央总书记。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/江泽民"}]',NULL,NULL,'国家主席','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jianzhen','鉴真','tang','[]',NULL,NULL,688,1,NULL,'year',763,1,NULL,'year','["高僧"]','唐代律宗高僧，俗姓淳于，扬州江阳人。受日本僧人邀请，历经多次失败后于753年东渡成功，在日本传戒、建寺并传播佛教戒律与唐代文化。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鉴真"}]',NULL,NULL,NULL,'[]');
