INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r12','成师','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','曲沃桓叔（成师），穆侯少子，曲沃第一代君主，前744–前731年在位。封于曲沃，渐与晋都翼城抗衡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曲沃桓叔"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]',NULL,NULL,'曲沃桓叔','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r13','平','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋孝侯（平），昭侯之子，前739–前724年在位。被曲沃庄伯派人刺杀，曲沃代翼之争加剧。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋孝侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','孝侯',NULL,'晋孝侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r14','鱓','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','曲沃庄伯（鱓），桓叔之子，前730–前716年在位。弑孝侯，晋鄂侯出兵反击未成。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曲沃庄伯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]',NULL,NULL,'曲沃庄伯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r15','却','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋鄂侯（却），孝侯之弟，前723–前718年在位。连年抵御曲沃庄伯，终为庄伯所弑。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋鄂侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','鄂侯',NULL,'晋鄂侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r16','光','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋哀侯（光），鄂侯之子，前717–前709年在位。为曲沃武公派人刺杀于宫阙之下。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋哀侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','哀侯',NULL,'晋哀侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r17','称','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，曲沃庄伯之子，名称。前715年继父为曲沃君，延续曲沃与翼城公室的争位；前678年灭晋侯缗、并有晋地，受周王册命为晋君，前677年去世，子诡诸继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曲沃武公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"},{"label":"《左传·庄公十六年》","url":"https://ctext.org/chun-qiu-zuo-zhuan/zhuang-gong-shi-liu-nian/zhs"}]','武公',NULL,'曲沃武公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r18','？','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，哀侯之子，史称小子侯，个人名失载。前708年继位，前705年为曲沃武公所杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋小子侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','小子侯',NULL,'晋小子侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r19','缗','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，名缗，晋侯。曲沃武公攻杀小子侯后，晋人立哀侯之弟于翼，是为缗；前678年为曲沃武公所灭，曲沃并晋。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/缗"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"},{"label":"《左传·庄公十六年》","url":"https://ctext.org/chun-qiu-zuo-zhuan/zhuang-gong-shi-liu-nian/zhs"}]',NULL,NULL,'缗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r2','宁族','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，燮之子，名宁族，谥武侯。继父燮为晋君；其后由成侯服人继位。传世文献对其事迹与在位年代记载有限。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋武侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','武侯',NULL,'晋武侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r20','诡诸','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋献公（诡诸），曲沃武公之子，前676–前651年在位。灭桓庄之族、骊姬之乱，并国十七服国三十八。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋献公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','献公',NULL,'晋献公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r21','夷吾','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋惠公（夷吾），献公之子，骊姬所生，前650–前637年在位。靠秦穆公回国即位，后与秦战于韩失国。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋惠公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','惠公',NULL,'晋惠公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r22','圉','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋怀公（圉），惠公之子，前637年在位。趁重耳在秦欲继位，秦送重耳回国，怀公被杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋怀公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','怀公',NULL,'晋怀公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r24','欢','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋襄公（欢），文公之子，前627–前621年在位。破秦救周，殽山败秦师，维持晋国霸业。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋襄公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','襄公',NULL,'晋襄公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r25','夷皋','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋灵公（夷皋），襄公之子，前620–前607年在位。荒淫用佞，赵盾屡谏不果，后为赵穿所弑。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋灵公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','灵公',NULL,'晋灵公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r26','黑臀','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋成公（黑臀），文公少母弟，前606–前600年在位。灵公被杀后赵氏拥立，寻讨弑灵公之罪。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋成公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','成公',NULL,'晋成公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r27','据','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋景公（据），成公之子，前599–前581年在位。灭赵氏，邲之战败楚，但六卿势力日盛。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋景公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','景公',NULL,'晋景公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r28','寿曼','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋厉公（寿曼），景公之子，前580–前573年在位。欲集权削六卿，为栾书、中行氏弑杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋厉公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','厉公',NULL,'晋厉公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r29','周','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋悼公（周），襄公曾孙，前572–前558年在位。年少即位却整饬六卿，九合诸侯，晋国复振。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋悼公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','悼公',NULL,'晋悼公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r3','服人','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，名服人，承袭武侯为晋君。传世文献主要保存其世系，事迹与具体在位年代失考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋成侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','成侯',NULL,'晋成侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r30','彪','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋平公（彪），悼公之子，前557–前532年在位。会诸侯于平丘，又弭兵于宋，霸业犹存。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋平公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','平公',NULL,'晋平公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r31','夷','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋昭公（夷），平公之子，前531–前526年在位。六卿专权加剧，昭公终死于饥贫。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋昭公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','昭公',NULL,'晋昭公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r32','弃疾','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋顷公（弃疾），昭公之子，前525–前512年在位。诛伯昏咎等大夫，加速六卿兼并。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋顷公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','顷公',NULL,'晋顷公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r33','午','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋定公（午），顷公之子，前511–前475年在位。赵襄子灭智氏，前453年韩赵魏共灭智伯，三家分晋前奏。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋定公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','定公',NULL,'晋定公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r34','凿','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋出公（凿），定公之子，前474–前452年在位。欲讨伐韩赵魏反被逼迁，死于齐。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋出公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','出公',NULL,'晋出公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r35','骄','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋哀公（骄），出公之后，前451–前434年在位。韩赵魏瓜分晋剩余公室土地，君主名存实亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋哀公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','哀公',NULL,'晋哀公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r36','柳','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋幽公（柳），哀公之子，前433–前416年在位。正室地位为赵氏所废，政权益为傀儡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋幽公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','幽公',NULL,'晋幽公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r37','止','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋烈公（止），幽公之后，前415–前389年在位。三家分晋已成定局，烈公仅守附庸之位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋烈公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','烈公',NULL,'晋烈公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r38','颀','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋孝公（颀），烈公之后，前388–前357年在位。魏惠王会诸侯朝天子，孝公仅为陪臣。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋孝公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','孝公',NULL,'晋孝公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r39','俱酒','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋静公（俱酒），孝公之子，前356–前349年在位。三家废晋静公，晋国六卿时代终结。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋静公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','静公',NULL,'晋静公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r4','福','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，名福，成侯之子，继位为晋君。北赵晋侯墓地及相关铭文研究为其名号与年代提供线索；传统编年记其卒于前859年，继位年份失考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋厉侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','厉侯',NULL,'晋厉侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r5','宜臼','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋靖侯（宜臼），厉侯之子，前858–前841年在位。在位末年周厉王出奔，史称共和。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋靖侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','靖侯',NULL,'晋靖侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r6','司徒','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋釐侯（司徒），靖侯之子，前840–前823年在位。西周晋国君主，史书记载有限。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋釐侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','釐侯',NULL,'晋釐侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r7','籍','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋献侯（籍），釐侯之子，前822–前812年在位。西周晋国世系君主，史书记载有限。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋献侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','献侯',NULL,'晋献侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r8','费','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋穆侯（费），献侯之子，前811–前785年在位。生太子仇与少子成师，酿成日后曲沃之乱。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋穆侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','穆侯',NULL,'晋穆侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r9','？','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，穆侯之弟，谥殇叔，个人名失载。穆侯死后取代太子仇为君；前781年文侯仇复位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋殇叔"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','殇叔',NULL,'晋殇叔','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-xi-qi','奚齐','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋献公与骊姬之子。献公病重时受命由荀息辅佐；献公死后，荀息拥立他继位，前651年在献公丧所被里克杀害，未能逾年。','[{"label":"《左传·僖公九年》","url":"https://ctext.org/chun-qiu-zuo-zhuan/xi-gong-jiu-nian/zhs"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]',NULL,NULL,'奚齐','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-zhuo-zi','卓子','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋献公之子。奚齐被杀后，荀息拥立公子卓以完成献公安葬；前651年周历十一月为里克所杀，荀息亦死。史籍未载其独立谥号。','[{"label":"《左传·僖公九年》","url":"https://ctext.org/chun-qiu-zuo-zhuan/xi-gong-jiu-nian/zhs"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]',NULL,NULL,'卓子','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jing-ke','荆轲','yan-chunqiu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["刺客"]','战国末卫国人，后游历燕地，受燕太子丹礼遇。前227年奉命携督亢地图入秦，行刺秦王政未遂而死；相关叙事见《史记·刺客列传》，后世广泛传为荆轲刺秦王。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/荆轲"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ju-r1','庶其','ju-chunqiu','[]','己',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','莒纪公（庶其），前615–前609年在位。偏爱少子季佗、慢待太子仆；仆杀己自立为厉公（《左传·文公十八年》）。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/莒纪公"}]','纪公',NULL,'莒纪公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ju-r1b','季佗','ju-chunqiu','[]','己',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','莒厉公（季佗），纪公之子，弑父自立，前608–前580年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/莒厉公"}]','厉公',NULL,'莒厉公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ju-r2','朱','ju-chunqiu','[]','己',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','莒渠丘公（朱），前579–前577年在位。疑为厉公之子，史载甚略。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/莒渠丘公"}]','渠丘公',NULL,'莒渠丘公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ju-r3','密州','ju-chunqiu','[]','己',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','莒犂比公（密州），前576–前542年在位。据《左传》称其「虐」、好争战，为莒国最活跃时期；死后莒渐衰。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/莒犂比公"}]','犂比公',NULL,'莒犂比公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ju-r4','舆','ju-chunqiu','[]','己',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','莒子舆（展舆），犂比公子，前541年在位仅一年。犂比公暴虐时先被立为太子，终短暂即位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/莒子舆"}]',NULL,NULL,'子舆','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ju-r5','去疾','ju-chunqiu','[]','己',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','莒著丘公（去疾），犂比公子，前540–前528年在位。著丘公卒后，子郊公狂与弟庚舆争立，引发内乱。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/莒著丘公"}]','著丘公',NULL,'莒著丘公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ju-r6','庚舆','ju-chunqiu','[]','己',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','莒共公（庚舆），犂比公子，好铸剑以人试刃，暴虐失国，前527–前519年在位。国人逐之，迎郊公狂复位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/莒共公"}]','共公',NULL,'莒共公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ju-r7','狂','ju-chunqiu','[]','己',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','莒郊公（狂），著丘公子，两度在位（前528年数月、前518–前481年）。柱厉叔知其不遇而去海上，后返国殉之；前481年卒。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/莒郊公"}]','郊公',NULL,'莒郊公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('juqu-mengxun','沮渠蒙逊','liang-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','卢水胡首领，397年参与反吕建北凉，后逐段业掌权；以张掖为中心扩展至河西大部，称河西王，与后秦、南凉等周旋，433年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/沮渠蒙逊"}]','武宣王',NULL,'北凉武宣王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('juqu-mujian','沮渠牧犍','liang-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','沮渠蒙逊之子，433年继位；北魏太武帝于439年攻陷姑臧，沮渠牧犍出降并被迁往平城，北凉河西政权结束。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/沮渠牧犍"},{"label":"《资治通鉴》卷122","url":"https://zh.wikisource.org/wiki/資治通鑑/卷122"}]',NULL,NULL,'北凉末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('kang-youwei','康有为','qing','[]',NULL,NULL,1858,1,NULL,'year',1927,1,NULL,'year','["政治家","思想家"]','晚清思想家、政治人物，初名祖诒，字广厦，广东南海人。甲午战后发起公车上书，组织强学会并推动维新变法；戊戌政变后流亡海外，晚年仍主张保皇。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/康有为"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('kasa-kehan','葛萨','huihu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["可汗","君主"]','亦称㕎馺特勤，篡位，唐封㕎馺可汗，840年牙帐陷落时被杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/㕎馺可汗"}]',NULL,NULL,'㕎馺可汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('khayishan','海山','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','海山，元武宗，长期在北方统兵，元成宗去世后在军队与蒙古宗王支持下即位。他以封赏和扩张官僚体系巩固新政权，并与弟爱育黎拔力八达约定兄终弟及；其朝财政开支扩大，纸币贬值加剧。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元武宗"}]','仁惠宣孝皇帝','武宗','元武宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('khoshila','和世㻋','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','和世㻋，元明宗，元武宗长子，曾长期流寓漠北。1328年在上都即位，次年与弟图帖睦尔会合并恢复兄弟继位安排；不久在赴大都途中去世，史籍记其死于宴会之后，死因说法不一。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/和世㻋"}]','翼献景孝皇帝','明宗','元明宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('kong-qiu','丘','zhou-east','[]','子','孔',-551,1,NULL,'year',-479,1,NULL,'year','["思想家"]','孔子，儒家开创者，传统生卒前551–前479年；孔子晚年整理文献、教授弟子；门人记录其言行形成《论语》，成为儒家经典。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孔子"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('kou-zhun','寇准','song-north','[]',NULL,NULL,961,1,NULL,'year',1023,1,NULL,'year','["政治家"]','北宋名相，真宗朝力主御驾亲征，促成澶渊之盟；澶州议和后因政争被贬，晚年谪居雷州，身后获赠中书令、谥忠愍。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/寇准"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('kuailv','夸吕','tuyuhun','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','吐谷浑可汗，与隋、唐往来。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/夸吕"}]',NULL,NULL,'可汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lai-qingde','赖清德','roc','[]',NULL,NULL,1959,10,NULL,'month',NULL,NULL,NULL,NULL,'["政治家"]','赖清德曾任立法委员、台南市长、行政院院长及副总统，2024年当选并就任中华民国总统。其任期延续于蔡英文之后，面对两岸关系、能源与产业转型等议题。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赖清德"},{"label":"交接日期复核来源","url":"https://www.president.gov.tw/News/28428"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lan-yu','蓝玉','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,1393,1,NULL,'year','["军事家"]','明初大将，捕鱼儿海大破北元，后涉党案被诛；洪武二十一年捕鱼儿海战俘获北元皇子与大量军民，后因蓝玉案被杀并株连多人。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/蓝玉"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lang-darma','朗达玛','tubo','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','吐蕃末代赞普，禁佛，842年被杀，帝国分裂。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朗达玛"}]',NULL,NULL,'赞普','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lao-zi','老子','chu-chunqiu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["思想家"]','春秋末思想家，道家学派重要代表，传统上尊称老子，姓李名耳。相传曾任周守藏室之史，后西出函谷关；《道德经》托名于他，成书与生平年代仍有争议。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/老子"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-ang','李昂','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','唐文宗李昂为穆宗次子，827年即位，曾试图整顿宦官专权并改善朝政。835年他与李训、郑注谋划诛除宦官，事泄后爆发甘露之变，计划失败且大批朝臣被杀；此后文宗受宦官挟制，840年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/唐文宗"}]','元圣昭献孝皇帝','文宗','唐文宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-anquan','李安全','xixia','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','夏仁宗侄、夏襄宗，废黜李纯佑后即位，依靠外戚势力执政。蒙古于1209年大举攻夏，西夏被迫求和并承受持续压力；1211年李遵顼发动政变夺位；在位1206—1211年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李安全"}]','敬穆皇帝','襄宗','夏襄宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-bai','李白','tang','[]',NULL,NULL,701,1,NULL,'year',762,1,NULL,'year','["诗人"]','盛唐诗人，字太白，号青莲居士，生地有争议。曾受唐玄宗召入长安任翰林供奉，后离京漫游；诗歌想象瑰奇、气势奔放，与杜甫并称“李杜”，世称“诗仙”。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李白"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-ban','李班','cheng-han','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','李雄养子，李雄死后于334年继位；因非李氏宗亲且受宗室排斥，在位数月即被李越等杀害，成汉转入李期统治。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李班_(成汉)"}]','哀皇帝',NULL,'成汉哀皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-bian','李昪','tang-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','本名徐知诰，徐温养子，长期掌握杨吴军政。937年迫吴睿帝杨溥禅位，先建齐、后改国号唐，史称南唐；在位时休兵息民、发展江淮经济，传位于子李璟；南唐承接杨吴江淮基业，前期休兵息民，为后来扩张积累资源。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李昪"}]',NULL,'烈祖','南唐烈祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-bingchang','李秉常','xixia','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','夏毅宗之子、夏惠宗，幼年继位后先由梁太后掌政，亲政尝试收回权力时与母后及外戚冲突。宋夏战争反复，梁氏重新控制朝政，他在位期间王权受到外戚牵制；在位1067—1086年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李秉常"}]','昭简皇帝','惠宗','夏惠宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-chen-tang','李忱','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','唐宣宗李忱为宪宗第十三子，846年即位，传统史书以其勤政、节俭和抑制宦官称道，时称大中之治。其间唐廷收复河湟部分地区，国势有所恢复，但藩镇割据和财政、军力困境并未根除。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/唐宣宗"}]','元圣至明成武献文睿智章仁神聪懿道大孝皇帝','宣宗','唐宣宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-chun','李纯','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','唐宪宗李纯为顺宗长子，805年即位，重用裴度等大臣并整军备、削平若干强藩，史称元和中兴。河北藩镇仍未完全受控，中央与地方的矛盾延续；820年宪宗在宫中暴死，史载与宦官有关。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/唐宪宗"}]','昭文章武大圣至神孝皇帝','宪宗','唐宪宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-chunyou','李纯佑','xixia','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','夏仁宗之子、夏桓宗，承接相对稳定的西夏政局。其在位后期蒙古势力兴起并向西北扩张，1206年被李安全废黜；在位1193—1206年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李纯佑"}]','昭简皇帝','桓宗','夏桓宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-conghou','李从厚','tang-hou','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','李嗣源第三子，明宗死后继位。即位后试图调动李从珂、石敬瑭等藩镇将领，引发政变；在位数月即被李从珂废黜，后被杀；废立反映后唐皇位依赖藩镇军队，中央难以约束握兵将领。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李从厚"}]','闵帝',NULL,'后唐闵帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-congke','李从珂','tang-hou','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','李嗣源养子，原镇凤翔。934年起兵推翻闵帝李从厚后即位，面对石敬瑭在河东反叛并向契丹求援；契丹与晋军攻入洛阳时自焚，后唐灭亡；后唐覆亡后契丹深入中原，北方王朝对边疆军事援助的依赖更加突出。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李从珂"}]',NULL,NULL,'后唐末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-cui','李漼','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','唐懿宗李漼为宣宗长子，859年即位。其朝廷多次对南诏用兵而失利，财政与边防压力加重；晚年黄巢起义爆发，动摇唐朝统治基础，懿宗于873年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/唐懿宗"}]','昭圣恭惠孝皇帝','懿宗','唐懿宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-cunxu','李存勖','tang-hou','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','李克用之子，继承河东晋王与沙陀军事集团。923年称帝建后唐，灭后梁并迁都洛阳；在位后期宠信伶人、用人失当，兵变中被杀，后唐随之进入内乱；灭梁完成李克用以来的复仇目标，但军事胜利未能转化为稳定治理。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李存勖"}]',NULL,'庄宗','后唐庄宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-dan','李旦','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','唐睿宗李旦为高宗与武则天之子，两度即位。684年首次即位后不久被母亲武则天废为皇嗣；710年唐隆政变后复位，翌年传位于太子李隆基，仍以太上皇身份参与政局，至712年正式让出最高权力。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/唐睿宗"}]','玄真大圣大兴孝皇帝','睿宗','唐睿宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-deming','李德明','xixia','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','李继迁之子，继承定难军及党项李氏势力后与北宋、辽朝往来，受宋册封为西平王。其长期避免全面战争并经营党项政权，扩展李氏控制区，为李元昊称帝建国准备条件；在位1004—1032年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李德明"},{"label":"宋史/卷485","url":"https://zh.wikisource.org/wiki/宋史/卷485"}]',NULL,NULL,'西夏王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-denghui','李登辉','roc','[]',NULL,NULL,1923,1,NULL,'year',2020,7,NULL,'month','["政治家"]','李登辉原任副总统，蒋经国去世后继任总统，并于1990年当选。任内推动终止动员戡乱时期、国会全面改选与总统直选，1996年成为首次全民直选产生的总统；2000年政党轮替后卸任。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李登辉"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-dewang','李德旺','xixia','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','李遵顼之子、夏献宗，继位时西夏已承受蒙古长期侵攻。其在位期间尝试联合金朝抵抗蒙古，但战局持续恶化，1226年由李睍继位；在位1223—1226年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李德旺"}]','南平王','献宗','夏献宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-gang','李纲','song-south','[]',NULL,NULL,1083,1,NULL,'year',1140,1,NULL,'year','["政治家","军事家"]','北宋末宰相，力主抗金，靖康之变前后多次起用；靖康年间组织东京防务并反对割地求和，南渡后数度出任宰执。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李纲"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-gao','李暠','liang-xi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','陇西李氏出身，曾依附后凉，400年据敦煌建立西凉；以敦煌为中心经营河西西部、发展屯田，417年去世后由子李歆继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李暠"}]','武昭王',NULL,'西凉武昭王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-heng','李亨','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','唐肃宗李亨为玄宗第三子，安史之乱中于756年在灵武即位，玄宗随后承认其帝位。肃宗依靠郭子仪、李光弼等将领并借回纥兵力收复长安、洛阳；763年叛乱最终平定，但藩镇坐大，中央对地方军政的控制削弱。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/唐肃宗"}]','文明武德大圣大宣孝皇帝','肃宗','唐肃宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-heng-mu','李恒','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','唐穆宗李恒为宪宗第三子，820年即位。朝廷未能延续元和年间的削藩攻势，成德等藩镇再度叛乱，河北局势恶化；穆宗在位期间亦有河朔用兵与宫廷奢游的记载，824年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/唐穆宗"}]','睿圣文惠孝皇帝','穆宗','唐穆宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-hongzhang','李鸿章','qing','[]',NULL,NULL,1823,1,NULL,'year',1901,1,NULL,'year','["政治家","军事家"]','晚清政治家、外交家，字少荃，安徽合肥人。创办淮军并参与洋务运动，任直隶总督、北洋大臣；代表清政府办理多项外交事务并签订《马关条约》《辛丑条约》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李鸿章"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-jing-nantang','李璟','tang-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','李昪长子，943年继位。南唐国力一度强盛，随后发动兼并闽、楚之战，却遭后周进攻并于958年割江北地、去帝号称国主；死后李煜继位；割江北地后南唐由扩张转为守成，对中原称臣取代帝号。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李璟"}]',NULL,'元宗','南唐元宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-jing-tang','李靖','tang','[]',NULL,NULL,571,1,NULL,'year',649,1,NULL,'year','["军事家"]','唐初名将，平定江南、北击突厥，封卫国公；代表战事包括平定萧铣、征讨东突厥与吐谷浑；晚年请辞兵权，著述影响唐代兵学。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李靖"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-jiqian','李继迁','xixia','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','党项拓跋氏后裔，北宋初年起兵反宋，辗转恢复夏州一带势力，并以灵州为重要据点。其子李德明承接其势力，李继迁被追尊为夏太祖，奠定后来西夏建国基础；在位982—1004年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李继迁"}]','光天皇帝','太祖','夏太祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-kuo','李适','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','唐德宗李适为代宗长子，779年即位，任用杨炎推行两税法，以适应均田制和租庸调制瓦解后的财政现实。建中年间试图削弱藩镇，引发四镇之乱与泾原兵变，德宗出逃奉天；此后朝廷在藩镇、宦官与文官之间反复调适。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/唐德宗"}]','神武孝文皇帝','德宗','唐德宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-liangzuo','李谅祚','xixia','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','李元昊之子，夏毅宗，幼年即位，由没藏太后及其兄没藏讹庞辅政。亲政后调整对宋关系并推动制度建设，后来在宫廷政变后由梁氏家族掌权；在位1048—1067年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李谅祚"}]','昭英皇帝','毅宗','夏毅宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-longji','李隆基','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','唐玄宗李隆基为睿宗之子，先参与710年唐隆政变，712年即位。开元年间整饬行政、任用贤臣，唐朝达到鼎盛；天宝后期朝政失衡，755年安禄山起兵，玄宗次年入蜀并传位李亨，唐朝由盛转衰。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/唐玄宗"}]','至道大圣大明孝皇帝','玄宗','唐玄宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-qi','李期','cheng-han','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','李雄之侄，334年杀李班继位；统治期间猜忌宗室、政局动荡，338年被堂兄李寿废黜，后自杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李期"}]',NULL,NULL,'成汉幽公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-qianshun','李乾顺','xixia','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','夏惠宗之子、夏崇宗，幼年即位，梁太后长期摄政，后亲政并维持西夏统治。其五十余年在位横跨宋辽对峙、金朝崛起及金灭辽后格局变化，西夏在此期间延续并巩固其国家制度；在位1086—1139年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李乾顺"}]','康靖皇帝','崇宗','夏崇宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-renxiao','李仁孝','xixia','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','夏崇宗之子、夏仁宗，在位期间整顿典章、尊崇儒学并发展学校与科举制度，推动西夏汉文和党项文字文教。其朝与金、南宋保持相对稳定的外交关系，西夏文化发展达到重要阶段；在位1139—1193年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李仁孝"}]','圣德皇帝','仁宗','夏仁宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-shen','李绅','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["诗人","政治家"]','中唐诗人、官员，字公垂，亳州人。早年写作《悯农》二首，揭示农事艰辛；后历任宰相等职，卷入牛李党争，其政治生涯与诗名常被后世分别评价。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李绅"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-shi','李势','cheng-han','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','李寿之子，343年继位为汉帝；成汉在其统治下衰弱，347年东晋桓温伐蜀时出降，成汉亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李势"},{"label":"《资治通鉴》卷97","url":"https://zh.wikisource.org/wiki/資治通鑑/卷097"}]',NULL,NULL,'成汉末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-shimin','李世民','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','唐太宗李世民为李渊次子，建唐与统一战争中的主要统帅，626年玄武门之变后即位。在位期间整顿政务、任用房玄龄、杜如晦、魏征等，形成以纳谏和制度建设著称的贞观政治，并向西域拓展；其治世成为后世参照。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/唐太宗"}]','文武大圣大广孝皇帝','太宗','唐太宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-shizhen','李时珍','ming','[]',NULL,NULL,1518,1,NULL,'year',1593,1,NULL,'year','["医学家"]','明代医药学家，字东璧，号濒湖，蕲州人。长期搜集药物与民间方剂，考订历代本草，历时约二十七年编成《本草纲目》，系统记载药物、产地与用法。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李时珍"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-shou','李寿','cheng-han','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','李雄堂弟、李骧之子，338年废李期即位；次年改国号为汉，迁都成都，缓和刑政并与东晋通使，343年死后由子李势继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李寿"},{"label":"《晋书》卷七·成帝纪（咸康四年夏四月李寿改国号汉）","url":"https://zh.wikisource.org/zh-hans/晋书/卷007"}]','昭文皇帝','中宗','成汉昭文皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-si','李斯','qin','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','秦相，助嬴政统一，推行郡县、书同文，后因赵高陷害被诛；秦始皇死后与赵高拥立胡亥，最终被构陷，在咸阳受五刑并夷三族。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李斯"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-siyuan','李嗣源','tang-hou','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','李克用养子，沙陀将领，曾助李存勖建立后唐。926年兵变后入洛阳即位，在位时裁减宫廷开支、整顿吏治，史称明宗之治；死后诸子争位，后唐迅速失序；相较庄宗，明宗以节俭和任用旧臣稳定战后政局；继承安排仍留下隐患。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李嗣源"}]',NULL,'明宗','后唐明宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-song','李诵','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','唐顺宗李诵为德宗长子，805年即位。即位后支持王叔文、王伾等推动改革，试图整顿宦官与藩镇势力，史称永贞革新；改革很快受挫，顺宗同年传位李纯，退居太上皇。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/唐顺宗"}]','至德弘道大圣大安孝皇帝','顺宗','唐顺宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-xian','李显','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','唐中宗李显为高宗与武则天之子。683年高宗去世后承统，684年1月3日正式受册为帝，同年2月26日被武则天废黜；705年神龙政变后复位。在第二段统治中，韦后及安乐公主等势力影响朝政，皇权受宫廷政治牵制；710年去世，随后李隆基与太平公主发动政变。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/唐中宗"},{"label":"资治通鉴·卷二〇三","url":"https://zh.wikisource.org/wiki/資治通鑑/卷203"}]','大和大圣大昭孝皇帝','中宗','唐中宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-xian-xixia','李睍','xixia','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','夏献宗之后继位的西夏末帝李睍，蒙古军攻夏期间即位，统治区域迅速收缩。1227年蒙古军攻灭西夏，他出降后被杀，西夏政权终结；在位1226—1227年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李睍"}]',NULL,NULL,'夏末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-xiannian','李先念','prc','[]',NULL,NULL,1909,6,NULL,'month',1992,6,NULL,'month','["政治家"]','1983年6月18日六届全国人大一次会议当选国家主席，为修宪恢复国家主席后的首任，至1988年4月8日卸任。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李先念"}]',NULL,NULL,'国家主席','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-xin','李歆','liang-xi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','李暠之子，417年继位并迁都酒泉；与北凉争战失利，420年兵败被沮渠蒙逊杀害，西凉亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李歆"},{"label":"資治通鑑/卷118","url":"https://zh.wikisource.org/wiki/資治通鑑/卷118"}]',NULL,NULL,'西凉末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-xiong','李雄','cheng-han','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','巴氐李特之子，304年据成都起兵，306年称成都王，建立成汉并据有益州；在位时招纳流民、恢复蜀地秩序，政权由此延续至347年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李雄_(十六国)"}]','武皇帝','太宗','成汉武皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-xiucheng','李秀成','taiping','[]',NULL,NULL,1823,1,NULL,'year',1864,8,NULL,'month','["军事家","政治家"]','太平天国忠王，后期主持军政；同治三年七月初六（1864年8月7日）城破后被俘处死。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李秀成"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-xuan-tang','李儇','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','唐僖宗李儇为懿宗第五子，873年即位时年幼，朝政长期受宦官田令孜影响。黄巢起义军攻入长安后，僖宗两度出奔，后在唐军及地方武装支持下复都；起义虽被镇压，藩镇力量与朝廷失控进一步加深。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/唐僖宗"}]','惠圣恭定孝皇帝','僖宗','唐僖宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-xuanshi','李选侍','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,1627,1,NULL,'year','["后妃"]','明光宗宠妃，光宗死后据乾清宫不肯迁出，引发移宫案；朝臣要求她迁出乾清宫保护皇长子，移宫案成为泰昌、天启之际政争之一。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李选侍"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-yan-tang','李炎','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','唐武宗李炎为穆宗第五子，840年由宦官拥立即位。会昌年间整顿财政、打击佛教寺院经济，并击败回鹘汗国，史称会昌中兴；其灭佛政策波及佛教及其他外来宗教，846年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/唐武宗"}]','至道昭肃孝皇帝','武宗','唐武宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-ye-tang','李晔','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','唐昭宗李晔为懿宗第七子，888年即位，试图恢复皇权，却陷于宦官、藩镇和朱温等势力的争夺。朱温控制朝廷后，904年迫使昭宗迁都洛阳并将其杀害；皇位由其子李柷承继。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/唐昭宗"}]','圣穆景文孝皇帝','昭宗','唐昭宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-yu-nantang','李煜','tang-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','李璟第六子，961年继位，承受后周以来的割地与称臣局面。向宋称臣以保境，975年宋军攻陷金陵后出降，南唐亡；被俘至汴京，后以词作著称；南唐灭亡标志宋朝控制长江以南的重要阶段完成。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李煜"}]',NULL,NULL,'南唐后主','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-yu-tang','李豫','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','唐代宗李豫为肃宗长子，平定安史之乱后于762年即位。在位初年处理战后重建，并面对吐蕃入侵及藩镇割据；朝廷承认部分河北藩镇的既成格局，唐廷此后长期依赖地方节度使与宦官维持统治。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/唐代宗"}]','睿文孝武皇帝','代宗','唐代宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-yuan','李渊','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','唐高祖李渊出身关陇贵族，隋末任太原留守。617年起兵，次年攻入长安并受隋恭帝禅让称帝，建立唐朝；统一战争由其子李世民等继续推进。626年玄武门之变后传位李世民，退居太上皇。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李渊"}]','神尧大圣大光孝皇帝','高祖','唐高祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-yuanhao','李元昊','xixia','[]',NULL,NULL,1003,1,NULL,'year',1048,1,NULL,'year','["皇帝"]','李德明之子，夏景宗，1038年脱离宋朝称帝、定国号大夏，建立西夏。其创制党项文字、改革官制并多次与宋交战，1044年宋夏议和后形成三国鼎立格局；在位1032—1048年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李元昊"},{"label":"宋史/卷485","url":"https://zh.wikisource.org/wiki/宋史/卷485"}]','武烈皇帝','景宗','夏景宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-yuanhong','黎元洪','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','黎元洪原为湖北新军将领，武昌起义后被推为湖北军政府都督。袁世凯死后他先后两度任大总统，任内与段祺瑞围绕参战、国会及内阁权力发生府院之争；第二任期在直皖冲突后结束。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/黎元洪"}]',NULL,NULL,'大总统','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-zhan','李湛','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','唐敬宗李湛为穆宗长子，824年即位，年少而在位短暂，朝政由宦官及近臣影响。827年敬宗在宫中被宦官刘克明等杀害，继位安排引发宫廷政变，皇弟李昂随后即位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/唐敬宗"}]','睿武昭愍孝皇帝','敬宗','唐敬宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-zhi','李治','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','唐高宗李治为太宗第九子，649年继位。前期与长孙无忌等辅政大臣共治，后逐步亲理政务；在位时唐灭百济、高句丽，疆域与对外影响达到高峰。晚年因病，皇后武则天参与决策并掌握朝政，为武周代唐埋下政治背景。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/唐高宗"}]','天皇大圣大弘孝皇帝','高宗','唐高宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-zhu-tang','李柷','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','唐哀帝李柷为昭宗第九子，904年即位时年幼，实权掌握在朱温手中。907年朱温迫使哀帝禅位，唐朝灭亡；李柷被降封为济阴王，后遭杀害。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/唐哀帝"}]','昭宣光烈孝皇帝',NULL,'唐哀帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-zicheng','李自成','dashun','[]',NULL,NULL,1606,9,NULL,'month',1645,5,NULL,'month','["皇帝","起义领袖"]','明末闯王，1644年在西安称帝建大顺，旋克北京，明亡；次年兵败被杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李自成"}]',NULL,NULL,'大顺皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-zongren','李宗仁','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家","政治家"]','李宗仁是桂系将领，抗战期间指挥台儿庄战役，后当选副总统。蒋介石于1949年引退后，他依法代理总统；蒋介石于1950年复行视事，李宗仁随后离开大陆并长期旅居海外。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李宗仁"}]',NULL,NULL,'代总统','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-zunxu','李遵顼','xixia','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','西夏宗室、夏神宗，以政变推翻李安全后即位。蒙古军持续进攻之际，他一度主动伐金以求缓解压力，却使西夏陷入更不利的外交与军事处境，后传位于子李德旺；在位1211—1223年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李遵顼"}]','英武皇帝','神宗','夏神宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lian-po','廉颇','zhao-warring','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','赵国名将，长平战前主将，负荆请罪与蔺相如释怨；赵王中反间计后以赵括代其为将，赵军长平战败；廉颇晚年客居魏、楚。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/廉颇"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liang-qichao','梁启超','qing','[]',NULL,NULL,1873,1,NULL,'year',1929,1,NULL,'year','["政治家","思想家"]','晚清思想家、政治家、新闻人，字卓如，号任公，广东新会人。师从康有为并参与戊戌变法，流亡期间创办报刊、倡导立宪与新民思想；回国后转向学术研究，著述丰富。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/梁启超"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liang-taihou','梁太后','han-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["太后","政治家"]','东汉顺帝皇后梁妠，梁商之女。顺帝死后以皇太后身份临朝，先后拥立冲帝、质帝与桓帝，后归政；质帝实际为其兄梁冀下毒所杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/梁妠"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liang-taihou-xixia','梁太后','xixia','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["后妃","政治家"]','惠宗李秉常之母，两度摄政，主张对宋用兵；她与梁氏外戚掌权期间，西夏多次与宋交战；个人生卒记载有限。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/梁太后"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lin-biao','林彪','prc','[]',NULL,NULL,1907,12,NULL,'month',1971,9,NULL,'month','["军事家","政治家"]','元帅，九大党章曾写为接班人；1971年9月13日乘机出逃，在蒙古温都尔汗坠机身亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/林彪"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lin-sen','林森','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','林森是辛亥革命元老，曾任国民政府委员长（主席）。1931—1943年任主席期间，实际军政决策主要由蒋介石等人掌握；抗日战争期间长期留重庆办公，1943年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/林森"}]',NULL,NULL,'国民政府主席','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lin-xiangru','蔺相如','zhao-warring','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','赵国名臣，完璧归赵、渑池之会，与廉颇将相和；赴秦交涉和氏璧、渑池之会时维护赵国尊严；与廉颇化解嫌隙后被称“将相和”。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/蔺相如"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lin-zexu','林则徐','qing','[]',NULL,NULL,1785,1,NULL,'year',1850,1,NULL,'year','["政治家"]','清代政治家，字元抚，福建侯官人。道光年间任湖广总督、钦差大臣，赴广东查禁鸦片并主持虎门销烟；鸦片战争后被贬，后参与西北边防与新疆治理。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/林则徐"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-ao','刘骜','han-west','[]',NULL,NULL,-51,1,NULL,'year',-7,1,NULL,'year','["皇帝"]','刘骜是元帝之子，继位后外戚王氏势力持续增长，朝政多由外戚与近臣参与。他无子嗣，由侄子刘欣继承皇位；其在位后期的权力结构为王莽掌政创造了条件。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉成帝"}]','孝成皇帝',NULL,'汉成帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-bang','刘邦','han-west','[]',NULL,NULL,-256,1,NULL,'year',-195,1,NULL,'year','["皇帝"]','刘邦出身沛县，秦末起兵反秦，先后与项羽争夺天下；前202年称帝、定都长安，建立汉朝。他平定异姓诸侯王并分封同姓王，确立汉初郡国并行格局。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘邦"},{"label":"漢書/卷001下","url":"https://zh.wikisource.org/wiki/漢書/卷001下"},{"label":"交接日期复核来源","url":"https://en.wikipedia.org/wiki/Liu_Bang"}]','高皇帝','太祖','汉高祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-bao','刘保','han-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘保是安帝与宫人李氏之子，曾被邓氏外戚废为济阴王；安帝死后，宦官迎立他为帝。他恢复皇位后任用宦官，梁氏外戚随后长期掌权，顺帝末年各地灾荒与民变频仍。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉顺帝"}]','孝顺皇帝',NULL,'汉顺帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-bei','刘备','shu','[]',NULL,NULL,161,1,NULL,'year',223,6,NULL,'month','["皇帝"]','汉景帝之子中山靖王刘胜之后，长期辗转于群雄之间，后据有益州。221年在成都称帝、国号汉，史称蜀汉；次年为报关羽之仇伐吴，夷陵之战败后退守永安，223年去世并由刘禅继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘备"}]','昭烈皇帝','烈祖','昭烈帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-bian','刘辩','han-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘辩是灵帝与何皇后之子，灵帝去世后由大将军何进等拥立为帝。宦官诛杀何进后，董卓入京并废刘辩为弘农王，改立其弟刘协；刘辩不久被董卓杀害。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉少帝刘辩"}]',NULL,NULL,'汉后少帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-bin','刘玢','han-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘龑次子，刘龑死后继位。统治仅一年多即被弟刘晟与党羽发动政变杀害，南汉皇位由刘晟承接；皇位更迭迅速，宗室争权恶化宫廷安全与政局稳定。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘玢"}]','殇帝',NULL,'南汉殇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-bing','刘炳','han-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘炳是顺帝之子，幼年即位，朝政由梁太后及其兄梁冀把持。他在位仅数月便去世，继位人选遂落入梁冀控制之下，东汉皇位此后长期受外戚干预。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉冲帝"}]','孝冲皇帝',NULL,'汉冲帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-can','刘粲','han-zhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘聪之子，318年继位；外戚靳准发动政变，刘粲即位不久即被杀，汉赵一度分裂，后由刘曜收拾局面。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘粲"}]',NULL,NULL,'汉赵末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-chang','刘鋹','han-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘晟之子，958年继位时年幼，朝政由宦官与近臣把持。面对北宋南征未能组织有效抵抗，971年广州失守后出降，南汉亡；南汉归宋后，岭南重新纳入中原王朝统治。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘鋹"}]',NULL,NULL,'南汉末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-che','刘彻','han-west','[]',NULL,NULL,-156,1,NULL,'year',-87,1,NULL,'year','["皇帝"]','刘彻为景帝之子，继位后加强中央集权，推行推恩令、盐铁专卖等措施，并以儒学确立国家礼制核心。他多次对匈奴用兵、派遣张骞出使西域，扩大汉朝影响；长期战争也加重财政与民间负担。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉武帝"}]','孝武皇帝','世宗','汉武帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-chengyou','刘承祐','han-hou','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘知远之子，948年继位时年幼，由权臣与武将辅政。950年疑忌枢密使郭威而诛其家，郭威起兵攻入开封；刘承祐在逃亡中被杀，后汉亡；军人拥立与废立成为中原王朝更替的重要方式，后汉由此迅速结束。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘承祐"}]','隐帝',NULL,'后汉隐帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-cong','刘聪','han-zhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘渊第四子，310年杀刘和夺位；在位期间扩张汉赵，311年攻陷洛阳俘晋怀帝、316年迫降晋愍帝，后期朝政受外戚与近臣干预。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘聪"}]','昭武皇帝',NULL,'汉赵昭武皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-fuling','刘弗陵','han-west','[]',NULL,NULL,-94,1,NULL,'year',-74,1,NULL,'year','["皇帝"]','刘弗陵是武帝幼子，八岁即位，霍光等大臣辅政。昭帝时期整顿武帝晚年政策、减轻赋役，并在对匈奴关系上取得进展；其统治与继位的宣帝时期常合称“昭宣之治”。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉昭帝"}]','孝昭皇帝',NULL,'汉昭帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-futong','刘福通','song-han','[]',NULL,NULL,NULL,NULL,NULL,NULL,1363,1,NULL,'year','["起义领袖"]','红巾军首领，拥立韩林儿为小明王，三路北伐；1363年安丰之战战死。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘福通"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-gong','刘？','han-west','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','西汉前少帝，名不详。汉惠帝去世后幼年即位，吕太后临朝称制。据《史记》，得知生母被杀、自己并非张皇后亲子后出怨言，被吕太后幽禁。前184年被废黜并杀害，吕太后另立常山王刘弘为帝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/西汉前少帝"},{"label":"《史记·吕太后本纪》","url":"https://zh.wikisource.org/wiki/史記/卷009"},{"label":"《汉书·高后纪》","url":"https://zh.wikisource.org/wiki/漢書/卷003"}]',NULL,NULL,'前少帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-he','刘贺','han-west','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘贺是武帝之孙、昌邑王，昭帝去世后由霍光等迎立为帝。因即位后行为失当及与辅政大臣冲突，在位二十七日即被废，返回封国，后世称汉废帝或海昏侯。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘贺"}]','海昏侯',NULL,'汉废帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-he-zhao','刘和','han-zhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘渊嫡长子，310年继位；即位后欲清除掌兵的兄弟，旋被刘聪发动政变杀死，在位仅七日。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘和"}]',NULL,NULL,'汉赵皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-heng','刘恒','han-west','[]',NULL,NULL,-203,1,NULL,'year',-157,1,NULL,'year','["皇帝"]','刘恒是刘邦之子，原为代王，在吕氏集团覆灭后由功臣迎立为帝。文帝崇尚俭约、减轻赋役并放宽刑罚，与景帝共同开创“文景之治”，为汉朝积累财力与社会稳定。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉文帝"}]','孝文皇帝','太宗','汉文帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-hong','刘宏','han-east','[]',NULL,NULL,157,1,NULL,'year',189,1,NULL,'year','["皇帝"]','刘宏是章帝玄孙，桓帝死后由窦太后及其父窦武等拥立。灵帝时期宦官干政、卖官与党争加深，184年黄巾起事爆发；为应对战乱而扩张的州牧与地方军力，推动中央权威瓦解。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉灵帝"}]','孝灵皇帝',NULL,'汉灵帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-hong-shao','刘弘','han-west','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘弘是吕太后去世后由吕氏拥立的后少帝，延续惠帝一系名义上的皇位。周勃、陈平等诛灭诸吕后废黜刘弘，迎立刘邦之子代王刘恒，汉廷由此转入文帝一系。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘弘"}]',NULL,NULL,'汉后少帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-hu','刘祜','han-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘祜是章帝之孙、清河孝王刘庆之子，由邓太后选立为帝。邓太后去世后他亲政，重新启用宦官并处置邓氏；其晚年西羌战事与宫廷权力斗争加重。安帝死后，北乡侯刘懿即位；刘懿病逝后，济阴王刘保在宦官政变中即位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉安帝"}]','孝安皇帝',NULL,'汉安帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-ji','刘基','ming','[]',NULL,NULL,1311,1,NULL,'year',1375,1,NULL,'year','["政治家","军事家"]','明初政治家、文学家，字伯温，浙江青田人。元末出仕后归附朱元璋，参与谋划统一战争及建国制度；洪武年间封诚意伯，著有《郁离子》及诗文集。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘基"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-jiyuan','刘继元','han-bei','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘钧养子，继刘继恩被杀后即位。北汉在北宋持续围攻下日益困窘，979年宋太宗亲征太原，刘继元出降，北汉亡，宋完成对中原与北方主要地区的统一；北汉归降后十国割据结束，宋完成主要汉地政权统一。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘继元"}]',NULL,NULL,'北汉末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-jun','刘骏','song-liu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘义隆第三子，平定刘劭之乱后于453年即位，在位至464年。即位初稳定朝局并拓展疆土，后期频繁征役、严酷治宗室，刘宋政治由此转趋动荡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘骏"}]','孝武皇帝','世祖','宋孝武帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-jun-bei','刘钧','han-bei','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘旻之子，954年继位，改名刘钧。北汉继续以契丹为外援，对后周、北宋用兵并数次遭败；968年去世后，养子刘继恩、刘继元相继继位；人口与财力劣势使北汉依靠契丹仍难扭转战略处境。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘钧"}]','睿皇帝',NULL,'北汉睿皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-kan','刘衎','han-west','[]',NULL,NULL,-9,1,NULL,'year',6,1,NULL,'year','["皇帝"]','刘衎是元帝之孙、平帝，年幼即位，朝政由辅政大司马王莽控制。王莽逐步扩大权力并于9年受禅代汉；刘衎在位期间去世，西汉皇统随新朝建立而中断。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉平帝"}]','孝平皇帝',NULL,'汉平帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-long','刘隆','han-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘隆是和帝幼子，和帝去世后由邓太后拥立，出生百余日即位。邓太后临朝辅政，刘隆不满周岁便去世，是东汉在位时间最短的皇帝之一；其后由安帝刘祜继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉殇帝"}]','孝殇皇帝',NULL,'汉殇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-min','刘旻','han-bei','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','本名刘崇，后汉高祖刘知远之弟。郭威代汉建周后，他在太原称帝，建立北汉并依附契丹，与后周及北宋长期争战；死后子刘钧继位；北汉是五代中原王朝之外延续至北宋初年的十国政权。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘旻"}]',NULL,'世祖','北汉世祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-panzi','刘盆子','chimei','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','赤眉军所立皇帝，西汉末被立为帝，后降刘秀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘盆子"}]',NULL,NULL,'赤眉帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-qi','刘启','han-west','[]',NULL,NULL,-188,1,NULL,'year',-141,1,NULL,'year','["皇帝"]','刘启为文帝之子，承继文帝的节俭与轻徭政策。即位初年平定吴楚等七国之乱，随后削弱诸侯王权、加强中央控制；其统治与文帝时期合称“文景之治”。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉景帝"}]','孝景皇帝',NULL,'汉景帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-shan','刘禅','shu','[]',NULL,NULL,207,1,NULL,'year',271,1,NULL,'year','["皇帝"]','刘备之子，223年继位，在位至263年，是蜀汉第二帝。刘备去世后由诸葛亮辅政，诸葛亮及其后蒋琬、费祎、姜维等先后主持国政；263年魏军攻入蜀地，刘禅向邓艾投降，蜀汉灭亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘禅"}]','孝怀皇帝',NULL,'蜀汉后主','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-shao','刘劭','song-liu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘义隆长子，453年弑父后短暂即位，旋被弟弟刘骏起兵击败并处死。其弑父篡位引发刘宋宗室内战，谥号元凶。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘劭"}]',NULL,NULL,'宋元凶','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-shaoqi','刘少奇','prc','[]',NULL,NULL,1898,11,NULL,'month',1969,11,NULL,'month','["政治家"]','1959年4月27日当选国家主席，1965年连任；1968年10月31日中共八届十二中全会撤销党内外职务。1969年11月12日在开封逝世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘少奇"}]',NULL,NULL,'国家主席','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-sheng','刘晟','han-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘龑之子，杀兄刘玢后即位。以严酷手段清除宗室和大臣，南汉政局趋于封闭；死后子刘鋹继位，宋军于971年灭南汉；清洗暂时巩固皇权，却未建立稳固的继承与治理体系。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘晟"}]',NULL,'中宗','南汉中宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-shi','刘奭','han-west','[]',NULL,NULL,-75,1,NULL,'year',-33,1,NULL,'year','["皇帝"]','刘奭为宣帝与许平君之子，承继皇位后重用儒臣，尝试以宽政和经学整顿朝政。他在位时朝廷外戚与近臣影响上升，西汉由宣帝时期的强势逐渐转向皇权受制。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉元帝"}]','孝元皇帝',NULL,'汉元帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-wenhui','刘文辉','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','川系军阀，字自乾，四川大邑人，为刘湘叔父。曾控制川康地区并任西康省主席，抗战后期与刘文辉等参与起义；中华人民共和国成立后任西南军政委员会副主席等职。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘文辉"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-xiang','刘湘','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','川系军阀，字甫澄，四川大邑人。长期参与四川军阀混战，1933年成为四川主要军事领袖；抗战爆发后任第七战区司令长官，率川军出川抗日，1938年病逝于汉口。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘湘"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-xie','刘协','han-east','[]',NULL,NULL,181,1,NULL,'year',234,1,NULL,'year','["皇帝"]','刘协是灵帝之子，董卓废少帝后拥立他为献帝，并迁都长安。曹操迎献帝至许县后控制朝廷，皇帝名义仍存而政权实权旁落；220年刘协禅位曹丕，东汉结束。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉献帝"}]','孝献皇帝',NULL,'汉献帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-xin','刘欣','han-west','[]',NULL,NULL,-27,1,NULL,'year',-1,1,NULL,'year','["皇帝"]','刘欣为元帝之孙、定陶恭王刘康之子，经成帝立为继承人后即位。他曾试图削弱王氏外戚，并宠信董贤；在位六年无子，死后由年幼的刘衎继位，王莽继续掌握朝政。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉哀帝"}]','孝哀皇帝',NULL,'汉哀帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-xiu','刘秀','han-east','[]',NULL,NULL,-5,1,NULL,'year',57,1,NULL,'year','["皇帝"]','刘秀为汉景帝后裔，王莽末年与兄刘縯起兵，昆阳之战后声望大振；25年即位重建汉室，定都洛阳。此后平定赤眉、隗嚣、公孙述等势力，恢复统一，并裁并官署、抑制豪强，史称光武中兴。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘秀"}]','光武皇帝','世祖','汉光武帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-xuan','刘玄','han-gengshi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','更始帝，绿林军拥立，新莽亡后短暂称帝，后为赤眉所杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/更始帝"}]',NULL,NULL,'更始帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-xun','刘询','han-west','[]',NULL,NULL,-91,1,NULL,'year',-48,1,NULL,'year','["皇帝"]','刘询是武帝曾孙，幼年因巫蛊之祸牵连，在民间长大，后由霍光等迎立为帝。他亲自理政后整顿吏治、抑制豪强，恢复社会经济，并支持赵充国等经营西北，西汉国势再度稳定。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉宣帝"}]','孝宣皇帝',NULL,'汉宣帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-yan','刘龑','han-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','原名刘岩，刘隐之弟，继承其在岭南的军政基础。917年在广州称帝，国号大越，次年改汉，史称南汉；在位时扩张岭南并强化宫廷统治，传位于子刘玢；南汉凭岭南屏障长期独立，广州成为政治与贸易中心。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘龑"}]',NULL,'高祖','南汉高祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-yao-jin','刘曜','han-zhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘渊族子、刘聪养子，318年平定靳准之乱后继位；319年迁都长安并改国号为赵，统治关中，与石勒争衡，329年兵败被后赵俘杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘曜"}]',NULL,NULL,'汉赵末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-yi-shao','刘懿','han-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘懿是济北惠王刘寿之子，安帝去世后由阎太后及其外戚拥立为帝，在位约七个月。刘懿病逝后，宦官与朝臣迎立被废为济阴王的刘保，是为顺帝；刘懿未留下年号。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉少帝"}]',NULL,NULL,'汉前少帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-yifu','刘义符','song-liu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘裕长子，刘宋第二帝，422—424年在位。即位后年少失政，徐羡之、傅亮等废黜并杀害他，改立其弟刘义隆。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘义符"}]',NULL,NULL,'宋少帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-yilong','刘义隆','song-liu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘裕第三子，424—453年在位，是刘宋在位较久的皇帝。其前期整顿吏治、发展经济，史称“元嘉之治”；后期北伐失利，终被太子刘劭弑杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘义隆"}]','文皇帝','太祖','宋文帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-ying','刘盈','han-west','[]',NULL,NULL,-211,1,NULL,'year',-188,1,NULL,'year','["皇帝"]','刘盈为刘邦与吕雉之子，继位为惠帝，在位时吕太后实际主政。他延续汉初轻徭薄赋政策，废除秦代部分严刑，与民休息；其早逝后吕氏势力一度掌权。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘盈"}]','孝惠皇帝',NULL,'汉惠帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-yu-fei','刘昱','song-liu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘彧长子，472—477年在位，年幼即位后逐渐亲政，行为失度并滥杀大臣。萧道成掌握朝政后将其杀害，另立刘准。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘昱"}]',NULL,NULL,'宋后废帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-yu-jin','刘裕','song-liu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家","政治家"]','东晋末年权臣，北伐灭南燕、后秦，后代晋建宋。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘裕"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-yu-song','刘彧','song-liu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘义隆之弟，465—472年在位，政变中被拥立为帝。为巩固权力大规模诛杀宗室，刘宋统治集团进一步削弱；死后子刘昱继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘彧"}]','明皇帝','太宗','宋明帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-yu-xi','刘禹锡','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["诗人","文学家","政治家"]','中唐诗人、政治家，作品多有咏史怀古之作；参与永贞革新失败后遭长期贬谪，晚年返朝；《陋室铭》《乌衣巷》等篇传世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘禹锡"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-yuan','刘渊','han-zhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','匈奴贵族，汉赵开国君主；304年乘晋末动乱起兵，先称汉王、后称帝，建都平阳并以汉为国号，借汉室名义联结匈奴诸部与中原士人。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘渊"}]','光文皇帝','高祖','汉赵光文皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-zhang','刘璋','shu','[]',NULL,NULL,176,1,NULL,'year',219,1,NULL,'year','["军阀"]','益州牧，刘焉之子；引刘备入蜀后失益州，东汉末地方势力；投降后被刘备迁往公安并封振威将军；刘备接管益州后建立蜀汉政权。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘璋"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-zhao','刘肇','han-east','[]',NULL,NULL,79,1,NULL,'year',106,1,NULL,'year','["皇帝"]','刘肇是章帝之子，幼年即位，由窦太后及窦氏外戚辅政；成年后与宦官郑众合作，清除窦氏势力。他在位时派班超巩固西域经营，汉朝国力仍盛，但外戚、宦官参与朝政的局面进一步形成。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉和帝"}]','孝和皇帝',NULL,'汉和帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-zhi','刘志','han-east','[]',NULL,NULL,132,1,NULL,'year',168,1,NULL,'year','["皇帝"]','刘志是章帝曾孙、蠡吾侯之子，梁冀拥立他为桓帝；桓帝后来借助宦官诛灭梁冀及其党羽。此后宦官集团势力膨胀，党锢之祸加剧士人冲突，东汉朝廷的控制力持续衰退。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉桓帝"}]','孝桓皇帝',NULL,'汉桓帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-zhiyuan','刘知远','han-hou','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','沙陀将领，长期任后晋河东节度使。契丹灭后晋、撤军北返后，他于947年在太原称帝，建立后汉并进据开封；即位不久病逝，由子刘承祐继位；后汉承接后晋崩溃后的权力真空，统治基础主要仍是沙陀军政集团。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘知远"}]',NULL,'高祖','后汉高祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-zhuang','刘庄','han-east','[]',NULL,NULL,28,1,NULL,'year',75,1,NULL,'year','["皇帝"]','刘庄是光武帝与阴丽华之子，继位后延续光武时期的行政整顿，重视法令与吏治，并支持班超经营西域。他在位时汉朝国力较强，明帝与其子章帝的统治常被视作东汉前期的稳定时期。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉明帝"}]','孝明皇帝','显宗','汉明帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-zhun','刘准','song-liu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘彧第三子，477—479年在位，幼年被萧道成立为帝，政权实权已归萧氏。479年禅位于萧道成，刘宋亡，南齐建立。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘准"}]','顺皇帝',NULL,'宋顺帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-ziye','刘子业','song-liu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘骏长子，464—465年在位，年少即位后诛杀宗室与大臣，统治迅速失去支持。寿命短促，在宫廷政变中被叔父刘彧一方杀死。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘子业"}]',NULL,NULL,'宋前废帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-zong-yuan','柳宗元','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["诗人","文学家","政治家"]','中唐文学家、政治家，字子厚，河东人，参与王叔文革新失败后被贬永州、柳州。与韩愈倡导古文运动，山水游记、寓言及《捕蛇者说》等作品传世，列唐宋八大家。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/柳宗元"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-zuan','刘缵','han-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘缵是章帝玄孙，冲帝去世后由梁冀迎立为帝。质帝年幼而聪敏，曾当面称梁冀为“跋扈将军”，不久便遭梁冀毒杀；梁氏随后拥立刘志。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉质帝"}]','孝质皇帝',NULL,'汉质帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-zuo','刘炟','han-east','[]',NULL,NULL,57,1,NULL,'year',88,1,NULL,'year','["皇帝"]','刘炟为明帝之子，继位后承续明帝的政务制度，重视儒学与经术，并维持对西域的经营。章帝时期社会相对安定；其子和帝年幼即位，朝廷此后逐渐受外戚辅政影响。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉章帝"}]','孝章皇帝','肃宗','汉章帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liuli-ming-wang','琉璃明王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','高句丽第二代君主，名类利、孺留，东明圣王之子。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/琉璃明王"}]',NULL,NULL,'琉璃明王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('long-shun','隆舜','nanzhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主","皇帝"]','世隆之子，亦称法，改国号大封民，谥武宣帝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/隆舜"}]','武宣帝',NULL,'皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('long-yun','龙云','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家","政治家"]','滇系军阀，字志舟，云南昭通人。1927年发动政变取代唐继尧，长期主政云南；抗战时期接受国民政府任命并支持滇军出征，1945年失去云南军政权力，后赴南京、香港等地。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/龙云"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-guang','吕光','liang-back','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','前秦将领，淝水之战后据凉州，386年称三河王、后称天王，建立后凉并定都姑臧；晚年诸子与权臣相争，政权分裂。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吕光"}]','武皇帝',NULL,'后凉武皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-long','吕隆','liang-back','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','吕光之侄，401年由吕超拥立；后凉已被北凉、南凉夹击，403年向后秦姚兴出降，后凉亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吕隆"},{"label":"資治通鑑/卷112","url":"https://zh.wikisource.org/wiki/資治通鑑/卷112"}]',NULL,NULL,'后凉末主','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-r1','酋','lu-chunqiu','[]','姬','鲁',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','伯禽之子酋，谥考公，在位四年，为鲁国第二代君主，世次见《史记·鲁周公世家》，事见《史记》本国世家记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁考公"}]','考公',NULL,'鲁考公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-r10','伯御','lu-chunqiu','[]','姬','鲁',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','懿公侄伯御弑君自立，在位十一年，前796年周宣王命鲁人杀伯御，立孝公称复位，事见《史记》本国世家记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/伯御"}]',NULL,NULL,'伯御','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-r11','称','lu-chunqiu','[]','姬','鲁',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','武公之子称，谥孝公，周宣王命杀伯御后立之，在位近三十年，鲁国政局复归嫡系，事见《史记》本国世家记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁孝公"}]','孝公',NULL,'鲁孝公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-r12','弗涅','lu-chunqiu','[]','姬','鲁',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','孝公之子弗涅，谥惠公，在位四十六年，娶孟子无子，继室声子生隐公，仲子生桓公，事见《史记》本国世家记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁惠公"}]','惠公',NULL,'鲁惠公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-r13','息姑','lu-chunqiu','[]','姬','鲁',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','惠公庶长子息姑，谥隐公，因弟允年幼而摄政，《春秋》纪年起于此，前712年为羽父所弑。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁隐公"}]','隐公',NULL,'鲁隐公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-r14','允','lu-chunqiu','[]','姬','鲁',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','惠公嫡子允，谥桓公，隐公遇弑后继位，会盟诸侯，前694年赴齐，为齐襄公所杀，事见《史记》本国世家记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁桓公"}]','桓公',NULL,'鲁桓公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-r15','同','lu-chunqiu','[]','姬','鲁',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','桓公嫡子同，谥庄公，即位初年谷丘败齐，长期与齐、晋周旋，在位三十一年，事见《史记》本国世家记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁庄公"}]','庄公',NULL,'鲁庄公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-r16','启','lu-chunqiu','[]','姬','鲁',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','庄公之子启，谥闵公，在位仅两年，庆父作乱，先后弑闵公与桓公庶子，鲁国几近亡国，事见《史记》本国世家记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁闵公"}]','闵公',NULL,'鲁闵公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-r17','申','lu-chunqiu','[]','姬','鲁',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','庄公嫡子申，谥釐公，季友立之复位，先后败齐、败宋，在位三十二年，奠定鲁中期局势。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁釐公"}]','釐公',NULL,'鲁釐公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-r18','兴','lu-chunqiu','[]','姬','鲁',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','釐公之子兴，谥文公，在位十八年，任用季孙、孟孙、叔孙，三桓势力渐盛，事见《史记》本国世家记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁文公"}]','文公',NULL,'鲁文公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-r19','馁','lu-chunqiu','[]','姬','鲁',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','文公之子馁，谥宣公，襄仲弑文公而立之，逆天乱常，三桓专权之势由此加剧，事见《史记》本国世家记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁宣公"}]','宣公',NULL,'鲁宣公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-r2','熙','lu-chunqiu','[]','姬','鲁',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','考公弟熙弑兄自立，谥炀公，在位六年，为鲁国早期因篡弑更迭之例，事见《史记》本国世家记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁炀公"}]','炀公',NULL,'鲁炀公','[]');
