INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-rongting','陆荣廷','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','民国旧桂系首领，字干卿，广西武鸣人。清末在广西镇压会党起势，曾任广西都督并影响两广政局；护法运动后旧桂系势力衰退，晚年离开政坛。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陆荣廷"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-xun','陆逊','wu','[]',NULL,NULL,183,1,NULL,'year',245,8,NULL,'month','["军事家","政治家"]','孙吴名将，夷陵之战、石亭之战主将，后官至丞相；夷陵获胜后任荆州牧，晚年卷入孙和与孙霸储位争议，遭孙权责问而病逝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陆逊"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-you','陆游','song-south','[]',NULL,NULL,1125,1,NULL,'year',1210,1,NULL,'year','["诗人"]','南宋诗人，字务观，号放翁，越州山阴人。仕途屡受主和派排挤，长期主张恢复中原；晚年退居故乡，创作大量诗词，作品兼写抗金抱负、日常生活与乡土风物。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陆游"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-zuan','吕纂','liang-back','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','吕光之子，399年杀兄吕绍夺位；统治期间持续面对沮渠蒙逊等势力挑战，401年被弟吕超所杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吕纂"}]','灵帝',NULL,'后凉灵帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('luo-sheng','逻盛','nanzhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','细奴逻之子，谥兴宗王，庙号世宗。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/逻盛"}]','兴宗王','世宗','诏王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lv-shang','尚','qi-chunqiu','["姜子牙","姜太公","太公"]','姜','吕',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主","军事家","政治家"]','姜姓，吕氏，名尚，号太公望，通称姜子牙。辅佐周文王、武王，参与克商，前1046年受封于齐营丘；因当地风俗修政，发展工商与鱼盐之利。卒年有异说，一说约前1026年卒，其子吕伋继为齐丁公。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/姜子牙"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"维基百科：齐国君主列表（早期年代与正文表有异）","url":"https://zh.wikipedia.org/wiki/齐国君主列表#姜齊君主列表"},{"label":"《资治通鉴外纪》成王条（太公卒年异说）","url":"https://www.shidianguji.com/book/SBCK033/chapter/SBCK033_14"},{"label":"维基百科：齐国君主表（早期推定年代）","url":"https://zh.wikipedia.org/wiki/齐国#姜齊君主列表"}]','太公',NULL,'齐太公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lv-zhi','吕雉','han-west','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇后","政治家"]','汉高祖刘邦皇后，名雉，字娥姁。刘邦去世后，她以皇太后身份临朝称制，扶立惠帝并掌握朝政，分封吕氏外戚；其死后吕氏势力被周勃、陈平等诛灭。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吕雉"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ma-bufang','马步芳','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','马家军重要首领，字子香，甘肃河州人，长期控制青海军政。抗战时期任国民政府军事委员会委员长西北行营主任等职；1949年赴海外，晚年居于沙特阿拉伯。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/马步芳"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ma-su','马谡','shu','[]',NULL,NULL,NULL,NULL,NULL,NULL,228,1,NULL,'year','["将领"]','蜀汉将领，街亭之战违诸葛亮节度，兵败被斩；正史只记街亭失守后马谡被收监处死；“挥泪斩马谡”细节出自《三国演义》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/马谡"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ma-xichong','马希崇','chu-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','马殷之子，参与推翻兄长马希萼后短暂掌权。951年南唐军入长沙，马希崇出降并被迁往金陵，马楚政权结束；马楚覆亡后湖南并入南唐，南方政权格局继续收缩。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/马希崇"},{"label":"資治通鑑/卷287","url":"https://zh.wikisource.org/wiki/資治通鑑/卷287"},{"label":"資治通鑑/卷289","url":"https://zh.wikisource.org/wiki/資治通鑑/卷289"},{"label":"資治通鑑/卷290","url":"https://zh.wikisource.org/wiki/資治通鑑/卷290"}]',NULL,NULL,'楚王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ma-xie','马希萼','chu-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','马殷之子，长期镇守朗州，与兄马希广争夺楚王位。攻下潭州后即位，但将领拥立其弟马希崇反叛；南唐乘乱出兵，马希萼被俘，楚国亡；马楚内乱为南唐出兵湖南提供机会。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/马希萼"},{"label":"資治通鑑/卷287","url":"https://zh.wikisource.org/wiki/資治通鑑/卷287"},{"label":"資治通鑑/卷289","url":"https://zh.wikisource.org/wiki/資治通鑑/卷289"},{"label":"資治通鑑/卷290","url":"https://zh.wikisource.org/wiki/資治通鑑/卷290"}]',NULL,NULL,'楚王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ma-xifan','马希范','chu-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','马殷之子，继位后扩建长沙城与宫室，并维持马楚对后晋、后汉的朝贡关系。其统治时期政权疆域与财赋达到高峰，但宫廷营建和赏赐耗费增加；死后诸弟争位；继承争端使马楚由鼎盛转入长期内战。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/马希范"},{"label":"資治通鑑/卷287","url":"https://zh.wikisource.org/wiki/資治通鑑/卷287"},{"label":"資治通鑑/卷289","url":"https://zh.wikisource.org/wiki/資治通鑑/卷289"},{"label":"資治通鑑/卷290","url":"https://zh.wikisource.org/wiki/資治通鑑/卷290"}]',NULL,NULL,'楚王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ma-xiguang','马希广','chu-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','马殷之子，马希范死后由部分大臣拥立。兄长马希萼不服，率军争夺潭州，马希广兵败被杀，楚国内战扩大；内战暴露诸王和将领各拥兵力的问题，南唐乘机干预。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/马希广"},{"label":"資治通鑑/卷287","url":"https://zh.wikisource.org/wiki/資治通鑑/卷287"},{"label":"資治通鑑/卷289","url":"https://zh.wikisource.org/wiki/資治通鑑/卷289"},{"label":"資治通鑑/卷290","url":"https://zh.wikisource.org/wiki/資治通鑑/卷290"}]',NULL,NULL,'楚王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ma-xisheng','马希声','chu-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','马殷之子，继承楚王位，在位时间较短。延续父亲对后梁的臣属关系，死后弟马希范继位；其短暂统治延续马殷建立的王位与对外关系。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/马希声"}]',NULL,NULL,'楚王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ma-yin','马殷','chu-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','许州鄢陵人，唐末随秦宗权部将孙儒转战，后控制湖南并以潭州为中心。受后梁封楚王，建立马楚政权；在位时发展茶业、鼓励商贸并维持对中原称臣；马楚以湖南为核心，依靠地方茶贸财赋并在中原政权间保持外交弹性。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/马殷"}]','武王',NULL,'楚武王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ma-yingjiu','马英九','roc','[]',NULL,NULL,1950,7,NULL,'month',NULL,NULL,NULL,NULL,'["政治家"]','马英九曾任法务部长、台北市长及国民党主席，2008年当选总统，成为政党轮替后的第二位总统。任内与大陆恢复制度化协商并推动直航、签署《两岸经济合作架构协议》，同时推动地方行政区调整；2016年卸任。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/马英九"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ma-zhiyuan','马致远','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["文学家"]','元代散曲家、戏曲家，字千里，号东篱，大都人。与关汉卿、白朴、郑光祖并称“元曲四大家”；杂剧《汉宫秋》取材昭君出塞，散曲作品多写羁旅与隐逸。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/马致远"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('mangsong-mangtsen','芒松芒赞','tubo','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','吐蕃赞普，松赞干布之孙，幼年即位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/芒松芒赞"}]',NULL,NULL,'赞普','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('mao-sui','毛遂','zhao-warring','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','战国赵国平原君门客。秦围邯郸时，他自荐随平原君赴楚求援，在楚廷陈说利害、促成合纵盟约；“毛遂自荐”由此成为典故。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/毛遂"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('mao-zedong','毛泽东','prc','[]',NULL,NULL,1893,12,NULL,'month',1976,9,NULL,'month','["政治家","军事家"]','1949年10月1日出任中央人民政府主席，1954年9月27日当选国家主席，至1959年4月27日不连任。其后仍任中共中央主席、中央军委主席，1976年9月9日在北京逝世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/毛泽东"}]',NULL,NULL,'国家主席','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('meichuan-wang','美川王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','好壤王，名乙弗，高句丽重要君主。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/美川王"}]',NULL,NULL,'美川王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('meng-chang','孟昶','shu-hou','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','孟知祥之子，934年继位，在位三十余年。前期整顿蜀地政务、兴修水利，后期政治渐趋奢靡；965年宋军入成都后出降，后蜀亡；后蜀长期维持相对稳定，最终仍在北宋西进时归降。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孟昶"}]','恭孝王',NULL,'后蜀后主','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('meng-hao-ran','孟浩然','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["诗人"]','盛唐诗人，襄州襄阳人，长期隐居鹿门山，后漫游吴越并入长安求仕未成。诗多描绘山水田园与隐逸生活，与王维齐名，后世并称“王孟”。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孟浩然"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('meng-jiao','孟郊','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["诗人"]','中唐诗人，字东野，湖州武康人，长期仕途不顺，晚年任溧阳尉。诗风峭硬，重视苦吟，《游子吟》以母子亲情著称，与贾岛并称“郊寒岛瘦”。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孟郊"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('meng-ke','孟子','zou-state','[]',NULL,NULL,-372,1,NULL,'year',-289,1,NULL,'year','["思想家"]','战国邹人，名轲，承继并发展孔子学说，游说齐、梁等国，主张仁政、民贵君轻与王道。其言论由弟子记录编成《孟子》，后世尊为亚圣。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孟子"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('meng-zhixiang','孟知祥','shu-hou','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','后唐明宗李嗣源女婿，曾任西川节度使，逐步兼并东川并控制两川。934年在成都称帝建立后蜀，同年去世，子孟昶继位并完成政权交接；后蜀承接前蜀旧地，孟氏在两川建立新的区域统治。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孟知祥"}]',NULL,'高祖','后蜀高祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ming-sheng','明升','xia-ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,1371,1,NULL,'year','["皇帝"]','明玉珍之子，父死后于1366年继位为夏主。1371年明军攻入重庆，明升出降，明夏亡；后被迁往高丽。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/明升"}]',NULL,NULL,'明夏帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ming-yuzhen','明玉珍','xia-ming','[]',NULL,NULL,1329,1,NULL,'year',1366,1,NULL,'year','["皇帝"]','随州人，初聚乡里自保，后归附徐寿辉并任元帅。1357年乘势攻取重庆，逐步据有四川大部；1362年在重庆称帝，国号夏，建元天统。建置官署、国子监并开科取士，赋税取十分之一。1366年病逝，谥钦文昭武皇帝、庙号太祖。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/明玉珍"}]','钦文昭武皇帝','太祖','明夏太祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('minning','旻宁','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','爱新觉罗·旻宁，嘉庆帝次子，清宣宗。道光朝面对鸦片输入与边疆、财政问题，1839年命林则徐禁烟；鸦片战争失败后签订《南京条约》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/道光帝"}]','成皇帝','宣宗','清宣宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('minzhong-wang','闵中王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','高句丽君主，名解色朱，大武神王之弟，太子年幼时被推举继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/閔中王"}]',NULL,NULL,'闵中王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('mo-nang-e-pang','没藏讹庞','xixia','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家","军事家"]','西夏权臣，毅宗朝没藏太后之父，长期摄政干政；他与没藏太后权势日增，后因擅权与太后决裂，遭夏毅宗诛杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/没藏讹庞"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('mo-xi','妹喜','xia','["末喜","妹嬉"]',NULL,'有施',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["后妃"]','有施氏女，传说夏桀伐有施而得，为桀妃；传统叙事常将其与夏亡并提，事属传说。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/妹喜"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('mo-yanchuo','磨延啜','huihu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["可汗","君主"]','骨力裴罗之子，唐封英武可汗。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/磨延啜"}]',NULL,NULL,'英武可汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('mongke','蒙哥','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["大汗"]','蒙哥，拖雷长子，1251年经忽里勒台推举为大汗。即位后整顿财政与人口登记，并派旭烈兀西征、命忽必烈经略南方；1259年攻宋期间在钓鱼城下去世，随后忽必烈与阿里不哥争位，帝国统合受到冲击。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/蒙哥"}]','桓肃皇帝','宪宗','蒙哥汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('mu-ne-btsan','穆尼赞普','tubo','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','吐蕃赞普，亦称木奈赞普，在位极短。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/穆尼赞普"}]',NULL,NULL,'赞普','[]');
