INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-state-r1c','成公','qi-state-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杞成公，前654–前637年在位。在位时将国都迁至缘陵（今山东昌乐东南）。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杞成公"}]','成公',NULL,'杞成公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-state-r2','姑容','qi-state-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杞桓公（姑容），前636–前567年在位，在位七十年，为杞国在位最久之君。屡遭强邻压迫迁国，《列子·天瑞》「杞人忧天」故事或与此忧患有关。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杞桓公"}]','桓公',NULL,'杞桓公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-state-r3','益姑','qi-state-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杞文公（益姑），前549–前536年在位。在位时迁都淳于（今山东安丘东北）。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杞文公"}]','文公',NULL,'杞文公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-state-r4','郁','qi-state-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杞平公（郁），前535–前518年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杞平公"}]','平公',NULL,'杞平公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-state-r5','维','qi-state-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杞湣公（维），前486–前471年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杞湣公"}]','湣公',NULL,'杞湣公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-state-r6','春','qi-state-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杞简公（春），末代君主，前448–前445年在位。前445年为齐所灭，杞国亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杞简公"}]','简公',NULL,'杞简公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-state-xi','遂','qi-state-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杞僖公（遂），弑兄隐公自立，前505–前487年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杞僖公"}]','僖公',NULL,'杞僖公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-state-xiao','匄','qi-state-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杞孝公（匄），桓公之子，前566–前550年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杞孝公"}]','孝公',NULL,'杞孝公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-state-yin','乞','qi-state-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','悼公之子，在位七月即为弟僖公所弑；死年与悼公同在前506年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杞隐公"}]','隐公',NULL,'杞隐公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qian-chu','钱俶','wuyue','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','钱元瓘第九子，原名钱弘俶，947年后实际执掌吴越，后改名钱俶。向后周、北宋持续称臣，978年纳土归宋，保全两浙百姓与宗族；纳土归宋使吴越和平结束，钱氏宗族获宋廷安置。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/钱俶"}]','忠懿王',NULL,'吴越忠懿王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qian-hongcong','钱弘倧','wuyue','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','钱元瓘之子，钱弘佐死后继位。权臣胡进思发动政变将其废黜并幽禁，钱弘俶随后即位，吴越王位转入另一支；政变说明吴越国主虽有世袭名义，实际仍受将领和权臣制约。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/钱弘倧"}]','忠逊王',NULL,'吴越忠逊王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qian-hongzuo','钱弘佐','wuyue','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','钱元瓘之子，年少继位，由元老水丘昭券等辅政。吴越继续向中原王朝称臣，钱弘佐在位六年后去世，弟钱弘倧继位；吴越对中原称臣的政策继续，钱氏家族内部传承暂时平稳。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/钱弘佐"}]','忠悼王',NULL,'吴越忠悼王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qian-liu','钱镠','wuyue','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杭州临安人，唐末以镇压浙西地方势力起家，受任镇海、镇东节度使。907年受封吴越王，控制两浙并以杭州为中心；在位时兴修海塘、水利，奠定吴越长期偏安基础；钱氏尊奉中原王朝名号以换取两浙自治，避免与北方政权长期正面争战。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/钱镠"}]','武肃王',NULL,'吴越武肃王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qian-yuangui','钱元瓘','wuyue','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','钱镠第七子，继承吴越王位，在位期间维持对后唐、后晋的臣属关系并经营两浙。934年杭州火灾后重建城郭，941年去世，子钱弘佐继位；杭州重建延续钱镠以来以地方经营维持政权的路线。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/钱元瓘"}]','文穆王',NULL,'吴越文穆王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qifu-chipan','乞伏炽磐','qin-xi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','乞伏乾归长子，412年继位；西秦势力复振，414年灭南凉并据有河湟，428年去世后由子乞伏暮末继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/乞伏炽磐"}]','文昭王','太祖','西秦文昭王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qifu-gan','乞伏乾归','qin-xi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','乞伏国仁之弟，388年继位并称河南王，后称秦王；一度降附后秦、出奔南凉，409年复国，412年被部下杀害。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/乞伏乾归"}]','文威皇帝',NULL,'西秦文威皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qifu-guoren','乞伏国仁','qin-xi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','鲜卑乞伏部首领，前秦淝水败后于385年称大单于、建元建国，建立西秦并据苑川；死后由弟乞伏乾归继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/乞伏国仁"}]','武元王',NULL,'西秦武元王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qifu-mumo','乞伏暮末','qin-xi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','乞伏炽磐之子，428年继位；遭夏军进逼后于431年降夏，西秦灭亡，随后被赫连定杀害。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/乞伏暮末"},{"label":"資治通鑑/卷121","url":"https://zh.wikisource.org/wiki/資治通鑑/卷121"}]',NULL,NULL,'西秦末主','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-hui','秦桧','song-south','[]',NULL,NULL,1090,1,NULL,'year',1155,1,NULL,'year','["政治家"]','南宋宰相，字会之，江宁人。曾被金军俘至北方，归宋后主持与金议和，长期执政；绍兴十一年促成宋金和议并参与构陷岳飞，后世对其评价多以此事为核心。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦桧"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r1','康','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','文公，在位五十年。初行大夫葬礼制度，秦国渐有起色，国势平稳，为后世奠基，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦文公"}]','文公',NULL,'秦文公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r10','和','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','共公，在位仅三年。旋即传位桓公，秦国继续衰落，国势转弱，无力外争，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦共公"}]','共公',NULL,'秦共公','[]');
