INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r12','石','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','景公，在位四十年。秦国维持于二流强国，国势平平，无力外争，割地求和，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦景公"}]','景公',NULL,'秦景公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r13','籍','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','哀公，在位三十六年。秦国国力平平，无力外争，维持小国局面，国势转弱，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦哀公"}]','哀公',NULL,'秦哀公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r14','宁','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','惠公，在位仅九年。旋即传位悼公，秦国继续衰落，国势转弱，无力外争，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦惠公"}]','惠公',NULL,'秦惠公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r15','盘','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','悼公，在位十四年。秦国继续衰落，国势危急，无力争霸，濒临灭亡，事迹载于《史记》相关记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦悼公"}]','悼公',NULL,'秦悼公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r16','刺','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','厉共公，在位三十四年。秦国国力衰弱，无力争霸，国势转弱，维持现状，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦厉共公"}]','厉共公',NULL,'秦厉共公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r17','欣','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','躁公，在位十四年。秦国继续衰落，国势危急，无力外争，濒临灭亡，事迹载于《史记》相关记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦躁公"}]','躁公',NULL,'秦躁公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r18','封','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','怀公，被庶长所弑。在位仅数年，政局动荡，秦国内乱，国势不稳，事迹载于《史记》相关记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦怀公"}]','怀公',NULL,'秦怀公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r19','肃','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','灵公，在位十三年。死后献公不得立，传位简公，政局动荡，国势转弱，事迹载于《史记》相关记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦灵公"}]','灵公',NULL,'秦灵公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r2','立','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','宪公，迁都徙民，国有起色。在位十二年，秦国继续发展，国势渐强，事迹载于《史记》相关记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦宪公"}]','宪公',NULL,'秦宪公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r20','悼子','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','简公，令吏带剑、初开徭。在位十五年，略有革新，国势渐起，为献公奠基，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦简公"}]','简公',NULL,'秦简公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r21','仁','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','惠公（战国），伐蜀取南郑。在位十二年，旋即传位出公，秦国继续扩张，国势渐强，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦惠公"}]','惠公',NULL,'秦惠公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r22','昌','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','童主，被庶长改迎献公所弑。在位仅两年，河西地为晋所夺，国势危急，濒临衰落，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦出公"}]','出公',NULL,'秦出公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r23','师隰','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','止殉、迁栎阳，收复部分失地。商鞅入秦前秦国已有革新，国势渐起，为孝公奠基，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦献公"}]','献公',NULL,'秦献公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r25','驷','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杀商鞅而沿用其法，灭巴蜀，臣平周王。秦国首称王号，国势强盛，为统一奠基，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦惠文王"}]','惠文王',NULL,'秦惠文王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r26','荡','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','武王，举鼎绝膑而亡。在位仅四年，秦国继续扩张，国势强盛，无力维持长期霸业，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦武王"}]','武王',NULL,'秦武王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r27','稷','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','在位五十六年，诱杀楚怀王，长平灭赵。为秦国一统奠定决定性基础，国势巅峰，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦昭襄王"}]','昭襄王',NULL,'秦昭襄王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r28','柱','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','孝文王，在位仅三天即卒。秦国王位匆匆传递，国势继续强盛，为庄襄王奠基，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦孝文王"}]','孝文王',NULL,'秦孝文王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r29','子楚','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','庄襄王，在位三年。秦占太原，切断韩交通要道，为灭韩铺路，国势继续强盛，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦庄襄王"},{"label":"史記/卷005","url":"https://zh.wikisource.org/wiki/史記/卷005"},{"label":"交接日期复核来源","url":"https://en.wikipedia.org/wiki/King_Zhuangxiang_of_Qin"}]','庄襄王',NULL,'秦庄襄王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r3','曼','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','庶子，被立为君后不久为叔父武公所弑。在位仅五年，政局动荡，国势不稳，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/出子"}]',NULL,NULL,'出子','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r4','说','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','武公，肃内政、平内乱。在位十九年，秦国渐稳，国势回升，为穆公霸业奠基，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦武公"}]','武公',NULL,'秦武公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r5','嘉','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','德公，在位仅两年，迁雍都。旋即传位宣公，秦国政局平稳，国势尚可，事迹载于《史记》相关记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦德公"}]','德公',NULL,'秦德公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r6','恬','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','宣公，在位十一年。秦国维持二流强国地位，国势平稳，无力争霸，事迹载于《史记》相关记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦宣公"}]','宣公',NULL,'秦宣公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r7','载','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','成公，在位仅四年。旋即传位穆公，秦国迎来霸业时期，国势渐强，事迹载于《史记》相关记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦成公"}]','成公',NULL,'秦成公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r8','任好','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','在位三十九年，霸西戎，为春秋五霸之一。晚年兵败晋国，国力由盛转衰，霸业渐失，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦穆公"}]','穆公',NULL,'秦穆公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r9','罃','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','康公，穆公之子。在位十一年，秦国维持现状，国势平稳，无力争霸，事迹载于《史记》相关记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦康公"}]','康公',NULL,'秦康公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qiu-fengjia','丘逢甲','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["诗人","教育家"]','晚清诗人、教育家，字仙根，广东镇平人，甲午战争后曾参与台湾抗日。清亡后返大陆办学、倡导新学，诗作记录台湾割让及遗民心境，与丘逢甲的台湾诗名相关。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/丘逢甲"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qu-chulu','屈出律','xiliao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','乃蛮王子，娶耶律直鲁古之女后夺取西辽权位。其统治引发当地穆斯林反抗，蒙古军西征时攻入西辽，屈出律于1218年被俘处死，政权灭亡；在位1211—1218年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/屈出律"}]',NULL,NULL,'西辽皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qu-yuan','屈原','chu-chunqiu','[]',NULL,NULL,-340,1,NULL,'year',-278,1,NULL,'year','["诗人","政治家"]','战国楚国诗人、政治人物，曾任左徒，主张举贤任能并联齐抗秦，后遭疏远。秦军攻破楚都郢后，他作《怀沙》并投汨罗江；《离骚》《九歌》等作品传世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/屈原"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('quan-fengyou','劝丰祐','nanzhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','劝利晟之弟，谥昭成王，在位三十余年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/劝丰祐"}]','昭成王',NULL,'南诏王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('quan-lisheng','劝利晟','nanzhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','劝龙晟之弟，谥靖王。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/劝利晟"}]','靖王',NULL,'南诏王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('quan-longsheng','劝龙晟','nanzhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','寻阁劝之子，谥幽王。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/劝龙晟"}]','幽王',NULL,'南诏王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ragibagh','阿速吉八','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','阿速吉八，元天顺帝，也孙铁木儿之子。泰定帝去世后，他在上都由权臣倒剌沙拥立；同年，支持图帖睦尔的势力在大都发动政变并赢得两都之战，阿速吉八败亡，在位仅数周。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/阿速吉八"}]',NULL,NULL,'元天顺帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ran-min','冉闵','ranwei','[]',NULL,NULL,NULL,NULL,NULL,NULL,352,6,NULL,'month','["皇帝"]','后赵将领石闵，父冉瞻本姓冉；石虎收养冉瞻后，石闵在后赵军中崛起。349年石虎死后诸子争位，石闵先后废杀石遵、石鉴，350年称帝、复姓冉并建魏，年号永兴。他试图重整邺城政权并与周边势力争战，后赵旧部、前燕及其他势力持续进攻；352年兵败被前燕慕容儁擒杀，冉魏随之覆亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/冉闵"}]','平帝',NULL,'魏平帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('rongliu-wang','荣留王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','高句丽荣留王，名建武，唐初君主。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/荣留王"}]',NULL,NULL,'荣留王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ruzi-ying','刘婴','han-west','[]',NULL,NULL,NULL,NULL,NULL,NULL,24,1,NULL,'year','["君主"]','刘婴是平帝死后由王莽立为皇太子的刘氏宗室，年幼时被称作“孺子”，始终未正式即皇帝位。王莽于9年建立新朝后将他废置；更始政权兴起后，刘婴在长安被杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孺子婴"}]',NULL,NULL,'孺子婴','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shang-yang','商鞅','qin','[]',NULL,NULL,-390,1,NULL,'year',-338,1,NULL,'year','["政治家"]','卫国人，秦孝公时主持变法，奠定秦统一基础；入秦后受封商於，推行军功爵、县制等改革。孝公去世后失去支持，前338年遭车裂。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/商鞅"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shangguan-waner','上官婉儿','tang','[]',NULL,NULL,664,1,NULL,'year',710,1,NULL,'year','["政治家","诗人"]','唐代女官、诗人，陕州陕县人，上官仪孙女。幼年入宫，受武则天赏识，长期掌管诏敕文书；唐中宗时期参与政务并影响宫廷政治，景龙四年在唐隆政变中被杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/上官婉儿"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shanshang-wang','山上王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','高句丽君主，名延优，山上王时期。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/山上王"}]',NULL,NULL,'山上王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shen-kuo','沈括','song-north','[]',NULL,NULL,1031,1,NULL,'year',1095,1,NULL,'year','["科学家"]','北宋科学家，梦溪笔谈作者，天文历法、物理皆有建树；《梦溪笔谈》记载磁针指南、活字印刷及地貌观察，是宋代科学史重要文献。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/沈括"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shen-zhuliang','沈诸梁','chu-chunqiu','["叶公"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','春秋末楚国大夫，封于叶，称叶公。曾参与平定白公胜之乱；“叶公好龙”出自刘向《新序》等后世故事，故事中的叶公形象不宜直接等同其完整生平。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/叶公"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sheng-luopi','盛逻皮','nanzhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','逻盛之子，谥威成王，庙号太宗。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/盛逻皮"}]','威成王','太宗','诏王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shi-chaoyi','史朝义','yan-anshi','[]',NULL,NULL,NULL,NULL,NULL,NULL,763,NULL,NULL,'year','["皇帝"]','史思明长子。761年弑父继位，改元显圣；唐军与回纥军收复洛阳后，他退往莫州一带。763年部将李怀仙降唐，史朝义败亡自尽，安史之乱至此平定。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/史朝义"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shi-chonggui','石重贵','jin-hou','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','石敬瑭侄，石敬瑭死后由宰相冯道等拥立。即位初向契丹称孙，随后拒绝臣服并与之交战；946至947年契丹南下攻陷开封，后晋亡，石重贵被迁往北方；对契丹政策由妥协转向对抗，最终以国亡和被迁徙告终。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/石重贵"}]','出帝',NULL,'后晋出帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shi-dakai','石达开','taiping','[]',NULL,NULL,1831,1,NULL,'year',1863,6,NULL,'month','["军事家"]','太平天国翼王，西征名将；咸丰七年出走后转战西南，同治二年五月初十（1863年6月10日）大渡河兵败被俘。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/石达开"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shi-hong','石弘','zhao-back','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','石勒之子，333年继位；政权实权掌握在石虎手中，石虎于翌年废杀石弘并夺位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/石弘"}]',NULL,NULL,'后赵皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shi-hu','石虎','zhao-back','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','石勒养子，334年废石弘自立，后称帝并迁都邺城；大举营建与频繁征伐加重国力消耗，其死后诸子争位，后赵迅速分裂。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/石虎"},{"label":"《资治通鉴》卷95","url":"https://zh.wikisource.org/wiki/資治通鑑/卷095"},{"label":"資治通鑑/卷098","url":"https://zh.wikisource.org/wiki/資治通鑑/卷098"}]','武皇帝','太祖','后赵武皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shi-jian','石鉴','zhao-back','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','石虎之子，石遵死后于349年被冉闵拥立；次年冉闵杀石鉴并控制邺城，石氏政权失去中枢。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/石鉴"}]',NULL,NULL,'后赵皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shi-jingtang','石敬瑭','jin-hou','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','李嗣源女婿，后唐河东节度使。936年借契丹兵推翻李从珂，建立后晋并以契丹为父国；割让燕云十六州、岁输财物，后晋因此长期受制于契丹；割让燕云十六州换来建国支持，却将北方防务主动权交给契丹。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/石敬瑭"}]',NULL,'高祖','后晋高祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shi-le','石勒','zhao-back','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','羯族首领，早年依附刘渊，后割据河北；319年称赵王，329年灭汉赵，建后赵并控制华北大部，重用张宾整饬政务，333年死后由石弘继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/石勒"}]','明皇帝','高祖','后赵明皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shi-long','世隆','nanzhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主","皇帝"]','劝丰祐之子，亦称酋龙，僭称帝号，改国号大礼，谥景庄帝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/世隆"}]','景庄帝',NULL,'皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shi-shi','石世','zhao-back','[]',NULL,NULL,339,1,NULL,'year',349,6,NULL,'month','["皇帝"]','石虎幼子，349年石虎死后由太后拥立；在位三十三日即被石遵废杀，后赵进入连续政变。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/石世"},{"label":"資治通鑑/卷098","url":"https://zh.wikisource.org/wiki/資治通鑑/卷098"}]',NULL,NULL,'后赵少帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shi-siming','史思明','yan-anshi','[]',NULL,NULL,NULL,NULL,NULL,NULL,761,NULL,NULL,'year','["皇帝","将领"]','安禄山旧部，曾受唐廷招抚，后复叛。759年杀安庆绪，恢复大燕国号并称帝，先用应天、后改顺天年号；761年为长子史朝义所杀。','[{"label":"故宫博物院","url":"https://www.dpm.org.cn/lemmas/239708.html"},{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/史思明"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shi-zhi','石祗','zhao-back','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','石虎之子，冉闵杀石鉴后在襄国称帝，延续石氏后赵；351年被部将刘显攻杀，后赵正式灭亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/石祗"}]',NULL,NULL,'后赵末帝','[]');
