INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('songtsen-gampo','松赞干布','tubo','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','吐蕃赞普，创制藏文，迎娶文成公主，与唐和亲。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/松赞干布"}]',NULL,NULL,'赞普','[]');
