INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sun-bin','孙膑','qi-chunqiu','[]',NULL,NULL,-378,1,NULL,'year',-316,1,NULL,'year','["军事家"]','战国齐国军事家，曾遭庞涓陷害而受膑刑，后在齐国任军师。协助田忌于桂陵、马陵击败魏军；《史记》称其为孙武后裔，但世系缺乏独立证据，具体身世仍有争议。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孙膑"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sun-chuanfang','孙传芳','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','北洋时期直系军阀，字馨远，山东历城人。1920年代控制福建、浙江、江苏、安徽、江西等地，号称“五省联帅”；北伐军进攻后失去地盘，1935年在天津被刺身亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孙传芳"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sun-hao','孙皓','wu','[]',NULL,NULL,242,1,NULL,'year',284,1,NULL,'year','["皇帝"]','孙权之孙、孙和之子，264年孙休去世后被拥立为帝，在位至280年。初立时曾开仓赈贫、释放宫女，后渐趋专断，吴国又因交州动乱与对晋战事而局势恶化；280年晋军攻入建业，孙皓出降，孙吴灭亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孙皓"}]',NULL,NULL,'吴末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sun-liang','孙亮','wu','[]',NULL,NULL,244,1,NULL,'year',260,6,NULL,'month','["皇帝"]','孙权少子，252年继位时年幼，由诸葛恪等辅政，在位至258年。诸葛恪被孙峻诛杀后，孙綝把持朝政并废孙亮为会稽王；孙亮后又被贬为侯官侯。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孙亮"}]',NULL,NULL,'会稽王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sun-quan','孙权','wu','[]',NULL,NULL,182,7,NULL,'month',252,5,NULL,'month','["皇帝"]','孙坚之子、孙策之弟，承接孙策经营的江东基业，逐步确立对长江中下游及岭南部分地区的统治。208年与刘备结盟，在赤壁之战中击退曹操；222年受封吴王，229年称帝，在位至252年，孙吴由其子孙继续统治。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孙权"}]','大皇帝','太祖','大皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sun-wu','孙武','wu-chunqiu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','齐国军事家，著《孙子兵法》，传为吴王阖闾将；《史记》称他向阖闾进呈兵法并训练吴军；其生平记载有限，兵书作者身份亦有学术讨论。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孙武"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sun-xiu','孙休','wu','[]',NULL,NULL,235,1,NULL,'year',264,9,NULL,'month','["皇帝"]','孙权第六子，258年在孙綝废黜孙亮后被迎立，在位至264年。他与张布等合谋诛杀孙綝，随后改任相关官员、整顿政务；其子年幼，死后由侄孙皓继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孙休"}]','景皇帝',NULL,'吴景帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sun-yat-sen','孙中山','roc','[]',NULL,NULL,1866,1,NULL,'year',1925,1,NULL,'year','["政治家"]','孙中山是近代革命运动的重要领袖，参与组织兴中会、同盟会并推动反清革命。武昌起义后各省代表推举他为中华民国临时大总统，1912年在南京就职；清帝退位后，他依约让位于袁世凯，转而致力于改组政党与推动革命。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孙中山"}]',NULL,NULL,'临时大总统','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('system-missing-ruler','史料缺',NULL,'[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["系统占位"]','国君姓名或世次失载。','[]',NULL,NULL,'史料缺','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('taizu-wang','太祖王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','高句丽太祖王，名宫，长期在位，国势渐强。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/太祖王"}]',NULL,NULL,'太祖王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tan-sitong','谭嗣同','qing','[]',NULL,NULL,1865,1,NULL,'year',1898,1,NULL,'year','["政治家","思想家"]','戊戌维新人物，变法失败后遇害，列为戊戌六君子；变法失败后拒绝出逃，1898年在北京遇害；《仁学》批判旧制度与纲常。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/谭嗣同"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tan-yankai','谭延闿','roc','["谭延闓"]',NULL,NULL,1880,1,NULL,'year',1930,9,NULL,'month','["政治家"]','谭延闿是湖南地方政治人物、国民党元老，曾任湖南督军及国民政府要职。宁汉合流后于1928年出任南京国民政府主席，张作霖离京后成为该包所记的主线元首；随后转任行政院院长。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/谭延闿"}]',NULL,NULL,'国民政府主席','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tang-jiyao','唐继尧','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家","政治家"]','滇系军阀首领，字蓂赓，云南会泽人。辛亥革命后任云南都督，护国战争中支持蔡锷讨袁，后长期控制云南并一度扩展至贵州、四川；1927年被部属政变驱逐。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/唐继尧"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tang-yin','唐寅','ming','[]',NULL,NULL,1470,1,NULL,'year',1524,1,NULL,'year','["画家","诗人"]','明代吴门画派代表，江南四大才子之一，桃花庵歌作者；科场案后放弃仕进，以卖画为生；与沈周、文徵明、仇英并称吴门四家。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/唐寅"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tao-yuanming','陶渊明','jin-east','[]',NULL,NULL,365,1,NULL,'year',427,1,NULL,'year','["诗人"]','东晋诗人，田园诗派开创者，桃花源记作者；《归去来兮辞》《饮酒》等作品传世；《桃花源记》描绘其理想中的社会图景。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陶渊明"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('temujin','铁木真','yuan','[]',NULL,NULL,1162,NULL,NULL,'year',1227,NULL,NULL,'year','["大汗"]','铁木真，孛儿只斤氏，后世称成吉思汗。经过多年征战与结盟统一蒙古高原诸部，1206年在忽里勒台被推举为大汗并建立大蒙古国；此后发动对金、西夏等地的战争，1227年在征夏途中去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/成吉思汗"}]','法天启运圣武皇帝','太祖','成吉思汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('temur','铁穆耳','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','铁穆耳，元成宗，忽必烈之孙。即位后确认忽必烈以来的制度与对外和议，暂停大规模征战，并处理西北诸王与元廷的冲突；在位后期健康恶化且未明确继承人，死后发生皇位继承争议。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元成宗"}]','钦明广孝皇帝','成宗','元成宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('teng-gong-middle','？','teng-chunqiu','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','西周中期滕侯簋所追祭的前任滕公，与早期滕侯方鼎、簋所见滕公应作区别。本名、具体世次及在位年失考。','[{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"}]',NULL,NULL,'公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('teng-hou-middle','？','teng-chunqiu','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','西周中期滕侯簋的作器者，为前任滕公作尊彝。本名、具体世次及在位年失考。','[{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"}]',NULL,NULL,'侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('teng-hou-su','苏','teng-chunqiu','["滕侯𩵦","姬𩵦","滕侯苏"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','两周之际滕侯盨的作器者，为其父滕仲作器。张志鹏释名苏，另一释法作𩵦；具体世次和在位年代失考。','[{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"}]',NULL,NULL,'侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('teng-hu','虎','teng-chunqiu','["孟虎","滕侯虎","姬敢"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','滕虎簋的作器者，铭文称其父为公命仲。通常与《礼记·檀弓上》的孟虎相联系，是滕伯文的叔父；部分世系表将其列为第五世滕君，张志鹏则将该世君主推为伯文之父。','[{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"},{"label":"《礼记·檀弓上》：滕伯文与孟虎的亲属关系","url":"https://ctext.org/text.pl?if=gb&node=9665&show=parallel"}]',NULL,NULL,'虎','[]');
