INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tian-he','和','qi-chunqiu','[]','妫','田',NULL,NULL,NULL,NULL,-384,1,NULL,'year','["君主"]','田齐太公（田和）。前391年放逐齐康公自立，前386年周安王列为诸侯，史称田氏代齐。前384年卒。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/田和"},{"label":"《史记·田敬仲完世家》","url":"https://zh.wikisource.org/wiki/史記/卷046"},{"label":"维基百科：齐国君主列表（年表及异说）","url":"https://zh.wikipedia.org/wiki/齐国君主列表"}]','太公',NULL,'齐太公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tian-shi','田巿','jiaodong-warring','[]','妫','田',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','秦末齐国宗室，田儋之子。前208年，田儋在临济战死后，齐人先立齐王建之弟田假为王；田儋从弟田荣驱逐田假，继而立田巿为齐王。项羽分封诸侯时，改封田巿为胶东王。前206年，田荣攻杀田巿于即墨。','[{"label":"《史记·田儋列传》","url":"https://zh.wikisource.org/wiki/史记/卷094"}]',NULL,NULL,'胶东王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tian-wen','田文','qi-chunqiu','["孟尝君"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','战国齐国宗室，齐威王之孙，封于薛，号孟尝君。广招门客，以善养士著称；曾任齐相并参与合纵，后历仕秦、魏，政治经历随诸侯局势多次变化。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孟尝君"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('togon-temur','妥懽帖睦尔','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','妥懽帖睦尔，元顺帝，元朝在中原的末代皇帝。其长期在位期间朝廷屡受权臣与派系斗争影响，黄河水患、财政危机及红巾军起义相继爆发；1368年明军攻入大都，他北走上都，元廷退居漠北。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元顺帝"}]','顺帝','惠宗','元惠宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('togus-temur','脱古思帖木儿','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','北元末主天元帝，1388年捕鱼儿海之战后为也速迭儿所杀，北元终结。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/脱古思帖木儿"}]',NULL,NULL,'天元帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tolui','拖雷','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["宗王"]','成吉思汗幼子，1227–1229年监国，蒙哥、忽必烈、阿里不哥之父。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/拖雷"}]',NULL,NULL,NULL,'[]');
