INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tufa-lilugu','秃发利鹿孤','liang-south','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','秃发乌孤之弟，399年继位；以广武为都并与后凉、北凉及西秦周旋，402年让位于弟秃发傉檀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秃发利鹿孤"}]',NULL,NULL,'南凉皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tufa-rutan','秃发傉檀','liang-south','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','秃发利鹿孤之弟，402年继位并迁都姑臧；多次与北凉及后秦交战，414年为西秦乞伏炽磐所灭，降后被杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秃发傉檀"},{"label":"資治通鑑/卷112","url":"https://zh.wikisource.org/wiki/資治通鑑/卷112"}]',NULL,NULL,'南凉末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tufa-wugu','秃发乌孤','liang-south','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','鲜卑秃发部首领，397年脱离后凉，先称西平王、后称武威王，建立南凉；定都乐都并扩张河湟，399年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秃发乌孤"}]','武成王',NULL,'南凉武成王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tugh-temur','图帖睦尔','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','图帖睦尔，元文宗，元武宗之子。两都之战中获胜后即位，曾让位于兄长和世㻋；和世㻋去世后复位。其朝设奎章阁、召集文臣编修典籍，皇位反复更替与权臣斗争仍持续。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元文宗"}]','圣明元孝皇帝','文宗','元文宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tuoba-gui','拓跋珪','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','代王拓跋什翼犍之孙，北魏开国君主。386年复立代国并改国号魏，逐步整合北方部众、迁都平城；在位至409年，奠定北魏扩张基础。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏道武帝"},{"label":"《魏书》卷二·太祖纪","url":"https://wk.100ke.info/wiki/魏書/卷2"},{"label":"代（十六国）","url":"https://zh.wikipedia.org/wiki/代_(十六国)"}]','道武皇帝','太祖','魏道武帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tuoba-hong','拓跋弘','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','拓跋浚长子，465—471年在位，史称献文帝。即位时年幼，冯太后临朝；后来传位于年幼的拓跋宏，仍参与朝政，最终去世于权力冲突之中。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏献文帝"}]','献文皇帝',NULL,'魏献文帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tuoba-jun','拓跋浚','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','拓跋晃之子，452—465年在位，史称文成帝。即位后重建朝廷秩序、缓和太武帝晚年的政治震荡，并恢复佛教活动；其子拓跋弘继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏文成帝"}]','文成皇帝','高宗','魏文成帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tuoba-kuo','拓跋廓','wei-west','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','元宝炬第四子，原姓元，554年由宇文泰拥立，史称西魏恭帝，在位至557年。宇文觉受禅建北周后，西魏灭亡；元廓随后被杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏恭帝"}]','恭帝',NULL,'魏恭帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tuoba-si','拓跋嗣','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','拓跋珪之子，409年继位，在位至423年，后尊为明元帝。其间巩固平城政权、向黄河流域扩张，并为子拓跋焘继续统一北方打下基础。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏明元帝"}]','明元皇帝','太宗','魏明元帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tuoba-tao','拓跋焘','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','拓跋嗣之子，424—452年在位，史称太武帝。通过长期征战先后灭夏、北燕、北凉，439年统一北方；晚年因宫廷冲突被宦官宗爱弑杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏太武帝"}]','太武皇帝','世祖','魏太武帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tuoba-yu','拓跋余','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','太武帝拓跋焘之子，452年在宗爱弑帝后被拥立，在位仅数月即遇害。其死引发宫廷清洗，文成帝拓跋浚随后即位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元余"}]',NULL,NULL,'魏南安王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tuyan','吐延','tuyuhun','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','慕容吐谷浑长子，继守青海。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吐延"}]',NULL,NULL,'河南王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wang-anshi','王安石','song-north','[]',NULL,NULL,1021,1,NULL,'year',1086,1,NULL,'year','["政治家"]','北宋政治家、文学家，字介甫，号半山，临川人。神宗朝任参知政事、宰相，主持熙宁变法，推行青苗、募役、方田等新法；变法引发长期争论，晚年退居金陵。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王安石"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wang-can','王粲','han-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["诗人","文学家"]','东汉末文学家，字仲宣，山阳高平人，建安七子之一。早年避乱荆州，后归附曹操，任侍中；作品《七哀诗》《登楼赋》记录战乱与流离，诗赋多篇由《文选》保存。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王粲"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wang-chang-ling','王昌龄','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["诗人"]','盛唐诗人，字少伯，京兆长安人，曾任地方官并历经贬谪。七绝尤工，边塞诗与宫怨诗传诵甚广，《出塞》《从军行》为代表作；安史之乱后遇害。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王昌龄"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wang-dao','王导','jin-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','东晋开国重臣，与司马睿共定江南，王与马共天下；东晋初任丞相、司徒，协调皇室与江东士族；王氏影响常以“王与马，共天下”概括。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王导"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wang-jian-qin','王翦','qin','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','战国末秦国名将，秦王政统一战争的主要统帅。率军灭赵、燕、楚，灭楚时以持重用兵著称；秦统一后退居故里。其子王贲亦为秦将。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王翦"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wang-jian-shu','王建','shu-qian','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','许州舞阳人，唐末入蜀任职，逐步控制西川并据成都。907年称帝建前蜀，扩展至两川及汉中；晚年因继承安排引发宫廷冲突，死后子王衍继位；四川盆地的地理条件支持前蜀独立，但晚年继承纷争影响政权稳定。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王建"}]',NULL,'高祖','前蜀高祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wang-jingwei','汪精卫','roc','["汪兆铭"]',NULL,NULL,NULL,NULL,NULL,NULL,1944,11,NULL,'month','["政治家"]','曾任中国国民党要职，抗战期间脱离重庆国民政府并与日本合作。1940年在南京建立汪伪国民政府，先任代主席、后任主席；1944年赴日治疗并由陈公博代理，11月病逝。','[{"label":"中国抗日战争史：汪精卫建立伪国民政府","url":"https://szzy.7lue.cn/read/eddf364fc59f9d9306913a56193b3e20/2dfe4578f86d60f92960c1df4e84e7b7.md"},{"label":"中国通史：汪精卫国民政府的僭立","url":"https://szzy.7lue.cn/read/5d14e01721b1a1ebbcbf1e7f1/fb899fb6618b6ef45941a56359ca9999.md"}]',NULL,NULL,'国民政府主席','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wang-jipeng','王继鹏','min-fujian','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','王延钧之子，改名王昶，杀父后继位并称帝。宠信宦官、兴建宫室，国内政变频仍；939年被叔父王延羲所杀；宦官与宗室争斗持续削弱闽国统治。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王继鹏"}]',NULL,NULL,'闽主','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wang-mang','王莽','xin','[]',NULL,NULL,-45,1,NULL,'year',23,1,NULL,'year','["皇帝"]','新莽开国皇帝，外戚出身，篡汉自立，改革失败，绿林起义而亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王莽"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wang-mian','王冕','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["诗人","画家"]','元末诗人、画家，字元章，号煮石山农，诸暨人。出身贫寒，曾游历各地，后隐居九里山；善画墨梅，诗作多写时政与民生，著有《竹斋集》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王冕"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wang-shenzhi','王审知','min-fujian','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','光州固始人，与兄王潮随军入闽并控制福建，王潮死后继任。受封闽王，定都福州，在位时奉中原正朔、轻徭薄赋并发展海上贸易，为闽政权奠基；闽地远离中原战场，王氏借地方开发和海贸形成区域政权。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王审知"}]',NULL,'太祖','闽太祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wang-shichong','王世充','zheng','[]',NULL,NULL,NULL,NULL,NULL,NULL,621,NULL,NULL,'year','["皇帝","将领","政治家"]','隋末据洛阳，拥立杨侗后杀之自立，建郑称帝；621年降唐，赴蜀途中被仇家独孤修德所杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王世充"}]',NULL,NULL,'郑帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wang-wei','王维','tang','[]',NULL,NULL,701,1,NULL,'year',761,1,NULL,'year','["诗人","画家"]','唐代诗人、画家，字摩诘，河东蒲州人。早年入仕，安史之乱时曾受伪职，乱平后复职；诗歌多写山水田园，兼擅绘画与音乐，与孟浩然并称“王孟”。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王维"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wang-xizhi','王羲之','jin-east','[]',NULL,NULL,303,1,NULL,'year',361,1,NULL,'year','["书法家"]','东晋书法家，字逸少，琅邪临沂人，官至会稽内史。工行、草、楷书，代表作《兰亭集序》被后世奉为行书典范，世称“书圣”；现存作品多为摹本。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王羲之"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wang-yan-shu','王衍','shu-qian','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','王建幼子，918年继位。统治期间宠信近臣、巡游奢侈，前蜀防务松弛；925年后唐军攻入成都，王衍出降，前蜀亡；前蜀覆亡显示地势险要无法弥补统治中枢松弛。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王衍"}]',NULL,NULL,'前蜀末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wang-yangming','王阳明','ming','[]',NULL,NULL,1472,1,NULL,'year',1529,1,NULL,'year','["思想家","军事家"]','明代心学集大成者，提出知行合一，平宁王之乱；平定宁王之乱后在江西、广西任事并讲学，弟子整理其说形成阳明学派。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王阳明"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wang-yanhan','王延翰','min-fujian','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','王审知长子，王审知死后继位。骄奢并与弟王延钧失和，926年被王延钧、王延禀起兵杀害，闽国由王延钧掌权；王延翰之死开启闽国连续的宗室内斗。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王延翰"}]',NULL,NULL,'闽主','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wang-yanjun','王延钧','min-fujian','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','王审知次子，联合王延禀推翻兄长王延翰后掌权，后称帝、改名王鏻。晚年猜忌宗室与大臣，934年被子王继鹏发动政变杀死；闽国称帝并未带来稳定，王位继承转为宫廷政变。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王延钧"}]',NULL,NULL,'闽主','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wang-yanxi','王延羲','min-fujian','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','王审知之子，王继鹏死后即位，后改名王曦并称帝。统治期间闽国内乱加剧，部将朱文进与连重遇发动兵变将其杀死，闽国分裂；福州与建州分立使南唐得以介入并最终灭闽。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王延羲"}]',NULL,NULL,'闽主','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wang-yanzheng','王延政','min-fujian','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','王审知之子，长期镇守建州，与福州王氏政权对立。朱文进被杀后入据福州并称帝，改国号大殷、后复称闽；945年南唐军攻陷建州，王延政出降，闽亡；闽国灭亡后福建纳入南唐版图。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王延政"}]',NULL,NULL,'闽主','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wang-zhaojun','王昭君','han-west','[]',NULL,NULL,-52,1,NULL,'year',-15,1,NULL,'year','["后妃"]','西汉宫人，名嫱，字昭君，南郡秭归人。汉元帝时出塞，与匈奴呼韩邪单于和亲，促进汉匈关系稳定；正史称其为“昭君”，后世文学对其经历多有演绎。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王昭君"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wang-zhi-huan','王之涣','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["诗人"]','盛唐边塞诗人，《登鹳雀楼》《凉州词》作者；《登鹳雀楼》《凉州词》名句流传；确切生卒年月不详，诗作主要由唐人选本保存。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王之涣"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wanyan-aguda','完颜阿骨打','jin-nvzhen','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','女真完颜部首领，金太祖，整合女真诸部后于1114年起兵反辽，次年称帝建金。金军迅速削弱辽朝，并开启与北宋联合灭辽、随后转而攻宋的局面；在位1115—1123年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/完颜阿骨打"}]',NULL,'太祖','金太祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wanyan-chenglin','完颜承麟','jin-nvzhen','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','金哀宗末年在蔡州城破前受禅即位，是金朝最后一位皇帝。其即位当天金军破城，他在巷战中阵亡，金朝至此覆亡；在位1234年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/完颜承麟"}]',NULL,NULL,'金末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wanyan-dan','完颜亶','jin-nvzhen','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','金太宗之侄、金熙宗，在位初期由宗室大臣辅政，随后推行官制与礼制改革、加强皇权。宫廷政争加剧后，他于1149年被完颜亮发动政变弑杀；在位1135—1149年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/完颜亶"}]',NULL,'熙宗','金熙宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wanyan-jing','完颜璟','jin-nvzhen','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','金世宗之孙、金章宗，在位时延续金朝制度与文化建设，重视法令、典章和文学艺术。其后期黄河水患、财政压力及对外冲突增多，盛世基础渐受侵蚀；在位1189—1208年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/完颜璟"}]',NULL,'章宗','金章宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wanyan-liang','完颜亮','jin-nvzhen','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','金太祖之孙、金海陵王，以政变夺位后强化中央集权，并于1153年迁都燕京（中都）。他发动南征宋朝，采石之战受挫后遭军中政变杀害；在位1150—1161年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/完颜亮"}]',NULL,NULL,'海陵王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wanyan-sheng','完颜晟','jin-nvzhen','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','金太祖之弟、金太宗，继位后攻灭辽朝，并在靖康之变中攻陷开封、俘虏宋徽宗与宋钦宗。金朝由东北政权扩张至华北，在位1123—1135年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/完颜晟"}]',NULL,'太宗','金太宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wanyan-shouxu','完颜守绪','jin-nvzhen','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','金宣宗之子、金哀宗，在蒙古持续进攻下辗转防守，曾尝试联合南宋抗蒙而未能扭转战局。蔡州被围时传位于完颜承麟，随后自缢，金朝灭亡；在位1223—1234年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/完颜守绪"}]',NULL,'哀宗','金哀宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wanyan-xun','完颜珣','jin-nvzhen','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','金世宗之孙、金宣宗，政变后即位，面对蒙古大军围攻中都，于1214年迁都南京（开封）。南迁虽暂避兵锋，却引发金与南宋冲突，蒙古持续南侵使金朝战略处境恶化；在位1213—1223年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/完颜珣"}]',NULL,'宣宗','金宣宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wanyan-yong','完颜雍','jin-nvzhen','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','金太祖孙、金世宗，在海陵王南征时于辽阳起兵，被拥立为帝。即位后结束南征，与南宋议和，整顿吏治并恢复经济，后世以“大定之治”称其朝；在位1161—1189年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/完颜雍"}]',NULL,'世宗','金世宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wanyan-yongji','完颜永济','jin-nvzhen','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','金世宗之子、金卫绍王，章宗无子而由其继位，朝廷权力受到权臣掣肘。蒙古崛起并进攻金境，完颜珣政变后将其处死；在位1208—1213年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/完颜永济"}]',NULL,NULL,'卫绍王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wei-bao','魏豹','han-gengshi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["诸侯"]','魏王豹，秦末复立魏国，楚汉间反复，终为韩信所灭。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏王豹"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wei-hou','韦后','tang','[]',NULL,NULL,644,1,NULL,'year',710,7,NULL,'month','["皇后","政治家"]','唐中宗皇后。中宗复位后参与朝政并任用韦氏亲属；710年中宗去世后，临淄王李隆基等发动政变，韦后在宫中被杀，韦氏势力随之瓦解。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韦皇后"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wei-qing','卫青','han-west','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','西汉名将，字仲卿，河东平阳人，为卫子夫之弟。汉武帝时多次率军出击匈奴，收复河南地并深入漠北，官至大司马大将军；其外甥霍去病亦为名将。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫青"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wei-r1','击','wei-warring','[]','姬','魏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','文侯之子，武侯。吴起奔楚，秦攻韩赵而未全力救，国势有损，霸业渐衰，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏武侯"}]','武侯',NULL,'魏武侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wei-r2','罃','wei-warring','[]','姬','魏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','惠成王，迁都大梁。桂陵、马陵惨败，又遭秦齐夹击，魏国由盛转衰，无力争霸，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏惠成王"}]','惠成王',NULL,'魏惠成王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wei-r3','嗣','wei-warring','[]','姬','魏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','襄王，在位二十二年。魏国已非战国强国，无力争霸，国势转衰，割地求和，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏襄王"}]','襄王',NULL,'魏襄王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wei-r4','遫','wei-warring','[]','姬','魏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','昭王，在位十八年。秦国屡攻魏国，割地求和，国势日衰，濒临灭亡，事迹载于《史记》相关记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏昭王"}]','昭王',NULL,'魏昭王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wei-r5','圉','wei-warring','[]','姬','魏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','安僖王，在位三十三年。魏国沦为秦国附庸，割地求和，国势危急，濒临灭亡，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏安僖王"}]','安僖王',NULL,'魏安僖王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wei-r6','午','wei-warring','[]','姬','魏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','景湣王，在位十四年。秦国攻魏取地，魏国奄奄一息，濒临灭亡，无力抵抗，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏景湣王"}]','景湣王',NULL,'魏景湣王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wei-r7','假','wei-warring','[]','姬','魏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','魏国末代君主。前225年秦灭魏，国亡，魏国历史终结，姬姓魏国不复存在，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/假"}]',NULL,NULL,'假','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wei-wen','斯','wei-warring','[]','姬','魏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','尊师重道，任用李悝、吴起改革，灭中山。魏国率先强盛，为战国初霸，国势巅峰，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏文侯"}]','文侯',NULL,'魏文侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wei-zheng','魏征','tang','[]',NULL,NULL,580,1,NULL,'year',643,1,NULL,'year','["政治家"]','唐太宗时名相，以直言敢谏著称，为贞观之治奠基；唐太宗曾命人整理其谏议；魏征死后太宗一度撤毁墓碑，后来又恢复。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏征"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wei-zhongxian','魏忠贤','ming','[]',NULL,NULL,1568,1,NULL,'year',1627,1,NULL,'year','["政治家"]','明末权阉，天启朝专权，东林党争对手，后自缢；他控制东厂并打击东林党人，崇祯即位后失势，在逮捕途中自缢。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏忠贤"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('weiguo-r0','封','wei-weiguo','[]','姬','卫',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','周武王弟封，康叔，封于卫镇抚殷遗民，为卫国开国君主，世系为周王室同姓分支，事见《史记》本国世家记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫康叔"}]','康叔',NULL,'卫康叔','[]');
