INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wu-qi','吴起','wei-warring','[]',NULL,NULL,-440,1,NULL,'year',-381,1,NULL,'year','["军事家","政治家"]','战国初期军事家、政治家，先后仕鲁、魏、楚。任魏西河守时治军拓地，入楚后任令尹，推行变法、整顿贵族与官制；楚悼王死后遭旧贵族杀害。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吴起"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wu-r0','乘','wu-chunqiu','[]','姬','姑发',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','吴国始称王者，在位时屡伐楚国，开吴国争霸之业，国势渐强，为后世霸业奠基，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吴王寿梦"}]',NULL,NULL,'寿梦','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wu-r1','遏','wu-chunqiu','[]','姬','姑发',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','寿梦之子，依遗命实行兄终弟及。战死传位弟余祭，吴国继续扩张，国势强盛，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吴王诸樊"}]',NULL,NULL,'诸樊','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wu-r2','余祭','wu-chunqiu','[]','姬','姑发',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','诸樊之弟，在位仅三年。继续实行兄终弟及，传位余昧，国势平稳，维持扩张，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吴王余祭"}]',NULL,NULL,'余祭','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wu-r3','余眛','wu-chunqiu','[]','姬','姑发',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','余祭之弟，在位十六年。兄终弟及末代，传位诸樊子僚，吴国政局动荡不安，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吴王余昧"}]',NULL,NULL,'余昧','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wu-r4','僚','wu-chunqiu','[]','姬','姑发',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','诸樊之侄，在位十一年。遭公子光（阖闾）刺杀，吴国权力更迭，政局动荡，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吴王僚"}]',NULL,NULL,'僚','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wu-xian','巫咸','shang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家","学者"]','太戊时大臣，与伊陟并治；后世亦传为巫师、星历之祖。生卒年不可考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/巫咸"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wu-zetian','武则天','zhou-wu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','武则天原为唐太宗才人，后成为唐高宗皇后；高宗晚年参与处理政务，683年后先后以太后身份临朝。690年改国号周、称帝，是中国历史上唯一正式称帝的女性；在位期间延揽官员、强化中央统治并尊崇佛教。705年神龙政变后退位，唐中宗复位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/武则天"}]',NULL,NULL,'武曌','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wu-zixu','伍子胥','wu-chunqiu','[]',NULL,NULL,-559,1,NULL,'year',-484,1,NULL,'year','["军事家","政治家"]','楚人，助吴王阖闾破楚入郢，后被夫差赐死；夫差听信伯嚭谗言，令其自尽并投尸江中；其故事成为忠谏遭谗的典故。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/伍子胥"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wuheti','乌纥提','tuyuhun','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','大单于，吐谷浑中期君主。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/乌纥提"}]',NULL,NULL,'大单于','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wujie-kehan','乌希特勤','huihu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["可汗","君主"]','亦称乌介特勤，840年南逃，唐封乌介可汗，846年被杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/乌介可汗"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xi-jinping','习近平','prc','[]',NULL,NULL,1953,6,NULL,'month',NULL,NULL,NULL,NULL,'["政治家"]','2013年3月14日当选国家主席，其后连任。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/习近平"},{"label":"交接日期复核来源","url":"https://newyork.china-consulate.gov.cn/xw/201303/t20130314_4246479.htm"}]',NULL,NULL,'国家主席','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xi-nuoluo','细奴逻','nanzhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','蒙舍诏首领，蒙姓，649年即位，谥奇嘉王，庙号高祖。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/细奴逻"}]','奇嘉王','高祖','诏王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xia-wanchun','夏完淳','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["诗人","抗清人物"]','明末诗人、抗清人物，字存古，松江华亭人，父夏允彝抗清殉难后继续起兵。被清军俘获时年仅十七岁，拒绝降清而死；诗文留下明末士人的亡国感受。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/夏完淳"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiahou-yuan','夏侯渊','wei','[]',NULL,NULL,NULL,NULL,NULL,NULL,219,1,NULL,'year','["将领"]','东汉末至三国曹魏将领，字妙才，沛国谯人，曹操族弟。长期镇守关中、凉州及汉中，定军山之战中遭刘备军突袭阵亡；以善于长途奔袭著称。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/夏侯渊"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiang-liang','项梁','chu-west','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["起义领袖","将领"]','项羽叔父，会稽起兵反秦，立楚怀王，战死于定陶；率项氏部众起兵反秦并拥立楚怀王，前208年在定陶遭秦军夜袭战死。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/项梁"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiang-yu','项羽','chu-west','[]',NULL,NULL,-232,1,NULL,'year',-202,1,NULL,'year','["霸王","军事家"]','西楚霸王，巨鹿破秦军，垓下败于刘邦后自刎。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/项羽"}]',NULL,NULL,'西楚霸王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-baojuan','萧宝卷','qi-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','萧鸾之子，499—501年在位。其猜忌诛杀大臣引发各地叛乱，雍州刺史萧衍起兵攻入建康，萧宝卷被杀，南齐政权随之崩解。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧宝卷"}]',NULL,NULL,'东昏侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-baorong','萧宝融','qi-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','萧鸾之子，501年由萧衍拥立于江陵，次年迁至建康并禅位。502年萧衍受禅建梁，南齐结束。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧宝融"}]','和帝',NULL,'齐和帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-cha','萧詧','xiliang','[]',NULL,NULL,519,1,NULL,'year',562,2,NULL,'month','["皇帝"]','梁武帝萧衍之孙、昭明太子萧统第三子，因父未继储位而长期经营襄阳。侯景之乱后，他与兄萧誉、梁元帝萧绎失和，转而依附西魏；江陵陷落后，西魏于555年立他为梁主，置江陵防主控制其政权。萧詧在位至562年，西梁疆域受限，终身处于西魏宗主权下。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧詧"}]','宣皇帝','中宗','梁宣帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-chuo','萧绰','liao','[]',NULL,NULL,953,1,NULL,'year',1009,1,NULL,'year','["政治家"]','辽景宗皇后，圣宗朝萧太后，摄政多年，与宋订澶渊之盟；与宋订立澶渊之盟，确立辽宋长期和平边界；辽史记其辅佐圣宗并参与军政。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧绰"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-cong','萧琮','xiliang','[]',NULL,NULL,558,1,NULL,'year',607,1,NULL,'year','["皇帝"]','萧巋之子，585年继位为西梁末帝，年号广运。西梁国力受隋控制；587年叔父萧岩等出奔陈朝后，隋文帝召萧琮入朝并废其国，封莒国公。入隋后他历任显职，隋炀帝即位后改封梁公，607年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧琮"}]','孝靖皇帝',NULL,'梁孝靖帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-daocheng','萧道成','qi-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','出身兰陵萧氏，历仕刘宋并凭平定内乱掌握禁军，479年受禅建南齐，在位至482年。即位后裁减冗官、整顿朝政，奠定萧氏王朝基础。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧道成"}]','高皇帝','太祖','齐高帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-defei','萧德妃','beiliao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["后妃","政治家"]','耶律淳妃，耶律淳死后临朝称制，北辽旋亡；金军攻取燕京后她与耶律大石离开，后来归附天祚帝并被杀，北辽后续划分有争议。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧德妃"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-dong','萧栋','liang-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','萧统之孙、豫章王萧欢之子，551年被侯景从禁中拥立为帝。侯景旋即废其为淮阴王并囚禁；梁宗室随后继续拥兵争位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧栋"}]',NULL,NULL,'梁废帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-fangzhi','萧方智','liang-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','萧绎之侄，555年在江陵一度受西魏扶立，后由陈霸先迎立于建康，在位至557年。陈霸先受禅建陈，南梁正式结束。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧方智"}]','敬帝',NULL,'梁敬帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-gang','萧纲','liang-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','萧衍第三子，549年侯景攻陷建康后被拥立，在位至551年。侯景为巩固控制废黜并杀害他，梁廷此后沦为侯景操纵的傀儡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧纲"}]','简文帝',NULL,'梁简文帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-he','萧何','han-west','[]',NULL,NULL,-257,1,NULL,'year',-193,1,NULL,'year','["政治家"]','汉初相国，定都长安、制律令，与韩信、张良并称三杰；刘邦入关后保护秦朝图籍，为汉初掌握户籍、地理和郡县资料提供基础。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧何"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-kui','萧巋','xiliang','[]',NULL,NULL,542,1,NULL,'year',585,5,NULL,'month','["皇帝"]','萧詧之子，562年承袭西梁君位，在位二十三年，改用天保年号。西梁依附西魏、北周，后又与隋保持婚姻和朝贡关系；隋文帝曾为晋王杨广纳其女为妃。萧巋于585年去世，太子萧琮继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧巋"}]','孝明皇帝','世宗','梁明帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-luan','萧鸾','qi-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','齐高帝侄、齐武帝堂弟，494年废杀萧昭文后即位，在位至498年。为巩固旁支统治大肆诛戮高帝、武帝子孙，造成南齐宗室凋敝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧鸾"}]','明皇帝','高宗','齐明帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-tabuyan','萧塔不烟','xiliao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝","政治家"]','耶律大石遗孀，西辽感天皇后。大石死后她以摄政者身份维持政权，并在其子耶律夷列成年后交还权力；临朝称制1143—1150年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧塔不烟"}]',NULL,NULL,'感天皇后','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-yan','萧衍','liang-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','南齐宗室将领，平定内乱后于502年受禅建梁，在位至549年。前期推行宽政并崇尚佛教；晚年侯景叛乱攻陷建康，萧衍被困台城而死。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧衍"}]','武皇帝','高祖','梁武帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-yi','萧绎','liang-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','萧衍第七子，先据江陵与侯景及各地梁军相持，552年称帝，在位至555年。西魏军攻陷江陵后将其杀害，梁朝西部核心由此覆灭。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧绎"}]','孝元皇帝',NULL,'梁元帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-ze','萧赜','qi-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','萧道成长子，482—493年在位。其年号“永明”时期朝政相对安定、文化兴盛，但晚年未妥善安排继承，身后引发皇位争夺。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧赜"}]','武皇帝','世祖','齐武帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-zhaowen','萧昭文','qi-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','萧昭业之弟，494年被萧鸾拥立，在位仅数月即遭废黜并被杀。其短暂即位反映南齐宗室权力已由萧鸾掌控。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧昭文"}]',NULL,NULL,'齐海陵王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-zhaoye','萧昭业','qi-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','萧赜之孙、文惠太子萧长懋之子，494年短暂在位。萧鸾以其荒怠为由废杀，另立其弟萧昭文，南齐皇位由此落入旁支。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧昭业"}]',NULL,NULL,'齐郁林王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiaoshoulin-wang','小兽林王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','高句丽君主，名丘夫，迁都平壤前夕。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/小兽林王"}]',NULL,NULL,'小兽林王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xichuan-wang','西川王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','高句丽君主，名药卢，中川王之子。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/西川王"}]',NULL,NULL,'西川王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xie-an','谢安','jin-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','东晋陈郡谢氏政治家，长期隐居东山，后出仕任宰相。淝水之战时主持朝政并协调谢玄等将领迎战前秦，战后谢氏声望大增；其从容应对成为后世典故。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/谢安"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xie-xuan','谢玄','jin-east','[]',NULL,NULL,343,1,NULL,'year',388,1,NULL,'year','["军事家"]','东晋将领，陈郡谢氏成员，谢安侄。受命经营京口、组建北府兵，淝水之战中任前线主将，击败前秦军；此后参与北伐，收复黄河以南多地。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/谢玄"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xin-qiji','辛弃疾','song-south','[]',NULL,NULL,1140,1,NULL,'year',1207,1,NULL,'year','["词人","军事家"]','南宋词人、将领，字幼安，号稼轩，济南历城人。金军南下时在山东起兵，南归后多次上书主张抗金，曾任地方官并整军备战；词作兼有豪放气象与沉郁身世之感。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/辛弃疾"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xingda-wang','新大王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','高句丽君主，名伯固，新大王时期。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/新大王"}]',NULL,NULL,'新大王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiong-zhuang','侣','chu-chunqiu','[]','芈','熊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','穆王之子。初期韬光养晦，后励精图治；邲之战大败晋军，又曾问鼎洛邑，列春秋五霸，前613–前591年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/楚庄王"}]','庄王',NULL,'楚庄王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xu-guangqi','徐光启','ming','[]',NULL,NULL,1562,1,NULL,'year',1633,1,NULL,'year','["科学家","政治家"]','明代科学家，与利玛窦合译几何原本，主持历法改革；他参与翻译《几何原本》前六卷，并主持编修《崇祯历书》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/徐光启"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xu-shichang','徐世昌','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','徐世昌是清末翰林出身的北洋政治人物，与袁世凯关系密切。1918年当选大总统，主张停战与“偃武修文”，但南北分裂、军阀割据未能消弭；1922年直系控制北京后辞职。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/徐世昌"}]',NULL,NULL,'大总统','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xu-shouhui','徐寿辉','song-xu','[]',NULL,NULL,1320,1,NULL,'year',1360,1,NULL,'year','["皇帝"]','罗田人，元末红巾军首领。1351年在蕲水起事称帝，以蕲水为都，后迁汉阳；部众一度扩展至湖广、江西等地，政权称宋，史籍亦称天完。陈友谅掌握军政后挟其东下，1360年在采石被杀。明玉珍后来追谥应天启运献武皇帝、庙号世宗。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/徐寿辉"}]','应天启运献武皇帝','世宗','徐宋世宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xu-xiake','徐霞客','ming','[]',NULL,NULL,1587,1,NULL,'year',1641,1,NULL,'year','["地理学家"]','明代地理学家、旅行家，名弘祖，字振之，南直隶江阴人。自青年起多次远游，考察山川、洞穴与水系，行旅日记由后人整理为《徐霞客游记》，兼具地理观察与文学价值。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/徐霞客"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xuanye','玄烨','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','爱新觉罗·玄烨，顺治帝第三子，清圣祖。亲政后平定三藩、统一台湾，抗击准噶尔并签订《尼布楚条约》，康熙朝国势与疆域进一步发展。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/康熙帝"}]','仁皇帝','圣祖','清圣祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xuanzang','玄奘','tang','[]',NULL,NULL,602,1,NULL,'year',664,1,NULL,'year','["高僧","学者"]','唐代高僧、译经家，俗姓陈，名祎，洛州缑氏人。贞观年间西行求法，历经中亚抵达印度，回国后在长安主持译经并撰《大唐西域记》，推动唯识学传播。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/玄奘"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xue-r1','谷','xue-chunqiu','[]','任',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','春秋薛国国君，任姓，名谷，谥献公。在位始年不详。《左传·昭公三十一年》载夏四月丁巳薛伯谷卒，秋葬薛献公（前511年）。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/薛献公"},{"label":"《左传·昭公三十一年》","url":"https://zh.wikisource.org/wiki/春秋左氏傳/昭公#昭公三十一年"},{"label":"《春秋滕薛杞越莒邾許七國統表》卷三（引《左传》杜注、孔疏）","url":"https://www.shidianguji.com/zh/book/CADAL02030731/chapter/1l6u63jtnvzfq"}]','献公',NULL,'薛献公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xue-r2','定','xue-chunqiu','[]','任',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','薛襄公，薛国君主。在薛（前510年—前498年）在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/薛襄公"}]','襄公',NULL,'薛襄公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xue-r3','比','xue-chunqiu','[]','任',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','公比，薛国君主。在薛（前497年—前497年）在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/薛公比"}]',NULL,NULL,'公比','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xue-r4','夷','xue-chunqiu','[]','任',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','是春秋时代薛国国君，任姓，伯爵，名夷。鲁定公十三年（前497年），薛国人弑杀薛公比，拥立公子夷为君。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/薛惠公"}]','惠公',NULL,'薛惠公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xue-rengui','薛仁贵','tang','[]',NULL,NULL,614,1,NULL,'year',683,1,NULL,'year','["军事家"]','唐代将领，名礼，字仁贵，绛州龙门人。贞观末从军，参与征辽东、讨九姓铁勒及征高句丽，后镇守安东；“白袍将军”等传奇多见于后世演义。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/薛仁贵"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xun-gequan','寻阁劝','nanzhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','异牟寻之子，亦称新觉劝，谥孝惠王，在位仅一年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/寻阁劝"}]','孝惠王',NULL,'南诏王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ya-yanchuo','移地健','huihu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["可汗","君主"]','药罗葛氏，磨延啜次子，唐封英义可汗，后世常称牟羽可汗，引入摩尼教为国教。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/牟羽可汗"}]',NULL,NULL,'英义可汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-huiqing','颜惠庆','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["外交家","政治家"]','颜惠庆是外交官、曾任国务总理。1926年段祺瑞离职后，他主持摄政内阁并以国务院名义短暂摄行大总统职权；奉系与国民军争夺北京政权期间，政府权力迅速更替。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/颜惠庆"}]',NULL,NULL,'国务院摄行','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-jiagan','严家淦','roc','[]',NULL,NULL,1905,10,NULL,'month',1993,12,NULL,'month','["政治家"]','严家淦是财政与行政官员，曾任台湾省政府主席、行政院院长及副总统。蒋介石于1975年去世后，他继任总统至1978年；任内支持行政院推动十大建设，并筹设新竹科学工业园区。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/严家淦"}]',NULL,NULL,'领导人','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r1','克','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，名克，西周早期燕侯，通常认为是召公奭之子。琉璃河出土的克罍、克盉铭文记载周王命克为燕侯，并赐予人口与职官；是早期燕国分封的重要见证。具体在位起讫年代失考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕侯克"},{"label":"首都博物馆：克罍及分封燕侯铭文","url":"https://www.capitalmuseum.org.cn/collection/30a9844041e24d919ad497143c9db47b"},{"label":"河南博物院：燕侯旨鼎","url":"https://www.chnmus.net/sitesources/hnsbwy/page_pc/clzl/zlhg/dszhzgdwh/debfzmds/article301959f6691644fd9661d4e7ed7e351f.html"}]',NULL,NULL,'克','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r10','宣侯','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，谥宣侯，在位十三年。春秋前期燕国仍较薄弱，事迹载录甚略，前710–前698年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕宣侯"}]','宣侯',NULL,'燕宣侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r11','桓侯','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，谥桓侯，在位七年。事迹多见世系记载，政事不见详载，前697–前691年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕桓侯"}]','桓侯',NULL,'燕桓侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r12','庄公','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','燕桓侯之后，前690—前658年在位。曾与宋、卫参与拥立王子颓；后来山戎侵燕，齐桓公出兵救援，燕君送齐桓公出境，齐以所至之地赠燕。卒后子襄公继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕庄公"},{"label":"《史记·燕召公世家》","url":"https://zh.wikisource.org/zh-hans/史記/卷034"}]','庄公',NULL,'燕庄公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r13','襄公','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，谥襄公，庄公之子。在位近四十年，燕国仍居东偏小国之列，前657–前618年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕襄公"}]','襄公',NULL,'燕襄公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r14','桓公','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','谥桓，有两段在位：前617–前602年与前372–前362年；或为同名异君，史家有争议。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕桓公"}]','桓公',NULL,'燕桓公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r15','宣公','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，谥宣公，在位十四年。春秋中期燕国仍多赖世系记载，前601–前587年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕宣公"}]','宣公',NULL,'燕宣公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r16','昭公','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，谥昭公，在位十二年，政治军事事迹载录甚略，年代见于《燕世家》，前586–前574年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕昭公"}]','昭公',NULL,'燕昭公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r17','武公','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，谥武公，在位十八年，世系可考而政事少见详载，年代见于《燕世家》，前573–前555年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕武公"}]','武公',NULL,'燕武公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r18','文公','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','燕前文公，燕武公之后，前554—前549年在位，卒后燕懿公继立。《史记·燕召公世家》记其在位六年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕前文公"}]','文公',NULL,'燕文公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r19','懿公','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，谥懿公，在位仅四年，事迹载录甚略，年代见于《燕世家》，前548–前545年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕懿公"}]','懿公',NULL,'燕懿公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r2','旨','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，名旨，西周早期燕侯，见于燕侯旨鼎等青铜器铭文。通常列为克之后的燕君，关于其为克之弟或克之子的关系，学者有不同解释。具体在位起讫年代失考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕侯旨"},{"label":"河南博物院：燕侯旨鼎","url":"https://www.chnmus.net/sitesources/hnsbwy/page_pc/clzl/zlhg/dszhzgdwh/debfzmds/article301959f6691644fd9661d4e7ed7e351f.html"},{"label":"燕国君主列表及所据考古、世系研究","url":"https://zh.wikipedia.org/wiki/燕国#君主列表"}]',NULL,NULL,'旨','[]');
