INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r21','悼公','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，谥悼公，在位六年，事迹载录甚略，年代见于《燕世家》，前535–前529年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕悼公"}]','悼公',NULL,'燕悼公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r22','共公','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，谥共公，在位五年，事迹载录甚略，年代见于《燕世家》，前528–前524年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕共公"}]','共公',NULL,'燕共公','[]');
