INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r28','载','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','名载，谥简公（战国）。在位四十余年，前414–前373年；后被桓公二世所代，事迹载于《燕世家》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕简公"}]','简公',NULL,'燕简公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r3','舞','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，名舞，西周早期燕侯，出土铜器有“匽侯舞”等铭文，传世文献未载其政事。学者据铭文考订其世次；与其他早期燕侯的关系及具体在位起讫年代仍有未明之处。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕侯舞"},{"label":"燕国君主列表及所据考古、世系研究","url":"https://zh.wikipedia.org/wiki/燕国#君主列表"}]',NULL,NULL,'舞','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r30','文公','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','燕后文公，燕桓公之后、燕易王之父，前361—前333年在位。燕国君主世系表将其与春秋时期燕前文公区分；本名失载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕后文公"}]','文公',NULL,'燕后文公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r31','易王','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，谥易王，文公之后。在位时燕与齐争，事迹载于战国史料，前332–前321年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕易王"}]','易王',NULL,'燕易王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r32','哙','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬哙，无谥。听信邹子之等，禅位于相子之，引发内乱，齐国田章破燕，哙死，前320–前314年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/哙"}]',NULL,NULL,'哙','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r33','职','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬职，燕王哙庶兄。流落赵国后复国即位；用乐毅、邹衍等，合五国伐齐，占齐七十余城，前312–前279年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕昭王"}]','昭王',NULL,'燕昭王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r34','惠王','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','谥惠（战国）。疑乐毅而召还，乐毅奔赵；后与齐、秦较量，前278–前271年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕惠王"}]','惠王',NULL,'燕惠王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r35','讙','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬讙，谥武成。在位十二年，燕国国力经昭惠之后已不如前，前270–前258年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕武成王"}]','武成王',NULL,'燕武成王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r36','遇','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬遇，谥孝王（战国）。在位仅三年，事迹载录甚略，年代见于《燕世家》，前257–前255年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕孝王"}]','孝王',NULL,'燕孝王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r37','喜','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬喜，无谥。秦将王翦、李信攻燕，喜逃亡辽东，后被俘处死，燕亡，前254–前222年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/喜"}]',NULL,NULL,'喜','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r4','惠侯','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','燕国西周君主，前864—前827年在位。《史记·燕召公世家》记召公以下九世至惠侯；其在位期间经历周厉王奔彘与共和，周宣王初立时去世，子釐侯继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕惠侯"},{"label":"《史记·燕召公世家》","url":"https://zh.wikisource.org/zh-hans/史記/卷034"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/zh-hans/史記/卷014"}]','惠侯',NULL,'燕惠侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r5','庄','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','燕惠侯之子，名庄，谥釐侯，前826—前791年在位。其二十一年郑桓公初封于郑；在位三十六年而卒，子顷侯继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕釐侯"},{"label":"《史记·燕召公世家》","url":"https://zh.wikisource.org/zh-hans/史記/卷034"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/zh-hans/史記/卷014"}]','釐侯',NULL,'燕釐侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r6','顷侯','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，谥顷侯。事迹在《史记·燕世家》及后世追述中甚略，前790–前767年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕顷侯"}]','顷侯',NULL,'燕顷侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r7','哀侯','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，谥哀侯，在位仅二年。卒后由郑侯继立，事迹载录甚略，前766–前765年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕哀侯"}]','哀侯',NULL,'燕哀侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r8','郑侯','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，谥郑侯。相传在位三十六年，事迹载录甚略，年代见于《燕世家》，前764–前729年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕郑侯"}]','郑侯',NULL,'燕郑侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r9','穆侯','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，谥穆侯，世系所载君主，政事不见详载，年代见于《燕世家》，前728–前711年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕穆侯"}]','穆侯',NULL,'燕穆侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-song','严嵩','ming','[]',NULL,NULL,1480,1,NULL,'year',1567,1,NULL,'year','["政治家"]','嘉靖朝权相，专擅朝政二十年，后遭徐阶等弹劾倒台；徐阶联合言官促成弹劾，严嵩失势后家产被籍没，晚年贫困。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/严嵩"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-xishan','阎锡山','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家","政治家"]','民国时期晋系首领，字百川，山西五台人。长期主政山西，推行地方建设与军事改革，曾任国民政府要职；抗战期间组织晋绥军，内战后赴台湾，1950年病逝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/阎锡山"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-ying','晏婴','qi-chunqiu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','齐国名相，辅佐齐景公；二桃杀三士等事与其相关；他以节俭、善谏和外交辞令闻名，相关言行主要由《晏子春秋》保存。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晏婴"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-zhenqing','颜真卿','tang','[]',NULL,NULL,709,1,NULL,'year',784,1,NULL,'year','["书法家","政治家"]','唐代书法家，颜体创始人，安史之乱中守平原；颜体书法端庄雄健，代表作《祭侄文稿》；晚年拒绝劝降李希烈而遇害。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/颜真卿"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-chu','杨初','chouchi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杨氏宗族成员，337年杀杨毅夺取仇池之位，先后与东晋及后赵交涉并受封仇池公、天水公。355年杨毅之弟杨宋奴派人刺杀杨初；杨初之子杨国随即杀宋奴继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨初_(仇池)"}]',NULL,NULL,'仇池王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-guang','杨广','sui','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','隋文帝与独孤皇后次子，604年继位，在位至618年4月。迁都洛阳、营建贯通南北的运河并增置进士科；三征高句丽及大规模征发引发广泛反抗。617年李渊在长安拥立其孙杨侑，仍尊杨广为太上皇；杨广于618年4月在江都被弑，死讯传至洛阳后，杨侗于6月即位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/隋炀帝"}]','炀皇帝',NULL,'隋炀帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-guifei','杨玉环','tang','[]',NULL,NULL,719,1,NULL,'year',756,1,NULL,'year','["后妃"]','唐玄宗贵妃，名玉环，蒲州永乐人。原为寿王李瑁妃，后入宫受宠；安史之乱中随玄宗西行，马嵬驿兵变后被赐死，具体经过见于唐代史籍与后世文学。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨贵妃"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-guo-chouchi','杨国','chouchi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杨初之子，355年在父亲被杀后诛杀杨宋奴，继承仇池。次年为族中长辈杨俊所杀并取代，杨国在位仅约一年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨国_(仇池)"}]',NULL,NULL,'仇池王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-hao','杨浩','sui','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','隋文帝之孙、秦王杨俊之子。618年宇文化及在江都弑杀杨广后拥立杨浩，作为隋室继统者短暂在位；同年宇文化及废杀杨浩。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨浩"}]',NULL,NULL,'隋秦王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-jian','杨坚','sui','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝","政治家"]','弘农杨氏，北周随国公杨忠之子，历仕北周，宣帝时受遗诏辅政。581年接受北周静帝禅让建立隋朝，589年灭陈统一南北；在位期间整顿官制与律令、推行均田和户籍财政措施，开创开皇时期的稳定与富庶。604年去世后由次子杨广继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨坚"}]','文皇帝','高祖',NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-jun-chouchi','杨俊','chouchi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杨氏宗族长辈，356年杀杨国夺取仇池，接受东晋所授仇池公等封号。其统治约四年，死后由儿子杨世继位；仇池随后仍在东晋与前秦之间维持地方政权。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨俊_(仇池)"}]',NULL,NULL,'仇池王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-longyan','杨隆演','wu-shi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杨行密次子，杨渥死后由徐温拥立。徐温掌握军政，杨隆演先受封吴王，919年建立吴国；其在位期间为权臣控制，死后杨溥继位；吴国名号的确立并未改变徐温掌权的格局。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨隆演"}]',NULL,NULL,'吴王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-maosou','杨茂搜','chouchi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','略阳清水氐人，杨氏部落首领杨飞龙的养子。296年关中齐万年之乱时，杨茂搜率部众退保仇池，自称辅国将军、右贤王，收纳流民并建立前仇池统治。其死后由儿子杨难敌承袭，部落事务又由杨难敌与杨坚头分领。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨茂搜"}]',NULL,NULL,'仇池王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-nandi','杨难敌','chouchi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杨茂搜之子，约317年继承仇池部众，与弟杨坚头分领部曲，驻守下辨一带。刘曜进攻时一度避走晋寿，危机解除后返回仇池；他在位期间周旋于汉赵、东晋等势力之间，死后由儿子杨毅继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨难敌"}]',NULL,NULL,'仇池王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-pu','杨溥','wu-shi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','杨行密之子、杨隆演之弟，徐温死后由徐知诰继续掌权。927年称帝，国号吴；937年徐知诰迫其禅位，吴亡，杨溥被迁居润州并于次年去世；吴的禅代由长期掌权的徐知诰完成，南唐取代杨氏政权。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨溥"}]',NULL,NULL,'吴末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-shangkun','杨尚昆','prc','[]',NULL,NULL,1907,7,NULL,'month',1998,9,NULL,'month','["政治家"]','1988年4月8日当选国家主席，至1993年3月27日卸任。恢复国家主席后唯一一任非中共中央政治局常委担任的国家主席。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨尚昆"}]',NULL,NULL,'国家主席','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-shi','杨时','song-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["思想家"]','北宋学者，字中立，福建将乐人，早年从程颢、程颐问学，后长期讲学并任地方官。程门立雪故事记其与游酢拜访程颐、立雪候教，体现后世对其尊师求学的推重。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨时"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-shi-chouchi','杨世','chouchi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杨俊之子，约360年继承仇池，沿袭向东晋称藩并接受封号的做法。前秦扩张期间仇池受其压力；杨世约370年去世后，儿子杨纂继位，而叔父杨统与之争权，削弱了抵御前秦的能力。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨世_(仇池)"}]',NULL,NULL,'仇池王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-tong','杨侗','sui','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','隋文帝之孙、元德太子杨昭之子。618年杨广死讯传至洛阳后，由留守官拥立；此前长安的杨侑已于同月禅位于李渊。次年王世充废黜并杀害杨侗，隋朝宗室统治至此结束。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨侗"}]',NULL,NULL,'隋越王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-tong-chouchi','杨统','chouchi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','前仇池末期杨氏宗室，史料多记为武都太守，并记载他与杨纂争夺权位。371年前秦攻仇池时，杨统率武都部众降秦。不同史料对其是否曾短暂自立及具体继位次序记载不一。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨统_(仇池)"}]',NULL,NULL,'仇池王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-wo','杨渥','wu-shi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杨行密长子，905年继承淮南节度使之位。徐温、张颢等权臣相争，杨渥试图亲政而遭废杀；杨隆演继位，杨吴实权转入徐氏；徐温成为杨吴实际掌权者，杨氏君主逐渐转为名义统治。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨渥"}]',NULL,NULL,'吴王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-xingmi','杨行密','wu-shi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','庐州人，唐末起兵后任淮南节度使，与孙儒等军阀争夺江淮。控制扬州及淮南后受封吴王，为杨吴奠基；其子杨渥继位，政权由权臣徐温掌握；杨吴以淮南为根基，在五代北方政权更迭中维持江淮独立。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨行密"}]',NULL,'太祖','吴太祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-xiuqing','杨秀清','taiping','[]',NULL,NULL,1823,1,NULL,'year',1856,9,NULL,'month','["政治家","军事家"]','太平天国东王，定都天京后掌军政大权；咸丰六年八月初四（1856年9月2日）天京事变中被北王韦昌辉所杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨秀清"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-yi-chouchi','杨毅','chouchi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杨难敌之子，334年继承仇池势力，向东晋称藩并受封征南将军。仇池内部权力斗争延续，337年被族兄杨初杀害，君位由杨初取得。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨毅_(仇池)"}]',NULL,NULL,'仇池王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-yizhen','杨义贞','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','大理将领杨义贞于1080年发动政变，杀段廉义并短暂称帝。其统治旋即被高氏势力推翻，段寿辉继位；后世君主名录将其列入，但其正统地位有限；在位1080年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨义贞"}]','上明皇帝',NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-you','杨侑','sui','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','隋文帝之孙、元德太子杨昭之子，617年由李渊在长安拥立为帝，尊仍在江都的杨广为太上皇。618年杨广遇弑后，杨侑禅位于李渊，隋朝长安政权结束。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨侑"}]','恭帝',NULL,'隋恭帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-zuan-chouchi','杨纂','chouchi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杨世之子，约370年承袭仇池，曾与叔父杨统争夺权力，并向东晋寻求承认。371年前秦苻坚遣军攻仇池，杨纂在鹫峡战败后投降，被送往长安；前仇池由此结束。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨纂_(仇池)"}]',NULL,NULL,'仇池王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yangyuan-wang','阳原王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','高句丽君主，名平成，安原王长子。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/阳原王"}]',NULL,NULL,'阳原王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yao-chang','姚苌','qin-back','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','羌族首领，曾为前秦将领；淝水之战后于384年起兵，386年称帝建立后秦，385年俘杀苻坚，控制关中并与前秦、西秦争夺陇右。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/姚苌"}]','武昭皇帝','太祖','后秦武昭皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yao-chonghua','重华','wu-di','["舜","虞舜","重华"]','姚',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','帝舜有虞氏。《史记》记其践帝位后三十九年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/舜"}]',NULL,NULL,'舜','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yao-hong','姚泓','qin-back','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','姚兴之子，416年继位；内部宗室冲突削弱国力，刘裕北伐于417年攻陷长安，姚泓出降后被杀，后秦亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/姚泓"}]',NULL,NULL,'后秦末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yao-li-shi','姚里氏','dongliao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["王后","政治家"]','耶律留哥妻，元史立为妃；留哥卒后佩虎符权领其众七年，请以嫡子薛阇袭爵。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/姚里氏"}]',NULL,NULL,'王后','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yao-xing','姚兴','qin-back','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','姚苌之子，394年继位；扩张后秦至关中、陇右及河西东部，提倡佛教并支持鸠摩罗什译经，晚年诸子争权，416年去世后后秦迅速衰弱。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/姚兴"}]','文桓皇帝',NULL,'后秦文桓皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ye-jianying','叶剑英','prc','[]',NULL,NULL,1897,4,NULL,'month',1986,10,NULL,'month','["军事家","政治家"]','元帅。1976年10月与华国锋等粉碎「四人帮」；1978–1983年任全国人大常委会委员长。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/叶剑英"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelang-duotong','多同','yelang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','夜郎侯，汉武帝遣唐蒙通夜郎时在位；《史记》载其国为西南夷最大。在位起讫无通行记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/夜郎"}]',NULL,NULL,'夜郎侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelang-xin','兴','yelang','[]',NULL,NULL,NULL,NULL,NULL,NULL,-27,1,NULL,'year','["君主"]','夜郎王，前27年被邛郿侯陈立所杀，夜郎国亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/夜郎"}]',NULL,NULL,'夜郎王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelu-abaoji','耶律阿保机','liao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','契丹迭剌部首领，辽太祖，整合契丹诸部并扩张其势力，916年称帝，建立辽朝。其统治奠定契丹国家制度与后续经营农耕地区的基础，在位916—926年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律阿保机"}]',NULL,'太祖','辽太祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelu-chun','耶律淳','beiliao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','辽朝宗室，金军南下时在燕京被拥立为帝，建立短暂的北辽政权，与天祚帝所代表的辽廷并存。其去世后北辽迅速失去凝聚力，燕京亦于1122年被金军攻取；在位1122年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律淳"}]',NULL,NULL,'北辽皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelu-dashi','耶律大石','xiliao','[]',NULL,NULL,1087,1,NULL,'year',1143,1,NULL,'year','["皇帝"]','辽太祖后裔，辽亡后率部西行，联结西域势力并于1124年前后建立西辽，号葛儿汗。其政权以巴拉沙衮为中心，控制中亚绿洲与交通要地；在位1124—1143年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律大石"},{"label":"遼史/卷30","url":"https://zh.wikisource.org/wiki/遼史/卷30"}]',NULL,'德宗','西辽德宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelu-deguang','耶律德光','liao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','辽太宗耶律阿保机次子，承继皇位后南下争夺中原，灭后晋并于947年进入汴京。辽军随后北撤，辽朝势力一度深入华北；在位927—947年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律德光"}]',NULL,'太宗','辽太宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelu-gunai','耶律古乃','dongliao','[]',NULL,NULL,1234,1,NULL,'year',1269,1,NULL,'year','["君主"]','耶律收国奴长子，1259年嗣爵；至元六年广宁并入东京，去职同年卒。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律古乃"}]',NULL,NULL,'辽王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelu-hongji','耶律洪基','liao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','辽兴宗之子、辽道宗，长期在位，前期辽宋关系总体延续和平，后期则受宫廷党争及冤狱影响，政治秩序转弱。女真势力在辽东北部兴起，成为辽朝晚期的重要压力；在位1055—1101年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律洪基"}]',NULL,'道宗','辽道宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelu-jing','耶律璟','liao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','辽太宗之子、辽穆宗，承接世宗遇弑后的皇位，长期统治但少有对外扩张。其晚年政局动荡，969年被近侍刺杀，景宗继位；在位951—969年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律璟"}]',NULL,'穆宗','辽穆宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelu-liuge','耶律留哥','dongliao','[]',NULL,NULL,1165,1,NULL,'year',1220,1,NULL,'year','["君主"]','金末契丹将领，1213年称辽王、国号辽，改元天统；拒称帝，蒙古仍封辽王。史称东辽。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律留哥"},{"label":"元史/卷149","url":"https://zh.wikisource.org/wiki/元史/卷149"}]',NULL,NULL,'辽王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelu-longxu','耶律隆绪','liao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','辽景宗之子、辽圣宗，幼年即位，由母亲萧绰摄政；亲政后继续改革官制、整合南北面治理。辽与北宋在澶州交战后缔结澶渊之盟，形成长期和平关系；在位982—1031年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律隆绪"}]',NULL,'圣宗','辽圣宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelu-pusuwan','耶律普速完','xiliao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝","政治家"]','耶律夷列之妹，西辽承天太后，兄长死后以摄政身份掌政。她在宫廷冲突中被处死，耶律直鲁古随后即位；临朝称制1163—1177年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律普速完"}]',NULL,NULL,'承天太后','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelu-ruan','耶律阮','liao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','辽太宗侄、辽世宗，太宗死后在辽军中被拥立，继位引发宗室权力冲突。他在位期间持续应对内部争位与后周压力，951年南征途中被近侍刺杀；在位947—951年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律阮"}]',NULL,'世宗','辽世宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelu-shouguonu','耶律收国奴','dongliao','[]',NULL,NULL,1215,1,NULL,'year',1259,1,NULL,'year','["君主"]','耶律薛阇之子，1238年袭爵，行广宁府路总管军民万户府事，易名石剌。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律收国奴"}]',NULL,NULL,'辽王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelu-sibu','耶律厮不','dongliao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["宗室"]','留哥属下郡王，1216年僭帝号于澄州，国号辽、改元天威，史称后辽；月余被杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律厮不"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelu-xian','耶律贤','liao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','辽世宗之子、辽景宗，在位时任用萧绰等人整顿政务，并在高梁河之战后维持辽宋边境格局。他与皇后萧绰所生的耶律隆绪继位，辽朝由此进入长期稳定发展阶段；在位969—982年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律贤"}]',NULL,'景宗','辽景宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelu-xieshe','耶律薛阇','dongliao','[]',NULL,NULL,1193,1,NULL,'year',1238,1,NULL,'year','["君主"]','耶律留哥嫡长子，1226年袭辽王爵，后行广宁路都元帅府事。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律薛阇"}]',NULL,NULL,'辽王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelu-yanxi','耶律延禧','liao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','辽道宗之孙、辽天祚帝，继位时辽朝已面临女真崛起与内部离心。金军接连攻取辽地，他辗转逃亡并于1125年被俘，辽朝主体政权覆亡；在位1101—1125年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律延禧"}]',NULL,NULL,'辽天祚帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelu-yilie','耶律夷列','xiliao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','耶律大石之子、萧塔不烟之后的西辽君主，承接父辈在中亚建立的统治。其在位期间西辽继续控制七河与河中部分地区；在位1150—1163年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律夷列"}]',NULL,'仁宗','西辽仁宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelu-zhilugu','耶律直鲁古','xiliao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','耶律夷列之子、耶律普速完之后继位，统治西辽后期。乃蛮王子屈出律借婚姻与宫廷政变夺权，直鲁古被废，西辽逐渐走向覆亡；在位1177—1211年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律直鲁古"}]',NULL,NULL,'西辽皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelu-zongzhen','耶律宗真','liao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','辽圣宗之子、辽兴宗，在位期间辽宋维持澶渊之盟，但与西夏的外交及军事关系趋于紧张。其朝廷经历宫廷权力斗争，皇位由长子耶律洪基承继；在位1031—1055年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律宗真"}]',NULL,'兴宗','辽兴宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yeshuntuemur','也孙铁木儿','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','也孙铁木儿，元泰定帝，元武宗之侄，在大都与上都政治势力支持下即位。其朝以稳固蒙古宗王与勋贵为要务；1328年去世后，权臣拥立其子阿速吉八，随即引发两都之战。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元泰定帝"}]',NULL,NULL,'元泰定帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yeyan','叶延','tuyuhun','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','329年确立吐谷浑国号，以父名为氏。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/叶延"}]',NULL,NULL,'吐谷浑王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yi-mouxun','异牟寻','nanzhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','阁罗凤之孙、凤伽异之子，谥孝桓王，复臣于唐。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/异牟寻"}]','孝桓王',NULL,'南诏王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yi-xin','奕訢','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','恭亲王，与慈禧等发动辛酉政变，参与晚清政务；主持总理各国事务衙门，推动同文馆与近代军工建设，参与洋务运动。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/恭親王"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yi-yin','尹','shang','["伊挚","阿衡","保衡"]',NULL,'伊',-1649,1,NULL,'year',-1540,1,NULL,'year','["政治家"]','商初重臣，名挚，有莘氏媵臣出身；辅汤灭夏，历外丙、仲壬、太甲、沃丁。传说曾放太甲于桐宫。生卒年代有争议。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/伊尹"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yi-zhi','陟','shang','[]',NULL,'伊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','伊尹之子，太戊时为相。传说亳有祥桑榖合生，伊陟劝太戊修德，殷道复兴。生卒年不可考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/伊陟"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ying-huhai','胡亥','qin','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','秦二世皇帝，赵高矫诏即位，秦政益暴，终致天下反叛。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦二世"}]',NULL,NULL,'秦二世','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ying-qi','开','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','护送周平王东迁有功，受封诸侯。伐戎建初功，秦国始为一方诸侯，开启霸业之路，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦襄公"}]','襄公',NULL,'秦襄公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ying-quliang','渠梁','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','颁布求贤令，用商鞅变法，迁都咸阳。奠定秦国富强基础，为统一六国铺路，开启霸业新篇。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦孝公"}]','孝公',NULL,'秦孝公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ying-zheng','嬴政','qin','["嬴政","赵政","秦始皇"]','嬴','赵',-259,1,NULL,'year',-210,1,NULL,'year','["皇帝"]','秦始皇帝，灭六国统一天下，建立中国首个大一统中央集权帝国。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦始皇"},{"label":"史記/卷006","url":"https://zh.wikisource.org/wiki/史記/卷006"},{"label":"《史记·秦本纪》","url":"https://zh.wikisource.org/wiki/史記/卷005"},{"label":"秦庄襄王纪日及儒略历换算","url":"https://en.wikipedia.org/wiki/King_Zhuangxiang_of_Qin"}]',NULL,NULL,'始皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ying-ziying','子婴','qin','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','秦末秦王，赵高废二世后立之，刘邦入关后投降，秦朝终结。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦王子婴"}]',NULL,NULL,'秦王子婴','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yingyang-wang','婴阳王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','高句丽婴阳王，名元，与隋、唐对峙。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/婴阳王"}]',NULL,NULL,'婴阳王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yinzhen','胤禛','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','爱新觉罗·胤禛，康熙帝第四子，清世宗。即位后整顿财政，推行摊丁入亩、耗羡归公等政策，实行改土归流并设军机处，加强中央集权。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/雍正帝"}]','宪皇帝','世宗','清世宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yiqi-fangxun','放勋','wu-di','["尧","唐尧","陶唐","伊祁放勋","放勋"]','祁','陶唐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','帝尧陶唐氏，帝喾子，祁姓，名放勋。通行称陶唐氏，后世或作伊祁。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/尧"}]',NULL,NULL,'尧','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yizhu','奕詝','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','爱新觉罗·奕詝，道光帝第四子，清文宗。咸丰朝爆发太平天国运动，清廷又在第二次鸦片战争中战败；英法联军攻入北京后，他避居热河并于1861年病逝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/咸丰帝"}]','显皇帝','文宗','清文宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yongyan','颙琰','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','爱新觉罗·颙琰，乾隆帝第十五子，清仁宗。亲政后诛和珅，镇压白莲教起义；其后清廷财政、吏治与边防问题逐渐加重。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/嘉庆帝"}]','睿皇帝','仁宗','清仁宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yu-qian','于谦','ming','[]',NULL,NULL,1398,1,NULL,'year',1457,2,NULL,'month','["政治家","军事家"]','明代政治家、军事家，字廷益，钱塘人。土木堡之变后主持北京防务，组织军民击退瓦剌军并稳定明廷；英宗复辟后以谋逆罪被杀，后获平反，谥忠肃。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/于谦"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yu-yunwen','虞允文','song-south','[]',NULL,NULL,1110,1,NULL,'year',1174,1,NULL,'year','["军事家","政治家"]','南宋政治家、将领，字彬甫，隆州仁寿人。绍兴三十一年金军南下时，他以文臣身份赴采石督师，组织宋军击退金军渡江攻势；后历任宰执，参与南宋军政事务。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虞允文"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-bao-ju','元宝炬','wei-west','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','元愉之子，535年由宇文泰拥立于长安，成为西魏首帝，在位至551年。西魏政务和军队主要由宇文泰掌握；其子元钦继位后与权臣冲突。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元宝炬"}]','文皇帝',NULL,'魏文帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-chonghuan','袁崇焕','ming','[]',NULL,NULL,1584,1,NULL,'year',1630,1,NULL,'year','["军事家"]','明末督师，宁远大捷、宁锦大捷，后被崇祯冤杀；崇祯帝因反间传闻将其下狱处死，后经平反追谥襄愍。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/袁崇焕"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-hong','元宏','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','拓跋弘之子，471—499年在位，史称孝文帝。亲政后迁都洛阳，推行改汉姓、改服制与官制等改革，推动北魏统治中心及鲜卑贵族深度转型。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏孝文帝"}]','孝文皇帝','高祖','魏孝文帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-ke','元恪','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','元宏之子，499—515年在位，史称宣武帝。延续洛阳朝廷与对南朝的军事行动，晚年外戚、高门势力上升；死后幼子元诩继位，胡太后临朝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏宣武帝"}]','宣武皇帝',NULL,'魏宣武帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-lang','元朗','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','北魏宗室安定王元朗，531年由高欢拥立，在位至532年。高欢击败尔朱氏后改立孝文帝之孙元修，元朗被废；北魏政权此后由高欢掌控。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元朗"}]','节闵帝',NULL,'魏节闵帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-qin','元钦','wei-west','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','元宝炬长子，551年继位，史称西魏废帝，在位至554年。试图摆脱宇文泰控制并谋杀其亲信，事泄后被废杀，弟元廓继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元钦"}]',NULL,NULL,'魏废帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-shan-jian','元善见','wei-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','元亶之子，534年高欢迁都邺城后拥立为帝，东魏唯一皇帝，在位至550年。政令长期受高欢父子控制，550年高洋逼其禅位，东魏亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏孝静帝"}]','孝静皇帝',NULL,'魏孝静帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-shao','袁绍','han-east','[]',NULL,NULL,154,1,NULL,'year',202,6,NULL,'month','["军阀"]','东汉末军阀，字本初，汝南汝阳人，出身汝南袁氏。董卓乱政后参与关东联军，控制冀、青、并等州；官渡之战败于曹操，202年病逝，袁氏势力随后瓦解。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/袁绍"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-shi-xiaoming-daughter','元氏','wei-north','["元姑娘","孝明帝之女","女帝元氏"]',NULL,NULL,528,1,NULL,'year',NULL,NULL,NULL,NULL,'["皇帝"]','孝明帝元诩与潘充华之女，姓名失载。528年孝明帝死后，胡太后以皇子名义立她为帝，旋即承认其为皇女，改立临洮王世子元钊；此后事迹失载。','[{"label":"维基百科：孝明帝之女","url":"https://zh.wikipedia.org/wiki/元氏_(魏孝明帝女)"},{"label":"《资治通鉴》卷152","url":"https://zh.wikisource.org/zh-hans/資治通鑑/卷152"},{"label":"《魏书》卷13·皇后列传","url":"https://zh.wikisource.org/zh-hans/魏書/卷13"}]',NULL,NULL,'女帝元氏','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-shikai','袁世凯','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家","军事家"]','袁世凯出身淮军系统，晚清历任要职并参与新军建设。辛亥革命后接任临时大总统，1913年正式就任；其政府镇压二次革命、解散国民党，1915年称帝引发护国战争，次年取消帝制并去世，北洋政府权力随之分散。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/袁世凯"}]',NULL,NULL,'大总统','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-xiu','元修','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','元宏之孙，532年由高欢拥立，史称孝武帝。534年与高欢决裂后西奔长安投宇文泰；北魏由此分为东魏、西魏，元修次年被宇文泰杀害。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏孝武帝"}]','孝武皇帝',NULL,'魏孝武帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-xu','元诩','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','元恪之子，515—528年在位，史称孝明帝。即位后由生母胡太后临朝，成年后试图收回权力；528年胡太后与郑俨、徐纥合谋将其毒杀，尔朱荣借机发动河阴之变。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏孝明帝"},{"label":"《资治通鉴》卷152","url":"https://zh.wikisource.org/zh-hans/資治通鑑/卷152"},{"label":"《魏书》卷13·皇后列传","url":"https://zh.wikisource.org/zh-hans/魏書/卷13"}]','孝明皇帝',NULL,'魏孝明帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-ye','元晔','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','北魏宗室长广王，尔朱世隆等人在530年拥立为帝，在位至531年。高欢起兵反尔朱氏后，元晔被废并遭软禁，随后由元朗被拥立。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元晔"}]',NULL,NULL,'魏长广王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-zhao','元钊','wei-north','["北魏幼主","魏幼主"]',NULL,NULL,526,1,NULL,'year',528,5,17,'day','["皇帝"]','临洮王元宝晖之子、孝文帝元宏曾孙。528年孝明帝死后，胡太后先立皇女，旋改立年幼的元钊，继续临朝。尔朱荣拥立元子攸并进军洛阳，同年在河阴将元钊与胡太后沉入黄河。','[{"label":"维基百科：元钊","url":"https://zh.wikipedia.org/wiki/元钊"},{"label":"《资治通鉴》卷152","url":"https://zh.wikisource.org/zh-hans/資治通鑑/卷152"},{"label":"《魏书》卷13·皇后列传","url":"https://zh.wikisource.org/zh-hans/魏書/卷13"}]',NULL,NULL,'魏幼主','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-zi-you','元子攸','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','元勰之子，528年在尔朱荣扶立下即位，史称孝庄帝。亲政后于530年诛杀尔朱荣，却很快被尔朱氏势力拘捕并杀害，北魏朝廷进一步失控。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏孝庄帝"},{"label":"《资治通鉴》卷152","url":"https://zh.wikisource.org/zh-hans/資治通鑑/卷152"},{"label":"《魏书》卷10·孝庄纪","url":"https://zh.wikisource.org/zh-hans/魏書/卷10"}]','孝庄皇帝',NULL,'魏孝庄帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yue-fei','岳飞','song-south','[]',NULL,NULL,1103,1,NULL,'year',1142,1,NULL,'year','["军事家"]','南宋将领，字鹏举，相州汤阴人。金军南侵时组织岳家军，收复襄汉并在郾城等地作战；主张继续抗金，后遭秦桧等构陷，被宋高宗赐死于临安大理寺狱。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/岳飞"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yue-r10','错枝','yue-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','在位仅两年，为弟所弑。越国内乱频仍，国势继续衰落，无力维持霸主地位，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/错枝"}]',NULL,NULL,'错枝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yue-r11','无余','yue-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','在位十一年，越国继续衰落，无力维持霸主地位，诸侯纷纷自立，国势转弱，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/无余"}]',NULL,NULL,'无余','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yue-r12','无颛','yue-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','在位近二十年，越国内乱不止，诸侯纷纷自立，国势奄奄一息，濒临分裂，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/无颛"}]',NULL,NULL,'无颛','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yue-r13','无彊','yue-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','越国末代君主，无彊。扩张过度，遭楚、齐攻杀，越国分裂，霸业终结，国亡，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/无彊"}]',NULL,NULL,'无彊','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yue-r3','夫谭','yue-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','越国早期君主，夫谭。在位时越国尚弱，处于吴国阴影之下，无力争霸，国势平平，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/夫谭"}]',NULL,NULL,'夫谭','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yue-r4','允常','yue-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','允常，勾践之父。在位时越国与吴国时有争战，国势渐起，为勾践霸业奠基，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/允常"}]',NULL,NULL,'允常','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yue-r6','与夷','yue-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','越王鹿郢，名与夷，又名鹿郢、于赐，勾践之子。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鹿郢"}]',NULL,NULL,'鹿郢','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yue-r7','不寿','yue-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','勾践之子，不寿。在位时吴国已亡，越国内部渐有纷争，国势转衰，无力维持霸业，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/不寿"}]',NULL,NULL,'不寿','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yue-r8','翁','yue-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','越王朱勾，名翁，一作州勾，不寿之子。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱勾"}]',NULL,NULL,'朱勾','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yue-r9','翳','yue-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','迁都琅邪，分封诸子于各地。越国由盛转衰，内乱加剧，诸侯离心，霸业渐失，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/翳"}]',NULL,NULL,'翳','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuwen-huaji','宇文化及','xu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["将领","政治家"]','江都兵变主谋，杀隋炀帝后拥立杨浩。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宇文化及"}]',NULL,NULL,'许帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuwen-jue','宇文觉','zhou-bei','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','宇文泰第三子，557年受西魏恭帝禅位建北周，旋即被权臣宇文护废杀。北周初年皇帝更替频繁，政权实权由宇文护掌握。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周孝闵帝"}]','孝闵帝',NULL,'周孝闵帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuwen-yan','宇文衍','zhou-bei','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','宇文赟之子，579年由父亲禅位即位，史称静帝，在位至581年。年幼而受外戚杨坚控制，581年杨坚受禅建立隋朝，北周灭亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周静帝"}]','静帝',NULL,'周静帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuwen-yong','宇文邕','zhou-bei','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','宇文泰第四子，560年继位，史称武帝，在位至578年。亲政后诛杀宇文护，整顿军政并于577年灭北齐，统一北方；筹备南征期间病逝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周武帝"}]','武皇帝',NULL,'周武帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuwen-yu','宇文毓','zhou-bei','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','宇文泰长子，557年继位，史称明帝，在位至560年。朝政仍由宇文护主导，宇文毓试图削弱其权力，后被宇文护派人毒杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周明帝"}]','明皇帝',NULL,'周明帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuwen-yun','宇文赟','zhou-bei','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','宇文邕长子，578年继位，史称宣帝，在位至579年。即位后迅速传位年幼的宇文阐，自称天元皇帝，仍操控朝政；其死后杨坚掌握辅政权。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周宣帝"}]','宣皇帝',NULL,'周宣帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zaichun','载淳','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','爱新觉罗·载淳，咸丰帝之子，清穆宗。幼年即位，由慈安太后与慈禧太后垂帘听政；同治朝平定太平天国等内乱，实行洋务，1875年病逝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/同治帝"}]','毅皇帝','穆宗','清穆宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zaitian','载湉','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','爱新觉罗·载湉，醇亲王奕譞之子，清德宗。亲政后支持康有为等推行戊戌变法；庚子事变后清廷推进新政，1908年病逝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/光绪帝"}]','景皇帝','德宗','清德宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zeng-guofan','曾国藩','qing','[]',NULL,NULL,1811,1,NULL,'year',1872,1,NULL,'year','["政治家","军事家"]','晚清政治家、军事统帅，初名子城，字伯涵，湖南湘乡人。奉命在湖南编练湘军，镇压太平天国；历任两江总督等职，推动洋务事业，家书与文集广泛流传。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曾国藩"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-chonghua','张重华','liang-front','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','张骏之子，346年继位；年少时由大臣辅政，持续抵御后赵及前秦压力，353年去世后由幼子张耀灵承位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张重华"}]','桓王',NULL,'前凉桓王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-fei','张飞','shu','[]',NULL,NULL,168,1,NULL,'year',221,6,NULL,'month','["将领"]','蜀汉名将，长坂之战掩护刘备撤退，后镇守阆中；被部将范强、张达刺杀后，二人携首级投奔孙权；蜀汉追谥桓侯。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张飞"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-gui','张轨','liang-front','["士彦"]',NULL,NULL,255,1,NULL,'year',314,6,20,'day','["君主"]','安定张氏出身，字士彦。西晋凉州刺史，前凉奠基者；永嘉之乱后保境安民，河西安定。卒谥武公。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张轨"},{"label":"太平御覽/0124","url":"https://zh.wikisource.org/wiki/太平御覽/0124"},{"label":"晉書/卷086","url":"https://zh.wikisource.org/wiki/晉書/卷086"}]','武公',NULL,'前凉武公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-han','章邯','qin','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["将领"]','秦末将领，曾任少府。陈胜起义后率骊山刑徒镇压起义军，击败项梁；巨鹿之战中秦军被项羽击溃后投降项羽，后受封雍王，楚汉战争中败于刘邦。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/章邯"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-he','张郃','wei','[]',NULL,NULL,NULL,NULL,NULL,NULL,231,8,NULL,'month','["将领"]','曹魏名将，字儁乂，河间鄚人。原为袁绍部将，官渡之战后归曹操，参与平定北方及多次对蜀作战；街亭之战击败马谡，后在木门道与蜀军交战中中箭身亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张郃"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-ji','张继','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["诗人"]','中唐诗人，字懿孙，襄州人，天宝年间进士。曾任盐铁判官等职，诗作多有行旅与生活感受，《枫桥夜泊》因“姑苏城外寒山寺”广为传诵。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张继"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-jun','张骏','liang-front','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','张寔之子，324年继位；前凉在其统治下势力扩展至西域和河西诸郡，名义上奉晋，成为张氏政权的强盛时期。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张骏_(十六国)"}]','文王',NULL,'前凉文王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-juzheng','张居正','ming','[]',NULL,NULL,1525,1,NULL,'year',1582,1,NULL,'year','["政治家"]','明神宗首辅，推行考成法、一条鞭法等改革，史称万历中兴；万历初推行考成法、清丈土地与一条鞭法；死后被夺谥籍产，天启年间复名。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张居正"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-liang','张良','han-west','[]',NULL,NULL,-250,1,NULL,'year',-186,1,NULL,'year','["政治家","军事家"]','秦末汉初谋臣，字子房，韩国贵族后裔。曾在博浪沙谋刺秦始皇未成，后辅佐刘邦，鸿门宴上助其脱险并参与楚汉决策；汉朝建立后封留侯，晚年退居。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张良"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-liao','张辽','wei','[]',NULL,NULL,169,1,NULL,'year',222,9,NULL,'month','["将领"]','东汉末至曹魏名将，字文远，雁门马邑人。先后效力丁原、董卓、吕布，归曹操后镇守合肥；逍遥津之战率精骑突击孙权军，成为魏吴战争中的著名战例。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张辽"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-lihua','张丽华','chen-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,589,1,NULL,'year','["后妃","政治家"]','南朝陈后主贵妃，出身寒微，入宫后受陈叔宝宠爱并生育皇子。隋军攻破建康时，她与后主藏入井中后被俘杀害；正史未载其确切生年，后世亦有不同死因叙述。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张丽华"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-mao','张茂','liang-front','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','张寔之弟，320年继掌凉州；沿用晋年号并以晋臣自居，实际维持河西独立统治，修缮姑臧城并经营地方。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张茂_(前凉)"}]','成王',NULL,'前凉成王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-qian','张骞','han-west','[]',NULL,NULL,-164,1,NULL,'year',-114,1,NULL,'year','["外交家"]','西汉外交家，汉中成固人。建元年间奉汉武帝命出使大月氏，途中被匈奴拘留十余年后返汉；后再次出使乌孙，推动汉朝与西域诸国往来，被誉为“凿空”。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张骞"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-sengyou','张僧繇','liang-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["画家"]','南北朝画家，安乐寺画龙点睛传说与其相关；安乐寺画龙点睛故事见唐代《历代名画记》，属于后世传说，画家真迹今已不存。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张僧繇"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-shi','张寔','liang-front','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','张轨之子，张轨死后于314年继掌凉州；承袭父亲保境安民、奉晋正朔的政策，抵御地方叛乱，奠定张氏河西政权。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张寔"},{"label":"太平御覽/0124","url":"https://zh.wikisource.org/wiki/太平御覽/0124"},{"label":"晉書/卷086","url":"https://zh.wikisource.org/wiki/晉書/卷086"}]','昭王',NULL,'前凉昭王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-shicheng','张士诚','zhou-zhang','[]',NULL,NULL,1321,1,NULL,'year',1367,1,NULL,'year','["皇帝"]','泰州盐贩，1353年起兵反元，次年在高邮称诚王、国号周，建元天祐。1356年据平江（今苏州）并以之为中心经营江南，1363年称吴王。朱元璋军围攻平江近一年，城破后张士诚被俘，政权于1367年覆亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张士诚"}]',NULL,NULL,'诚王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-tianxi','张天锡','liang-front','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','张骏之子，363年夺位；前凉在前秦扩张下日益孤立，376年苻坚大军来攻时出降，张氏政权终结。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张天锡_(前凉)"},{"label":"資治通鑑/卷101","url":"https://zh.wikisource.org/wiki/資治通鑑/卷101"}]',NULL,NULL,'前凉末王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-xianzhong','张献忠','daxi','[]',NULL,NULL,1606,1,NULL,'year',1647,1,NULL,'year','["皇帝","起义领袖"]','明末农民军领袖，1644年于成都称帝，国号大西；1647年1月2日战死于西充凤凰山。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张献忠"}]',NULL,NULL,'大西皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-xuanjing','张玄靓','liang-front','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','张重华之子，幼年继位，长期由张天锡等权臣辅政；363年张天锡发动政变，废张玄靓为凉王并将其杀害。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张玄靓"}]','冲王',NULL,'前凉冲王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-xueliang','张学良','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','奉系将领，字汉卿，张作霖之子。1928年张作霖遇刺后接掌东北，宣布东北易帜、归附南京国民政府；1936年与杨虎城发动西安事变，促成国共合作抗日，后长期被软禁。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张学良"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-xun','张巡','tang','[]',NULL,NULL,NULL,NULL,NULL,NULL,757,1,NULL,'year','["军事家"]','唐代将领，字巡，南阳人。安史之乱中坚守睢阳，守城数月以阻叛军南下江淮，至德二载城破被俘遇害；守城事迹见于两《唐书》，后世对其守城中的食人记载亦有讨论。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张巡"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-yanghao','张养浩','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["文学家","政治家"]','元代散曲家、政治家，字希孟，济南人。曾任监察御史、礼部尚书等职，因关中大旱奉命赈灾，亲赴民间救济；散曲《山坡羊·潼关怀古》借古抒怀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张养浩"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-zuo','张祚','liang-front','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','张骏之子，353年废杀侄子张耀灵夺位并称帝；统治失政，355年为张天锡等所杀，前凉恢复张氏宗室继承。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张祚_(前凉)"}]','威王',NULL,'前凉威王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-zuolin','张作霖','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家","政治家"]','张作霖出身东北地方武装，逐步控制奉天并建立奉系，成为北洋后期重要军政领袖。1927年就任陆海军大元帅并在北京行使最高权力；北伐军推进后撤离北京，1928年在皇姑屯遭日军炸车身亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张作霖"}]',NULL,NULL,'陆海军大元帅','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-bing','赵昺','song-south','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','宋度宗之子，端宗赵昰之弟。端宗病逝后，陆秀夫等拥立赵昺于崖山；1279年宋军在崖山海战中覆亡，陆秀夫负帝投海，南宋至此结束。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋帝昺"}]',NULL,NULL,'宋帝昺','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-dun','赵惇','song-south','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','宋孝宗第三子，承父赵昚之位。其在位期间宋金维持和议，朝政受外戚与近臣影响；晚年因与父亲关系失和而禅位于子赵扩，仍尊孝宗为太上皇。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋光宗"}]',NULL,'光宗','宋光宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-gao','赵高','qin','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','秦宦官，矫诏立胡亥，指鹿为马，后被子婴诛杀；秦二世自杀后他企图另立秦王子婴，随后被子婴诱杀于斋宫。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵高"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-gou','赵构','song-south','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','宋徽宗第九子、宋钦宗之弟。靖康之变后在应天府即位，后渡江定都临安，重建宋廷并开启南宋；绍兴和议后与金长期对峙，晚年传位于养子赵昚。岳飞之死发生于其执政时期，和议及相关决策长期影响后世评价。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋高宗"}]',NULL,'高宗','宋高宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-heng','赵恒','song-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','宋太宗第三子、宋真宗，继位后面对辽军南下，1004年与辽订澶渊之盟，确立宋辽长期和平与岁币关系。其朝推行文治并扩充科举，后期政治与财政议题亦渐受关注；在位997—1022年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋真宗"}]',NULL,'真宗','宋真宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-huan','赵桓','song-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','宋徽宗之子、宋钦宗，金军围攻开封时受禅即位，试图议和并组织防务。1127年开封陷落，他与徽宗及宗室被金军俘虏北迁，北宋灭亡；在位1126—1127年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋钦宗"}]',NULL,'钦宗','宋钦宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-ji','赵佶','song-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','宋神宗之子、宋徽宗，在位期间艺术与宫廷文化兴盛，重用蔡京等人并推动新法后续政策。联金攻辽后外交判断失误，金军南下围困开封，他禅位于子赵桓，后在靖康之变中被俘北迁；在位1100—1126年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋徽宗"}]',NULL,'徽宗','宋徽宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-jia-dai','赵嘉','dai-warring','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','代王，代国君主。在代（前228年—前222年）在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/代王嘉"}]',NULL,NULL,'代王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-jiande','赵建德','nanyue','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','南越末代君主，吕嘉所立，前111年汉军灭南越时被俘。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵建德"}]',NULL,NULL,'南越王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-kuangyi','赵光义','song-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','赵匡胤之弟，继位后继续统一战争，灭北汉，使中原与南方大部纳入宋朝统治。其北伐辽朝在高梁河受挫，随后以文官体系和中央集权巩固新王朝；在位976—997年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵光义"}]',NULL,'太宗','宋太宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-kuangyin','赵匡胤','song-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','后周禁军将领，陈桥兵变后受禅称帝，建立北宋并逐步削弱藩镇、整合中央军权。他继续推进统一战争，先后平定荆南、湖南、后蜀及南汉，为宋初统一奠基；在位960—976年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵匡胤"}]',NULL,'太祖','宋太祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-kuo','赵扩','song-south','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','宋光宗之子，1194年继位。其在位时韩侂胄主持开禧北伐，伐金失利后再度议和；宁宗无子，晚年由权臣史弥远拥立宗室赵昀为皇子并继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋宁宗"}]',NULL,'宁宗','宋宁宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-lie','籍','zhao-warring','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','前403年与魏、韩同受周室册封为诸侯，赵国正式立国，定都邯郸，开启战国历史，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵烈侯"}]','烈侯',NULL,'赵烈侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-mo','赵眜','nanyue','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','南越文王，赵佗孙，在位期间与汉朝修好。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵眜"}]',NULL,NULL,'南越文王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-qi','赵禥','song-south','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','宋理宗侄、宋太祖后裔，1264年继位。其在位前期由贾似道掌权，宋廷在蒙古压力下失去襄阳等战略要地；度宗去世后，幼子赵显继位，南宋危局进一步加深。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋度宗"}]',NULL,'度宗','宋度宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-r1','','zhao-warring','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','烈侯之子，武侯。在位十三年，名失考，事迹不详，国势平稳，无力争霸，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵武侯"},{"label":"《史记·赵世家》","url":"https://ctext.org/shiji/zhao-shi-jia/zh"}]','武侯',NULL,'赵武侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-r2','章','zhao-warring','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','敬侯，迁都邯郸，赵国势力东移。在位十二年，国势渐起，为后世霸业奠基，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵敬侯"}]','敬侯',NULL,'赵敬侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-r3','种','zhao-warring','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','成侯，曾与韩魏分晋，俘虏晋君。在位二十五年，国势尚可，无力争霸，事迹载于《史记》相关记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵成侯"}]','成侯',NULL,'赵成侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-r4','语','zhao-warring','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','肃侯，时赵魏大战，赵国中衰。壮志未酬而卒，传位武灵王，国势转弱，事迹载于《史记》相关记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵肃侯"}]','肃侯',NULL,'赵肃侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-r5','雍','zhao-warring','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','推行胡服骑射，灭中山，拓土云中、雁门、代郡。沙丘之乱中被幽禁饿死，赵国由盛转衰，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵武灵王"}]','武灵王',NULL,'赵武灵王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-r6','何','zhao-warring','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','武灵王之子，惠文王。杀忠臣肥义，秦赵长平之战惨败，国力大损，国势危急，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵惠文王"}]','惠文王',NULL,'赵惠文王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-r7','丹','zhao-warring','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','孝成王，在位时赖名将李牧支撑赵国。长平之后赵国元气大伤，国势危急，无力争霸，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵孝成王"}]','孝成王',NULL,'赵孝成王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-r8','偃','zhao-warring','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','悼襄王，在位九年。秦国连破赵国，国势危急，割地求和，濒临灭亡，事迹载于《史记》相关记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵悼襄王"}]','悼襄王',NULL,'赵悼襄王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-r9','迁','zhao-warring','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','幽缪王，赵国末代君主。前228年秦灭赵，公子嘉逃代自立，旋亦亡，赵国终结，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵幽缪王"}]','幽缪王',NULL,'赵幽缪王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-shen','赵昚','song-south','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','宋太祖七世孙，宋高宗养子，1162年受禅继位。其在位时起用主战官员、为岳飞平反，并与金议和，推动战后恢复，史称“乾淳之治”；晚年传位于子赵惇。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋孝宗"}]',NULL,'孝宗','宋孝宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-sheng','赵胜','zhao-warring','["平原君"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','战国赵国宗室，赵武灵王之子，封平原君，以礼贤养士闻名。秦围邯郸时组织守城并赴楚求援，门客毛遂随行促成楚赵合纵；与孟尝君、信陵君、春申君并称战国四公子。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/平原君"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-shi','赵㬎','song-south','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','宋度宗之子，四岁继位。其在位时元军进逼临安，1276年临安陷落后被俘并降元，南宋朝廷随之失去都城；其后被送往北方，南宋遗臣另立端宗、帝昺继续抗元。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋恭帝"}]',NULL,NULL,'宋恭帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-shi-duan','赵昰','song-south','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','宋度宗之子、恭帝赵显之兄，临安失守后由宋室与遗臣拥立。其在位期间朝廷辗转闽粤沿海，在元军追击中退至广东；1278年病逝，群臣拥立其弟赵昺。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋端宗"}]',NULL,'端宗','宋端宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-shu','赵曙','song-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','宋仁宗养子、濮安懿王赵允让之子，仁宗无子而被迎立，是北宋首位以旁支入继的皇帝。其在位仅四年，政务多由重臣处理，死后由子赵顼继位；在位1063—1067年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋英宗"}]',NULL,'英宗','宋英宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-tuo','赵佗','nanyue','[]',NULL,NULL,-240,1,NULL,'year',-137,1,NULL,'year','["君主"]','南越开国君主，秦将，秦亡后据岭南自立，前203年建南越国。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵佗"}]',NULL,NULL,'南越武王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-xing','赵兴','nanyue','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','南越末王之一，赵婴齐之子，年幼即位，为吕嘉所杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵兴"}]',NULL,NULL,'南越王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-xu','赵顼','song-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','宋英宗之子、宋神宗，锐意改变积弱财政与军备，任用王安石推行新法，围绕改革形成持续朝争。对西夏战争未能取得决定性胜利，熙河开边则扩大宋在西北的控制；在位1067—1085年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋神宗"}]',NULL,'神宗','宋神宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-yingqi','赵婴齐','nanyue','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','南越明王，赵眜之子，归汉入朝，卒于长安。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵婴齐"}]',NULL,NULL,'南越明王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-yun','赵昀','song-south','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','宋太祖十世孙，原名赵与莒，由史弥远拥立为宁宗继承人，1224年即位。其在位前期权臣史弥远专政，后与蒙古联手灭金，继而面对蒙古南侵；晚年政务受贾似道影响，南宋国势转危。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋理宗"}]',NULL,'理宗','宋理宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-zhe','赵煦','song-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','宋神宗之子、宋哲宗，幼年继位，由高太后与司马光等主持政务，撤销多项新法，史称元祐更化。亲政后转而恢复神宗时期政策，朝中新旧党争延续；在位1085—1100年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋哲宗"}]',NULL,'哲宗','宋哲宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-zhen','赵祯','song-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','宋真宗之子、宋仁宗，幼年即位，由刘太后临朝，亲政后长期统治。其朝有庆历新政、宋夏战争与庆历和议，文臣政治和文化发展显著；在位1022—1063年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋仁宗"}]',NULL,'仁宗','宋仁宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-zhuo','赵括','zhao-warring','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','战国赵国将领，赵奢之子。长平之战中接替廉颇为主将，改变守势后遭秦军包围；赵括率精锐突围时中秦军射杀，赵军余部随后投降并遭坑杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵括"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-ziyang','赵紫阳','prc','[]',NULL,NULL,1919,10,NULL,'month',2005,1,NULL,'year','["政治家"]','1980年代任国务院总理、中共中央总书记；1989年免职，2005年1月17日逝世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵紫阳"}]',NULL,NULL,NULL,'[]');
