INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-guifei','郑贵妃','ming','[]',NULL,NULL,1565,1,NULL,'year',1630,1,NULL,'year','["后妃"]','万历帝宠妃，梃击案牵连其党，国本之争核心人物；朱常洵封福王后国本之争暂息；郑贵妃与梃击案的关联说法不一。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑贵妃"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-he','郑和','ming','[]',NULL,NULL,1371,1,NULL,'year',1433,1,NULL,'year','["军事家"]','明代航海家，永乐朝率船队七下西洋，沟通中外；船队七下西洋，开展外交、贸易往来，航迹抵达印度洋与东非沿岸。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑和"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-jing','郑经','mingzheng','[]',NULL,NULL,1642,10,NULL,'month',1681,3,NULL,'month','["君主"]','郑成功嫡长子，1662年嗣延平王，据台湾奉永历正朔；1681年卒。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑经"}]','文王',NULL,'延平王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-keshuang','郑克塽','mingzheng','[]',NULL,NULL,1670,1,NULL,'year',1707,1,NULL,'year','["君主"]','郑经之子，1681年嗣延平王；1683年澎湖战败降清，明郑终结。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑克塽"}]',NULL,NULL,'延平王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-r0','友','zheng-chunqiu','[]','姬','郑',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','周宣王封弟友于郑，任周室司徒。前771年犬戎陷镐京，桓公遇害，子掘突继位为武公，郑国迁于中原。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑桓公"}]','桓公',NULL,'郑桓公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-r1','掘突','zheng-chunqiu','[]','姬','郑',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','助平王东迁，与母申侯共灭申国。灭东虢、郐等国，郑国由畿内诸侯转为中原大国，奠定霸业基础。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑武公"}]','武公',NULL,'郑武公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-r10','子兰','zheng-chunqiu','[]','姬','郑',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','文公之子，灵公之弟。弑兄即位，在列国间周旋，维系郑国在中原的存续，国势尚可，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑穆公"}]','穆公',NULL,'郑穆公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-r11','子夷','zheng-chunqiu','[]','姬','郑',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','穆公之子，在位仅一年。因戏弄大夫子家猗指，被弑而亡，郑国再陷内乱，政局不稳，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑灵公"}]','灵公',NULL,'郑灵公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-r12','子坚','zheng-chunqiu','[]','姬','郑',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','灵公之弟，弑兄自立。楚国伐郑，襄公求和割地，郑国国势日衰，仰息于强邻，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑襄公"}]','襄公',NULL,'郑襄公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-r13','沸','zheng-chunqiu','[]','姬','郑',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','在位不足两年，遭兄釐公内乱而被弑，郑国政局继续动荡不安，无力外争，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑悼公"}]','悼公',NULL,'郑悼公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-r14','睔','zheng-chunqiu','[]','姬','郑',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','执政期间郑国夹缝于晋楚之间，多次遣使盟楚，在列国间艰难周旋求存，国势渐弱，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑成公"}]','成公',NULL,'郑成公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-r15','恽','zheng-chunqiu','[]','姬','郑',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','在位五年而卒，末代君主中郑国局面尚可维持，但已无力争霸，仰息于晋楚，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑釐公"}]','釐公',NULL,'郑釐公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-r16','嘉','zheng-chunqiu','[]','姬','郑',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','在位三十五年，郑国已沦为二流小国，仰息于晋楚等强邻之间，无力外争，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑简公"}]','简公',NULL,'郑简公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-r17','宁','zheng-chunqiu','[]','姬','郑',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','孔子弟子子产执政之年，修城施政、作刑鼎，郑国稍得整顿，国势略有回升，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑定公"}]','定公',NULL,'郑定公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-r18','趸','zheng-chunqiu','[]','姬','郑',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','定公之弟，弑兄自立。在位十二年而亡，郑国继续衰落，无力维持大国地位，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑献公"}]','献公',NULL,'郑献公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-r19','胜','zheng-chunqiu','[]','姬','郑',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','在位三十八年，郑国名存实亡，仅守新郑一地，无力外争，仰息于韩等强邻，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑声公"}]','声公',NULL,'郑声公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-r2','寤生','zheng-chunqiu','[]','姬','郑',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','春秋初年第一强国，与周王室「交质」交战。兼并小国、侵夺许国，「多行不义必自毙」典出其事。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑庄公"}]','庄公',NULL,'郑庄公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-r20','易','zheng-chunqiu','[]','姬','郑',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','在位仅七年，为共公之弟所弑，郑国内乱不止，国势奄奄一息，无力维持，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑哀公"}]','哀公',NULL,'郑哀公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-r21','丑','zheng-chunqiu','[]','姬','郑',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','在位三十年，郑国式微，无力外争，仰息于韩等强邻，维持小国局面，事迹载于《史记》相关记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑共公"}]','共公',NULL,'郑共公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-r22','已','zheng-chunqiu','[]','姬','郑',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','在位不足一年，为𦈡公所弑，郑国濒临灭亡，政局极度动荡，国势危急，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑幽公"}]','幽公',NULL,'郑幽公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-r23','骀','zheng-chunqiu','[]','姬','郑',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','弑幽公自立，在位二十七年。郑国已濒临灭亡，无力抵抗韩国，国势危急，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑𦈡公"}]','𦈡公',NULL,'郑𦈡公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-r24','乙','zheng-chunqiu','[]','姬','郑',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','郑国末代君主。前375年为韩武子所灭，国亡，郑国历史终结，姬姓郑国不复存在，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑康公"}]','康公',NULL,'郑康公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-r3','忽','zheng-chunqiu','[]','姬','郑',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','庄公嫡长子，曾作人质于周。两度即位，复位不久即为大夫所弑，郑国内乱加剧，国势转衰。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑昭公"}]','昭公',NULL,'郑昭公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-r4','突','zheng-chunqiu','[]','姬','郑',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','庄公庶子，曾流亡宋国被立为君。两度执政，终为夫人与大夫所弑，政局动荡，郑国衰落，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑厉公"}]','厉公',NULL,'郑厉公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-r6','子亹','zheng-chunqiu','[]','姬','郑',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','厉公之子，在位仅七月。政局动荡，旋即被杀，郑国权力更迭频繁，无力维持稳定局面，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/子亹"}]',NULL,NULL,'子亹','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-r7','婴','zheng-chunqiu','[]','姬','郑',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','厉公幼子，在位十四年。厉公死后复位，国势已远不如庄公时的鼎盛局面，郑国渐衰，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/子婴"}]',NULL,NULL,'子婴','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-r9','踕','zheng-chunqiu','[]','姬','郑',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','在位四十五年，屡侵许国、干预诸侯。曾逐太子建与重耳，招致晋国日后伐郑，国势受损，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑文公"}]','文公',NULL,'郑文公','[]');
