INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhou-guo-jie','揭','zhou-guo-west','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','周考王之弟，封于王城，续周公之职，为西周国始祖。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/西周国"}]','桓公',NULL,'西周桓公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhou-guo-jiu','咎','zhou-guo-west','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','西周末任君，前256年秦攻西周国，纳土降秦后卒。中间武公世系在位年失考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/西周国"}]','文公',NULL,'西周文公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhou-guo-wugong','武公','zhou-guo-west','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','西周惠公长子，承惠公为西周国君，文公之父。《史记·周本纪》及《史记集解》引徐广注可证其世系，但未载本名；部分后世君主表称其名共之，出处未详。在位起讫年无可靠记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/西周武公"}]','武公',NULL,'武公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhou-guo-zao','灶','zhou-guo-west','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','中国历史上的古国名，在今日河南洛陽一帶，战国时期的一个小国。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/西周国"}]','威公',NULL,'西周威公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhou-yu','周瑜','wu','[]',NULL,NULL,175,1,NULL,'year',210,1,NULL,'year','["军事家"]','东汉末孙吴将领，字公瑾，庐江舒人。辅佐孙策平定江东，孙权时任水军统帅；208年赤壁之战与刘备联军击败曹操军，后筹划攻取益州，病逝于巴丘。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周瑜"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhou-ziqi','周自齐','roc','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','周自齐为北洋政府官员，曾任国务总理。黎元洪辞职后，他于1922年短暂以国务院名义摄行大总统职权，直至黎元洪复任；此段反映当时总统职位与内阁更迭的频繁。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周自齐"}]',NULL,NULL,'国务院摄行','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-changluo','朱常洛','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱翊钧长子，长期受册立之争影响，1620年继位。其即位后调整部分父朝旧政，却在位仅约一个月便病逝；围绕其服用红丸及死因的争议成为“红丸案”，由子朱由校继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/明光宗"}]','贞皇帝','光宗','明光宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-de','朱德','prc','[]',NULL,NULL,1886,12,NULL,'month',1976,7,NULL,'month','["军事家","政治家"]','开国元帅。1975年1月17日四届全国人大一次会议当选全国人大常委会委员长，1976年7月6日在任上去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱德"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-di','朱棣','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱元璋第四子，初封燕王，驻守北平。建文帝削藩后起兵，历经靖难之役攻入南京并即位；在位期间迁都北京、经营北方边防，派郑和多次下西洋，并编修《永乐大典》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱棣"}]','文皇帝','成祖','明成祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-gaochi','朱高炽','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱棣长子，长期以太子身份留守北京并监国，1424年继位。其即位后调整永乐时期部分政策，起用士人、减轻刑狱与赋役，力图休养生息；在位不足一年，由子朱瞻基继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱高炽"}]','昭皇帝','仁宗','明仁宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-houcong','朱厚熜','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','兴献王朱祐杬之子，朱厚照无嗣后由宗室入继大统。即位初年围绕生父尊号爆发“大礼议”，其后长期居西苑修道、以严嵩等人理政；在位期间遭遇倭寇侵扰和俺答汗兵临北京的庚戌之变。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱厚熜"}]','肃皇帝','世宗','明世宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-houzhao','朱厚照','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱祐樘长子，十五岁即位。其在位时宠信宦官刘瑾，后亲自出巡并以“威武大将军”等名号活动；1519年宁王朱宸濠叛乱被平定，朱厚照次年无嗣去世，由堂弟朱厚熜入继。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱厚照"}]','毅皇帝','武宗','明武宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-jianshen','朱见深','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱祁镇长子，曾在土木堡之变后被立为太子，父亲复位后恢复储位，1464年即位。其在位时平反于谦冤案、恢复景泰帝名号，同时宠信万贵妃并设西厂；晚年由子朱祐樘继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱见深"}]','纯皇帝','宪宗','明宪宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-qiyu','朱祁钰','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱瞻基次子、朱祁镇之弟。土木堡之变后，群臣拥立其为帝以稳定局势；他组织北京保卫战、任用于谦等人击退瓦剌，后改立太子。1457年朱祁镇复位，朱祁钰不久去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱祁钰"}]','景皇帝','代宗','明代宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-qizhen','朱祁镇','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱瞻基长子，先后两度在位（1435—1449、1457—1464）。首次在位时宦官王振权势上升，1449年亲征瓦剌并在土木堡被俘；弟朱祁钰继位后，他被迎回幽居，1457年经夺门之变复位，随后处死于谦等人。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱祁镇"}]','睿皇帝','英宗','明英宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-wen','朱温','liang-hou','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','原名朱温，参加黄巢起义后降唐，凭宣武军起家并控制唐廷。907年迫唐哀帝禅位称帝，建立后梁、定都开封；在位期间以武力重组藩镇，晚年因继承问题被子朱友珪弑杀；后梁崛起使晚唐藩镇竞争转为五代王朝更迭，与河东李氏的战争成为中原政局主轴。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱温"}]',NULL,'太祖','后梁太祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-wenjin','朱文进','min-fujian','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','闽将，因王延羲猜忌而与连重遇发动政变，杀王延羲后自立为闽主。王氏宗室王延政自建州起兵反攻，朱文进在位仅数月即被杀；短暂掌权未能结束王氏宗室与福州军将之间的冲突。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱文进"}]',NULL,NULL,'闽主','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-yihai','朱以海','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','鲁监国，弘光亡后监国于绍兴，与隆武、永历并立；后入海，1653年去监国号。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱以海"}]',NULL,NULL,'鲁监国','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-yiming','朱翊钧','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱载坖之子，十岁即位，初由李太后与张居正辅政。张居正改革推动整顿吏治、清丈田地与赋税改革；亲政后，明军平定宁夏、播州并援朝抗倭，后期皇帝长期不理朝政，党争与财政危机加剧。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱翊钧"}]','显皇帝','神宗','明神宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-youcheng','朱祐樘','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱见深之子，1487年继位。其在位时整顿吏治、减轻部分赋役，任用王恕等官员，政治相对稳定，后世称“弘治中兴”；他长期专宠张皇后，死后由子朱厚照继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱祐樘"}]','达皇帝','孝宗','明孝宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-yougui','朱友珪','liang-hou','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱温之子，初封郢王。912年发动政变弑父即位，次年遭弟朱友贞与将领袁象先起兵推翻，自杀身亡，后梁政局持续动荡；宫变暴露后梁继承秩序脆弱，也削弱朱氏政权凝聚力。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱友珪"}]',NULL,NULL,'后梁末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-youjian','朱由检','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱常洛第五子、朱由校之弟，1627年即位。其勤于政务但面对后金战争、灾荒、财政枯竭与农民起义，内外交困；李自成军攻入北京后，朱由检于1644年自缢，明朝在北京的统治结束。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/崇祯帝"}]','毅皇帝','思宗','明思宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-youjiao','朱由校','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱常洛长子，十六岁继位。其在位时魏忠贤与客氏势力扩张，东林党争及辽东战事持续；皇帝本人喜好木作，故后世有“木匠皇帝”之称。1627年无子去世，由弟朱由检继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱由校"}]','哲皇帝','熹宗','明熹宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-youlang','朱由榔','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','永历帝，南明末帝，肇庆称帝，与鲁监国、绍武并立，后为吴三桂所害。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/永历帝"}]',NULL,NULL,'永历帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-yousong','朱由崧','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','弘光帝，南明首任，都南京，被俘处死。在南明（1644年—1645年）在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/弘光帝"}]',NULL,NULL,'弘光帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-youzhen','朱友贞','liang-hou','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱温之子，朱友珪死后由开封群臣拥立，在位期间与后唐李存勖长期交战。923年后唐军攻入开封，后梁灭亡，朱友贞自尽；连年败战使后梁失去军队与藩镇支持，朱氏政权建立仅十余年便告覆亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱友贞"}]',NULL,NULL,'后梁末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-yuanzhang','朱元璋','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','濠州钟离人，元末投郭子兴红巾军，逐步建立自己的军队。1356年据集庆（后改应天府），以江南为根基扩张；先后击败陈友谅、张士诚等势力。1364年称吴王，初仍奉韩宋龙凤年号，1367年改用吴年号并遣军北伐；1368年在应天称帝、国号明。即位后整顿赋役与户籍、强化中央集权，后废中书省和丞相制度。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱元璋"},{"label":"《明史》卷一·太祖本纪（吴二年即皇帝位、定国号大明）","url":"https://zh.wikisource.org/zh-hans/明史/卷1"}]','高皇帝','太祖','明太祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-yujian','朱聿键','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','隆武帝，南明，都福州，清军攻汀州时被俘。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/隆武帝"}]',NULL,NULL,'隆武帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-yunwen','朱允炆','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱元璋之孙、皇太子朱标之子，1398年承祖父之位。建文帝推行削藩，引发叔父燕王朱棣起兵的靖难之役；1402年南京失守后下落不明，朱棣即位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/建文帝"}]',NULL,NULL,'建文帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-yuyue','朱聿鐭','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','绍武帝，隆武之弟，1646年广州称帝，与肇庆永历并立，旋为清军所破。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/绍武帝"}]',NULL,NULL,'绍武帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-zaihou','朱载坖','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱厚熜第三子，1567年继位。其在位时起用高拱、张居正等人调整政务，隆庆年间开放海贸并与蒙古俺答部议和互市；死后由十岁的儿子朱翊钧继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱载坖"}]','庄皇帝','穆宗','明穆宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-zhanji','朱瞻基','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱高炽长子，自幼随祖父朱棣参与北征，1425年继位。其在位时与“三杨”等大臣共同理政，延续宽政并整顿边务，形成所谓“仁宣之治”；死后由子朱祁镇继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱瞻基"}]','章皇帝','宣宗','明宣宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhuang-qiao','庄蹻','dian','[]',NULL,NULL,NULL,NULL,NULL,NULL,-256,1,NULL,'year','["君主"]','楚将，入滇称滇王，据滇池，开创滇国世系。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/庄蹻"}]',NULL,NULL,'滇王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhuang-xin','庄辛','chu-chunqiu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','战国楚国大夫，曾任谏官。楚顷襄王亲近佞臣、疏远贤者时，庄辛以“亡羊补牢”等譬喻劝谏；故事见《战国策·楚策》，具体言行带有策士文学色彩。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/庄辛"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhuang-zhou','庄子','song-chunqiu','[]',NULL,NULL,-369,1,NULL,'year',-286,1,NULL,'year','["思想家"]','战国宋国蒙人，名周，道家思想家。曾任漆园吏，拒绝楚威王聘相；其思想与寓言主要见于后世编定的《庄子》，强调顺应自然、逍遥自适。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/庄子"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhuge-liang','诸葛亮','shu','[]',NULL,NULL,181,1,NULL,'year',234,8,NULL,'month','["政治家","军事家"]','三国蜀汉政治家、军事家，字孔明，琅邪阳都人。刘备三顾茅庐后出仕，辅佐建立蜀汉并任丞相；刘备死后主持朝政，多次北伐曹魏，卒于五丈原。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/诸葛亮"}]',NULL,NULL,NULL,'[]');
