INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zou-he','何','zou-state','[]','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','邾子何，邾隐公之子，前471年由越人立为邾君。《左传·哀公二十四年》记其即位；其退位或卒年及后续继承次序无法由该条直接确定。','[{"label":"《左传·哀公二十四年》","url":"https://ctext.org/chun-qiu-zuo-zhuan/ai-gong-er-shi-si-nian/zhs"},{"label":"邾子何","url":"https://zh.wikipedia.org/wiki/%E9%82%BE%E5%AD%90%E4%BD%95"}]',NULL,NULL,'邾子何','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zou-jun-qing','庆','zou-state','[]','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','邾君庆，春秋早期邾君。枣庄东江春秋墓地出土铜壶铭文称“邾君庆作秦妊礼壶”；现代邾器研究据器铭将其列入邾国君主世系。具体在位年份未考。','[{"label":"冯峰：《说“醴壶”》（北京大学中国考古学研究中心）","url":"https://csca.pku.edu.cn/info/1018/1207.htm"},{"label":"张海：《邾器与两周邾邦史事》","url":"https://www.sohu.com/a/469705297_121124388"},{"label":"邾国君主世系图（据《春秋释例》等）","url":"https://zh.wikipedia.org/wiki/邾國君主世系圖"}]',NULL,NULL,'邾君庆','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zou-kaogong','考公','zou-state','[]','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','邾娄考公，传为邾隐公曾孙。《礼记·檀弓下》记徐君遣使来吊其丧；该记载未给出绝对年代，后世对其世代与年代有不同系年。','[{"label":"《礼记·檀弓下》","url":"https://ctext.org/liji/tan-gong-xia/zhs"},{"label":"邾娄考公","url":"https://zh.wikipedia.org/wiki/%E9%82%BE%E5%A8%84%E8%80%83%E5%85%AC"}]','考公',NULL,'邾娄考公','[]');
