INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('agri-bean-introduction','菜豆（四季豆）传入中国','agriculture','point','approximate_year',NULL,NULL,'截图列为明末传入；以17世纪初（1600年）作为明末年代锚点，不代表已考定的首次引入年。',1600,12,NULL,19211,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'菜豆原产中南美洲，明代随美洲作物交流传入中国，后来成为普遍栽培的食用豆类。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('agri-cabbage-introduction','卷心菜（洋白菜）传入中国','agriculture','point','approximate_year',NULL,NULL,'截图列为清代传入；以清代起始年1644年作最早时期锚点，确切引种年未明。',1644,12,NULL,19739,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'卷心菜又称洋白菜或甘蓝，源自欧洲地中海地区，清代经海路传入中国并逐步成为常见蔬菜。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('agri-carrot-introduction','胡萝卜传入中国','agriculture','point','approximate_year',NULL,NULL,'截图列为宋代传入；按宋代起始年960年虽为时期下限，但可核资料称南宋《绍兴本草》已载，取其成书时代起始1127年作为早期见载锚点。',1127,12,NULL,13535,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'胡萝卜原产西亚，宋代已在中国栽培并见于本草记载，后来成为常见根菜。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('agri-cashew-introduction','腰果传入中国','agriculture','point','approximate_year',NULL,NULL,'截图列入明清美洲作物，未给出确年；以明清之际1600年作为所述时期最早年份，表示年代框架而非确切引种年。',1600,12,NULL,19211,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'腰果原产美洲热带地区，随海上贸易传播至亚洲；在中国的引种和规模化栽培较晚，主要适应南方热带地区。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('agri-cauliflower-introduction','花菜传入中国','agriculture','point','approximate_year',NULL,NULL,'清朝农业科技史年表记1895年花椰菜见载；采用该最早明确记载年份。',1895,12,NULL,22751,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'花菜原产地中海地区，近代传入中国。晚清文献开始出现相关记载，此后逐渐成为常见蔬菜。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('agri-champa-rice-introduction','占城稻引入中国','agriculture','point','approximate_year',NULL,NULL,'宋真宗大中祥符五年（1012）遣使福建取占城稻并推广，是目前可核的早期大规模引种节点；本事件取此单年。',1012,12,NULL,12155,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'占城稻由越南中南部传入福建，具有早熟、耐旱等特点。北宋政府取种分发江淮、两浙推广，促进稻作复种和粮食增产。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('agri-cotton-introduction','亚洲棉传入中国','agriculture','point','approximate_year',NULL,NULL,'人民论坛文章将亚洲棉引入置于西汉；按截图标注的最早时期西汉起始年（前202年）作单点，不代表已有精确到年的引种证据。',-202,12,NULL,-2401,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'亚洲棉由印度方向传入中国，早期主要在边疆地区种植；宋元时期种植进一步向中原扩展，明代棉布逐渐成为重要衣料。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('agri-crops-introduction','汉代作物传入','agriculture','point','approximate_year',NULL,NULL,'传统记述将部分作物的传入与汉代西域交流联系起来；具体年代和路线因作物及史料而异。',-138,12,NULL,-1633,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'黄瓜、葡萄、石榴、核桃、大蒜、胡荽、芝麻、苜蓿、胡椒、豌豆、蚕豆、豇豆等作物在汉代前后经陆上交通传播至中国。古代记载将其中若干种与西域交流联系起来；各作物的来源、传播路线和具体传入时间并不相同。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('agri-eggplant-introduction','茄子传入中国','agriculture','point','approximate_year',NULL,NULL,'截图依据《齐民要术》列入魏晋南北朝时期；以该书成书约544年作为可核的早期栽培记载时点。',544,12,NULL,6539,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'茄子可能由南亚经贸易路线传入中国；魏晋南北朝农书《齐民要术》已有栽培记载，表明当时已在中国种植。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('agri-fig-introduction','无花果传入中国','agriculture','point','approximate_year',NULL,NULL,'截图记为魏晋南北朝（一说唐代盛行）；取该时期起始年220年作最早提及的年代锚点，不作为确切引种年。',220,12,NULL,2651,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'无花果原产西亚，魏晋南北朝时期已在中国传播；后世文献和园艺栽培记载逐渐增多。具体最初传入时间仍有不同说法。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('agri-luffa-introduction','丝瓜传入中国','agriculture','point','approximate_year',NULL,NULL,'实际传入年份难以考定。以宋代起始年（960）作为单点年代锚点，仅表示至宋代已见传播与栽培线索，不代表确切首传年。',960,12,NULL,11531,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'丝瓜原产地通常认为在南亚，经陆上或海上交通传入中国南方。丝瓜至迟在宋代已有栽培，宋元时期逐步传播；具体传入年份和路线难以考定。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('agri-onion-introduction','洋葱传入中国','agriculture','point','approximate_year',NULL,NULL,'截图列为清末传入；以清末阶段最早年份1840年作单点，作为年代范围下限。',1840,12,NULL,22091,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'洋葱原产西亚及中亚，经近代贸易传播到中国，晚清后逐渐在各地种植和食用。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('agri-peanut-introduction','花生传入中国','agriculture','point','approximate_year',NULL,NULL,'截图将花生列在明代中后期，并提及16世纪初经东南亚传播；取1500年作为其所述范围的最早年份，不视为确切首传年。',1500,12,NULL,18011,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'花生原产南美洲，明代经海路进入中国，随后逐渐成为重要油料和食用作物。早期引种路线与时间仍有不同说法。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('agri-pineapple-introduction','菠萝（凤梨）传入中国','agriculture','point','approximate_year',NULL,NULL,'截图列为明末由南美传入；按“明末”这一时期的最早年份取1600年作为单点，实际首传年未详。',1600,12,NULL,19211,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'菠萝原产南美洲热带地区，经海路传入亚洲并进入中国南方。此后在岭南、台湾等地逐步栽培。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('agri-potato-introduction','马铃薯传入中国','agriculture','point','approximate_year',NULL,NULL,'农业史年表将马铃薯传入中国记为17世纪中叶；按世纪中叶取1650年单点。',1650,12,NULL,19811,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'马铃薯原产南美洲安第斯地区，明末清初传入中国，之后在西南、华北等地逐渐种植，成为重要的高产粮食作物。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('agri-pumpkin-introduction','南瓜传入中国','agriculture','point','approximate_year',NULL,NULL,'截图列为明代美洲作物；按明代时期最早年份1368年无法证明具体引种，依其明代中后期传播叙述取1500年作最早年代锚点。',1500,12,NULL,18011,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'南瓜原产美洲，随跨洋贸易在明代传入中国，因适应性较强而传播到多地，成为蔬菜和粮食补充。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('agri-spinach-introduction','菠菜传入中国','agriculture','point','approximate_year',NULL,NULL,'农业科技史年表将菠菜传入中国记为646年；采用该早期记载年份。',646,12,NULL,7763,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'菠菜原产西亚，经中亚、尼泊尔等地传播入唐。此后逐渐成为常见绿叶蔬菜。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('agri-strawberry-introduction','现代草莓传入中国','agriculture','point','approximate_year',NULL,NULL,'截图列为近现代引入，未给出更早确年；取1911年作为近现代时期起点的年代锚点，确切首传年需进一步考证。',1911,12,NULL,22943,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'现代栽培草莓由欧洲品种杂交培育而来，近代传入中国后逐步开展栽培，与中国原有野生草莓资源不同。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('agri-sunflower-introduction','向日葵传入中国','agriculture','point','approximate_year',NULL,NULL,'截图将向日葵列在美洲作物输入潮中，未给出确切年份；按明清之际最早阶段取1600年作近似单点。',1600,12,NULL,19211,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'向日葵原产北美洲，明清之际经跨洋贸易传入中国，后逐渐发展为观赏、食用和油料作物。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('agri-watermelon-introduction','西瓜传入中国北方','agriculture','point','approximate_year',NULL,NULL,'农业科技史年表记953年胡桥将西瓜由回纥传入契丹地区；取该最早明确年份。',953,12,NULL,11447,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'西瓜源自非洲，经中亚向东传播。五代时期已有西瓜传入契丹地区的记载，之后逐步进入中原并广泛栽培。',NULL,NULL);
