INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('chengpu','城濮之战','battle','point','year',NULL,NULL,'鲁僖公二十八年，前632年',-632,12,NULL,-7561,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'楚围宋，宋向晋求援。晋先攻曹，因卫拒绝借道，又出兵伐卫；楚将宛春提出复曹、卫以换取楚军解宋围。晋采纳先轸之策，扣留宛春，暗中许诺复曹、卫，借此离间楚与曹、卫；又依晋文公旧诺退避三舍，最终在城濮击败楚军。战后晋复曹、卫，并于践土会盟，确立霸主地位。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('chenqiao-mutiny','陈桥兵变','politics','point','year',NULL,NULL,'显德七年正月初三至初四（960年）；《续资治通鉴长编》等记陈桥拥立与次日入京，按年精度记录。',960,12,NULL,11531,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'后周显德七年，朝廷命殿前都点检赵匡胤率军北上应对北汉、契丹来报。军队行至陈桥驿后拥立赵匡胤，赵随即率军返回开封，后周恭帝柴宗训禅位，赵匡胤建立宋朝。兵变以军队拥立完成政权更替，也开启北宋统一进程。',NULL,NULL);
