INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('civil-war','解放战争','battle','span',NULL,'year','year',NULL,NULL,NULL,NULL,NULL,1946,1,NULL,23352,1949,12,NULL,23399,'国共内战，三大战役后国民党退守台湾，大陆政权更迭。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('commerce-chili-introduction','辣椒传入中国','agriculture','point','approximate_year',NULL,NULL,'具体首传路线和年份未定；现有研究常置于16世纪后期至17世纪前期。按截图所列范围取最早年份1570作单点，表示最早提及的年代而非确切传入年。',1570,12,NULL,18851,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'辣椒原产美洲，随跨洋贸易传入亚洲并进入中国。早期多作观赏或药用植物，之后逐渐进入饮食，在各地形成不同的食用习惯。中国首传的路线和年份尚不能确考。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('commerce-longqing-yuegang-opening','隆庆开海','commerce','point','year',NULL,NULL,'隆庆元年（1567）；采用海澄县志等记载的开港年份。',1567,12,NULL,18815,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'明廷在福建月港有限度开放民间海上贸易，商船可依规出洋，月港成为东南沿海重要贸易港。政策并未废除海禁，走私、朝贡贸易与许可贸易仍交织并存。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('commerce-maize-introduction','玉米传入中国','agriculture','point','approximate_year',NULL,NULL,'1534年《巩县志》有“玉麦”记载，是目前常见的中国早期文献记录之一；以该最早记载年作单点，不等同于实际首次传入年。',1534,12,NULL,18419,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'玉米原产美洲，明代经海路及可能的陆路传入中国。1534年《巩县志》所见“玉麦”是早期记载之一；其耐旱、适应性强，后来在山地和旱地广泛种植。具体首传地点与路线尚有争议。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('commerce-qing-canton-system','广州一口通商','commerce','point','year',NULL,NULL,'乾隆二十二年（1757）政策转折；各口岸执行和限制逐渐落实，不将其解释为所有对外贸易一概中止。',1757,12,NULL,21095,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'清廷将西洋商船贸易集中于广州，外商主要通过广州行商体系交易。广州由此成为清代中西贸易的核心口岸，这一格局延续至鸦片战争前后。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('commerce-qing-maritime-trade-reopened','清廷开海','commerce','point','year',NULL,NULL,'康熙二十三年（1684）解除海禁、设置海关；开放港口的诏令及实施在1685年，事件以政策转折年定位。',1684,12,NULL,20219,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'平定台湾后，清廷解除海禁并设粤、闽、浙、江四海关管理海上贸易与征税；次年开放广州、漳州、宁波、云台山等贸易港。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('commerce-song-guangzhou-shipping-office','广州设市舶司','commerce','point','year',NULL,NULL,'开宝四年（971）；广州博物馆所藏北宋《大宋新修广利王庙之碑》记载平南汉后设司。',971,12,NULL,11663,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'北宋平定南汉后在广州设置市舶司，专门管理海外商船、蕃货和贸易事务。此后宋廷陆续在东南沿海增设机构，海贸成为国家财政与跨区域交流的重要组成。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('commerce-song-tea-horse-trade','茶马互市兴起','commerce','point','year',NULL,NULL,'熙宁七年（1074）被视为宋代茶马制度形成的重要年份；贸易实践和机构调整持续多年。',1074,12,NULL,12899,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'宋廷在四川等地设置茶马贸易机构，以茶换取西北及西南地区所需战马，并以官府专營、茶引等方式管理交易。茶马互市把边疆贸易、軍需供给与区域治理联系起来。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('commerce-sweet-potato-introduction','甘薯经海路传入福建','agriculture','point','approximate_year',NULL,NULL,'福建引种记载有万历十年（1582）、万历十一至十二年及万历二十一年（1593）等说法；按要求取最早提及的1582年，保留不同记载的分歧。',1582,12,NULL,18995,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'甘薯原产美洲，经海上贸易网络传入福建。关于陈益、陈振龙等人的引种时间和路线，地方记载并不一致；甘薯耐瘠、高产，后来成为重要的粮食补充和救荒作物。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('commerce-tobacco-introduction','烟草传入中国','agriculture','point','approximate_year',NULL,NULL,'烟草传入时间有16至17世纪等说；按资料提及的最早年份1540作单点。1624年《景岳全书》回述万历年间闽、广已有烟草，均不能据此断定准确首传年。',1540,12,NULL,18491,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'烟草原产美洲，经菲律宾吕宋及海上贸易网络传入中国，随后由东南沿海向内地传播。早期兼作药用，后来成为广泛种植和消费的经济作物。具体首传年份仍有争议。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('commerce-tomato-introduction','番茄传入中国','agriculture','point','approximate_year',NULL,NULL,'中国首传时间难以确考；1617年周文华《汝南圃史·植品》被用作番茄在华早期名称记载。按该最早文献线索取单点，不视为实际引种年。',1617,12,NULL,19415,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'番茄原产美洲，随海上贸易传播至亚洲并传入中国。中国首传时间和路线未能确证；明代文献中的相关名称提供了早期在华线索，番茄初期较为稀见，后来才普遍成为食用蔬菜。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('convention-of-burma','中英续议滇缅条约','politics','point','month',NULL,NULL,'光绪二十年十二月，中英签订',1894,12,NULL,22739,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'划定滇缅边界，开放蛮耗为商埠，英国进一步渗透西南边疆。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('convention-of-peking','北京条约','politics','point','month',NULL,NULL,'咸丰十年九月，与英法俄签订',1860,10,NULL,22329,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'割九龙司、增赔款、准许英法公使驻京，俄国确认瑷珲条约并割占乌苏里江以东。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('convention-of-sikkim','中英续议藏印条约','politics','point','month',NULL,NULL,'光绪十六年十二月，中英签订',1890,12,NULL,22691,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'隆务关之战后议和，划定藏印边界，承认英国对锡金的保护。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('cultural-revolution','文化大革命','politics','span',NULL,'month','month','1966年5月「五一六通知」至1976年10月粉碎「四人帮」',NULL,NULL,NULL,NULL,1966,5,NULL,23596,1976,10,NULL,23721,'长达十年的政治运动，党和国家领导层与社会秩序受到严重冲击，至粉碎「四人帮」结束。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('dawenkou','大汶口文化','culture','point','approximate_year',NULL,NULL,'约前4300–前2500；一说稍早自前4500，约前2500过渡为龙山。；原不确定范围：-4300年1月至-2500年12月；按既有事件说明转为代表时点。',-3400,1,NULL,-40788,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'以山东泰安大汶口命名，海岱地区新石器文化。陶鬶、拔牙习俗与陶器刻画符号，下接山东龙山文化。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('dayuan-expedition','远征大宛','battle','span',NULL,'approximate_year','approximate_year','太初二年，前103–前101年，李广利两征大宛；原不确定范围：-103年1月至-101年12月；按既有事件说明转为持续区间。',NULL,NULL,NULL,NULL,-103,1,NULL,-1224,-101,12,NULL,-1189,'汉武帝遣军远征大宛，历时三年，终斩其王。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('daze-uprising','大泽乡起义','politics','point','year',NULL,NULL,'秦二世元年七月，前209年',-209,12,NULL,-2485,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'陈胜、吴广揭竿而起，秦末农民战争爆发。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('deng-ai-crosses-yinping','邓艾偷渡阴平','battle','point','month',NULL,NULL,'景元四年冬十月（263年），邓艾自阴平道行军入蜀',263,10,NULL,3165,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'钟会军受阻于剑阁时，邓艾率军由阴平道穿越险阻，进至江油并击败蜀军，迫使蜀汉政权迅速瓦解。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('deng-southern-tour','邓小平南巡','politics','point','month',NULL,NULL,'1992年1–2月视察武昌、深圳、珠海、上海',1992,1,NULL,23904,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'邓小平南方谈话推动新一轮改革开放。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('dian-surrender-han','滇国降汉','politics','point','year',NULL,NULL,NULL,-109,12,NULL,-1285,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'汉武帝元封二年，滇王尝羌率众降汉，设益州郡。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('dingjunshan','定军山之战','battle','point','month',NULL,NULL,'建安二十四年正月，黄忠斩夏侯渊',219,1,NULL,2628,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'黄忠于定军山斩曹魏大将夏侯渊，汉中战局逆转，刘备军占上风。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('dingwu-north-china-famine','丁戊奇荒','disaster','span',NULL,'approximate_year','approximate_year','研究常以1876—1879年概括华北大饥荒，中文“丁戊”指灾情高峰所在的1877、1878年；部分资料将旱象追溯至1875年。此处用概略区间涵盖旱灾发展与灾后缓解，不采用有争议的死亡数字。；原不确定范围：1875年1月至1879年12月；按既有事件说明转为持续区间。',NULL,NULL,NULL,NULL,1875,1,NULL,22500,1879,12,NULL,22559,'晚清华北持续旱灾引发严重饥荒，山西、河南、陕西、直隶、山东等地受灾，灾情在1877—1878年尤重，并波及邻近地区。饥荒造成粮食短缺、人口流徙和大规模赈济；不同研究对灾害起讫及死亡规模的估计不一。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('dong-zhuo-enters-luoyang','董卓进京','politics','point','month',NULL,NULL,'中平六年八月末；按《后汉书·孝灵帝纪》所载少帝等于八月辛未还宫及董卓迎回少帝的记事，取公历189年9月25日为董卓护送少帝返回洛阳的年内节点；9月28日为其废立皇帝之日，不取作进京时间。',189,9,NULL,2276,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'董卓率军进入洛阳并控制朝廷，随后废黜汉少帝刘辩、拥立刘协为帝，东汉皇权由此进一步受制于军阀。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('dongliao-yelu-sibu-rebel','耶律厮不叛乱','politics','point','month',NULL,NULL,'元史太祖十一年丙子（1216年）僭帝号于澄州，改元天威，方阅月被杀',1216,2,NULL,14593,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'耶律厮不僭帝号于澄州，国号辽、改元天威；月余被杀，其后金山、统古与、喊舍相继自立。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('duomen-restoration','夺门之变','politics','point','month',NULL,NULL,'景泰八年正月十七日，石亨等拥英宗复辟',1457,2,NULL,17485,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'石亨、曹吉祥等拥英宗复辟，废景泰帝，于谦被害。',NULL,NULL);
