INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('erlitou','二里头文化','culture','point','approximate_year',NULL,NULL,'2015年AMS：文化早不过前1900、晚不过前1500；一期约前1750，四期约止于前1520。亦作约前1800–前1500。与文献夏朝不能简单等同。；原不确定范围：-1750年1月至-1520年12月；按既有事件说明转为代表时点。',-1640,1,NULL,-19668,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'河南偃师二里头，中原最早的大型都邑之一。宫城、青铜礼器与绿松石龙，是探索夏商分界与早期国家的核心遗存。',NULL,NULL);
