INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('he-jin-killed','何进被杀','politics','point','month',NULL,NULL,'《后汉书·孝灵帝纪》记为中平六年八月戊辰；据该年历日换算为公历189年9月22日。',189,9,NULL,2276,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'大将军何进谋划诛除宦官，计划泄露后被宦官诱杀于宫中。袁绍等率军攻入宫禁，戚宦冲突演变为朝廷武装混战，为董卓控制洛阳创造了局势。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('he-yin-massacre','河阴之变','politics','point','month',NULL,NULL,'528年，尔朱荣在河阴杀害胡太后、幼主元钊并屠杀百官。史书记于农历四月；据元钊条目换算为公历5月，事件整体保留月精度。',528,5,NULL,6340,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'尔朱荣在河阴将胡太后与幼主元钊沉入黄河，随后屠杀北魏王公朝臣两千余人。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('heirloom-seal-lost','传国玉玺失踪','politics','point','approximate_year',NULL,NULL,'传国玺失踪的具体时点与是否毁于火中存在记载差异，取后唐灭亡前后窗口。；原不确定范围：936年1月至937年12月；按既有事件说明转为代表时点。',936,12,NULL,11243,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'后唐末帝李从珂兵败自焚，传统记载称传国玉玺随之失去下落；此后宋太祖受禅时已不见传国玺。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('hemudu','河姆渡文化','culture','point','approximate_year',NULL,NULL,'河姆渡遗址四期碳十四：一期约前5000–前4500，四期约前3600–前3300；亦作前5000–前3000。；原不确定范围：-5000年1月至-3300年12月；按既有事件说明转为代表时点。',-4150,1,NULL,-49788,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'浙江余姚河姆渡，长江下游新石器文化。干栏式建筑、夹炭黑陶与大量栽培稻谷，证明江南史前稻作与定居。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('hengyang-defense','衡阳保卫战','battle','span',NULL,'month','month','1944年6月下旬至8月上旬；按中国第二历史档案馆专题记录。',NULL,NULL,NULL,NULL,1944,6,NULL,23333,1944,8,NULL,23335,'豫湘桂会战期间，日军围攻衡阳以控制粤汉铁路。第十军军长方先觉指挥守军依托工事顽强抵抗，日军多次进攻受挫；援军未能解围、弹药补给断绝后，衡阳于8月上旬失守。长期守城迟滞了日军推进，也成为豫湘桂战局中抵抗最持久的战斗之一。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('hexi-battle','河西之战','battle','point','year',NULL,NULL,'元狩二年，前121年，霍去病两次西进',-121,12,NULL,-1429,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'霍去病大破匈奴，夺取河西走廊，置武威、酒泉等郡。',NULL,NULL);
