INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('hundred-regiments-campaign','百团大战','battle','span',NULL,'month','month','1940年8月20日发起，战役阶段延续至1941年1月；不同战史对阶段划分有差异。',NULL,NULL,NULL,NULL,1940,8,NULL,23287,1941,1,NULL,23292,'为破击华北日军交通线、打击据点封锁，八路军在总部统一指挥下发动大规模进攻，重点攻击正太铁路，并扩展至同蒲、平汉等交通线。战役初期参战部队超过百个团，故称“百团大战”；铁路与据点遭到破坏，日军随后加强报复性“扫荡”，敌后战场的作战形态也随之变化。',NULL,NULL);
