INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-er-tao-sha-san-shi','二桃杀三士','idiom','point','year',NULL,NULL,'齐景公时，约前522年',-522,12,NULL,-6241,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'晏婴献二桃，公孙接、田开疆、古冶子争功，后二人自杀，古冶子亦自刎。','比喻用阴谋借刀杀人，或借小事除掉强者。',NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-fen-dao-yang-biao','分道扬镳','idiom','point','year',NULL,NULL,'北魏孝文帝迁都洛阳后，约493年；典出《北史》',493,12,NULL,5927,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'北魏孝文帝迁都洛阳后，洛阳令元志与御史中尉李彪争道，孝文帝命二人分路而行。','比喻目标不同，各走各的路；也指分道而行。',NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-feng-lang-ju-xu','封狼居胥','idiom','point','year',NULL,NULL,'元狩四年，前119年；典出《史记·卫将军骠骑列传》及《汉书·卫青霍去病传》',-119,12,NULL,-1405,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'汉武帝元狩四年（前119年），霍去病率军深入漠北击败匈奴左部，登狼居胥山祭天、于姑衍山祭地后返师。后世以“封狼居胥”概括这一战功，成为建功边疆的典故。','比喻建立显赫战功，常用来形容将领远征并取得重大胜利。',NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-fu-jing-qing-zui','负荆请罪','idiom','point','year',NULL,NULL,'渑池之会后将相和，约前279年',-279,12,NULL,-3325,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'廉颇闻蔺相如避让之由，负荆请罪，二人结为刎颈之交。','形容主动认错、道歉，请求责罚。',NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-gang-zheng-bu-a','刚正不阿','idiom','point','year',NULL,NULL,'嘉靖四十五年',1565,12,NULL,18791,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'海瑞上《治安疏》骂嘉靖，以刚直闻名。','刚强正直，不逢迎，无偏私。',NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-handan-xue-bu','邯郸学步','idiom','point','year',NULL,NULL,'庄子寓言',-300,12,NULL,-3577,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'《庄子》燕国少年学赵都邯郸之步，未能得能，又失其故步，匍匐而归。','比喻模仿别人不成，反而失去自己原有的技能。',NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-hu-fu-qi-she','胡服骑射','idiom','point','year',NULL,NULL,'赵武灵王十九年，前307年；《史记·赵世家》记其下令招骑射并议胡服。',-307,12,NULL,-3661,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'战国时赵武灵王面对北方游牧势力与中山国的威胁，决定改穿便于骑乘的胡服并训练骑射。赵国贵族公子成起初反对，武灵王亲自劝说后推行改革，增强了赵军机动能力，为此后北拓和攻取中山奠定基础。','指改穿便于骑射的胡服、学习骑马射箭；后用以比喻改革旧制，吸收他人所长以增强实力。',NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-hu-jia-hu-wei','狐假虎威','idiom','point','year',NULL,NULL,'《战国策·楚策》楚宣王问江乙时所举寓言',-275,12,NULL,-3277,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'《战国策·楚策》载楚宣王问江乙，江乙以虎狐同行、百兽皆走为喻。','比喻倚仗别人的势力欺压人。',NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-hua-long-dian-jing','画龙点睛','idiom','point','year',NULL,NULL,'梁陈间事，成语通行于唐',550,12,NULL,6611,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'张僧繇在金陵安乐寺画龙，点睛后龙破壁飞去。','比喻说话或写作在关键处点明要旨，使内容生动传神。',NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-hua-she-tian-zu','画蛇添足','idiom','point','year',NULL,NULL,'战国策寓言',-280,12,NULL,-3337,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'《战国策》楚人画蛇，先成者添足，酒不得饮。','比喻做了多余的事，反而把事情弄坏。',NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-hui-ji-ji-yi','讳疾忌医','idiom','point','year',NULL,NULL,'《韩非子》载扁鹊见蔡桓侯，战国寓言',-400,12,NULL,-4777,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'蔡桓侯讳疾忌医，扁鹊每见病深一层，终不可救。','比喻隐瞒缺点，拒绝批评和帮助。',NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-jia-dao-fa-guo','假道伐虢','idiom','point','year',NULL,NULL,'晋灭虢，前655年；《左传》记鲁僖公五年。',-655,12,NULL,-7837,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'晋献公先以讨伐虢国为名向虞国借道，灭虢后回师袭灭虞国。《左传·僖公二年、五年》记载了这两次借道与宫之奇的劝谏。','以借路为名，行灭亡对方之实；后用来比喻利用对方作为进攻第三方的通道，达到目的后再消灭对方。',NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-jiao-tu-san-ku','狡兔三窟','idiom','point','year',NULL,NULL,'冯谖谏孟尝君，战国',-300,12,NULL,-3577,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'《战国策》冯谖谓孟尝君：狡兔有三窟，仅得免其死耳。','比喻隐蔽的地方多，便于藏身或留有退路。',NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-jing-di-zhi-wa','井底之蛙','idiom','point','year',NULL,NULL,'庄子寓言',-320,12,NULL,-3817,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'《庄子》井蛙不可以语于海者，拘于虚也。','比喻见识狭窄、眼光短浅的人。',NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-jing-gong-zhi-niao','惊弓之鸟','idiom','point','year',NULL,NULL,'战国策寓言，约前251年',-251,12,NULL,-2989,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'《战国策》更羸与魏王处京台，引弓虚发，雁坠，盖其伤弓未愈。','比喻受过惊吓的人遇到类似情形就惶恐不安。',NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-jing-zhong-bao-guo','精忠报国','idiom','point','year',NULL,NULL,NULL,1140,12,NULL,13691,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'岳飞背刺「尽忠报国」，抗金名垂青史。','竭尽忠诚，报效国家。',NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-jiu-chi-rou-lin','酒池肉林','idiom','point','year',NULL,NULL,'商纣王末年，前1046年前后；主要见于后世文献，史源有争议',-1046,12,NULL,-12529,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'《史记·殷本纪》载纣王以酒为池、悬肉为林，后世以此形容奢靡纵欲。','形容生活极端奢侈、纵欲无度。',NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-ju-gong-jin-cui','鞠躬尽瘁','idiom','point','year',NULL,NULL,'五丈原病逝前后',234,8,NULL,2815,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'诸葛亮《后出师表》：「鞠躬尽瘁，死而后已。」','指恭敬谨慎，竭尽心力。',NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-kai-juan-you-yi','开卷有益','idiom','point','year',NULL,NULL,NULL,997,12,NULL,11975,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'宋太宗赵恒对读《太平御览》者说：「开卷有益，朕不以为劳。」','读书就有好处。',NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-ke-zhou-qiu-jian','刻舟求剑','idiom','point','year',NULL,NULL,'列子寓言',-300,12,NULL,-3577,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'《列子》楚人渡江剑坠，遽刻其舟曰「是吾剑所从坠」，舟止入水求之。','比喻拘泥成例、不知变通，或办事方法不对。',NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-lan-yu-chong-shu','滥竽充数','idiom','point','year',NULL,NULL,'齐宣王时，约前319—前301年',-310,12,NULL,-3697,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'齐宣王使三百人吹竽，南郭处士充数；湣王好一一听之，处士逃。','比喻没有真才实学的人混在行家里面充数，或以次充好。',NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-lao-ma-shi-tu','老马识途','idiom','point','year',NULL,NULL,'齐桓公征孤竹，约前664年',-664,12,NULL,-7945,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'齐桓公征孤竹迷途，管仲曰老马识途，遣老马先导得归。','比喻富有经验的人对情况熟悉，能起引导作用。',NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-le-bu-si-shu','乐不思蜀','idiom','point','year',NULL,NULL,NULL,263,12,NULL,3167,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'刘禅降魏后，司马昭问是否思蜀，答「此间乐，不思蜀」。','比喻乐而忘返，或安于现状不想回去。',NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-mai-du-huan-zhu','买椟还珠','idiom','point','year',NULL,NULL,'韩非子寓言',-275,12,NULL,-3277,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'《韩非子》楚人卖珠于郑，椟饰以木兰、薰以桂椒，郑人买其椟而还其珠。','比喻取舍不当，舍本逐末；也指不识货。',NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-mao-sui-zi-jian','毛遂自荐','idiom','point','year',NULL,NULL,'平原君合纵，前257年',-257,12,NULL,-3061,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'毛遂自荐随平原君赴楚，按剑而立，说服楚王合纵抗秦。','比喻自告奋勇，自己推荐自己担任某项工作。',NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-meng-mu-san-qian','孟母三迁','idiom','point','year',NULL,NULL,'孟子少年期于邹国，约前375年',-375,12,NULL,-4477,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'孟子幼时，孟母三迁其居，近墓则嬉墓，近市则嬉贾，近学宫则习礼。','比喻为子女成长选择良好环境。',NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-nan-yuan-bei-zhe','南辕北辙','idiom','point','year',NULL,NULL,'战国策寓言',-310,12,NULL,-3697,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'《战国策》有人欲之楚而北行，马良、用多、御善，愈善而离楚愈远。','比喻行动和目的相反，越努力离目标越远。',NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-po-fu-chen-zhou','破釜沉舟','idiom','point','year',NULL,NULL,'巨鹿之战前后',-207,12,NULL,-2461,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'项羽渡漳水后破釜沉舟，只带三日粮，大破秦军于巨鹿。','比喻下定决心，不顾一切地干到底。',NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-qi-ren-you-tian','杞人忧天','idiom','point','month',NULL,NULL,'《列子·天瑞》未记具体年代；按杞国仍存续的春秋末期约前500年推定定位',-500,12,NULL,-5977,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'《列子》杞国有人忧天地崩坠，身无所寄，废寝食者。','比喻不必要的或缺乏根据的忧虑和担心。',NULL);
