INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-sima-zhao-zhi-xin-luren-jiezhi','司马昭之心，路人皆知','idiom','point','month',NULL,NULL,'甘露五年五月（260）；《三国志·魏书·高贵乡公纪》裴松之注引《汉晋春秋》，原文作“路人所知也”',260,5,NULL,3124,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'甘露五年，曹髦召见王沈、王经、王业，愤言「司马昭之心，路人所知也」，后凝为成语。','比喻人的野心或意图非常明显，众人都已看出。',NULL);
