INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('idiom-zi-xiang-mao-dun','自相矛盾','idiom','point','year',NULL,NULL,'韩非子寓言',-280,12,NULL,-3337,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'《韩非子》楚人鬻盾与矛，誉盾坚莫能陷、矛利无不陷，或曰以矛陷盾，弗能应。','比喻言行前后抵触，不能自圆其说。',NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('jiahu','贾湖文化','culture','point','approximate_year',NULL,NULL,'贾湖遗址三期约距今9000–7800年；骨笛分期作前7000–前5800。一说属裴李岗文化类型。；原不确定范围：-7000年1月至-5800年12月；按既有事件说明转为代表时点。',-6400,1,NULL,-76788,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'河南舞阳贾湖，新石器早期聚落。出土七声音阶骨笛、炭化稻、龟甲契刻符号，为黄河—淮河间早期文化的代表。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('jianan-twenty-two-epidemic','建安二十二年大疫','disaster','point','year',NULL,NULL,'建安二十二年（217）；按年精度记录。史料未能证明该场疫情始于196年，也不能据此确认为鼠疫或伤寒。',217,12,NULL,2615,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'建安二十二年，北方疫病流行。曹丕次年致吴质书追述亲友多遭疫病，陈琳、徐幹、应玚、刘桢相继去世；曹植《说疫气》也记述当年疫病造成的广泛死亡。疫情影响建安文人群体，但史料不足以判定具体病原或量化死亡人数。',NULL,NULL);
