INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('kuiqiu','葵丘之盟','politics','point','year',NULL,NULL,'齐桓公三十五年，鲁僖公九年，前651年',-651,12,NULL,-7789,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'齐桓公会诸侯于葵丘，周襄王赐胙，齐霸达到顶点。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('kunlun-pass-battle','昆仑关战役','battle','span',NULL,'month','month','1939年12月至1940年1月；战斗起于12月中旬，昆仑关于1940年1月收复。',NULL,NULL,NULL,NULL,1939,12,NULL,23279,1940,1,NULL,23280,'日军占领南宁后威胁桂越交通与西南后方，中国军队集中力量反攻昆仑关。第五军等部在杜聿明指挥下与日军激战并一度攻克关隘，随后守住战果；战斗迟滞了日军向桂林、柳州方向的推进，成为桂南会战中的关键战役。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('kunyang-battle','昆阳之战','battle','point','year',NULL,NULL,'更始元年，23年，刘秀以少胜多破王莽军',23,12,NULL,287,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'刘秀率绿林军于昆阳大破王莽主力，新莽覆亡在即。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('later-jin-cedes-yanyun','后晋割让燕云十六州','politics','point','year',NULL,NULL,'936年后晋建国及相关契丹册立、割地约定；具体交割过程跨越936年前后。',936,12,NULL,11243,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'石敬瑭借契丹援助赢得帝位，向辽割让燕云十六州，北方门户自此长期处于辽、金控制之下。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('later-zhou-recovers-ying-mo','后周北伐收复瀛、莫二州','battle','point','year',NULL,NULL,'显德六年（959年）北伐；州县归属与进军阶段按年精度处理。',959,12,NULL,11519,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'后周世宗北伐，收复燕云南部的瀛州、莫州等地，但未能完成燕云十六州的整体收复。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('li-shou-change-country-name','李寿改国号为汉','politics','point','year',NULL,NULL,'咸康四年夏四月（原历），公元338年',338,12,NULL,4067,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'李寿发动政变废杀李期并即皇帝位，随后废“成”号、改国号为“汉”，改元汉兴，以承续汉朝统绪。改号后的政权仍是原成都政权的延续，后世为与其他汉政权区别而合称成汉；其后仍与东晋、后赵周旋，最终于347年为东晋桓温所灭。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('liangzhu','良渚文化','culture','point','approximate_year',NULL,NULL,'通行约前3300–前2300；亦记距今约5300–4000年（约前3300–前2000）。；原不确定范围：-3300年1月至-2300年12月；按既有事件说明转为代表时点。',-2800,1,NULL,-33588,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'环太湖地区新石器晚期文化。良渚古城、水利系统与琮璧钺玉礼器，常被视为长江下游早期国家形态。',NULL,NULL);
