INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('pingjin-campaign','平津作战','battle','span',NULL,'month','month','1937年7月至8月；各地战斗与撤退日期不一，按战事阶段记月。',NULL,NULL,NULL,NULL,1937,7,NULL,23250,1937,8,NULL,23251,'七七事变后，日军向平津地区扩大进攻，国民政府军与第二十九军等部在北平、天津及南苑一带抵抗。北平、天津先后失守，华北战事迅速扩大；这场作战揭示局部冲突已演变为全面战争。',NULL,NULL);
