INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('sarhu-battle','萨尔浒之战','battle','point','month',NULL,NULL,'万历四十七年三月，后金大败明军',1619,3,NULL,19430,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'努尔哈赤以少胜多，明军四路溃败，辽东战局逆转。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('second-changsha-campaign','第二次长沙会战','battle','span',NULL,'month','month','1941年9月至10月；按湖南战场史料所载会战阶段记月。',NULL,NULL,NULL,NULL,1941,9,NULL,23300,1941,10,NULL,23301,'日军第十一军再次进攻长沙，企图重创第九战区并迫使中国方面妥协。薛岳指挥守军在湘北阻击并反攻，日军一度突入长沙后因补给和后方受威胁而撤退，未能达成作战目标；会战显示日军仍试图以局部攻势改变相持态势。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('second-opium-war','第二次鸦片战争','battle','span',NULL,'year','year',NULL,NULL,NULL,NULL,NULL,1856,1,NULL,22272,1860,1,NULL,22320,'英法联军再度进攻，攻陷大沽、北京，圆明园被焚，清政府签订天津、北京条约。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('shanghai-campaign-1937','淞沪会战','battle','span',NULL,'month','month','1937年8月13日至11月12日；以月精度记录持续区间。',NULL,NULL,NULL,NULL,1937,8,NULL,23251,1937,11,NULL,23254,'1937年8月，国民政府军在上海主动投入大规模作战，试图牵制日军并争取国际关注。双方围绕闸北、江湾、大场及沿海登陆地持续激战，中国军队坚守三个月后因日军增援登陆而撤退，上海失守；会战粉碎了日方速胜预期，也使战争迅速扩展。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('shanghai-incident-1932','一·二八淞沪抗战','battle','span',NULL,'day','day','以1932年1月28日战事爆发至3月3日停战记录作战区间；5月5日签署《淞沪停战协定》，结束后续停战交涉。',NULL,NULL,NULL,NULL,1932,1,28,23184,1932,3,3,23186,'九一八事变后，中日关系持续紧张，上海的抵制日货风潮及日方挑衅使局势升级。1932年1月28日晚，日军突袭上海闸北，第十九路军在蒋光鼐、蔡廷锴等指挥下抵抗，随后第五军增援，战事扩展至吴淞等地；在上海民众支援与国际调停下，交战于3月3日停战，5月5日签署《淞沪停战协定》。此战阻止日军迅速占领上海，但协定限制中国军队在上海周边的部署。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('shangyang-reform','商鞅变法','politics','point','year',NULL,NULL,'秦孝公六年，前356年；史籍或作前359年，取前356年',-356,12,NULL,-4249,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'商鞅在秦国推行军功爵、什伍连坐、废井田等改革，奠定统一六国基础。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('shaokang-zhongxing','少康中兴','politics','span',NULL,'approximate_year','approximate_year','少康灭寒浞、恢复夏政；窗口取今本竹书年数顺推后的少康在位段，标推算；原不确定范围：-1959年1月至-1939年12月；按既有事件说明转为持续区间。',NULL,NULL,NULL,NULL,-1959,1,NULL,-23496,-1939,12,NULL,-23245,'后缗逃归有仍生少康；少康自有虞起兵，消灭寒浞、过浇，恢复夏后氏统治。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('shaoxing-treaty','绍兴和议','politics','point','year',NULL,NULL,NULL,1141,12,NULL,13703,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'宋金议和，割地纳贡，岳飞被害，南北对峙格局确立。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('shenlong-coup','神龙政变','politics','point','year',NULL,NULL,'长安五年正月癸卯发动，传统历日对应公历705年2月20日；按年精度记录。',705,12,NULL,8471,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'武则天病重之际，张柬之等朝臣联合禁军诛杀张易之、张昌宗，控制宫廷并促使太子李显监国。武则天随后退位，李显复位为唐中宗，武周结束、唐朝复辟；此后朝廷仍受韦后及其党羽影响。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('shimao','石峁','culture','point','approximate_year',NULL,NULL,'石峁城址属龙山晚期，通行碳十四约前2300–前1800（距今约4300–3800年）。；原不确定范围：-2300年1月至-1800年12月；按既有事件说明转为代表时点。',-2050,1,NULL,-24588,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'陕西神木石峁，目前所见中国史前规模最大的石构城址。皇城台、玉器与石雕，为河套—陕北早期邦国遗存。',NULL,NULL);
