INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('taierzhuang-battle','台儿庄战役','battle','span',NULL,'month','month','1938年3月23日至4月7日；中国第二历史档案馆档案专题采用此战斗区间。',NULL,NULL,NULL,NULL,1938,3,NULL,23258,1938,4,NULL,23259,'徐州会战中，日军沿津浦线南下争夺台儿庄。第五战区司令长官李宗仁调集部队防守，并组织侧翼反击；中国军队在台儿庄及其周边与日军反复争夺，迫使日军撤退。这是全面抗战以来正面战场的重要胜利，显著鼓舞了全国抗战士气。',NULL,NULL);
