INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('taiyuan-campaign','太原会战','battle','span',NULL,'month','month','1937年9月至11月；不同战史对会战起讫界定略有差异，按战役阶段记月。',NULL,NULL,NULL,NULL,1937,9,NULL,23252,1937,11,NULL,23254,'日军沿平绥、同蒲等方向进攻山西，第二战区依托长城、平型关、忻口及太原外围组织防御。平型关、忻口等战斗迟滞日军，但日军从娘子关方向突破后，太原于11月失守，山西正面防线瓦解；会战由此成为华北战局的重要转折。',NULL,NULL);
