INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('tang-tubo-changqing-alliance','唐蕃长庆会盟','politics','point','year',NULL,NULL,'长庆元年至二年（821—822年）分阶段立碑、会盟，采用821年作为事件锚点。',821,12,NULL,9863,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'唐与吐蕃订立长庆会盟，约定边界与和平关系，是唐蕃长期战争后重要的边疆秩序节点。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('tang-two-tax-law','两税法推行','politics','point','year',NULL,NULL,'建中元年（780年）颁行；《旧唐书·杨炎传》及《资治通鉴》记其制度与施行。',780,12,NULL,9371,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'唐德宗采纳杨炎建议，按居住地和资产等确定税额，分夏、秋两季征收，取代以丁身为主要依据的租庸调征收格局。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('tanglong-coup','唐隆政变','politics','point','year',NULL,NULL,'景龙四年六月二十日（唐隆元年，710年）；传统历日换算为公历7月21日，按年精度记录。',710,12,NULL,8531,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'唐中宗死后，韦太后临朝并控制禁军。临淄王李隆基与太平公主联络禁军发动政变，诛杀韦太后及安乐公主等韦氏势力；少帝李重茂退位，李旦复位为唐睿宗，李隆基被立为皇太子。',NULL,NULL);
