INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('taosi','陶寺文化','culture','point','approximate_year',NULL,NULL,'陶寺中期约前2100–前2000；观象台或可上溯至距今约4700年。此取龙山时代晋南陶寺通行年。；原不确定范围：-2300年1月至-1900年12月；按既有事件说明转为代表时点。',-2100,1,NULL,-25188,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'山西襄汾陶寺，晋南龙山时代都邑。宫殿、观象台、朱书扁壶与等级墓葬，常被用以探索早期国家与尧都传说。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('third-changsha-campaign','第三次长沙会战','battle','span',NULL,'month','month','1941年12月至1942年1月；湖南省档案馆与中国第二历史档案馆战场史料记载会战起讫。',NULL,NULL,NULL,NULL,1941,12,NULL,23303,1942,1,NULL,23304,'太平洋战争爆发后，日军为牵制中国军队并打通粤汉铁路，再度进攻长沙。第九战区以一部守城、主力在外围反击，长沙守军顶住日军猛攻后，中国军队于1942年1月转入反攻，日军撤退至新墙河以北；此次胜利提升了盟国对中国战场的关注。',NULL,NULL);
