INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('wuhan-campaign','武汉会战','battle','span',NULL,'month','month','1938年6月至10月；武汉于10月25日被日军占领，按月记录会战区间。',NULL,NULL,NULL,NULL,1938,6,NULL,23261,1938,10,NULL,23265,'南京失守后，武汉成为中国重要政治、军事中心。日军自长江南北多路进攻，国民政府军在大别山、长江沿线及万家岭等地节节抵抗；万家岭取得局部胜利，但武汉最终于10月失守。大规模抵抗迟滞日军攻势，标志战争由战略防御转入相持阶段。',NULL,NULL);
