INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('wuxu-reform','戊戌变法','politics','span',NULL,'year','year','光绪二十四年四月二十三日至八月初六（公历1898年6月11日至9月21日），共103天',NULL,NULL,NULL,NULL,1898,1,NULL,22776,1898,1,NULL,22776,'甲午战败与列强瓜分危机推动维新思潮发展。光绪帝采纳康有为等人的建议，自1898年6月起颁布新政，涉及政治、教育、经济和军事，试图改革清朝制度；慈禧太后于9月发动政变，囚禁光绪帝并废止新法，康有为、梁启超出走，谭嗣同等六人被杀。变法虽仅持续103天，却推动了近代中国的思想启蒙。',NULL,NULL);
