INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('xinkou-battle','忻口战役','battle','span',NULL,'month','month','1937年10月13日忻口正面战斗开始，11月上旬战线撤退；按月精度记载。',NULL,NULL,NULL,NULL,1937,10,NULL,23253,1937,11,NULL,23254,'日军突破内长城防线后，第二战区在忻口组织防御，由阎锡山统筹、卫立煌等指挥前线部队，八路军在日军侧后开展袭扰以配合作战。双方在阵地攻防中持续激战，守军最终因娘子关方向失守及太原受威胁而撤退；这是国共军队协同抗战的重要战例。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('xinyou-coup','辛酉政变','politics','point','year',NULL,NULL,'咸丰十一年（1861年，辛酉年）；故宫博物院资料记九月三十日发动、十一月初一开始垂帘听政，均为传统历日，故按年精度记录。',1861,12,NULL,22343,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'咸丰帝在热河病逝前安排载淳继位，并命载垣、端华、肃顺等八大臣赞襄政务。慈禧与慈安两宫太后联合恭亲王奕訢，在咸丰梓宫回京期间解除八大臣权力，载垣、端华被逼自尽，肃顺被处斩；两宫随后垂帘听政，清廷权力格局由此改变。',NULL,NULL);
