INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('xuzhou-campaign','徐州会战','battle','span',NULL,'month','month','1938年初至5月徐州撤退；各战斗跨多个省份且起讫口径不一。',NULL,NULL,NULL,NULL,1938,1,NULL,23256,1938,5,NULL,23260,'日军为打通津浦铁路、连接南北战场，分别由山东和长江下游向徐州合击。中国军队在临沂、台儿庄等地阻击后撤出徐州，避免被合围；日军虽占领徐州，却未能围歼中国主力，随后在武汉方向继续推进。台儿庄战役是徐州会战中的关键胜利，另作独立事件记录。',NULL,NULL);
