INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('yuxianggui-campaign','豫湘桂会战','battle','span',NULL,'month','month','1944年春至冬，分豫中、长衡、桂柳等阶段；按整体作战年度记载。',NULL,NULL,NULL,NULL,1944,4,NULL,23331,1944,12,NULL,23339,'日本为打通大陆交通线、连接华北与越南方向，发动“一号作战”，中国方面称豫湘桂会战。日军先后进攻河南、湖南、广西，攻占多座城市和机场；中国军队在局部战场持续抵抗，但整体防线严重崩溃，日军获得交通线并造成大规模难民流离。长衡会战及衡阳保卫战是其中的重要阶段，另作独立事件记录。',NULL,NULL);
