INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-event:hongmen-banquet:loc-hongmen-banquet','loc-f4353ee36ebbe0a0ad6bebc81f8a051d','event','hongmen-banquet','新丰鸿门','approximate',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'《史记·项羽本纪》称项羽驻军新丰鸿门。采用今鸿门堡村鸿门坂遗址附近作代表点；宴会遗址为后世认定位置，不将景区建筑视为汉代原址。','[{"label":"《史记·项羽本纪》","url":"https://zh.wikisource.org/wiki/史記/卷007"},{"label":"鸿门宴遗址地址与定位","url":"https://ditu.amap.com/place/B001D00964"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-event:huang-chao-uprising:loc-yuanju','loc-39bea5536ce486068b468de61ed288a6','event','huang-chao-uprising','曹州冤句','approximate',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'黄巢起义持续十余年并转战多地；据乾符二年黄巢在曹州冤句起兵的记载，取冤句故地作起事代表点。冤句故城具体位置有考证差异，坐标仅表示菏泽西南区域。','[{"label":"《新唐书·黄巢传》","url":"https://zh.wikisource.org/wiki/新唐書/卷225下"},{"label":"山东地情档案：黄巢籍贯考略","url":"https://shandong-chorography.org/database/fa01/section/3/article/60/"}]');
