INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-event:idiom-feng-lang-ju-xu:loc-feng-lang-ju-xu','loc-8479a6095d16bac22eb8971f44db0b24','event','idiom-feng-lang-ju-xu','狼居胥山','approximate',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'狼居胥山通常比定为今蒙古国肯特山一带，具体对应仍有历史地理争议；坐标为山脉区域近似代表点，不指向确定峰顶。另有其他考定，故精度为 approximate。','[{"label":"《汉书·卫青霍去病传》","url":"https://zh.wikisource.org/zh-hans/漢書/卷055"},{"label":"肯特山（蒙古国）","url":"https://zh.wikipedia.org/wiki/肯特山_(蒙古国)"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-event:jieting:loc-jieting','loc-f19fcca169729963595af0d6145fc033','event','jieting','街亭','approximate',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'街亭具体故址有争议，取通行考定区域。','[{"label":"地点资料","url":"https://zh.wikipedia.org/wiki/街亭之战"}]');
