INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-event:kublai-moves-capital-to-zhongdu:loc-kublai-moves-capital-to-zhongdu','loc-a286892c3d461160b24d88e277fb1120','event','kublai-moves-capital-to-zhongdu','中都','approximate',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'以迁入的金中都旧城区域为代表点；忽必烈此后在中都东北营建元大都，坐标不表示元大都城址。 地点名称原注：中都（今北京）。','[{"label":"北京市地方志：忽必烈迁都中都、元迁都大都","url":"https://www.bjdsdfz.cn/jcdq.jhtml"}]');
