INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-event:nanchang-campaign:loc-nanchang-campaign','loc-30a3cf6611edde8e06c2243abe038a59','event','nanchang-campaign','南昌','approximate',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'以南昌为争夺中心；会战还包括修水等外围战场。 地点名称原注：南昌会战代表点（南昌）。','[{"label":"OpenStreetMap：代表点坐标（WGS84）","url":"https://www.openstreetmap.org/#map=12/28.6829/115.8582"},{"label":"北京市委统战部：抗日战争时期的统一战线","url":"https://www.bjtzb.gov.cn/wwwroot/sdtyzx/publish/article/40/11335.shtml"}]');
