INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-ji-chonger-jin-chunqiu:cap-jin-chunqiu-jiang-669','loc-274b46582b7c685b4f68d87b936312ab','reign','reign-ji-chonger-jin-chunqiu','绛',NULL,-669,1,NULL,-585,12,NULL,-8016,-6997,'year','year','primary','《史记·晋世家》记献公八年城聚、命曰绛并始都之，取前669年；《左传》庄公二十六年（前668年）另记士蒍城绛。前585年景公迁新田后称故绛。城址有绛县南城村车厢城、翼城县南梁镇故城村及曲村—天马一带等说法，翼与绛是否同址亦有争议；暂保留绛县范围约略代表点，坐标为现代行政区中心，不作为古城遗址定位。 地点名称原注：绛（故绛）。','[{"label":"《史记》卷三十九·晋世家：翼都、曲沃封邑与献公都绛","url":"https://www.chinakongzi.org/kzsf/wxxs/mingpian/shiji/200705/t20070524_25208.htm"},{"label":"运城长安网：南城村车厢城与晋献公都绛的地方志记载","url":"https://www.ycpeace.gov.cn/a/wenyuan/biaolihedong/20211112/24167.html"},{"label":"潘明娟《圣都与俗都：晋国都城体系的演变》，《中原文化研究》2021年第2期","url":"https://www.zywhyj.cn/Uploads/PdfFile/2021-03-16/60506026c2527.pdf"}]');
