INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-jin-r27-jin-chunqiu:cap-jin-chunqiu-jiang-669','loc-274b46582b7c685b4f68d87b936312ab','reign','reign-jin-r27-jin-chunqiu','绛',NULL,-669,1,NULL,-585,12,NULL,-8016,-6997,'year','year','primary','《史记·晋世家》记献公八年城聚、命曰绛并始都之，取前669年；《左传》庄公二十六年（前668年）另记士蒍城绛。前585年景公迁新田后称故绛。城址有绛县南城村车厢城、翼城县南梁镇故城村及曲村—天马一带等说法，翼与绛是否同址亦有争议；暂保留绛县范围约略代表点，坐标为现代行政区中心，不作为古城遗址定位。 地点名称原注：绛（故绛）。','[{"label":"《史记》卷三十九·晋世家：翼都、曲沃封邑与献公都绛","url":"https://www.chinakongzi.org/kzsf/wxxs/mingpian/shiji/200705/t20070524_25208.htm"},{"label":"运城长安网：南城村车厢城与晋献公都绛的地方志记载","url":"https://www.ycpeace.gov.cn/a/wenyuan/biaolihedong/20211112/24167.html"},{"label":"潘明娟《圣都与俗都：晋国都城体系的演变》，《中原文化研究》2021年第2期","url":"https://www.zywhyj.cn/Uploads/PdfFile/2021-03-16/60506026c2527.pdf"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-jin-r27-jin-chunqiu:cap-jin-chunqiu-xinjiang-585','loc-3d5043964471fd257a273845e0c118f8','reign','reign-jin-r27-jin-chunqiu','新田/新绛',NULL,-585,1,NULL,-349,12,NULL,-7008,-4165,'year','year','primary','晋景公于前585年迁都新田，亦称新绛，故址为今侯马晋国遗址。《左传·成公六年》记“夏四月丁丑”，属周历，未经可靠公历换算仅录年精度。地图保留侯马城市范围约略代表点，不表示具体宫城位置。','[{"label":"《左传·成公六年》：晋景公迁都新田","url":"https://zh.wikisource.org/wiki/春秋左氏傳/成公"},{"label":"大连博物馆《晋国雄风》：曲沃小宗与翼都大宗、上郭古城","url":"https://www.dlmodernmuseum.com/news/detail/498.html"},{"label":"山西大学考古文博学院：天马—曲村、上郭—邱家庄与侯马新田","url":"https://archaeology.sxu.edu.cn/rcpy/yxsx/199ac6ba62514d118ef56d7d17add238.htm"}]');
