INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-nurhaci-qing:cap-qing-jiefan-1620','loc-cb4d41325d9e27b63ee876fa63edb8eb','reign','reign-nurhaci-qing','界藩城',NULL,1620,1,NULL,1620,12,NULL,19440,19451,'year','month','primary','故宫博物院年表记天命五年（1620）十月迁都界藩城。年精度年桶归入迁入地；坐标为永陵镇二道村附近约略点，未指认为精确遗址坐标。','[{"label":"故宫博物院：努尔哈赤年表","url":"https://www.dpm.org.cn/court/lineage/226250.html"},{"label":"高德地图地理编码与地点检索","url":"https://lbs.amap.com/api/webservice/guide/api/georegeo"}]');
